	/// <summary>
	/// Initializes platform-specific services for an <see cref="T:Avalonia.Application" />.
	/// </summary>
	public sealed class AppBuilder
	{
		public delegate void AppMainDelegate(Application app, string[] args);

		private static bool s_setupWasAlreadyCalled;

		private Action? _optionsInitializers;

		private Func<Application>? _appFactory;

		private IApplicationLifetime? _lifetime;

		/// <summary>
		/// Gets or sets a method to call the initialize the runtime platform services (e. g. AssetLoader)
		/// </summary>
		public Action? RuntimePlatformServicesInitializer { get; private set; }

		/// <summary>
		/// Gets the name of the currently selected windowing subsystem.
		/// </summary>
		public string? RuntimePlatformServicesName { get; private set; }

		/// <summary>
		/// Gets the <see cref="T:Avalonia.Application" /> instance being initialized.
		/// </summary>
		public Application? Instance { get; private set; }

		/// <summary>
		/// Gets the type of the Instance (even if it's not created yet)
		/// </summary>
		public Type? ApplicationType { get; private set; }

		/// <summary>
		/// Gets or sets a method to call the initialize the windowing subsystem.
		/// </summary>
		public Action? WindowingSubsystemInitializer { get; private set; }

		/// <summary>
		/// Gets the name of the currently selected windowing subsystem.
		/// </summary>
		public string? WindowingSubsystemName { get; private set; }

		/// <summary>
		/// Gets or sets a method to call the initialize the windowing subsystem.
		/// </summary>
		public Action? RenderingSubsystemInitializer { get; private set; }

		/// <summary>
		/// Gets a method to override a lifetime factory.
		/// </summary>
		[Obsolete("This property has no effect", true)]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		public Func<Type, IApplicationLifetime?>? LifetimeOverride { get; private set; }

		/// <summary>
		/// Gets the name of the currently selected rendering subsystem.
		/// </summary>
		public string? RenderingSubsystemName { get; private set; }

		/// <summary>
		/// Gets a method to call after the <see cref="T:Avalonia.Application" /> is setup.
		/// </summary>
		public Action<AppBuilder> AfterSetupCallback { get; private set; } = delegate
		{
		};

		/// <summary>
		/// Callbacks that are commonly used by backends to initialize avalonia views.
		/// </summary>
		private Action<AppBuilder> AfterApplicationSetupCallback { get; set; } = delegate
		{
		};

		public Action<AppBuilder> AfterPlatformServicesSetupCallback { get; private set; } = delegate
		{
		};

		private AppBuilder Self => this;

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.AppBuilder" /> class.
		/// </summary>
		private AppBuilder()
		{
		}

		/// <summary>
		/// Begin configuring an <see cref="T:Avalonia.Application" />.
		/// </summary>
		/// <typeparam name="TApp">The subclass of <see cref="T:Avalonia.Application" /> to configure.</typeparam>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public static AppBuilder Configure<TApp>() where TApp : Application, new()
		{
			return new AppBuilder
			{
				ApplicationType = typeof(TApp),
				_appFactory = () => new TApp()
			};
		}

		/// <summary>
		/// Begin configuring an <see cref="T:Avalonia.Application" />.
		/// </summary>
		/// <param name="appFactory">Factory function for <typeparamref name="TApp" />.</param>
		/// <typeparam name="TApp">The subclass of <see cref="T:Avalonia.Application" /> to configure.</typeparam>
		/// <remarks><paramref name="appFactory" /> is useful for passing of dependencies to <typeparamref name="TApp" />.</remarks>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public static AppBuilder Configure<TApp>(Func<TApp> appFactory) where TApp : Application
		{
			return new AppBuilder
			{
				ApplicationType = typeof(TApp),
				_appFactory = appFactory
			};
		}

		/// <summary>
		/// Begin configuring an <see cref="T:Avalonia.Application" />.
		/// Should only be used for testing and design purposes, as it relies on dynamic code.
		/// </summary>
		/// <param name="entryPointType">
		/// Parameter from which <see cref="T:Avalonia.AppBuilder" /> should be created.
		/// It either needs to have BuildAvaloniaApp -&gt; AppBuilder method or inherit Application.
		/// </param>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance. If can't be created, thrown an exception.</returns>
		internal static AppBuilder Configure([DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicParameterlessConstructor | DynamicallyAccessedMemberTypes.PublicMethods | DynamicallyAccessedMemberTypes.NonPublicMethods)] Type entryPointType)
		{
			if (entryPointType.GetMethod("BuildAvaloniaApp", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.FlattenHierarchy, null, Array.Empty<Type>(), null)?.Invoke(null, Array.Empty<object>()) is AppBuilder result)
			{
				return result;
			}
			if (typeof(Application).IsAssignableFrom(entryPointType))
			{
				return Configure(() => (Application)Activator.CreateInstance(entryPointType));
			}
			throw new InvalidOperationException("Unable to create AppBuilder from type \"" + entryPointType.FullName + "\". Input type either needs to have BuildAvaloniaApp -> AppBuilder method or inherit Application type.");
		}

		public AppBuilder AfterSetup(Action<AppBuilder> callback)
		{
			AfterSetupCallback = (Action<AppBuilder>)Delegate.Combine(AfterSetupCallback, callback);
			return Self;
		}

		[PrivateApi]
		public AppBuilder AfterApplicationSetup(Action<AppBuilder> callback)
		{
			AfterApplicationSetupCallback = (Action<AppBuilder>)Delegate.Combine(AfterApplicationSetupCallback, callback);
			return Self;
		}

		public AppBuilder AfterPlatformServicesSetup(Action<AppBuilder> callback)
		{
			AfterPlatformServicesSetupCallback = (Action<AppBuilder>)Delegate.Combine(AfterPlatformServicesSetupCallback, callback);
			return Self;
		}

		public void Start(AppMainDelegate main, string[] args)
		{
			Setup();
			main(Instance, args);
		}

		/// <summary>
		/// Sets up the platform-specific services for the application, but does not run it.
		/// </summary>
		/// <returns></returns>
		public AppBuilder SetupWithoutStarting()
		{
			Setup();
			return Self;
		}

		/// <summary>
		/// Sets up the platform-specific services for the application and initialized it with a particular lifetime, but does not run it.
		/// </summary>
		/// <param name="lifetime"></param>
		/// <returns></returns>
		public AppBuilder SetupWithLifetime(IApplicationLifetime lifetime)
		{
			_lifetime = lifetime;
			Setup();
			return Self;
		}

		/// <summary>
		/// Specifies a windowing subsystem to use.
		/// </summary>
		/// <param name="initializer">The method to call to initialize the windowing subsystem.</param>
		/// <param name="name">The name of the windowing subsystem.</param>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public AppBuilder UseWindowingSubsystem(Action initializer, string name = "")
		{
			WindowingSubsystemInitializer = initializer;
			WindowingSubsystemName = name;
			return Self;
		}

		/// <summary>
		/// Specifies a rendering subsystem to use.
		/// </summary>
		/// <param name="initializer">The method to call to initialize the rendering subsystem.</param>
		/// <param name="name">The name of the rendering subsystem.</param>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public AppBuilder UseRenderingSubsystem(Action initializer, string name = "")
		{
			RenderingSubsystemInitializer = initializer;
			RenderingSubsystemName = name;
			return Self;
		}

		/// <summary>
		/// Specifies a runtime platform subsystem to use.
		/// </summary>
		/// <param name="initializer">The method to call to initialize the runtime platform subsystem.</param>
		/// <param name="name">The name of the runtime platform subsystem.</param>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public AppBuilder UseRuntimePlatformSubsystem(Action initializer, string name = "")
		{
			RuntimePlatformServicesInitializer = initializer;
			RuntimePlatformServicesName = name;
			return Self;
		}

		/// <summary>
		/// Specifies a standard runtime platform subsystem to use.
		/// </summary>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public AppBuilder UseStandardRuntimePlatformSubsystem()
		{
			RuntimePlatformServicesInitializer = delegate
			{
				StandardRuntimePlatformServices.Register(ApplicationType?.Assembly);
			};
			RuntimePlatformServicesName = "StandardRuntimePlatform";
			return Self;
		}

		/// <summary>
		/// Configures platform-specific options
		/// </summary>
		public AppBuilder With<T>(T options)
		{
			_optionsInitializers = (Action)Delegate.Combine(_optionsInitializers, (Action)delegate
			{
				AvaloniaLocator.CurrentMutable.Bind<T>().ToConstant(options);
			});
			return Self;
		}

		/// <summary>
		/// Configures platform-specific options
		/// </summary>
		public AppBuilder With<T>(Func<T> options)
		{
			_optionsInitializers = (Action)Delegate.Combine(_optionsInitializers, (Action)delegate
			{
				AvaloniaLocator.CurrentMutable.Bind<T>().ToFunc(options);
			});
			return Self;
		}

		/// <summary>
		/// Registers an action that is executed with the current font manager.
		/// </summary>
		/// <param name="action">The action.</param>
		/// <returns>An <see cref="T:Avalonia.AppBuilder" /> instance.</returns>
		public AppBuilder ConfigureFonts(Action<FontManager> action)
		{
			return AfterSetup(delegate
			{
				action?.Invoke(FontManager.Current);
			});
		}

		/// <summary>
		/// Sets up the platform-specific services for the <see cref="T:Avalonia.Application" />.
		/// </summary>
		private void Setup()
		{
			if (RuntimePlatformServicesInitializer == null)
			{
				throw new InvalidOperationException("No runtime platform services configured.");
			}
			if (WindowingSubsystemInitializer == null)
			{
				throw new InvalidOperationException("No windowing system configured.");
			}
			if (RenderingSubsystemInitializer == null)
			{
				throw new InvalidOperationException("No rendering system configured.");
			}
			if (_appFactory == null)
			{
				throw new InvalidOperationException("No Application factory configured.");
			}
			if (s_setupWasAlreadyCalled)
			{
				throw new InvalidOperationException("Setup was already called on one of AppBuilder instances");
			}
			s_setupWasAlreadyCalled = true;
			SetupUnsafe();
		}

		/// <summary>
		/// Setup method that doesn't check for input initalizers being set.
		/// Nor 
		/// </summary>
		internal void SetupUnsafe()
		{
			_optionsInitializers?.Invoke();
			RuntimePlatformServicesInitializer?.Invoke();
			RenderingSubsystemInitializer?.Invoke();
			WindowingSubsystemInitializer?.Invoke();
			AfterPlatformServicesSetupCallback?.Invoke(Self);
			Instance = _appFactory();
			Instance.ApplicationLifetime = _lifetime;
			AvaloniaLocator.CurrentMutable.BindToSelf(Instance);
			Instance.RegisterServices();
			Instance.Initialize();
			AfterApplicationSetupCallback?.Invoke(Self);
			AfterSetupCallback?.Invoke(Self);
			Instance.OnFrameworkInitializationCompleted();
		}
	}
	/// <summary>
	/// Encapsulates a Avalonia application.
	/// </summary>
	/// <remarks>
	/// The <see cref="T:Avalonia.Application" /> class encapsulates Avalonia application-specific
	/// functionality, including:
	/// - A global set of <see cref="P:Avalonia.Application.DataTemplates" />.
	/// - A global set of <see cref="P:Avalonia.Application.Styles" />.
	/// - A <see cref="T:Avalonia.Input.FocusManager" />.
	/// - An <see cref="P:Avalonia.Application.InputManager" />.
	/// - Registers services needed by the rest of Avalonia in the <see cref="M:Avalonia.Application.RegisterServices" />
	/// method.
	/// - Tracks the lifetime of the application.
	/// </remarks>
	public class Application : AvaloniaObject, IDataContextProvider, IGlobalDataTemplates, IDataTemplateHost, IGlobalStyles, IStyleHost, IThemeVariantHost, IResourceHost, IResourceNode, IResourceHost2, IApplicationPlatformEvents, IOptionalFeatureProvider
	{
		/// <summary>
		/// The application-global data templates.
		/// </summary>
		private DataTemplates? _dataTemplates;

		private Styles? _styles;

		private IResourceDictionary? _resources;

		private Action<IReadOnlyList<IStyle>>? _stylesAdded;

		private Action<IReadOnlyList<IStyle>>? _stylesRemoved;

		private IApplicationLifetime? _applicationLifetime;

		private bool _setupCompleted;

		private EventHandler<ResourcesChangedToken>? _resourcesChanged2;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Application.DataContext" /> property.
		/// </summary>
		public static readonly StyledProperty<object?> DataContextProperty = StyledElement.DataContextProperty.AddOwner<Application>();

		/// <inheritdoc cref="F:Avalonia.Controls.ThemeVariantScope.ActualThemeVariantProperty" />
		public static readonly StyledProperty<ThemeVariant> ActualThemeVariantProperty = ThemeVariantScope.ActualThemeVariantProperty.AddOwner<Application>();

		/// <inheritdoc cref="F:Avalonia.Controls.ThemeVariantScope.RequestedThemeVariantProperty" />
		public static readonly StyledProperty<ThemeVariant?> RequestedThemeVariantProperty = ThemeVariantScope.RequestedThemeVariantProperty.AddOwner<Application>();

		private string? _name;

		/// <summary>
		/// Defines Name property
		/// </summary>
		public static readonly DirectProperty<Application, string?> NameProperty = AvaloniaProperty.RegisterDirect("Name", (Application o) => o.Name, delegate(Application o, string? v)
		{
			o.Name = v;
		});

		/// <summary>
		/// Gets or sets the Applications's data context.
		/// </summary>
		/// <remarks>
		/// The data context property specifies the default object that will
		/// be used for data binding.
		/// </remarks>
		public object? DataContext
		{
			get
			{
				return GetValue(DataContextProperty);
			}
			set
			{
				SetValue(DataContextProperty, value);
			}
		}

		/// <inheritdoc cref="P:Avalonia.Controls.ThemeVariantScope.RequestedThemeVariant" />
		public ThemeVariant? RequestedThemeVariant
		{
			get
			{
				return GetValue(RequestedThemeVariantProperty);
			}
			set
			{
				SetValue(RequestedThemeVariantProperty, value);
			}
		}

		/// <inheritdoc />
		public ThemeVariant ActualThemeVariant => GetValue(ActualThemeVariantProperty);

		/// <summary>
		/// Gets the current instance of the <see cref="T:Avalonia.Application" /> class.
		/// </summary>
		/// <value>
		/// The current instance of the <see cref="T:Avalonia.Application" /> class.
		/// </value>
		public static Application? Current => AvaloniaLocator.Current.GetService<Application>();

		/// <summary>
		/// Gets or sets the application's global data templates.
		/// </summary>
		/// <value>
		/// The application's global data templates.
		/// </value>
		public DataTemplates DataTemplates => _dataTemplates ?? (_dataTemplates = new DataTemplates());

		/// <summary>
		/// Gets the application's input manager.
		/// </summary>
		/// <value>
		/// The application's input manager.
		/// </value>
		internal InputManager? InputManager { get; private set; }

		/// <summary>
		/// Gets the application's global resource dictionary.
		/// </summary>
		public IResourceDictionary Resources
		{
			get
			{
				return _resources ?? (_resources = new ResourceDictionary(this));
			}
			set
			{
				value = value ?? throw new ArgumentNullException("value");
				_resources?.RemoveOwner(this);
				_resources = value;
				_resources.AddOwner(this);
			}
		}

		/// <summary>
		/// Gets the application's global styles.
		/// </summary>
		/// <value>
		/// The application's global styles.
		/// </value>
		/// <remarks>
		/// Global styles apply to all windows in the application.
		/// </remarks>
		public Styles Styles => _styles ?? (_styles = new Styles(this));

		/// <inheritdoc />
		bool IDataTemplateHost.IsDataTemplatesInitialized => _dataTemplates != null;

		/// <inheritdoc />
		bool IResourceNode.HasResources
		{
			get
			{
				IResourceDictionary? resources = _resources;
				if (resources == null || !resources.HasResources)
				{
					return ((IResourceNode)_styles)?.HasResources ?? false;
				}
				return true;
			}
		}

		/// <summary>
		/// Gets the styling parent of the application, which is null.
		/// </summary>
		IStyleHost? IStyleHost.StylingParent => null;

		/// <inheritdoc />
		bool IStyleHost.IsStylesInitialized => _styles != null;

		/// <summary>
		/// Application lifetime, use it for things like setting the main window and exiting the app from code
		/// Currently supported lifetimes are:
		/// - <see cref="T:Avalonia.Controls.ApplicationLifetimes.IClassicDesktopStyleApplicationLifetime" />
		/// - <see cref="T:Avalonia.Controls.ApplicationLifetimes.ISingleViewApplicationLifetime" />
		/// - <see cref="T:Avalonia.Controls.ApplicationLifetimes.IControlledApplicationLifetime" /> 
		/// - <see cref="T:Avalonia.Controls.ApplicationLifetimes.IActivatableApplicationLifetime" /> 
		/// </summary>
		public IApplicationLifetime? ApplicationLifetime
		{
			get
			{
				return _applicationLifetime;
			}
			set
			{
				if (_setupCompleted)
				{
					throw new InvalidOperationException("It's not possible to change ApplicationLifetime after Application was initialized.");
				}
				_applicationLifetime = value;
			}
		}

