		/// Initializes the application by loading XAML etc.
		/// </summary>
		public virtual void Initialize()
		{
		}

		/// <inheritdoc />
		public bool TryGetResource(object key, ThemeVariant? theme, out object? value)
		{
			value = null;
			IResourceDictionary? resources = _resources;
			if (resources == null || !resources.TryGetResource(key, theme, out value))
			{
				return Styles.TryGetResource(key, theme, out value);
			}
			return true;
		}

		void IResourceHost.NotifyHostedResourcesChanged(ResourcesChangedEventArgs e)
		{
			_resourcesChanged2?.Invoke(this, ResourcesChangedToken.Create());
			this.ResourcesChanged?.Invoke(this, e);
		}

		void IResourceHost2.NotifyHostedResourcesChanged(ResourcesChangedToken token)
		{
			_resourcesChanged2?.Invoke(this, token);
			this.ResourcesChanged?.Invoke(this, ResourcesChangedEventArgs.Empty);
		}

		void IStyleHost.StylesAdded(IReadOnlyList<IStyle> styles)
		{
			_stylesAdded?.Invoke(styles);
		}

		void IStyleHost.StylesRemoved(IReadOnlyList<IStyle> styles)
		{
			_stylesRemoved?.Invoke(styles);
		}

		/// <summary>
		/// Register's the services needed by Avalonia.
		/// </summary>
		public virtual void RegisterServices()
		{
			AvaloniaSynchronizationContext.InstallIfNeeded();
			FocusManager constant = new FocusManager();
			InputManager = new InputManager();
			IPlatformSettings platformSettings = PlatformSettings;
			if (platformSettings != null)
			{
				platformSettings.ColorValuesChanged += OnColorValuesChanged;
				OnColorValuesChanged(platformSettings, platformSettings.GetColorValues());
			}
			AvaloniaLocator.CurrentMutable.Bind<IAccessKeyHandler>().ToTransient<AccessKeyHandler>().Bind<IGlobalDataTemplates>()
				.ToConstant(this)
				.Bind<IGlobalStyles>()
				.ToConstant(this)
				.Bind<IThemeVariantHost>()
				.ToConstant(this)
				.Bind<IFocusManager>()
				.ToConstant(constant)
				.Bind<IInputManager>()
				.ToConstant(InputManager)
				.Bind<IToolTipService>()
				.ToConstant(new ToolTipService(InputManager))
				.Bind<IKeyboardNavigationHandler>()
				.ToTransient<KeyboardNavigationHandler>()
				.Bind<IDragDropDevice>()
				.ToConstant(DragDropDevice.Instance);
			if (AvaloniaLocator.Current.GetService<IPlatformDragSource>() == null)
			{
				AvaloniaLocator.CurrentMutable.Bind<IPlatformDragSource>().ToTransient<InProcessDragSource>();
			}
			AvaloniaLocator.CurrentMutable.Bind<IGlobalClock>().ToConstant(MediaContext.Instance.Clock);
			_setupCompleted = true;
		}

		public virtual void OnFrameworkInitializationCompleted()
		{
		}

		void IApplicationPlatformEvents.RaiseUrlsOpened(string[] urls)
		{
			this.UrlsOpened?.Invoke(this, new UrlOpenedEventArgs(urls));
		}

		/// <summary>
		/// Queries for an optional feature.
		/// </summary>
		/// <param name="featureType">Feature type.</param>
		/// <remarks>
		/// Features currently supported by <see cref="M:Avalonia.Application.TryGetFeature(System.Type)" />:
		/// <list type="bullet">
		/// <item>IPlatformSettings</item>
		/// <item>IActivatableApplicationLifetime</item>
		/// </list>
		/// </remarks>
		public object? TryGetFeature(Type featureType)
		{
			if (featureType == typeof(IPlatformSettings))
			{
				return AvaloniaLocator.Current.GetService<IPlatformSettings>();
			}
			if (featureType == typeof(IActivatableLifetime))
			{
				return AvaloniaLocator.Current.GetService<IActivatableLifetime>();
			}
			return null;
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == RequestedThemeVariantProperty)
			{
				ThemeVariant newValue = change.GetNewValue<ThemeVariant>();
				if ((object)newValue != null && newValue != ThemeVariant.Default)
				{
					SetValue(ActualThemeVariantProperty, newValue);
				}
				else
				{
					ClearValue(ActualThemeVariantProperty);
				}
			}
			else if (change.Property == ActualThemeVariantProperty)
			{
				this.ActualThemeVariantChanged?.Invoke(this, EventArgs.Empty);
			}
		}

		private void OnColorValuesChanged(object? sender, PlatformColorValues e)
		{
			SetValue(ActualThemeVariantProperty, (ThemeVariant)e.ThemeVariant, BindingPriority.Template);
		}
	}
	/// <summary>
	/// IClassicDesktopStyleApplicationLifetime related AppBuilder extensions.
	/// </summary>
	public static class ClassicDesktopStyleApplicationLifetimeExtensions
	{
		private static ClassicDesktopStyleApplicationLifetime PrepareLifetime(AppBuilder builder, string[] args, Action<IClassicDesktopStyleApplicationLifetime>? lifetimeBuilder)
		{
			ClassicDesktopStyleApplicationLifetime classicDesktopStyleApplicationLifetime = new ClassicDesktopStyleApplicationLifetime();
			classicDesktopStyleApplicationLifetime.SubscribeGlobalEvents();
			classicDesktopStyleApplicationLifetime.Args = args;
			lifetimeBuilder?.Invoke(classicDesktopStyleApplicationLifetime);
			return classicDesktopStyleApplicationLifetime;
		}

		/// <summary>
		/// Setups the Application with a IClassicDesktopStyleApplicationLifetime, but doesn't show the main window and doesn't run application main loop.
		/// </summary>
		/// <param name="builder">Application builder.</param>
		/// <param name="args">Startup arguments.</param>
		/// <param name="lifetimeBuilder">Lifetime builder to modify the lifetime before application started.</param>
		/// <returns>Exit code.</returns>
		public static AppBuilder SetupWithClassicDesktopLifetime(this AppBuilder builder, string[] args, Action<IClassicDesktopStyleApplicationLifetime>? lifetimeBuilder = null)
		{
			ClassicDesktopStyleApplicationLifetime classicDesktopStyleApplicationLifetime = PrepareLifetime(builder, args, lifetimeBuilder);
			classicDesktopStyleApplicationLifetime.SetupCore(args);
			return builder.SetupWithLifetime(classicDesktopStyleApplicationLifetime);
		}

		/// <summary>
		/// Starts the Application with a IClassicDesktopStyleApplicationLifetime, shows main window and runs application main loop.
		/// </summary>
		/// <param name="builder">Application builder.</param>
		/// <param name="args">Startup arguments.</param>
		/// <param name="lifetimeBuilder">Lifetime builder to modify the lifetime before application started.</param>
		/// <returns>Exit code.</returns>
		public static int StartWithClassicDesktopLifetime(this AppBuilder builder, string[] args, Action<IClassicDesktopStyleApplicationLifetime>? lifetimeBuilder = null)
		{
			ClassicDesktopStyleApplicationLifetime classicDesktopStyleApplicationLifetime = PrepareLifetime(builder, args, lifetimeBuilder);
			builder.SetupWithLifetime(classicDesktopStyleApplicationLifetime);
			return classicDesktopStyleApplicationLifetime.Start(args);
		}

		/// <summary>
		/// Starts the Application with a IClassicDesktopStyleApplicationLifetime, shows main window and runs application main loop.
		/// </summary>
		/// <param name="builder">Application builder.</param>
		/// <param name="args">Startup arguments.</param>
		/// <param name="shutdownMode">Lifetime shutdown mode.</param>
		/// <returns>Exit code.</returns>
		public static int StartWithClassicDesktopLifetime(this AppBuilder builder, string[] args, ShutdownMode shutdownMode)
		{
			ClassicDesktopStyleApplicationLifetime classicDesktopStyleApplicationLifetime = PrepareLifetime(builder, args, delegate(IClassicDesktopStyleApplicationLifetime l)
			{
				l.ShutdownMode = shutdownMode;
			});
			builder.SetupWithLifetime(classicDesktopStyleApplicationLifetime);
			return classicDesktopStyleApplicationLifetime.Start(args);
		}
	}
	public static class LoggingExtensions
	{
		/// <summary>
		/// Logs Avalonia events to the <see cref="T:System.Diagnostics.Trace" /> sink.
		/// </summary>
		/// <param name="builder">The app builder instance.</param>
		/// <param name="level">The minimum level to log.</param>
		/// <param name="areas">The areas to log. Valid values are listed in <see cref="T:Avalonia.Logging.LogArea" />.</param>
		/// <returns>The app builder instance.</returns>
		public static AppBuilder LogToTrace(this AppBuilder builder, LogEventLevel level = LogEventLevel.Warning, params string[] areas)
		{
			return builder.LogToDelegate(delegate(string s)
			{
				Trace.WriteLine(s);
			}, level, areas);
		}

		/// <summary>
		/// Logs Avalonia events to a TextWriter
		/// </summary>
		/// <param name="builder">The app builder instance.</param>
		/// <param name="writer">The TextWriter that's used for log events.</param>
		/// <param name="level">The minimum level to log.</param>
		/// <param name="areas">The areas to log. Valid values are listed in <see cref="T:Avalonia.Logging.LogArea" />.</param>
		/// <returns>The app builder instance.</returns>
		public static AppBuilder LogToTextWriter(this AppBuilder builder, TextWriter writer, LogEventLevel level = LogEventLevel.Warning, params string[] areas)
		{
			return builder.LogToDelegate(TextWriter.Synchronized(writer).WriteLine, level, areas);
		}

		/// <summary>
		/// Logs Avalonia events to a custom delegate
		/// </summary>
		/// <param name="builder">The app builder instance.</param>
		/// <param name="logCallback">The callback that's used for log events.</param>
		/// <param name="level">The minimum level to log.</param>
		/// <param name="areas">The areas to log. Valid values are listed in <see cref="T:Avalonia.Logging.LogArea" />.</param>
		/// <returns>The app builder instance.</returns>
		public static AppBuilder LogToDelegate(this AppBuilder builder, Action<string> logCallback, LogEventLevel level = LogEventLevel.Warning, params string[] areas)
		{
			Logger.Sink = new StringLogSink(logCallback, level, areas);
			return builder;
		}
	}
	public static class SystemFontAppBuilderExtension
	{
		public static AppBuilder WithSystemFontSource(this AppBuilder appBuilder, Uri fontSource)
		{
			return appBuilder.ConfigureFonts(delegate(FontManager fontManager)
			{
				if (fontManager.SystemFonts is SystemFontCollection systemFontCollection)
				{
					systemFontCollection.AddCustomFontSource(fontSource);
				}
			});
		}
	}
