	[PrivateApi]
	public abstract class ScreensBase<TKey, TScreen>(IEqualityComparer<TKey>? screenKeyComparer) : IScreenImpl where TKey : notnull where TScreen : PlatformScreen
	{
		private readonly Dictionary<TKey, TScreen> _allScreensByKey = ((<screenKeyComparer>P != null) ? new Dictionary<TKey, TScreen>(<screenKeyComparer>P) : new Dictionary<TKey, TScreen>());

		private IReadOnlyList<TScreen>? _allScreens;

		private int? _screenCount;

		private bool? _screenDetailsRequestGranted;

		private DispatcherOperation? _onChangeOperation;

		public int ScreenCount
		{
			get
			{
				int valueOrDefault = _screenCount.GetValueOrDefault();
				if (!_screenCount.HasValue)
				{
					valueOrDefault = GetScreenCount();
					_screenCount = valueOrDefault;
					return valueOrDefault;
				}
				return valueOrDefault;
			}
		}

		public IReadOnlyList<Screen> AllScreens
		{
			get
			{
				EnsureScreens();
				return _allScreens;
			}
		}

		public Action? Changed { get; set; }

		protected ScreensBase()
			: this((IEqualityComparer<TKey>?)null)
		{
		}

		public Screen? ScreenFromWindow(IWindowBaseImpl window)
		{
			return ScreenFromTopLevel(window);
		}

		public Screen? ScreenFromTopLevel(ITopLevelImpl topLevel)
		{
			return ScreenFromTopLevelCore(topLevel);
		}

		public Screen? ScreenFromPoint(PixelPoint point)
		{
			return ScreenFromPointCore(point);
		}

		public Screen? ScreenFromRect(PixelRect rect)
		{
			return ScreenFromRectCore(rect);
		}

		public void OnChanged()
		{
			_screenCount = null;
			_allScreens = null;
			_onChangeOperation?.Abort();
			_onChangeOperation = Dispatcher.UIThread.InvokeAsync(delegate
			{
				if (Changed != null || _allScreensByKey.Count > 0)
				{
					EnsureScreens();
					Changed?.Invoke();
				}
			}, DispatcherPriority.Input);
		}

		public async Task<bool> RequestScreenDetails()
		{
			_ = _screenDetailsRequestGranted == true;
			if (!_screenDetailsRequestGranted.HasValue)
			{
				_screenDetailsRequestGranted = await RequestScreenDetailsCore();
			}
			return _screenDetailsRequestGranted.Value;
		}

		protected bool TryGetScreen(TKey key, [MaybeNullWhen(false)] out TScreen screen)
		{
			EnsureScreens();
			return _allScreensByKey.TryGetValue(key, out screen);
		}

		protected virtual void ScreenAdded(TScreen screen)
		{
			ScreenChanged(screen);
		}

		protected virtual void ScreenChanged(TScreen screen)
		{
		}

		protected virtual void ScreenRemoved(TScreen screen)
		{
			screen.OnRemoved();
		}

		protected virtual int GetScreenCount()
		{
			return AllScreens.Count;
		}

		protected abstract IReadOnlyList<TKey> GetAllScreenKeys();

		protected abstract TScreen CreateScreenFromKey(TKey key);

		protected virtual Task<bool> RequestScreenDetailsCore()
		{
			return Task.FromResult(result: true);
		}

		protected virtual Screen? ScreenFromTopLevelCore(ITopLevelImpl topLevel)
		{
			if (topLevel is IWindowImpl window)
			{
				return ScreenHelper.ScreenFromWindow(window, AllScreens);
			}
			return null;
		}

		protected virtual Screen? ScreenFromPointCore(PixelPoint point)
		{
			return ScreenHelper.ScreenFromPoint(point, AllScreens);
		}

		protected virtual Screen? ScreenFromRectCore(PixelRect rect)
		{
			return ScreenHelper.ScreenFromRect(rect, AllScreens);
		}

		[MemberNotNull("_allScreens")]
		private void EnsureScreens()
		{
			if (_allScreens != null)
			{
				return;
			}
			Dispatcher.UIThread.VerifyAccess();
			IReadOnlyList<TKey> allScreenKeys = GetAllScreenKeys();
			HashSet<TKey> hashSet = new HashSet<TKey>(allScreenKeys, <screenKeyComparer>P);
			foreach (TKey key in _allScreensByKey.Keys)
			{
				if (!hashSet.Contains(key) && _allScreensByKey.TryGetValue(key, out var value) && _allScreensByKey.Remove(key))
				{
					ScreenRemoved(value);
				}
			}
			List<TScreen> list = new List<TScreen>(allScreenKeys.Count);
			foreach (TKey item in allScreenKeys)
			{
				if (_allScreensByKey.TryGetValue(item, out var value2))
				{
					ScreenChanged(value2);
					list.Add(value2);
					continue;
				}
				TScreen val = CreateScreenFromKey(item);
				ScreenAdded(val);
				_allScreensByKey[item] = val;
				list.Add(val);
			}
			_allScreens = list;
		}
	}
