		/// Multiply this value by 100 to get a percentage.
		/// Both X and Y scaling factors are assumed uniform.
		/// </remarks>
		public double Scaling { get; protected set; } = 1.0;

		/// <inheritdoc cref="P:Avalonia.Platform.Screen.Scaling" />
		[Obsolete("Use the Scaling property instead.", true)]
		[EditorBrowsable(EditorBrowsableState.Never)]
		public double PixelDensity => Scaling;

		/// <summary>
		/// Gets the overall pixel-size and position of the screen.
		/// </summary>
		/// <remarks>
		/// This generally is the raw pixel counts in both the X and Y direction.
		/// </remarks>
		public PixelRect Bounds { get; protected set; }

		/// <summary>
		/// Gets the actual working-area pixel-size of the screen.
		/// </summary>
		/// <remarks>
		/// This area may be smaller than <see href="Bounds" /> to account for notches and
		/// other block-out areas such as taskbars etc.
		/// </remarks>
		public PixelRect WorkingArea { get; protected set; }

		/// <summary>
		/// Gets a value indicating whether the screen is the primary one.
		/// </summary>
		public bool IsPrimary { get; protected set; }

		/// <inheritdoc cref="P:Avalonia.Platform.Screen.IsPrimary" />
		[Obsolete("Use the IsPrimary property instead.", true)]
		[EditorBrowsable(EditorBrowsableState.Never)]
		public bool Primary => IsPrimary;

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Platform.Screen" /> class.
		/// </summary>
		/// <param name="scaling">The scaling factor applied to the screen by the operating system.</param>
		/// <param name="bounds">The overall pixel-size of the screen.</param>
		/// <param name="workingArea">The actual working-area pixel-size of the screen.</param>
		/// <param name="isPrimary">Whether the screen is the primary one.</param>
		[Unstable("This API may be removed in Avalonia 12. If you depend on this API, please open an issue with details of your use-case.")]
		public Screen(double scaling, PixelRect bounds, PixelRect workingArea, bool isPrimary)
		{
			Scaling = scaling;
			Bounds = bounds;
			WorkingArea = workingArea;
			IsPrimary = isPrimary;
		}

		private protected Screen()
		{
		}

		/// <summary>
		/// Tries to get the platform handle for the Screen.
		/// </summary>
		/// <returns>
		/// An <see cref="T:Avalonia.Platform.IPlatformHandle" /> describing the screen handle, or null if the handle
		/// could not be retrieved.
		/// </returns>
		public virtual IPlatformHandle? TryGetPlatformHandle()
		{
			return null;
		}

		/// <inheritdoc />
		public override int GetHashCode()
		{
			return RuntimeHelpers.GetHashCode(this);
		}

		/// <inheritdoc />
		public override bool Equals(object? obj)
		{
			if (obj is Screen other)
			{
				return Equals(other);
			}
			return false;
		}

		/// <inheritdoc />
		public virtual bool Equals(Screen? other)
		{
			return (object)this == other;
		}

		public static bool operator ==(Screen? left, Screen? right)
		{
			return object.Equals(left, right);
		}

		public static bool operator !=(Screen? left, Screen? right)
		{
			return !object.Equals(left, right);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			StringBuilder stringBuilder = StringBuilderCache.Acquire();
			stringBuilder.Append("Screen");
			stringBuilder.Append(" { ");
			stringBuilder.AppendFormat("{0} = {1}", "DisplayName", DisplayName);
			IPlatformHandle platformHandle = TryGetPlatformHandle();
			if (platformHandle != null)
			{
				stringBuilder.AppendFormat(", {0}: {1}", platformHandle.HandleDescriptor, platformHandle.Handle);
			}
			stringBuilder.Append(" } ");
			return StringBuilderCache.GetStringAndRelease(stringBuilder);
		}

		/// <summary>
		/// When screen is removed, we should at least empty all the properties. 
		/// </summary>
		internal void OnRemoved()
		{
			DisplayName = null;
			PixelRect bounds = (WorkingArea = default(PixelRect));
			Bounds = bounds;
			Scaling = 0.0;
			CurrentOrientation = ScreenOrientation.None;
		}
	}
	internal static class ScreenHelper
	{
		public static Screen? ScreenFromPoint(PixelPoint point, IReadOnlyList<Screen> screens)
		{
			foreach (Screen screen in screens)
			{
				if (screen.Bounds.ContainsExclusive(point))
				{
					return screen;
				}
			}
			return null;
		}

		public static Screen? ScreenFromRect(PixelRect bounds, IReadOnlyList<Screen> screens)
		{
			Screen result = null;
			double num = 0.0;
			foreach (Screen screen in screens)
			{
				double num2 = MathUtilities.Clamp(bounds.X, screen.Bounds.X, screen.Bounds.X + screen.Bounds.Width);
				double num3 = MathUtilities.Clamp(bounds.Y, screen.Bounds.Y, screen.Bounds.Y + screen.Bounds.Height);
				double num4 = MathUtilities.Clamp(bounds.X + bounds.Width, screen.Bounds.X, screen.Bounds.X + screen.Bounds.Width);
				double num5 = MathUtilities.Clamp(bounds.Y + bounds.Height, screen.Bounds.Y, screen.Bounds.Y + screen.Bounds.Height);
				double num6 = (num4 - num2) * (num5 - num3);
				if (num6 > num)
				{
					num = num6;
					result = screen;
				}
			}
			return result;
		}

		public static Screen? ScreenFromWindow(IWindowBaseImpl window, IReadOnlyList<Screen> screens)
		{
			return ScreenFromRect(new PixelRect(window.Position, PixelSize.FromSize(window.FrameSize ?? window.ClientSize, window.DesktopScaling)), screens);
		}
	}
