			AutomationPeer parent = automationPeer.GetParent();
			while (automationPeer.GetProvider<IRootProvider>() == null && parent != null)
			{
				automationPeer = parent;
				parent = automationPeer.GetParent();
			}
			return automationPeer;
		}

