	/// <summary>
	/// An automation peer which represents a <see cref="T:Avalonia.Controls.Control" /> element.
	/// </summary>
	public class ControlAutomationPeer : AutomationPeer
	{
		private IReadOnlyList<AutomationPeer>? _children;

		private bool _childrenValid;

		private AutomationPeer? _parent;

		private bool _parentValid;

		public Control Owner { get; }

		public ControlAutomationPeer(Control owner)
		{
			Owner = owner ?? throw new ArgumentNullException("owner");
			Initialize();
		}

		public AutomationPeer GetOrCreate(Control element)
		{
			if (element == Owner)
			{
				return this;
			}
			return CreatePeerForElement(element);
		}

		/// <summary>
		/// Gets the <see cref="T:Avalonia.Automation.Peers.AutomationPeer" /> for a <see cref="T:Avalonia.Controls.Control" />, creating it if
		/// necessary.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The automation peer.</returns>
		/// <remarks>
		/// Despite the name (which comes from the analogous WPF API), this method does not create
		/// a new peer if one already exists: instead it returns the existing peer.
		/// </remarks>
		public static AutomationPeer CreatePeerForElement(Control element)
		{
			return element.GetOrCreateAutomationPeer();
		}

		/// <summary>
		/// Gets an existing <see cref="T:Avalonia.Automation.Peers.AutomationPeer" /> for a <see cref="T:Avalonia.Controls.Control" />.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The automation peer if already created; otherwise null.</returns>
		/// <remarks>
		/// To ensure that a peer is created, use <see cref="M:Avalonia.Automation.Peers.ControlAutomationPeer.CreatePeerForElement(Avalonia.Controls.Control)" />.
		/// </remarks>
		public static AutomationPeer? FromElement(Control element)
		{
			return element.GetAutomationPeer();
		}

		protected override void BringIntoViewCore()
		{
			Owner.BringIntoView();
		}

		protected override IReadOnlyList<AutomationPeer> GetOrCreateChildrenCore()
		{
			IReadOnlyList<AutomationPeer> readOnlyList = _children ?? Array.Empty<AutomationPeer>();
			if (_childrenValid)
			{
				return readOnlyList;
			}
			IReadOnlyList<AutomationPeer> readOnlyList2 = GetChildrenCore() ?? Array.Empty<AutomationPeer>();
			foreach (AutomationPeer item in readOnlyList.Except(readOnlyList2))
			{
				item.TrySetParent(null);
			}
			foreach (AutomationPeer item2 in readOnlyList2)
			{
				item2.TrySetParent(this);
			}
			_childrenValid = true;
			return _children = readOnlyList2;
		}

		protected virtual IReadOnlyList<AutomationPeer>? GetChildrenCore()
		{
			IAvaloniaList<Visual> visualChildren = Owner.VisualChildren;
			if (visualChildren.Count == 0)
			{
				return null;
			}
			List<AutomationPeer> list = new List<AutomationPeer>();
			foreach (Visual item in visualChildren)
			{
				if (item is Control control)
				{
					AutomationPeer orCreate = GetOrCreate(control);
					if (control.IsVisible)
					{
						list.Add(orCreate);
					}
				}
			}
			return list;
		}

		protected override AutomationPeer? GetLabeledByCore()
		{
			Control labeledBy = AutomationProperties.GetLabeledBy(Owner);
			if (labeledBy != null)
			{
				Control element = labeledBy;
				return GetOrCreate(element);
			}
			return null;
		}

		protected override string? GetNameCore()
		{
			string name = AutomationProperties.GetName(Owner);
			if (string.IsNullOrWhiteSpace(name))
			{
				AutomationPeer labeledBy = GetLabeledBy();
				if (labeledBy != null)
				{
					name = labeledBy.GetName();
				}
			}
			return name;
		}

		protected override string? GetHelpTextCore()
		{
			string text = AutomationProperties.GetHelpText(Owner);
			if (string.IsNullOrWhiteSpace(text))
			{
				IEnumerable<string> enumerable = DataValidationErrors.GetErrors(Owner)?.Select((object x) => x.ToString());
				text = ((enumerable != null) ? string.Join(Environment.NewLine, enumerable.ToArray()) : null);
			}
			if (string.IsNullOrWhiteSpace(text))
			{
				text = ToolTip.GetTip(Owner) as string;
			}
			if (string.IsNullOrWhiteSpace(text))
			{
				text = GetPlaceholderTextCore();
			}
			return text;
		}

		protected override AutomationLandmarkType? GetLandmarkTypeCore()
		{
			return AutomationProperties.GetLandmarkType(Owner);
		}

		protected override int GetHeadingLevelCore()
		{
			return AutomationProperties.GetHeadingLevel(Owner);
		}

