	public class ToggleButtonAutomationPeer : ContentControlAutomationPeer, IToggleProvider
	{
		public new ToggleButton Owner => (ToggleButton)base.Owner;

		ToggleState IToggleProvider.ToggleState => ToState(Owner.IsChecked);

		public ToggleButtonAutomationPeer(ToggleButton owner)
			: base(owner)
		{
			Owner.PropertyChanged += delegate(object? a, AvaloniaPropertyChangedEventArgs e)
			{
				if (e.Property == ToggleButton.IsCheckedProperty)
				{
					RaisePropertyChangedEvent(TogglePatternIdentifiers.ToggleStateProperty, ToState((bool?)e.OldValue), ToState((bool?)e.NewValue));
				}
			};
		}

		private ToggleState ToState(bool? value)
		{
			if (value.HasValue)
			{
				if (value == true)
				{
					return ToggleState.On;
				}
				return ToggleState.Off;
			}
			return ToggleState.Indeterminate;
		}

		void IToggleProvider.Toggle()
		{
			EnsureEnabled();
			Owner.PerformClick();
		}

