			}

			/// <summary>
			/// Check if the string values are equal.
			/// </summary>
			/// <param name="text">The AutoCompleteBox prefix text.</param>
			/// <param name="value">The item's string value.</param>
			/// <returns>Returns true if the condition is met.</returns>
