		/// <see cref="T:Avalonia.Controls.AutoCompleteBox" /> control has
		/// focus.
		/// </summary>
		/// <returns>true to indicate the
		/// <see cref="T:Avalonia.Controls.AutoCompleteBox" /> has focus;
		/// otherwise, false.</returns>
		protected bool HasFocus()
		{
			return base.IsKeyboardFocusWithin;
		}

		/// <summary>
		/// Handles the FocusChanged event.
		/// </summary>
		/// <param name="hasFocus">A value indicating whether the control
		/// currently has the focus.</param>
		private void FocusChanged(bool hasFocus)
		{
			bool isFocused = _isFocused;
			_isFocused = hasFocus;
			if (hasFocus)
			{
				if (!isFocused && TextBox != null && TextBoxSelectionLength <= 0)
				{
					TextBox.Focus();
					TextBox.SelectAll();
				}
			}
			else
			{
				IFocusScope focusScope = GetFocusScope();
				if (focusScope != null)
				{
					IInputElement inputElement = FocusManager.GetFocusManager(this)?.GetFocusedElement(focusScope);
					if (inputElement == null || (inputElement != this && inputElement is Visual target && !this.IsVisualAncestorOf(target)))
					{
						SetCurrentValue(IsDropDownOpenProperty, value: false);
					}
				}
				_userCalledPopulate = false;
				TextBox? textBox = TextBox;
				int num;
				if (textBox == null || textBox.ContextFlyout?.IsOpen != true)
				{
					TextBox? textBox2 = TextBox;
					num = ((textBox2 != null && textBox2.ContextMenu?.IsOpen == true) ? 1 : 0);
				}
				else
				{
					num = 1;
				}
				FlyoutBase? contextFlyout = base.ContextFlyout;
				bool flag = (contextFlyout != null && contextFlyout.IsOpen) || (base.ContextMenu?.IsOpen ?? false);
				if (num == 0 && !flag && ClearSelectionOnLostFocus)
				{
					ClearTextBoxSelection();
				}
			}
			_isFocused = hasFocus;
			IFocusScope? GetFocusScope()
			{
				for (IInputElement inputElement2 = this; inputElement2 != null; inputElement2 = (inputElement2 as Visual)?.GetVisualParent<IInputElement>() ?? ((inputElement2 as IHostedVisualTreeRoot)?.Host as IInputElement))
				{
					if (inputElement2 is IFocusScope result && inputElement2 is Visual { VisualRoot: Visual { IsVisible: not false } })
					{
						return result;
					}
				}
				return null;
			}
		}

