			}
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
			switch (e.Key)
			{
			case Key.Return:
				OnClick();
				e.Handled = true;
				break;
			case Key.Space:
				if (base.IsFocused)
				{
					if (ClickMode == ClickMode.Press)
					{
						OnClick();
					}
					IsPressed = true;
					e.Handled = true;
				}
				break;
			case Key.Escape:
				if (Flyout != null)
				{
					CloseFlyout();
				}
				break;
			}
			base.OnKeyDown(e);
		}

		/// <inheritdoc />
		protected override void OnKeyUp(KeyEventArgs e)
		{
			if (e.Key == Key.Space && base.IsFocused)
			{
				if (ClickMode == ClickMode.Release)
				{
					OnClick();
				}
				IsPressed = false;
				e.Handled = true;
			}
			base.OnKeyUp(e);
		}

