				{
					CloseFlyout();
				}
				else
				{
					OpenFlyout();
				}
				RoutedEventArgs e = new RoutedEventArgs(ClickEvent);
				RaiseEvent(e);
				ICommand? command = Command;
				object commandParameter = CommandParameter;
				ICommand command2 = command;
				if (!e.Handled && command2 != null && command2.CanExecute(commandParameter))
				{
					command2.Execute(commandParameter);
					e.Handled = true;
				}
			}
		}

