			}
			if (_isFlyoutOpen && base.IsEffectivelyEnabled)
			{
				e.Handled = true;
				OnClick();
				return;
			}
			IsPressed = true;
			e.Handled = true;
			if (ClickMode == ClickMode.Press)
			{
				OnClick();
			}
		}

		/// <inheritdoc />
