						command3.CanExecuteChanged -= CanExecuteChangedHandler;
					}
					if (command2 != null)
					{
						ICommand command4 = command2;
						command4.CanExecuteChanged += CanExecuteChangedHandler;
					}
				}
				CanExecuteChanged(command2, CommandParameter);
			}
			else if (change.Property == CommandParameterProperty)
			{
