				if (base.VisualRoot is IInputElement root2)
				{
					if (newValue2)
					{
						ListenForDefault(root2);
					}
					else
					{
						StopListeningForDefault(root2);
					}
				}
			}
			else if (change.Property == IsPressedProperty)
			{
				UpdatePseudoClasses();
			}
			else if (change.Property == FlyoutProperty)
			{
				var (flyoutBase, flyout) = change.GetOldAndNewValue<FlyoutBase>();
				if (flyoutBase != null && flyoutBase.IsOpen)
				{
					flyoutBase.Hide();
				}
				UnregisterFlyoutEvents(flyoutBase);
				RegisterFlyoutEvents(flyout);
				UpdatePseudoClasses();
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new ButtonAutomationPeer(this);
		}

		/// <inheritdoc />
		protected override void UpdateDataValidation(AvaloniaProperty property, BindingValueType state, Exception? error)
		{
			base.UpdateDataValidation(property, state, error);
			if (property == CommandProperty && state == BindingValueType.BindingError && _commandCanExecute)
			{
				_commandCanExecute = false;
				UpdateIsEffectivelyEnabled();
			}
		}

		internal void PerformClick()
		{
			OnClick();
		}

		private static void OnAccessKeyPressed(Button sender, AccessKeyPressedEventArgs e)
		{
			if (!e.Handled && e.Target == null)
			{
				e.Target = sender;
				e.Handled = true;
			}
		}

		/// <summary>
		/// Called when the <see cref="E:System.Windows.Input.ICommand.CanExecuteChanged" /> event fires.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void CanExecuteChanged(object? sender, EventArgs e)
		{
			CanExecuteChanged(Command, CommandParameter);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void CanExecuteChanged(ICommand? command, object? parameter)
		{
			if (((ILogical)this).IsAttachedToLogicalTree)
			{
				bool flag = command?.CanExecute(parameter) ?? true;
				if (flag != _commandCanExecute)
				{
					_commandCanExecute = flag;
					UpdateIsEffectivelyEnabled();
				}
			}
		}

		/// <summary>
		/// Registers all flyout events.
		/// </summary>
		/// <param name="flyout">The flyout to connect events to.</param>
		private void RegisterFlyoutEvents(FlyoutBase? flyout)
		{
			if (flyout != null)
			{
				flyout.Opened += Flyout_Opened;
				flyout.Closed += Flyout_Closed;
			}
		}

		/// <summary>
		/// Explicitly unregisters all flyout events.
		/// </summary>
		/// <param name="flyout">The flyout to disconnect events from.</param>
		private void UnregisterFlyoutEvents(FlyoutBase? flyout)
		{
			if (flyout != null)
			{
				flyout.Opened -= Flyout_Opened;
				flyout.Closed -= Flyout_Closed;
			}
		}

		/// <summary>
		/// Starts listening for the Enter key when the button <see cref="P:Avalonia.Controls.Button.IsDefault" />.
		/// </summary>
		/// <param name="root">The input root.</param>
		private void ListenForDefault(IInputElement root)
		{
			root.AddHandler(InputElement.KeyDownEvent, new Action<object, KeyEventArgs>(RootDefaultKeyDown));
		}

		/// <summary>
		/// Starts listening for the Escape key when the button <see cref="P:Avalonia.Controls.Button.IsCancel" />.
		/// </summary>
		/// <param name="root">The input root.</param>
		private void ListenForCancel(IInputElement root)
		{
			root.AddHandler(InputElement.KeyDownEvent, new Action<object, KeyEventArgs>(RootCancelKeyDown));
		}

		/// <summary>
		/// Stops listening for the Enter key when the button is no longer <see cref="P:Avalonia.Controls.Button.IsDefault" />.
		/// </summary>
		/// <param name="root">The input root.</param>
		private void StopListeningForDefault(IInputElement root)
		{
			root.RemoveHandler(InputElement.KeyDownEvent, new Action<object, KeyEventArgs>(RootDefaultKeyDown));
		}

		/// <summary>
		/// Stops listening for the Escape key when the button is no longer <see cref="P:Avalonia.Controls.Button.IsCancel" />.
		/// </summary>
		/// <param name="root">The input root.</param>
		private void StopListeningForCancel(IInputElement root)
		{
			root.RemoveHandler(InputElement.KeyDownEvent, new Action<object, KeyEventArgs>(RootCancelKeyDown));
		}

		/// <summary>
		/// Called when a key is pressed on the input root and the button <see cref="P:Avalonia.Controls.Button.IsDefault" />.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void RootDefaultKeyDown(object? sender, KeyEventArgs e)
		{
			if (e.Key == Key.Return && base.IsEffectivelyVisible && base.IsEffectivelyEnabled)
			{
				OnClick();
				e.Handled = true;
			}
		}

		/// <summary>
		/// Called when a key is pressed on the input root and the button <see cref="P:Avalonia.Controls.Button.IsCancel" />.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void RootCancelKeyDown(object? sender, KeyEventArgs e)
		{
			if (e.Key == Key.Escape && base.IsEffectivelyVisible && base.IsEffectivelyEnabled)
			{
				OnClick();
				e.Handled = true;
			}
		}

		/// <summary>
		/// Updates the visual state of the control by applying latest PseudoClasses.
		/// </summary>
		private void UpdatePseudoClasses()
		{
			base.PseudoClasses.Set(":flyout-open", _isFlyoutOpen);
			base.PseudoClasses.Set(":pressed", IsPressed);
		}

		void ICommandSource.CanExecuteChanged(object sender, EventArgs e)
		{
			CanExecuteChanged(sender, e);
		}

		void IClickableControl.RaiseClick()
		{
			OnClick();
		}

		/// <summary>
		/// Event handler for when the button's flyout is opened.
		/// </summary>
		private void Flyout_Opened(object? sender, EventArgs e)
		{
			if ((sender as FlyoutBase)?.Target == this)
			{
				_isFlyoutOpen = true;
				UpdatePseudoClasses();
				OnFlyoutOpened();
			}
		}

		/// <summary>
		/// Event handler for when the button's flyout is closed.
		/// </summary>
		private void Flyout_Closed(object? sender, EventArgs e)
		{
			if ((sender as FlyoutBase)?.Target == this)
			{
				_isFlyoutOpen = false;
				UpdatePseudoClasses();
				OnFlyoutClosed();
			}
		}
	}
	public enum Location
	{
		Left,
		Right
	}
	/// <summary>
	/// Represents a spinner control that includes two Buttons.
	/// </summary>
	[TemplatePart("PART_DecreaseButton", typeof(Button))]
	[TemplatePart("PART_IncreaseButton", typeof(Button))]
	[PseudoClasses(new string[] { ":left", ":right" })]
	public class ButtonSpinner : Spinner
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ButtonSpinner.AllowSpin" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> AllowSpinProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ButtonSpinner.ShowButtonSpinner" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> ShowButtonSpinnerProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ButtonSpinner.ButtonSpinnerLocation" /> property.
		/// </summary>
		public static readonly StyledProperty<Location> ButtonSpinnerLocationProperty;

		private Button? _decreaseButton;

		private Button? _increaseButton;

		/// <summary>
		/// Gets or sets the DecreaseButton template part.
		/// </summary>
		private Button? DecreaseButton
		{
			get
			{
				return _decreaseButton;
			}
			set
			{
				if (_decreaseButton != null)
				{
					_decreaseButton.Click -= OnButtonClick;
				}
				_decreaseButton = value;
				if (_decreaseButton != null)
				{
					_decreaseButton.Click += OnButtonClick;
				}
			}
		}

		/// <summary>
		/// Gets or sets the IncreaseButton template part.
		/// </summary>
		private Button? IncreaseButton
		{
			get
			{
				return _increaseButton;
			}
			set
			{
				if (_increaseButton != null)
				{
					_increaseButton.Click -= OnButtonClick;
				}
				_increaseButton = value;
				if (_increaseButton != null)
				{
					_increaseButton.Click += OnButtonClick;
				}
			}
		}

		/// <summary>
		/// Gets or sets a value indicating whether the <see cref="T:Avalonia.Controls.ButtonSpinner" /> should allow to spin.
		/// </summary>
		public bool AllowSpin
		{
			get
			{
				return GetValue(AllowSpinProperty);
			}
			set
			{
				SetValue(AllowSpinProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets a value indicating whether the spin buttons should be shown.
		/// </summary>
		public bool ShowButtonSpinner
		{
			get
			{
				return GetValue(ShowButtonSpinnerProperty);
			}
			set
			{
				SetValue(ShowButtonSpinnerProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets current location of the <see cref="T:Avalonia.Controls.ButtonSpinner" />.
		/// </summary>
		public Location ButtonSpinnerLocation
		{
			get
			{
				return GetValue(ButtonSpinnerLocationProperty);
			}
			set
			{
				SetValue(ButtonSpinnerLocationProperty, value);
			}
		}

		public ButtonSpinner()
		{
			UpdatePseudoClasses(ButtonSpinnerLocation);
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.ButtonSpinner" /> class.
		/// </summary>
		static ButtonSpinner()
		{
			AllowSpinProperty = AvaloniaProperty.Register<ButtonSpinner, bool>("AllowSpin", defaultValue: true);
			ShowButtonSpinnerProperty = AvaloniaProperty.Register<ButtonSpinner, bool>("ShowButtonSpinner", defaultValue: true);
			ButtonSpinnerLocationProperty = AvaloniaProperty.Register<ButtonSpinner, Location>("ButtonSpinnerLocation", Location.Right);
			AllowSpinProperty.Changed.Subscribe(AllowSpinChanged);
		}

		/// <inheritdoc />
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			IncreaseButton = e.NameScope.Find<Button>("PART_IncreaseButton");
			DecreaseButton = e.NameScope.Find<Button>("PART_DecreaseButton");
			SetButtonUsage();
		}

		/// <inheritdoc />
		protected override void OnPointerReleased(PointerReleasedEventArgs e)
		{
			base.OnPointerReleased(e);
			if (IncreaseButton != null && !IncreaseButton.IsEnabled)
			{
				Point position = e.GetPosition(IncreaseButton);
				if (position.X > 0.0 && position.X < IncreaseButton.Width && position.Y > 0.0 && position.Y < IncreaseButton.Height)
				{
					e.Handled = true;
				}
			}
			if (DecreaseButton != null && !DecreaseButton.IsEnabled)
			{
				Point position = e.GetPosition(DecreaseButton);
				if (position.X > 0.0 && position.X < DecreaseButton.Width && position.Y > 0.0 && position.Y < DecreaseButton.Height)
				{
					e.Handled = true;
				}
			}
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
			if (this.IsAllowedXYNavigationMode(e.KeyDeviceType))
			{
				return;
			}
			switch (e.Key)
			{
			case Key.Up:
				if (AllowSpin)
				{
					OnSpin(new SpinEventArgs(Spinner.SpinEvent, SpinDirection.Increase));
					e.Handled = true;
				}
				break;
			case Key.Down:
				if (AllowSpin)
				{
					OnSpin(new SpinEventArgs(Spinner.SpinEvent, SpinDirection.Decrease));
					e.Handled = true;
				}
				break;
			case Key.Return:
				if ((IncreaseButton != null && IncreaseButton.IsFocused) || (DecreaseButton != null && DecreaseButton.IsFocused))
				{
					e.Handled = true;
				}
				break;
			}
		}

		/// <inheritdoc />
		protected override void OnPointerWheelChanged(PointerWheelEventArgs e)
		{
			base.OnPointerWheelChanged(e);
			if (AllowSpin && base.IsKeyboardFocusWithin && e.Delta.Y != 0.0)
			{
				SpinEventArgs e2 = new SpinEventArgs(Spinner.SpinEvent, (e.Delta.Y < 0.0) ? SpinDirection.Decrease : SpinDirection.Increase, usingMouseWheel: true);
				OnSpin(e2);
				e.Handled = true;
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == ButtonSpinnerLocationProperty)
			{
				UpdatePseudoClasses(change.GetNewValue<Location>());
			}
		}

		protected override void OnValidSpinDirectionChanged(ValidSpinDirections oldValue, ValidSpinDirections newValue)
		{
			SetButtonUsage();
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.ButtonSpinner.AllowSpin" /> property value changed.
		/// </summary>
		/// <param name="oldValue">The old value.</param>
		/// <param name="newValue">The new value.</param>
		protected virtual void OnAllowSpinChanged(bool oldValue, bool newValue)
		{
			SetButtonUsage();
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.ButtonSpinner.AllowSpin" /> property value changed.
		/// </summary>
		/// <param name="e">The event args.</param>
		private static void AllowSpinChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Sender is ButtonSpinner buttonSpinner)
			{
				bool oldValue = (bool)e.OldValue;
				bool newValue = (bool)e.NewValue;
				buttonSpinner.OnAllowSpinChanged(oldValue, newValue);
			}
		}

		/// <summary>
		/// Disables or enables the buttons based on the valid spin direction.
		/// </summary>
		private void SetButtonUsage()
		{
			if (IncreaseButton != null)
			{
				IncreaseButton.IsEnabled = AllowSpin && (base.ValidSpinDirection & ValidSpinDirections.Increase) == ValidSpinDirections.Increase;
			}
			if (DecreaseButton != null)
			{
				DecreaseButton.IsEnabled = AllowSpin && (base.ValidSpinDirection & ValidSpinDirections.Decrease) == ValidSpinDirections.Decrease;
			}
		}

		/// <summary>
		/// Called when user clicks one of the spin buttons.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void OnButtonClick(object? sender, RoutedEventArgs e)
		{
			if (AllowSpin)
			{
				SpinDirection direction = ((sender != IncreaseButton) ? SpinDirection.Decrease : SpinDirection.Increase);
				OnSpin(new SpinEventArgs(Spinner.SpinEvent, direction));
			}
		}

		private void UpdatePseudoClasses(Location location)
		{
			base.PseudoClasses.Set(":left", location == Location.Left);
			base.PseudoClasses.Set(":right", location == Location.Right);
		}
	}
