		internal void OnHeaderClick()
		{
			CalendarItem monthControl = MonthControl;
			if (monthControl != null && monthControl.MonthView != null && monthControl.YearView != null)
			{
				monthControl.MonthView.IsVisible = false;
				monthControl.YearView.IsVisible = true;
				UpdateMonths();
			}
		}

		internal void ResetStates()
		{
			CalendarItem monthControl = MonthControl;
			int num = 49;
			if (monthControl != null && monthControl.MonthView != null)
			{
				for (int i = 7; i < num; i++)
				{
					((CalendarDayButton)monthControl.MonthView.Children[i]).IgnoreMouseOverState();
				}
			}
		}

		internal void UpdateMonths()
		{
			CalendarItem monthControl = MonthControl;
			if (monthControl != null)
			{
				switch (DisplayMode)
				{
				case CalendarMode.Month:
					monthControl.UpdateMonthMode();
					break;
				case CalendarMode.Year:
					monthControl.UpdateYearMode();
					break;
				case CalendarMode.Decade:
					monthControl.UpdateDecadeMode();
					break;
				}
			}
		}

		internal static bool IsValidDateSelection(Calendar cal, DateTime? value)
		{
			if (!value.HasValue)
			{
				return true;
			}
			if (cal.BlackoutDates.Contains(value.Value))
			{
				return false;
			}
			cal._displayDateIsChanging = true;
			if (DateTime.Compare(value.Value, cal.DisplayDateRangeStart) < 0)
			{
				cal.DisplayDateStart = value;
			}
			else if (DateTime.Compare(value.Value, cal.DisplayDateRangeEnd) > 0)
			{
				cal.DisplayDateEnd = value;
			}
			cal._displayDateIsChanging = false;
			return true;
		}

		private static bool IsValidKeyboardSelection(Calendar cal, DateTime? value)
		{
			if (!value.HasValue)
			{
				return true;
			}
			if (cal.BlackoutDates.Contains(value.Value))
			{
				return false;
			}
			if (DateTime.Compare(value.Value, cal.DisplayDateRangeStart) >= 0)
			{
				return DateTime.Compare(value.Value, cal.DisplayDateRangeEnd) <= 0;
			}
			return false;
		}

		/// <summary>
		/// This method highlights the days in MultiSelection mode without
		/// adding them to the SelectedDates collection.
		/// </summary>
		internal void HighlightDays()
		{
			if (!HoverEnd.HasValue || !HoverStart.HasValue)
			{
				return;
			}
			CalendarItem monthControl = MonthControl;
			if (!HoverEndIndex.HasValue || !HoverStartIndex.HasValue)
			{
				return;
			}
			SortHoverIndexes(out var startIndex, out var endIndex);
			for (int i = startIndex; i <= endIndex; i++)
			{
				if (!(monthControl.MonthView.Children[i] is CalendarDayButton calendarDayButton))
				{
					continue;
				}
				calendarDayButton.IsSelected = true;
				DateTime? dateTime = calendarDayButton.DataContext as DateTime?;
				if (dateTime.HasValue && DateTimeHelper.CompareDays(HoverEnd.Value, dateTime.Value) == 0)
				{
					if (FocusButton != null)
					{
						FocusButton.IsCurrent = false;
					}
					calendarDayButton.IsCurrent = HasFocusInternal;
					FocusButton = calendarDayButton;
				}
			}
		}

		/// <summary>
		/// This method un-highlights the days that were hovered over but not
		/// added to the SelectedDates collection or un-highlighted the
		/// previously selected days in SingleRange Mode.
		/// </summary>
		internal void UnHighlightDays()
		{
			if (!HoverEnd.HasValue || !HoverStart.HasValue)
			{
				return;
			}
			CalendarItem monthControl = MonthControl;
			if (!HoverEndIndex.HasValue || !HoverStartIndex.HasValue)
			{
				return;
			}
			SortHoverIndexes(out var startIndex, out var endIndex);
			if (SelectionMode == CalendarSelectionMode.MultipleRange)
			{
				for (int i = startIndex; i <= endIndex; i++)
				{
					if (monthControl.MonthView.Children[i] is CalendarDayButton calendarDayButton)
					{
						DateTime? dateTime = calendarDayButton.DataContext as DateTime?;
						if (dateTime.HasValue && !SelectedDates.Contains(dateTime.Value))
						{
							calendarDayButton.IsSelected = false;
						}
					}
				}
			}
			else
			{
				for (int i = startIndex; i <= endIndex; i++)
				{
					((CalendarDayButton)monthControl.MonthView.Children[i]).IsSelected = false;
				}
			}
		}

		internal void SortHoverIndexes(out int startIndex, out int endIndex)
		{
			if (DateTimeHelper.CompareDays(HoverEnd.Value, HoverStart.Value) > 0)
			{
				startIndex = HoverStartIndex.Value;
				endIndex = HoverEndIndex.Value;
			}
			else
			{
				startIndex = HoverEndIndex.Value;
				endIndex = HoverStartIndex.Value;
			}
		}

		internal void OnPreviousClick()
		{
			if (DisplayMode == CalendarMode.Month)
			{
				DateTime? dateTime = DateTimeHelper.AddMonths(DateTimeHelper.DiscardDayTime(DisplayDate), -1);
				if (dateTime.HasValue)
				{
					if (!LastSelectedDate.HasValue || DateTimeHelper.CompareYearMonth(LastSelectedDate.Value, dateTime.Value) != 0)
					{
						LastSelectedDate = dateTime.Value;
					}
					SetCurrentValue(DisplayDateProperty, dateTime.Value);
				}
				return;
			}
			if (DisplayMode == CalendarMode.Year)
			{
				DateTime? dateTime2 = DateTimeHelper.AddYears(new DateTime(SelectedMonth.Year, 1, 1), -1);
				if (dateTime2.HasValue)
				{
					SelectedMonth = dateTime2.Value;
				}
				else
				{
					SelectedMonth = DateTimeHelper.DiscardDayTime(DisplayDateRangeStart);
				}
			}
			else
			{
				DateTime? dateTime3 = DateTimeHelper.AddYears(new DateTime(SelectedYear.Year, 1, 1), -10);
				if (dateTime3.HasValue)
				{
					int year = Math.Max(1, DateTimeHelper.DecadeOfDate(dateTime3.Value));
					SelectedYear = new DateTime(year, 1, 1);
				}
				else
				{
					SelectedYear = DateTimeHelper.DiscardDayTime(DisplayDateRangeStart);
				}
			}
			UpdateMonths();
		}

		internal void OnNextClick()
		{
			if (DisplayMode == CalendarMode.Month)
			{
				DateTime? dateTime = DateTimeHelper.AddMonths(DateTimeHelper.DiscardDayTime(DisplayDate), 1);
				if (dateTime.HasValue)
				{
					if (!LastSelectedDate.HasValue || DateTimeHelper.CompareYearMonth(LastSelectedDate.Value, dateTime.Value) != 0)
					{
						LastSelectedDate = dateTime.Value;
					}
					SetCurrentValue(DisplayDateProperty, dateTime.Value);
				}
				return;
			}
			if (DisplayMode == CalendarMode.Year)
			{
				DateTime? dateTime2 = DateTimeHelper.AddYears(new DateTime(SelectedMonth.Year, 1, 1), 1);
				if (dateTime2.HasValue)
				{
					SelectedMonth = dateTime2.Value;
				}
				else
				{
					SelectedMonth = DateTimeHelper.DiscardDayTime(DisplayDateRangeEnd);
				}
			}
			else
			{
				DateTime? dateTime3 = DateTimeHelper.AddYears(new DateTime(SelectedYear.Year, 1, 1), 10);
				if (dateTime3.HasValue)
				{
					int year = Math.Max(1, DateTimeHelper.DecadeOfDate(dateTime3.Value));
					SelectedYear = new DateTime(year, 1, 1);
				}
				else
				{
					SelectedYear = DateTimeHelper.DiscardDayTime(DisplayDateRangeEnd);
				}
			}
			UpdateMonths();
		}

		/// <summary>
		/// If the day is a trailing day, Update the DisplayDate.
		/// </summary>
		/// <param name="selectedDate">Inherited code: Requires comment.</param>
		internal void OnDayClick(DateTime selectedDate)
		{
			int num = DateTimeHelper.CompareYearMonth(selectedDate, DisplayDateInternal);
			if (SelectionMode == CalendarSelectionMode.None)
			{
				LastSelectedDate = selectedDate;
			}
			if (num > 0)
			{
				OnNextClick();
			}
			else if (num < 0)
			{
				OnPreviousClick();
			}
		}

		private void OnMonthClick()
		{
			CalendarItem monthControl = MonthControl;
			if (monthControl != null && monthControl.YearView != null && monthControl.MonthView != null)
			{
				monthControl.YearView.IsVisible = false;
				monthControl.MonthView.IsVisible = true;
				if (!LastSelectedDate.HasValue || DateTimeHelper.CompareYearMonth(LastSelectedDate.Value, DisplayDate) != 0)
				{
					LastSelectedDate = DisplayDate;
				}
				UpdateMonths();
			}
		}

		public override string ToString()
		{
			if (SelectedDate.HasValue)
			{
				return SelectedDate.Value.ToString(DateTimeHelper.GetCurrentDateFormat());
			}
			return string.Empty;
		}

		/// <summary>
		/// This method adds the days that were selected by Keyboard to the
		/// SelectedDays Collection.
		/// </summary>
		private void AddSelection()
		{
			if (!HoverEnd.HasValue || !HoverStart.HasValue)
			{
				return;
			}
			foreach (DateTime selectedDate in SelectedDates)
			{
				RemovedItems.Add(selectedDate);
			}
			SelectedDates.ClearInternal();
			SelectedDates.AddRange(HoverStart.Value, HoverEnd.Value);
		}

		/// <summary>
		/// Handles tap range selection logic for date range selection.
		/// </summary>
		/// <param name="selectedDate">The date that was tapped.</param>
		/// <returns>True if the tap was handled as part of range selection; otherwise, false.</returns>
		internal bool ProcessTapRangeSelection(DateTime selectedDate)
		{
			if (!AllowTapRangeSelection || (SelectionMode != CalendarSelectionMode.SingleRange && SelectionMode != CalendarSelectionMode.MultipleRange))
			{
				return false;
			}
			if (!IsValidDateSelection(this, selectedDate))
			{
				return false;
			}
			if (!_isTapRangeSelectionActive || !_tapRangeStart.HasValue)
			{
				_isTapRangeSelectionActive = true;
				_tapRangeStart = selectedDate;
				if (SelectionMode == CalendarSelectionMode.SingleRange)
				{
					foreach (DateTime selectedDate2 in SelectedDates)
					{
						RemovedItems.Add(selectedDate2);
					}
					SelectedDates.ClearInternal();
				}
				if (!SelectedDates.Contains(selectedDate))
				{
					SelectedDates.Add(selectedDate);
				}
				return true;
			}
			DateTime dateTime = _tapRangeStart.Value;
			DateTime dateTime2 = selectedDate;
			if (DateTime.Compare(dateTime, dateTime2) > 0)
			{
				DateTime dateTime3 = dateTime2;
				dateTime2 = dateTime;
				dateTime = dateTime3;
			}
			CalendarDateRange range = new CalendarDateRange(dateTime, dateTime2);
			if (BlackoutDates.ContainsAny(range))
			{
				_tapRangeStart = selectedDate;
				if (SelectionMode == CalendarSelectionMode.SingleRange)
				{
					foreach (DateTime selectedDate3 in SelectedDates)
					{
						RemovedItems.Add(selectedDate3);
					}
					SelectedDates.ClearInternal();
				}
				if (!SelectedDates.Contains(selectedDate))
				{
					SelectedDates.Add(selectedDate);
				}
				return true;
			}
			if (SelectionMode == CalendarSelectionMode.SingleRange)
			{
				foreach (DateTime selectedDate4 in SelectedDates)
				{
					RemovedItems.Add(selectedDate4);
				}
				SelectedDates.ClearInternal();
			}
			SelectedDates.AddRange(dateTime, dateTime2);
			_isTapRangeSelectionActive = false;
			_tapRangeStart = null;
			return true;
		}

		private void ProcessSelection(bool shift, DateTime? lastSelectedDate, int? index)
		{
			if (SelectionMode == CalendarSelectionMode.None && lastSelectedDate.HasValue)
			{
				OnDayClick(lastSelectedDate.Value);
			}
			else if (lastSelectedDate.HasValue && !index.HasValue && !shift && ProcessTapRangeSelection(lastSelectedDate.Value))
			{
				OnDayClick(lastSelectedDate.Value);
			}
			else
			{
				if (!lastSelectedDate.HasValue || !IsValidKeyboardSelection(this, lastSelectedDate.Value))
				{
					return;
				}
				if (SelectionMode == CalendarSelectionMode.SingleRange || SelectionMode == CalendarSelectionMode.MultipleRange)
				{
					foreach (DateTime selectedDate in SelectedDates)
					{
						RemovedItems.Add(selectedDate);
					}
					SelectedDates.ClearInternal();
					if (shift)
					{
						_isShiftPressed = true;
						if (!HoverStart.HasValue)
						{
							if (LastSelectedDate.HasValue)
							{
								HoverStart = LastSelectedDate;
							}
							else if (DateTimeHelper.CompareYearMonth(DisplayDateInternal, DateTime.Today) == 0)
							{
								HoverStart = DateTime.Today;
							}
							else
							{
								HoverStart = DisplayDateInternal;
							}
							CalendarDayButton calendarDayButton = FindDayButtonFromDay(HoverStart.Value);
							if (calendarDayButton != null)
							{
								HoverStartIndex = calendarDayButton.Index;
							}
						}
						UnHighlightDays();
						CalendarDateRange range = ((DateTime.Compare(HoverStart.Value, lastSelectedDate.Value) >= 0) ? new CalendarDateRange(lastSelectedDate.Value, HoverStart.Value) : new CalendarDateRange(HoverStart.Value, lastSelectedDate.Value));
						if (!BlackoutDates.ContainsAny(range))
						{
							HoverEnd = lastSelectedDate;
							if (index.HasValue)
							{
								HoverEndIndex += index;
							}
							else
							{
								CalendarDayButton calendarDayButton = FindDayButtonFromDay(HoverEndInternal.Value);
								if (calendarDayButton != null)
								{
									HoverEndIndex = calendarDayButton.Index;
								}
							}
						}
						OnDayClick(HoverEnd.Value);
						HighlightDays();
					}
					else
					{
						HoverStart = lastSelectedDate;
						HoverEnd = lastSelectedDate;
						AddSelection();
						OnDayClick(lastSelectedDate.Value);
					}
				}
				else
				{
					LastSelectedDate = lastSelectedDate.Value;
					if (SelectedDates.Count > 0)
					{
						SelectedDates[0] = lastSelectedDate.Value;
					}
					else
					{
						SelectedDates.Add(lastSelectedDate.Value);
					}
					OnDayClick(lastSelectedDate.Value);
				}
			}
		}

		protected override void OnPointerReleased(PointerReleasedEventArgs e)
		{
			base.OnPointerReleased(e);
			if (!HasFocusInternal && e.InitialPressMouseButton == MouseButton.Left)
			{
				Focus();
			}
		}

		internal void OnDayButtonMouseUp(PointerReleasedEventArgs e)
		{
			this.DayButtonMouseUp?.Invoke(this, e);
		}

		/// <summary>
		/// Default mouse wheel handler for the calendar control.
		/// </summary>
		/// <param name="e">Mouse wheel event args.</param>
		protected override void OnPointerWheelChanged(PointerWheelEventArgs e)
		{
			base.OnPointerWheelChanged(e);
			if (e.Handled)
			{
				return;
			}
			CalendarExtensions.GetMetaKeyState(e.KeyModifiers, out var ctrl, out var shift);
			if (!ctrl)
			{
				if (e.Delta.Y > 0.0)
				{
					ProcessPageUpKey(shift: false);
				}
				else
				{
					ProcessPageDownKey(shift: false);
				}
			}
			else if (e.Delta.Y > 0.0)
			{
				ProcessDownKey(ctrl, shift);
			}
			else
			{
				ProcessUpKey(ctrl, shift);
			}
			e.Handled = true;
		}

		internal void Calendar_KeyDown(KeyEventArgs e)
		{
			if (!e.Handled && base.IsEnabled)
			{
				e.Handled = ProcessCalendarKey(e);
			}
		}

		internal bool ProcessCalendarKey(KeyEventArgs e)
		{
			if (DisplayMode == CalendarMode.Month && LastSelectedDate.HasValue && DateTimeHelper.CompareYearMonth(LastSelectedDate.Value, DisplayDateInternal) != 0 && FocusButton != null && !FocusButton.IsInactive)
			{
				return true;
			}
			Key key = e.Key;
			CalendarExtensions.GetMetaKeyState(e.KeyModifiers, out var ctrl, out var shift);
			switch (key)
			{
			case Key.Up:
				ProcessUpKey(ctrl, shift);
				return true;
			case Key.Down:
				ProcessDownKey(ctrl, shift);
				return true;
			case Key.Left:
				ProcessLeftKey(shift);
				return true;
			case Key.Right:
				ProcessRightKey(shift);
				return true;
			case Key.PageDown:
				ProcessPageDownKey(shift);
				return true;
			case Key.PageUp:
				ProcessPageUpKey(shift);
				return true;
			case Key.Home:
				ProcessHomeKey(shift);
				return true;
			case Key.End:
				ProcessEndKey(shift);
				return true;
			case Key.Return:
			case Key.Space:
				return ProcessEnterKey();
			default:
				return false;
			}
		}

		internal void ProcessUpKey(bool ctrl, bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
				if (ctrl)
				{
					SelectedMonth = DisplayDateInternal;
					SetCurrentValue(DisplayModeProperty, CalendarMode.Year);
				}
				else
				{
					DateTime? lastSelectedDate = DateTimeHelper.AddDays(LastSelectedDate.GetValueOrDefault(DateTime.Today), -7);
					ProcessSelection(shift, lastSelectedDate, -7);
				}
				break;
			case CalendarMode.Year:
				if (ctrl)
				{
					SelectedYear = SelectedMonth;
					SetCurrentValue(DisplayModeProperty, CalendarMode.Decade);
				}
				else
				{
					DateTime? selectedMonth = DateTimeHelper.AddMonths(_selectedMonth, -4);
					OnSelectedMonthChanged(selectedMonth);
				}
				break;
			case CalendarMode.Decade:
				if (!ctrl)
				{
					DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, -4);
					OnSelectedYearChanged(selectedYear);
				}
				break;
			}
		}

		internal void ProcessDownKey(bool ctrl, bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
				if (!ctrl || shift)
				{
					DateTime? lastSelectedDate = DateTimeHelper.AddDays(LastSelectedDate.GetValueOrDefault(DateTime.Today), 7);
					ProcessSelection(shift, lastSelectedDate, 7);
				}
				break;
			case CalendarMode.Year:
				if (ctrl)
				{
					SetCurrentValue(DisplayDateProperty, SelectedMonth);
					SetCurrentValue(DisplayModeProperty, CalendarMode.Month);
				}
				else
				{
					DateTime? selectedMonth = DateTimeHelper.AddMonths(_selectedMonth, 4);
					OnSelectedMonthChanged(selectedMonth);
				}
				break;
			case CalendarMode.Decade:
				if (ctrl)
				{
					SelectedMonth = SelectedYear;
					SetCurrentValue(DisplayModeProperty, CalendarMode.Year);
				}
				else
				{
					DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, 4);
					OnSelectedYearChanged(selectedYear);
				}
				break;
			}
		}

		internal void ProcessLeftKey(bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = DateTimeHelper.AddDays(LastSelectedDate.GetValueOrDefault(DateTime.Today), -1);
				ProcessSelection(shift, lastSelectedDate, -1);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime? selectedMonth = DateTimeHelper.AddMonths(_selectedMonth, -1);
				OnSelectedMonthChanged(selectedMonth);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, -1);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		internal void ProcessRightKey(bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = DateTimeHelper.AddDays(LastSelectedDate.GetValueOrDefault(DateTime.Today), 1);
				ProcessSelection(shift, lastSelectedDate, 1);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime? selectedMonth = DateTimeHelper.AddMonths(_selectedMonth, 1);
				OnSelectedMonthChanged(selectedMonth);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, 1);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		private bool ProcessEnterKey()
		{
			switch (DisplayMode)
			{
			case CalendarMode.Year:
				SetCurrentValue(DisplayDateProperty, SelectedMonth);
				SetCurrentValue(DisplayModeProperty, CalendarMode.Month);
				return true;
			case CalendarMode.Decade:
				SelectedMonth = SelectedYear;
				SetCurrentValue(DisplayModeProperty, CalendarMode.Year);
				return true;
			default:
				return false;
			}
		}

		internal void ProcessHomeKey(bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = new DateTime(DisplayDateInternal.Year, DisplayDateInternal.Month, 1);
				ProcessSelection(shift, lastSelectedDate, null);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime value = new DateTime(_selectedMonth.Year, 1, 1);
				OnSelectedMonthChanged(value);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = new DateTime(DateTimeHelper.DecadeOfDate(SelectedYear), 1, 1);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		internal void ProcessEndKey(bool shift)
		{
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = new DateTime(DisplayDateInternal.Year, DisplayDateInternal.Month, 1);
				if (DateTimeHelper.CompareYearMonth(DateTime.MaxValue, lastSelectedDate.Value) > 0)
				{
					lastSelectedDate = DateTimeHelper.AddMonths(lastSelectedDate.Value, 1).Value;
					lastSelectedDate = DateTimeHelper.AddDays(lastSelectedDate.Value, -1).Value;
				}
				else
				{
					lastSelectedDate = DateTime.MaxValue;
				}
				ProcessSelection(shift, lastSelectedDate, null);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime value = new DateTime(_selectedMonth.Year, 12, 1);
				OnSelectedMonthChanged(value);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = new DateTime(DateTimeHelper.EndOfDecade(SelectedYear), 1, 1);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		internal void ProcessPageDownKey(bool shift)
		{
			if (!shift)
			{
				OnNextClick();
				return;
			}
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = DateTimeHelper.AddMonths(LastSelectedDate.GetValueOrDefault(DateTime.Today), 1);
				ProcessSelection(shift, lastSelectedDate, null);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime? selectedMonth = DateTimeHelper.AddYears(_selectedMonth, 1);
				OnSelectedMonthChanged(selectedMonth);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, 10);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		internal void ProcessPageUpKey(bool shift)
		{
			if (!shift)
			{
				OnPreviousClick();
				return;
			}
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime? lastSelectedDate = DateTimeHelper.AddMonths(LastSelectedDate.GetValueOrDefault(DateTime.Today), -1);
				ProcessSelection(shift, lastSelectedDate, null);
				break;
			}
			case CalendarMode.Year:
			{
				DateTime? selectedMonth = DateTimeHelper.AddYears(_selectedMonth, -1);
				OnSelectedMonthChanged(selectedMonth);
				break;
			}
			case CalendarMode.Decade:
			{
				DateTime? selectedYear = DateTimeHelper.AddYears(SelectedYear, -10);
				OnSelectedYearChanged(selectedYear);
				break;
			}
			}
		}

		private void Calendar_KeyUp(KeyEventArgs e)
		{
			if (!e.Handled && (e.Key == Key.LeftShift || e.Key == Key.RightShift))
			{
				ProcessShiftKeyUp();
			}
		}

		internal void ProcessShiftKeyUp()
		{
			if (_isShiftPressed && (SelectionMode == CalendarSelectionMode.SingleRange || SelectionMode == CalendarSelectionMode.MultipleRange))
			{
				AddSelection();
				_isShiftPressed = false;
			}
		}

		protected override void OnGotFocus(GotFocusEventArgs e)
		{
			base.OnGotFocus(e);
			HasFocusInternal = true;
			switch (DisplayMode)
			{
			case CalendarMode.Month:
			{
				DateTime day;
				if (LastSelectedDate.HasValue && DateTimeHelper.CompareYearMonth(DisplayDateInternal, LastSelectedDate.Value) == 0)
				{
					day = LastSelectedDate.Value;
				}
				else
				{
					day = DisplayDate;
					LastSelectedDate = DisplayDate;
				}
				FocusButton = FindDayButtonFromDay(day);
				if (FocusButton != null)
				{
					FocusButton.IsCurrent = true;
				}
				break;
			}
			case CalendarMode.Year:
			case CalendarMode.Decade:
				if (FocusCalendarButton != null)
				{
					FocusCalendarButton.IsCalendarButtonFocused = true;
				}
				break;
			}
		}

		protected override void OnLostFocus(RoutedEventArgs e)
		{
			base.OnLostFocus(e);
			HasFocusInternal = false;
			switch (DisplayMode)
			{
			case CalendarMode.Month:
				if (FocusButton != null)
				{
					FocusButton.IsCurrent = false;
				}
				break;
			case CalendarMode.Year:
			case CalendarMode.Decade:
				if (FocusCalendarButton != null)
				{
					FocusCalendarButton.IsCalendarButtonFocused = false;
				}
				break;
			}
		}

		/// <summary>
		///  Called when the IsEnabled property changes.
		/// </summary>
		/// <param name="e">Property changed args.</param>
		private void OnIsEnabledChanged(AvaloniaPropertyChangedEventArgs e)
		{
			bool isEnabled = (bool)e.NewValue;
			MonthControl?.UpdateDisabled(isEnabled);
		}

		static Calendar()
		{
			FirstDayOfWeekProperty = AvaloniaProperty.Register<Calendar, DayOfWeek>("FirstDayOfWeek", DateTimeHelper.GetCurrentDateFormat().FirstDayOfWeek);
			IsTodayHighlightedProperty = AvaloniaProperty.Register<Calendar, bool>("IsTodayHighlighted", defaultValue: true);
			HeaderBackgroundProperty = AvaloniaProperty.Register<Calendar, IBrush>("HeaderBackground");
			DisplayModeProperty = AvaloniaProperty.Register<Calendar, CalendarMode>("DisplayMode", CalendarMode.Month, inherits: false, BindingMode.OneWay, IsValidDisplayMode);
			SelectionModeProperty = AvaloniaProperty.Register<Calendar, CalendarSelectionMode>("SelectionMode", CalendarSelectionMode.SingleDate);
			AllowTapRangeSelectionProperty = AvaloniaProperty.Register<Calendar, bool>("AllowTapRangeSelection", defaultValue: true);
			SelectedDateProperty = AvaloniaProperty.Register<Calendar, DateTime?>("SelectedDate", null, inherits: false, BindingMode.TwoWay);
			DisplayDateProperty = AvaloniaProperty.Register<Calendar, DateTime>("DisplayDate", default(DateTime), inherits: false, BindingMode.TwoWay);
			DisplayDateStartProperty = AvaloniaProperty.Register<Calendar, DateTime?>("DisplayDateStart", null, inherits: false, BindingMode.TwoWay);
			DisplayDateEndProperty = AvaloniaProperty.Register<Calendar, DateTime?>("DisplayDateEnd", null, inherits: false, BindingMode.TwoWay);
			InputElement.IsEnabledProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnIsEnabledChanged(e);
			});
			FirstDayOfWeekProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnFirstDayOfWeekChanged(e);
			});
			IsTodayHighlightedProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnIsTodayHighlightedChanged(e);
			});
			DisplayModeProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnDisplayModePropertyChanged(e);
			});
			SelectionModeProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnSelectionModeChanged(e);
			});
			AllowTapRangeSelectionProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnAllowTapRangeSelectionChanged(e);
			});
			SelectedDateProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnSelectedDateChanged(e);
			});
			DisplayDateProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnDisplayDateChanged(e);
			});
			DisplayDateStartProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnDisplayDateStartChanged(e);
			});
			DisplayDateEndProperty.Changed.AddClassHandler(delegate(Calendar x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnDisplayDateEndChanged(e);
			});
			InputElement.KeyDownEvent.AddClassHandler(delegate(Calendar x, KeyEventArgs e)
			{
				x.Calendar_KeyDown(e);
			});
			InputElement.KeyUpEvent.AddClassHandler(delegate(Calendar x, KeyEventArgs e)
			{
				x.Calendar_KeyUp(e);
			});
		}

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:System.Windows.Controls.Calendar" /> class.
		/// </summary>
		public Calendar()
		{
			SetCurrentValue(DisplayDateProperty, DateTime.Today);
			UpdateDisplayDate(this, DisplayDate, DateTime.MinValue);
			BlackoutDates = new CalendarBlackoutDatesCollection(this);
			SelectedDates = new SelectedDatesCollection(this);
			RemovedItems = new Collection<DateTime>();
		}

		/// <summary>
		/// Builds the visual tree for the
		/// <see cref="T:System.Windows.Controls.Calendar" /> when a new
		/// template is applied.
		/// </summary>
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			Root = e.NameScope.Find<Panel>("PART_Root");
			SelectedMonth = DisplayDate;
			SelectedYear = DisplayDate;
			if (Root != null)
			{
				CalendarItem calendarItem = e.NameScope.Find<CalendarItem>("PART_CalendarItem");
				if (calendarItem != null)
				{
					calendarItem.Owner = this;
				}
			}
		}
	}
	public sealed class CalendarDateRange
	{
		/// <summary>
		/// Gets the first date in the represented range.
		/// </summary>
		/// <value>The first date in the represented range.</value>
		public DateTime Start { get; private set; }

		/// <summary>
		/// Gets the last date in the represented range.
		/// </summary>
		/// <value>The last date in the represented range.</value>
		public DateTime End { get; private set; }

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:System.Windows.Controls.CalendarDateRange" /> class
		/// with a single date.
		/// </summary>
		/// <param name="day">The date to be represented by the range.</param>
		public CalendarDateRange(DateTime day)
		{
			Start = day;
			End = day;
		}

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:System.Windows.Controls.CalendarDateRange" /> class
		/// with a range of dates.
		/// </summary>
		/// <param name="start">
		/// The start of the range to be represented.
		/// </param>
		/// <param name="end">The end of the range to be represented.</param>
		public CalendarDateRange(DateTime start, DateTime end)
		{
			if (DateTime.Compare(end, start) >= 0)
			{
				Start = start;
				End = end;
			}
			else
			{
				Start = start;
				End = start;
			}
		}

		/// <summary>
		/// Returns true if any day in the given DateTime range is contained in
		/// the current CalendarDateRange.
		/// </summary>
		/// <param name="range">Inherited code: Requires comment 1.</param>
		/// <returns>Inherited code: Requires comment 2.</returns>
		internal bool ContainsAny(CalendarDateRange range)
		{
			if (range == null)
			{
				throw new ArgumentNullException("range");
			}
			int num = DateTime.Compare(Start, range.Start);
			if (num > 0 || DateTime.Compare(End, range.Start) < 0)
			{
				if (num >= 0)
				{
					return DateTime.Compare(Start, range.End) <= 0;
				}
				return false;
			}
			return true;
		}
	}
	internal static class DateTimeHelper
	{
		public static DateTime? AddDays(DateTime time, int days)
		{
			System.Globalization.Calendar calendar = new GregorianCalendar();
			try
			{
				return calendar.AddDays(time, days);
			}
			catch (ArgumentException)
			{
				return null;
			}
		}

		public static DateTime? AddMonths(DateTime time, int months)
		{
			System.Globalization.Calendar calendar = new GregorianCalendar();
			try
			{
				return calendar.AddMonths(time, months);
			}
			catch (ArgumentException)
			{
				return null;
			}
		}

		public static DateTime? AddYears(DateTime time, int years)
		{
			System.Globalization.Calendar calendar = new GregorianCalendar();
			try
			{
				return calendar.AddYears(time, years);
			}
			catch (ArgumentException)
			{
				return null;
			}
		}

		public static int CompareDays(DateTime dt1, DateTime dt2)
		{
			return DateTime.Compare(DiscardTime(dt1), DiscardTime(dt2));
		}

		public static int CompareYearMonth(DateTime dt1, DateTime dt2)
		{
			return (dt1.Year - dt2.Year) * 12 + (dt1.Month - dt2.Month);
		}

		public static int DecadeOfDate(DateTime date)
		{
			return date.Year - date.Year % 10;
		}

		public static DateTime DiscardDayTime(DateTime d)
		{
			return new DateTime(d.Year, d.Month, 1, 0, 0, 0);
		}

		public static DateTime DiscardTime(DateTime d)
		{
			return d.Date;
		}

		public static int EndOfDecade(DateTime date)
		{
			return DecadeOfDate(date) + 9;
		}

		public static DateTimeFormatInfo GetCurrentDateFormat()
		{
			if (CultureInfo.CurrentCulture.Calendar is GregorianCalendar)
			{
				return CultureInfo.CurrentCulture.DateTimeFormat;
			}
			System.Globalization.Calendar[] optionalCalendars = CultureInfo.CurrentCulture.OptionalCalendars;
			foreach (System.Globalization.Calendar calendar in optionalCalendars)
			{
				if (calendar is GregorianCalendar)
				{
					DateTimeFormatInfo dateTimeFormat = new CultureInfo(CultureInfo.CurrentCulture.Name).DateTimeFormat;
					dateTimeFormat.Calendar = calendar;
					return dateTimeFormat;
				}
			}
			DateTimeFormatInfo dateTimeFormat2 = new CultureInfo(CultureInfo.InvariantCulture.Name).DateTimeFormat;
			dateTimeFormat2.Calendar = new GregorianCalendar();
			return dateTimeFormat2;
		}

		public static bool InRange(DateTime date, CalendarDateRange range)
		{
			if (CompareDays(date, range.Start) > -1 && CompareDays(date, range.End) < 1)
			{
				return true;
			}
			return false;
		}

		public static string ToYearMonthPatternString(DateTime date)
		{
			DateTimeFormatInfo currentDateFormat = GetCurrentDateFormat();
			return date.ToString(currentDateFormat.YearMonthPattern, currentDateFormat);
		}

		public static string ToYearString(DateTime date)
		{
			DateTimeFormatInfo currentDateFormat = GetCurrentDateFormat();
			return date.Year.ToString(currentDateFormat);
		}
	}
	/// <summary>
	/// A panel that displays child controls at arbitrary locations.
	/// </summary>
	/// <remarks>
	/// Unlike other <see cref="T:Avalonia.Controls.Panel" /> implementations, the <see cref="T:Avalonia.Controls.Canvas" /> doesn't lay out
	/// its children in any particular layout. Instead, the positioning of each child control is
	/// defined by the <code>Canvas.Left</code>, <code>Canvas.Top</code>, <code>Canvas.Right</code>
	/// and <code>Canvas.Bottom</code> attached properties.
	/// </remarks>
	public class Canvas : Panel, INavigableContainer
	{
		/// <summary>
		/// Defines the Left attached property.
		/// </summary>
		public static readonly AttachedProperty<double> LeftProperty;

		/// <summary>
		/// Defines the Top attached property.
		/// </summary>
		public static readonly AttachedProperty<double> TopProperty;

		/// <summary>
		/// Defines the Right attached property.
		/// </summary>
		public static readonly AttachedProperty<double> RightProperty;

		/// <summary>
		/// Defines the Bottom attached property.
		/// </summary>
		public static readonly AttachedProperty<double> BottomProperty;

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.Canvas" /> class.
		/// </summary>
		static Canvas()
		{
			LeftProperty = AvaloniaProperty.RegisterAttached<Canvas, Control, double>("Left", double.NaN);
			TopProperty = AvaloniaProperty.RegisterAttached<Canvas, Control, double>("Top", double.NaN);
			RightProperty = AvaloniaProperty.RegisterAttached<Canvas, Control, double>("Right", double.NaN);
			BottomProperty = AvaloniaProperty.RegisterAttached<Canvas, Control, double>("Bottom", double.NaN);
			Visual.ClipToBoundsProperty.OverrideDefaultValue<Canvas>(defaultValue: false);
			Panel.AffectsParentArrange<Canvas>(new AvaloniaProperty[4] { LeftProperty, TopProperty, RightProperty, BottomProperty });
		}

		/// <summary>
		/// Gets the value of the Left attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The control's left coordinate.</returns>
		public static double GetLeft(AvaloniaObject element)
		{
			return element.GetValue(LeftProperty);
		}

		/// <summary>
		/// Sets the value of the Left attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <param name="value">The left value.</param>
		public static void SetLeft(AvaloniaObject element, double value)
		{
			element.SetValue(LeftProperty, value);
		}

		/// <summary>
		/// Gets the value of the Top attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The control's top coordinate.</returns>
		public static double GetTop(AvaloniaObject element)
		{
			return element.GetValue(TopProperty);
		}

		/// <summary>
		/// Sets the value of the Top attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <param name="value">The top value.</param>
		public static void SetTop(AvaloniaObject element, double value)
		{
			element.SetValue(TopProperty, value);
		}

		/// <summary>
		/// Gets the value of the Right attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The control's right coordinate.</returns>
		public static double GetRight(AvaloniaObject element)
		{
			return element.GetValue(RightProperty);
		}

		/// <summary>
		/// Sets the value of the Right attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <param name="value">The right value.</param>
		public static void SetRight(AvaloniaObject element, double value)
		{
			element.SetValue(RightProperty, value);
		}

		/// <summary>
		/// Gets the value of the Bottom attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <returns>The control's bottom coordinate.</returns>
		public static double GetBottom(AvaloniaObject element)
		{
			return element.GetValue(BottomProperty);
		}

		/// <summary>
		/// Sets the value of the Bottom attached property for a control.
		/// </summary>
		/// <param name="element">The control.</param>
		/// <param name="value">The bottom value.</param>
		public static void SetBottom(AvaloniaObject element, double value)
		{
			element.SetValue(BottomProperty, value);
		}

		/// <summary>
		/// Gets the next control in the specified direction.
		/// </summary>
		/// <param name="direction">The movement direction.</param>
		/// <param name="from">The control from which movement begins.</param>
		/// <param name="wrap">Whether to wrap around when the first or last item is reached.</param>
		/// <returns>The control.</returns>
		IInputElement? INavigableContainer.GetControl(NavigationDirection direction, IInputElement? from, bool wrap)
		{
			return null;
		}

		/// <summary>
		/// Measures the control.
		/// </summary>
		/// <param name="availableSize">The available size.</param>
		/// <returns>The desired size of the control.</returns>
		protected override Size MeasureOverride(Size availableSize)
		{
			availableSize = new Size(double.PositiveInfinity, double.PositiveInfinity);
			foreach (Control child in base.Children)
			{
				child.Measure(availableSize);
			}
			return default(Size);
		}

		/// <summary>
		/// Arranges a single child.
		/// </summary>
		/// <param name="child">The child to arrange.</param>
		/// <param name="finalSize">The size allocated to the canvas.</param>
		protected virtual void ArrangeChild(Control child, Size finalSize)
		{
			double x = 0.0;
			double y = 0.0;
			double left = GetLeft(child);
			if (!double.IsNaN(left))
			{
				x = left;
			}
			else
			{
				double right = GetRight(child);
				if (!double.IsNaN(right))
				{
					x = finalSize.Width - child.DesiredSize.Width - right;
				}
			}
			double top = GetTop(child);
			if (!double.IsNaN(top))
			{
				y = top;
			}
			else
			{
				double bottom = GetBottom(child);
				if (!double.IsNaN(bottom))
				{
					y = finalSize.Height - child.DesiredSize.Height - bottom;
				}
			}
			child.Arrange(new Rect(new Point(x, y), child.DesiredSize));
		}

		/// <summary>
		/// Arranges the control's children.
		/// </summary>
		/// <param name="finalSize">The size allocated to the control.</param>
		/// <returns>The space taken.</returns>
		protected override Size ArrangeOverride(Size finalSize)
		{
			foreach (Control child in base.Children)
			{
				ArrangeChild(child, finalSize);
			}
			return finalSize;
		}
	}
	/// <summary>
	/// An items control that displays its items as pages that fill the control.
	/// </summary>
	public class Carousel : SelectingItemsControl
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Carousel.PageTransition" /> property.
		/// </summary>
		public static readonly StyledProperty<IPageTransition?> PageTransitionProperty;

		/// <summary>
		/// The default value of <see cref="F:Avalonia.Controls.ItemsControl.ItemsPanelProperty" /> for 
		/// <see cref="T:Avalonia.Controls.Carousel" />.
		/// </summary>
		private static readonly FuncTemplate<Panel?> DefaultPanel;

		private IScrollable? _scroller;

		/// <summary>
		/// Gets or sets the transition to use when moving between pages.
		/// </summary>
		public IPageTransition? PageTransition
		{
			get
			{
				return GetValue(PageTransitionProperty);
			}
			set
			{
				SetValue(PageTransitionProperty, value);
			}
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.Carousel" /> class.
		/// </summary>
		static Carousel()
		{
			PageTransitionProperty = AvaloniaProperty.Register<Carousel, IPageTransition>("PageTransition");
			DefaultPanel = new FuncTemplate<Panel>(() => new VirtualizingCarouselPanel());
			SelectingItemsControl.SelectionModeProperty.OverrideDefaultValue<Carousel>(SelectionMode.AlwaysSelected);
			ItemsControl.ItemsPanelProperty.OverrideDefaultValue<Carousel>(DefaultPanel);
		}

		/// <summary>
		/// Moves to the next item in the carousel.
		/// </summary>
		public void Next()
		{
			if (base.SelectedIndex < base.ItemCount - 1)
			{
				int selectedIndex = base.SelectedIndex + 1;
				base.SelectedIndex = selectedIndex;
			}
		}

		/// <summary>
		/// Moves to the previous item in the carousel.
		/// </summary>
		public void Previous()
		{
			if (base.SelectedIndex > 0)
			{
				int selectedIndex = base.SelectedIndex - 1;
				base.SelectedIndex = selectedIndex;
			}
		}

		protected override Size ArrangeOverride(Size finalSize)
		{
			Size result = base.ArrangeOverride(finalSize);
			if (_scroller != null)
			{
				_scroller.Offset = new Vector(base.SelectedIndex, 0.0);
			}
			return result;
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_scroller = e.NameScope.Find<IScrollable>("PART_ScrollViewer");
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == SelectingItemsControl.SelectedIndexProperty && _scroller != null)
			{
				int newValue = change.GetNewValue<int>();
				_scroller.Offset = new Vector(newValue, 0.0);
			}
		}
	}
