				{
					ScrollIntoView(base.Selection.SelectedIndex);
					control = ContainerFromIndex(selectedIndex);
				}
				if (control != null && CanFocus(control))
				{
					control.Focus();
				}
			}
		}

		private bool CanFocus(Control control)
