			}
		}

		private void SelectFocusedItem()
		{
			foreach (Control realizedContainer in GetRealizedContainers())
			{
				if (realizedContainer.IsFocused)
				{
					base.SelectedIndex = IndexFromContainer(realizedContainer);
					break;
				}
			}
		}

		private bool SelectNext()
		{
			return MoveSelection(base.SelectedIndex, 1, base.WrapSelection);
		}

		private bool SelectPrevious()
		{
			return MoveSelection(base.SelectedIndex, -1, base.WrapSelection);
		}

		private bool MoveSelection(int startIndex, int step, bool wrap)
		{
			int itemCount = base.ItemCount;
			for (int i = startIndex + step; i != startIndex; i += step)
			{
				if (i < 0 || i >= itemCount)
				{
					if (!wrap)
					{
						return false;
					}
					if (i < 0)
					{
						i += itemCount;
					}
					else if (i >= itemCount)
					{
						i %= itemCount;
					}
				}
				object? o = base.ItemsView[i];
				Control o2 = ContainerFromIndex(i);
				if (IsSelectable(o) && IsSelectable(o2))
				{
					base.SelectedIndex = i;
					return true;
				}
			}
			return false;
			static bool IsSelectable(object? obj)
			{
