			}
		}

		/// <summary>
		/// Clears the selection
		/// </summary>
		public void Clear()
		{
			base.SelectedItem = null;
			base.SelectedIndex = -1;
		}

		private void HandleTextValueBindingValueChanged(AvaloniaPropertyChangedEventArgs? textSearchPropChange, AvaloniaPropertyChangedEventArgs? displayMemberPropChange)
		{
			IBinding binding;
			if (textSearchPropChange == null)
			{
				IBinding textBinding = TextSearch.GetTextBinding(this);
				if (textBinding != null)
				{
					binding = textBinding;
					goto IL_003f;
				}
			}
			binding = ((textSearchPropChange != null && textSearchPropChange.NewValue is IBinding binding2) ? binding2 : ((displayMemberPropChange == null || !(displayMemberPropChange.NewValue is IBinding binding3)) ? null : binding3));
			goto IL_003f;
