			if (_textValueBindingEvaluator == null)
			{
				_textValueBindingEvaluator = BindingEvaluator<string>.TryCreate(binding);
			}
			else if (binding == null)
			{
				_textValueBindingEvaluator = null;
			}
			else
			{
				_textValueBindingEvaluator.UpdateBinding(binding);
			}
			if (_textValueBindingEvaluator != null)
			{
				_textValueBindingEvaluator.Value = GetItemTextValue(base.SelectedValue);
			}
		}

		private void TextChanged(string? newValue)
		{
			if (!IsEditable || _skipNextTextChanged)
			{
				return;
			}
			int selectedIndex = -1;
			object selectedItem = null;
			int num = -1;
			foreach (object item in base.Items)
			{
				num++;
				string itemTextValue = GetItemTextValue(item);
				if (string.Equals(newValue, itemTextValue, StringComparison.CurrentCultureIgnoreCase))
				{
					selectedIndex = num;
					selectedItem = item;
					break;
				}
			}
			_skipNextTextChanged = true;
			try
			{
				base.SelectedIndex = selectedIndex;
				base.SelectedItem = selectedItem;
			}
			finally
			{
				_skipNextTextChanged = false;
			}
			KeyboardNavigation.SetTabOnceActiveElement(this, null);
		}

		private string GetItemTextValue(object? item)
		{
			return TextSearch.GetEffectiveText(item, _textValueBindingEvaluator);
		}
	}
