	/// - <see cref="F:Avalonia.Controls.Control.ContextRequestedEvent" /> and other context menu related members.
	/// </remarks>
	public class Control : InputElement, IDataTemplateHost, IVisualBrushInitialize, ISetterValue
	{
		private enum LoadState : byte
		{
			Unloaded,
			Loaded,
			LoadPending
		}

