		/// <summary>
		/// Schedules <see cref="M:Avalonia.Controls.Control.OnLoadedCore" /> to be called for this control.
		/// For performance, it will be queued with other controls.
		/// </summary>
		internal void ScheduleOnLoadedCore()
		{
			if (_loadState == LoadState.Unloaded)
			{
				bool num = _loadedQueue.Add(this);
				_loadState = LoadState.LoadPending;
				if (num && !_isLoadedProcessing)
				{
					_isLoadedProcessing = true;
					Dispatcher.UIThread.Post(loadedProcessingAction, DispatcherPriority.Loaded);
				}
			}
		}

		/// <summary>
		/// Invoked as the first step of marking the control as loaded and raising the
		/// <see cref="E:Avalonia.Controls.Control.Loaded" /> event.
		/// </summary>
		internal void OnLoadedCore()
		{
			if (_loadState == LoadState.LoadPending && ((ILogical)this).IsAttachedToLogicalTree)
			{
				_loadState = LoadState.Loaded;
				OnLoaded(new RoutedEventArgs(LoadedEvent, this));
			}
			else
			{
				_loadState = LoadState.Unloaded;
			}
		}

		/// <summary>
		/// Invoked as the first step of marking the control as unloaded and raising the
		/// <see cref="E:Avalonia.Controls.Control.Unloaded" /> event.
		/// </summary>
		internal void OnUnloadedCore()
		{
			switch (_loadState)
			{
			case LoadState.Loaded:
				_loadState = LoadState.Unloaded;
				OnUnloaded(new RoutedEventArgs(UnloadedEvent, this));
				break;
			case LoadState.LoadPending:
				_loadedQueue.Remove(this);
				_loadState = LoadState.Unloaded;
				break;
			}
		}

