		/// <inheritdoc />
		protected sealed override void OnAttachedToVisualTreeCore(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTreeCore(e);
			InitializeIfNeeded();
			ScheduleOnLoadedCore();
			base.Holding += OnHoldEvent;
		}

		private void OnHoldEvent(object? sender, HoldingRoutedEventArgs e)
		{
			if (e.Source == this && !e.Handled && e.HoldingState == HoldingState.Started)
			{
				PointerEventArgs pointerEventArgs = e.PointerEventArgs;
				ContextRequestedEventArgs e2 = ((pointerEventArgs != null) ? new ContextRequestedEventArgs(pointerEventArgs) : new ContextRequestedEventArgs());
				RaiseEvent(e2);
				e.Handled = e2.Handled;
			}
		}

		/// <inheritdoc />
		protected sealed override void OnDetachedFromVisualTreeCore(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTreeCore(e);
			OnUnloadedCore();
			base.Holding -= OnHoldEvent;
		}

		/// <inheritdoc />
		protected override void OnGotFocus(GotFocusEventArgs e)
		{
			base.OnGotFocus(e);
			if (!base.IsFocused || (e.NavigationMethod != NavigationMethod.Tab && e.NavigationMethod != NavigationMethod.Directional))
			{
				return;
			}
			AdornerLayer adornerLayer = AdornerLayer.GetAdornerLayer(this);
			if (adornerLayer == null)
			{
				return;
			}
			if (_focusAdorner == null)
			{
				ITemplate<Control> template;
				if (!IsSet(FocusAdornerProperty))
				{
					template = adornerLayer.DefaultFocusAdorner;
				}
				else
				{
					ITemplate<Control> value = GetValue(FocusAdornerProperty);
					template = value;
				}
				ITemplate<Control> template2 = template;
				if (template2 != null)
				{
					_focusAdorner = template2.Build();
				}
			}
			if (_focusAdorner != null)
			{
				Visual templateFocusTarget = GetTemplateFocusTarget();
				if (templateFocusTarget != null)
				{
					AdornerLayer.SetAdornedElement(_focusAdorner, templateFocusTarget);
					adornerLayer.Children.Add(_focusAdorner);
				}
			}
		}

		/// <inheritdoc />
		protected override void OnLostFocus(RoutedEventArgs e)
		{
			base.OnLostFocus(e);
			if (_focusAdorner?.Parent != null)
			{
				((Panel)_focusAdorner.Parent).Children.Remove(_focusAdorner);
				_focusAdorner = null;
			}
		}

		/// <summary>
		/// Returns a new, type-specific <see cref="T:Avalonia.Automation.Peers.AutomationPeer" /> implementation for the control.
		/// </summary>
		/// <returns>The type-specific <see cref="T:Avalonia.Automation.Peers.AutomationPeer" /> implementation.</returns>
		protected virtual AutomationPeer OnCreateAutomationPeer()
		{
			return new NoneAutomationPeer(this);
		}

		internal AutomationPeer? GetAutomationPeer()
		{
			VerifyAccess();
			return _automationPeer;
		}

		internal AutomationPeer GetOrCreateAutomationPeer()
		{
			VerifyAccess();
			if (_automationPeer != null)
			{
				return _automationPeer;
			}
			_automationPeer = OnCreateAutomationPeer();
			return _automationPeer;
		}

		/// <inheritdoc />
		protected override void OnPointerReleased(PointerReleasedEventArgs e)
		{
			base.OnPointerReleased(e);
			if (e.Source == this && !e.Handled && e.InitialPressMouseButton == MouseButton.Right)
			{
				ContextRequestedEventArgs e2 = new ContextRequestedEventArgs(e);
				RaiseEvent(e2);
				e.Handled = e2.Handled;
			}
		}

		/// <inheritdoc />
		protected override void OnKeyUp(KeyEventArgs e)
		{
			base.OnKeyUp(e);
			if (e.Source != this || e.Handled)
			{
				return;
			}
			List<KeyGesture> list = TopLevel.GetTopLevel(this)?.PlatformSettings?.HotkeyConfiguration.OpenContextMenu;
			if (list == null)
			{
				return;
			}
			bool flag = false;
			for (int i = 0; i < list.Count; i++)
			{
				KeyGesture keyGesture = list[i];
				flag |= keyGesture.Matches(e);
				if (flag)
				{
					break;
				}
			}
			if (flag)
			{
				ContextRequestedEventArgs e2 = new ContextRequestedEventArgs();
				RaiseEvent(e2);
				e.Handled = e2.Handled;
			}
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == Visual.BoundsProperty)
			{
				Rect oldValue = change.GetOldValue<Rect>();
				Rect newValue = change.GetNewValue<Rect>();
				if (newValue.Size != oldValue.Size)
				{
					SizeChangedEventArgs e = new SizeChangedEventArgs(SizeChangedEvent, this, new Size(oldValue.Width, oldValue.Height), new Size(newValue.Width, newValue.Height));
					OnSizeChanged(e);
				}
			}
		}

		internal static void ResetLoadedQueueForUnitTests()
		{
			_loadedQueue.Clear();
			_loadedProcessingQueue.Clear();
			_isLoadedProcessing = false;
		}
	}
	/// <summary>
	/// Adds common functionality to <see cref="T:Avalonia.Controls.Control" />.
	/// </summary>
	public static class ControlExtensions
	{
		/// <summary>
		/// Tries to bring the control into view.
		/// </summary>
		/// <param name="control">The control.</param>
		public static void BringIntoView(this Control control)
		{
			if (control == null)
			{
				throw new ArgumentNullException("control");
			}
			control.BringIntoView(new Rect(control.Bounds.Size));
		}

		/// <summary>
		/// Tries to bring the control into view.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <param name="rect">The area of the control to being into view.</param>
		public static void BringIntoView(this Control control, Rect rect)
		{
			if (control == null)
			{
				throw new ArgumentNullException("control");
			}
			if (control.IsEffectivelyVisible)
			{
				RequestBringIntoViewEventArgs e = new RequestBringIntoViewEventArgs
				{
					RoutedEvent = Control.RequestBringIntoViewEvent,
					TargetObject = control,
					TargetRect = rect
				};
				control.RaiseEvent(e);
			}
		}

		/// <summary>
		/// Finds the named control in the scope of the specified control.
		/// </summary>
		/// <typeparam name="T">The type of the control to find.</typeparam>
		/// <param name="control">The control to look in.</param>
		/// <param name="name">The name of the control to find.</param>
		/// <returns>The control or null if not found.</returns>
		public static T? FindControl<T>(this Control control, string name) where T : Control
		{
			if (control == null)
			{
				throw new ArgumentNullException("control");
			}
			if (name == null)
			{
				throw new ArgumentNullException("name");
			}
			return (control.FindNameScope() ?? throw new InvalidOperationException("Could not find parent name scope.")).Find<T>(name);
		}

		/// <summary>
		/// Finds the named control in the scope of the specified control and throws if not found.
		/// </summary>
		/// <typeparam name="T">The type of the control to find.</typeparam>
		/// <param name="control">The control to look in.</param>
		/// <param name="name">The name of the control to find.</param>
		/// <returns>The control.</returns>
		public static T GetControl<T>(this Control control, string name) where T : Control
		{
			if (control == null)
			{
				throw new ArgumentNullException("control");
			}
			if (name == null)
			{
				throw new ArgumentNullException("name");
			}
			return (control.FindNameScope() ?? throw new InvalidOperationException("Could not find parent name scope.")).Find<T>(name) ?? throw new ArgumentException("Could not find control named '" + name + "'.");
		}

		/// <summary>
		/// Sets a pseudoclass depending on an observable trigger.
		/// </summary>
		/// <param name="classes">The pseudoclasses collection.</param>
		/// <param name="name">The name of the pseudoclass to set.</param>
		/// <param name="trigger">The trigger: true adds the pseudoclass, false removes.</param>
		/// <returns>A disposable used to cancel the subscription.</returns>
		public static IDisposable Set(this IPseudoClasses classes, string name, IObservable<bool> trigger)
		{
			if (classes == null)
			{
				throw new ArgumentNullException("classes");
			}
			return trigger.Subscribe(delegate(bool x)
			{
				classes.Set(name, x);
			});
		}
	}
