		private static DateTimeOffset CoerceDate(AvaloniaObject sender, DateTimeOffset value)
		{
			DateTimeOffset value2 = sender.GetValue(MaxYearProperty);
			if (value > value2)
			{
				return value2;
			}
			DateTimeOffset value3 = sender.GetValue(MinYearProperty);
			if (value < value3)
			{
				return value3;
			}
			return value;
		}

		public DatePickerPresenter()
		{
			DateTimeOffset now = DateTimeOffset.Now;
			SetCurrentValue(MinYearProperty, new DateTimeOffset(now.Year - 100, 1, 1, 0, 0, 0, now.Offset));
			SetCurrentValue(MaxYearProperty, new DateTimeOffset(now.Year + 100, 12, 31, 0, 0, 0, now.Offset));
			SetCurrentValue(DateProperty, now);
			_calendar = new GregorianCalendar();
		}

		static DatePickerPresenter()
		{
			Func<AvaloniaObject, DateTimeOffset, DateTimeOffset> coerce = CoerceDate;
			DateProperty = AvaloniaProperty.Register<DatePickerPresenter, DateTimeOffset>("Date", default(DateTimeOffset), inherits: false, BindingMode.OneWay, null, coerce);
			DayFormatProperty = DatePicker.DayFormatProperty.AddOwner<DatePickerPresenter>();
			DayVisibleProperty = DatePicker.DayVisibleProperty.AddOwner<DatePickerPresenter>();
			MaxYearProperty = DatePicker.MaxYearProperty.AddOwner<DatePickerPresenter>();
			MinYearProperty = DatePicker.MinYearProperty.AddOwner<DatePickerPresenter>();
			MonthFormatProperty = DatePicker.MonthFormatProperty.AddOwner<DatePickerPresenter>();
			MonthVisibleProperty = DatePicker.MonthVisibleProperty.AddOwner<DatePickerPresenter>();
			YearFormatProperty = DatePicker.YearFormatProperty.AddOwner<DatePickerPresenter>();
			YearVisibleProperty = DatePicker.YearVisibleProperty.AddOwner<DatePickerPresenter>();
			KeyboardNavigation.TabNavigationProperty.OverrideDefaultValue<DatePickerPresenter>(KeyboardNavigationMode.Cycle);
		}

		private static void OnDateRangeChanged(DatePickerPresenter sender, AvaloniaPropertyChangedEventArgs e)
		{
			sender.CoerceValue(DateProperty);
		}

		private void OnDateChanged(DateTimeOffset newValue)
		{
			_syncDate = newValue;
			InitPicker();
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_templateItems = new TemplateItems
			{
				_pickerContainer = e.NameScope.Get<Grid>("PART_PickerContainer"),
				_monthHost = e.NameScope.Get<Panel>("PART_MonthHost"),
				_dayHost = e.NameScope.Get<Panel>("PART_DayHost"),
				_yearHost = e.NameScope.Get<Panel>("PART_YearHost"),
				_monthSelector = e.NameScope.Get<DateTimePickerPanel>("PART_MonthSelector"),
				_daySelector = e.NameScope.Get<DateTimePickerPanel>("PART_DaySelector"),
				_yearSelector = e.NameScope.Get<DateTimePickerPanel>("PART_YearSelector"),
				_acceptButton = e.NameScope.Get<Button>("PART_AcceptButton"),
				_monthUpButton = SelectorButton("PART_MonthUpButton", DateTimePickerPanelType.Month, SpinDirection.Decrease),
				_monthDownButton = SelectorButton("PART_MonthDownButton", DateTimePickerPanelType.Month, SpinDirection.Increase),
				_dayUpButton = SelectorButton("PART_DayUpButton", DateTimePickerPanelType.Day, SpinDirection.Decrease),
				_dayDownButton = SelectorButton("PART_DayDownButton", DateTimePickerPanelType.Day, SpinDirection.Increase),
				_yearUpButton = SelectorButton("PART_YearUpButton", DateTimePickerPanelType.Year, SpinDirection.Decrease),
				_yearDownButton = SelectorButton("PART_YearDownButton", DateTimePickerPanelType.Year, SpinDirection.Increase),
				_dismissButton = e.NameScope.Find<Button>("PART_DismissButton"),
				_firstSpacer = e.NameScope.Find<Control>("PART_FirstSpacer"),
				_secondSpacer = e.NameScope.Find<Control>("PART_SecondSpacer")
			};
			_templateItems.Value._acceptButton.Click += OnAcceptButtonClicked;
			_templateItems.Value._monthSelector.SelectionChanged += OnMonthChanged;
			_templateItems.Value._daySelector.SelectionChanged += OnDayChanged;
			_templateItems.Value._yearSelector.SelectionChanged += OnYearChanged;
			Button dismissButton = _templateItems.Value._dismissButton;
			if (dismissButton != null)
			{
				dismissButton.Click += OnDismissButtonClicked;
			}
			InitPicker();
			Button? SelectorButton(string name, DateTimePickerPanelType type, SpinDirection direction)
			{
				Button button = e.NameScope.Find<Button>(name);
				if (button != null)
				{
					button.Click += delegate
					{
						OnSelectorButtonClick(type, direction);
					};
					return button;
				}
				return null;
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == DateProperty)
			{
				OnDateChanged(change.GetNewValue<DateTimeOffset>());
			}
			else if (change.Property == MaxYearProperty || change.Property == MinYearProperty)
			{
				OnDateRangeChanged(this, change);
			}
			else if (change.Property == MonthFormatProperty || change.Property == YearFormatProperty || change.Property == DayFormatProperty)
			{
				InitPicker();
			}
		}

		protected override void OnKeyDown(KeyEventArgs e)
		{
			switch (e.Key)
			{
			case Key.Escape:
				OnDismiss();
				e.Handled = true;
				break;
			case Key.Tab:
			{
				IInputElement inputElement = FocusManager.GetFocusManager(this)?.GetFocusedElement();
				if (inputElement != null)
				{
					KeyboardNavigationHandler.GetNext(inputElement, NavigationDirection.Next)?.Focus(NavigationMethod.Tab);
					e.Handled = true;
				}
				break;
			}
			case Key.Return:
				SetCurrentValue(DateProperty, _syncDate);
				OnConfirmed();
				e.Handled = true;
				break;
			}
			base.OnKeyDown(e);
		}

		/// <summary>
		/// Initializes the picker selectors.
		/// </summary>
		private void InitPicker()
		{
			TemplateItems? templateItems = _templateItems;
			if (templateItems.HasValue)
			{
				TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
				_suppressUpdateSelection = true;
				valueOrDefault._monthSelector.MaximumValue = 12;
				valueOrDefault._monthSelector.MinimumValue = 1;
				valueOrDefault._monthSelector.ItemFormat = MonthFormat;
				valueOrDefault._daySelector.ItemFormat = DayFormat;
				valueOrDefault._yearSelector.MaximumValue = MaxYear.Year;
				valueOrDefault._yearSelector.MinimumValue = MinYear.Year;
				valueOrDefault._yearSelector.ItemFormat = YearFormat;
				SetGrid(valueOrDefault);
				DateTimeOffset date = Date;
				if (DayVisible)
				{
					valueOrDefault._daySelector.FormatDate = date.Date;
					int daysInMonth = _calendar.GetDaysInMonth(date.Year, date.Month);
					valueOrDefault._daySelector.MaximumValue = daysInMonth;
					valueOrDefault._daySelector.MinimumValue = 1;
					valueOrDefault._daySelector.SelectedValue = date.Day;
				}
				if (MonthVisible)
				{
					valueOrDefault._monthSelector.SelectedValue = date.Month;
					valueOrDefault._monthSelector.FormatDate = date.Date;
				}
				if (YearVisible)
				{
					valueOrDefault._yearSelector.SelectedValue = date.Year;
					valueOrDefault._yearSelector.FormatDate = date.Date;
				}
				_suppressUpdateSelection = false;
				SetInitialFocus(valueOrDefault);
			}
		}

		private void SetGrid(TemplateItems items)
		{
			string shortDatePattern = CultureInfo.CurrentCulture.DateTimeFormat.ShortDatePattern;
			List<(Panel, int)> list = new List<(Panel, int)>();
			list.Add((items._monthHost, MonthVisible ? shortDatePattern.IndexOf("m", StringComparison.OrdinalIgnoreCase) : (-1)));
			list.Add((items._yearHost, YearVisible ? shortDatePattern.IndexOf("y", StringComparison.OrdinalIgnoreCase) : (-1)));
			list.Add((items._dayHost, DayVisible ? shortDatePattern.IndexOf("d", StringComparison.OrdinalIgnoreCase) : (-1)));
			list.Sort(((Panel?, int) x, (Panel?, int) y) => x.Item2 - y.Item2);
			items._pickerContainer.ColumnDefinitions.Clear();
			int num = 0;
			foreach (var item in list)
			{
				if (item.Item1 == null)
				{
					continue;
				}
				item.Item1.IsVisible = item.Item2 != -1;
				if (item.Item2 != -1)
				{
					if (num > 0)
					{
						items._pickerContainer.ColumnDefinitions.Add(new ColumnDefinition(0.0, GridUnitType.Auto));
					}
					items._pickerContainer.ColumnDefinitions.Add(new ColumnDefinition((item.Item1 == items._monthHost) ? 138 : 78, GridUnitType.Star));
					if (item.Item1.Parent == null)
					{
						items._pickerContainer.Children.Add(item.Item1);
					}
					Grid.SetColumn(item.Item1, num++ * 2);
				}
			}
			ConfigureSpacer(items._firstSpacer, num > 1);
			ConfigureSpacer(items._secondSpacer, num > 2);
			static void ConfigureSpacer(Control? spacer, bool visible)
			{
				if (spacer != null)
				{
					Grid.SetColumn(spacer, visible ? 1 : 0);
					spacer.IsVisible = visible;
				}
			}
		}

		private void SetInitialFocus(TemplateItems items)
		{
			int num = (MonthVisible ? Grid.GetColumn(items._monthHost) : int.MaxValue);
			int num2 = (DayVisible ? Grid.GetColumn(items._dayHost) : int.MaxValue);
			int num3 = (YearVisible ? Grid.GetColumn(items._yearHost) : int.MaxValue);
			if (num < num2 && num < num3)
			{
				items._monthSelector.Focus(NavigationMethod.Pointer);
			}
			else if (num2 < num && num2 < num3)
			{
				items._monthSelector.Focus(NavigationMethod.Pointer);
			}
			else if (num3 < num && num3 < num2)
			{
				items._yearSelector.Focus(NavigationMethod.Pointer);
			}
		}

		private void OnDismissButtonClicked(object? sender, RoutedEventArgs e)
		{
			OnDismiss();
		}

		private void OnAcceptButtonClicked(object? sender, RoutedEventArgs e)
		{
			SetCurrentValue(DateProperty, _syncDate);
			OnConfirmed();
		}

		private void OnSelectorButtonClick(DateTimePickerPanelType type, SpinDirection direction)
		{
			DateTimePickerPanel dateTimePickerPanel = type switch
			{
				DateTimePickerPanelType.Month => _templateItems?._monthSelector, 
				DateTimePickerPanelType.Day => _templateItems?._daySelector, 
				DateTimePickerPanelType.Year => _templateItems?._yearSelector, 
				_ => throw new NotImplementedException(), 
			};
			switch (direction)
			{
			case SpinDirection.Increase:
				dateTimePickerPanel?.ScrollDown();
				break;
			case SpinDirection.Decrease:
				dateTimePickerPanel?.ScrollUp();
				break;
			default:
				throw new NotImplementedException();
			}
		}

		private void OnYearChanged(object? sender, EventArgs e)
		{
			if (_suppressUpdateSelection)
			{
				return;
			}
			TemplateItems? templateItems = _templateItems;
			if (!templateItems.HasValue)
			{
				return;
			}
			TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
			int daysInMonth = _calendar.GetDaysInMonth(valueOrDefault._yearSelector.SelectedValue, _syncDate.Month);
			DateTimeOffset dateTimeOffset = (_syncDate = new DateTimeOffset(valueOrDefault._yearSelector.SelectedValue, _syncDate.Month, (_syncDate.Day > daysInMonth) ? daysInMonth : _syncDate.Day, 0, 0, 0, _syncDate.Offset));
			if (DayVisible && _syncDate.Month == 2)
			{
				_suppressUpdateSelection = true;
				valueOrDefault._daySelector.FormatDate = dateTimeOffset.Date;
				if (valueOrDefault._daySelector.MaximumValue != daysInMonth)
				{
					valueOrDefault._daySelector.MaximumValue = daysInMonth;
				}
				else
				{
					valueOrDefault._daySelector.RefreshItems();
				}
				_suppressUpdateSelection = false;
			}
		}

		private void OnDayChanged(object? sender, EventArgs e)
		{
			if (!_suppressUpdateSelection)
			{
				TemplateItems? templateItems = _templateItems;
				if (templateItems.HasValue)
				{
					TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
					_syncDate = new DateTimeOffset(_syncDate.Year, _syncDate.Month, valueOrDefault._daySelector.SelectedValue, 0, 0, 0, _syncDate.Offset);
				}
			}
		}

		private void OnMonthChanged(object? sender, EventArgs e)
		{
			if (_suppressUpdateSelection)
			{
				return;
			}
			TemplateItems? templateItems = _templateItems;
			if (!templateItems.HasValue)
			{
				return;
			}
			TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
			int daysInMonth = _calendar.GetDaysInMonth(_syncDate.Year, valueOrDefault._monthSelector.SelectedValue);
			DateTimeOffset syncDate = new DateTimeOffset(_syncDate.Year, valueOrDefault._monthSelector.SelectedValue, (_syncDate.Day > daysInMonth) ? daysInMonth : _syncDate.Day, 0, 0, 0, _syncDate.Offset);
			if (!DayVisible)
			{
				_syncDate = syncDate;
				return;
			}
			_suppressUpdateSelection = true;
			valueOrDefault._daySelector.FormatDate = syncDate.Date;
			_syncDate = syncDate;
			if (valueOrDefault._daySelector.MaximumValue != daysInMonth)
			{
				valueOrDefault._daySelector.MaximumValue = daysInMonth;
			}
			else
			{
				valueOrDefault._daySelector.RefreshItems();
			}
			_suppressUpdateSelection = false;
		}

		internal double GetOffsetForPopup()
		{
			TemplateItems? templateItems = _templateItems;
			if (templateItems.HasValue)
			{
				TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
				double height = valueOrDefault._acceptButton.Bounds.Height;
				return (0.0 - (base.MaxHeight - height)) / 2.0 - valueOrDefault._monthSelector.ItemHeight / 2.0;
			}
			return 0.0;
		}
	}
	/// <summary>
