		public static readonly StyledProperty<int> MinuteIncrementProperty = AvaloniaProperty.Register<TimePicker, int>("MinuteIncrement", 1, inherits: false, BindingMode.OneWay, null, CoerceMinuteIncrement);

		/// <summary>
