		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_templateItems = new TemplateItems
			{
				_pickerContainer = e.NameScope.Get<Grid>("PART_PickerContainer"),
				_periodHost = e.NameScope.Get<Panel>("PART_PeriodHost"),
				_secondHost = e.NameScope.Find<Panel>("PART_SecondHost"),
				_hourSelector = e.NameScope.Get<DateTimePickerPanel>("PART_HourSelector"),
				_minuteSelector = e.NameScope.Get<DateTimePickerPanel>("PART_MinuteSelector"),
				_secondSelector = e.NameScope.Find<DateTimePickerPanel>("PART_SecondSelector"),
				_periodSelector = e.NameScope.Get<DateTimePickerPanel>("PART_PeriodSelector"),
				_secondSpacer = e.NameScope.Get<Control>("PART_SecondSpacer"),
				_thirdSpacer = e.NameScope.Find<Control>("PART_ThirdSpacer"),
				_acceptButton = e.NameScope.Get<Button>("PART_AcceptButton"),
				_hourUpButton = SelectorButton("PART_HourUpButton", DateTimePickerPanelType.Hour, SpinDirection.Decrease),
				_hourDownButton = SelectorButton("PART_HourDownButton", DateTimePickerPanelType.Hour, SpinDirection.Increase),
				_minuteUpButton = SelectorButton("PART_MinuteUpButton", DateTimePickerPanelType.Minute, SpinDirection.Decrease),
				_minuteDownButton = SelectorButton("PART_MinuteDownButton", DateTimePickerPanelType.Minute, SpinDirection.Increase),
				_secondUpButton = SelectorButton("PART_SecondUpButton", DateTimePickerPanelType.Second, SpinDirection.Decrease),
				_secondDownButton = SelectorButton("PART_SecondDownButton", DateTimePickerPanelType.Second, SpinDirection.Increase),
				_periodUpButton = SelectorButton("PART_PeriodUpButton", DateTimePickerPanelType.TimePeriod, SpinDirection.Decrease),
				_periodDownButton = SelectorButton("PART_PeriodDownButton", DateTimePickerPanelType.TimePeriod, SpinDirection.Increase),
				_dismissButton = e.NameScope.Find<Button>("PART_DismissButton")
			};
			_templateItems.Value._acceptButton.Click += OnAcceptButtonClicked;
			Button dismissButton = _templateItems.Value._dismissButton;
			if (dismissButton != null)
			{
				dismissButton.Click += OnDismissButtonClicked;
			}
			InitPicker();
			Button? SelectorButton(string name, DateTimePickerPanelType type, SpinDirection direction)
			{
				Button button = e.NameScope.Find<Button>(name);
				if (button != null)
				{
					button.Click += delegate
					{
						OnSelectorButtonClick(type, direction);
					};
					return button;
				}
				return null;
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == MinuteIncrementProperty || change.Property == SecondIncrementProperty || change.Property == ClockIdentifierProperty || change.Property == UseSecondsProperty || change.Property == TimeProperty)
			{
				InitPicker();
			}
		}

		protected override void OnKeyDown(KeyEventArgs e)
		{
			switch (e.Key)
			{
			case Key.Escape:
				OnDismiss();
				e.Handled = true;
				break;
			case Key.Tab:
			{
				IInputElement inputElement = FocusManager.GetFocusManager(this)?.GetFocusedElement();
				if (inputElement != null)
				{
					KeyboardNavigationHandler.GetNext(inputElement, NavigationDirection.Next)?.Focus(NavigationMethod.Tab);
					e.Handled = true;
				}
				break;
			}
			case Key.Return:
				OnConfirmed();
				e.Handled = true;
				break;
			}
			base.OnKeyDown(e);
		}

		protected override void OnConfirmed()
		{
			TemplateItems? templateItems = _templateItems;
			if (templateItems.HasValue)
			{
				TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
				int num = valueOrDefault._hourSelector.SelectedValue;
				int selectedValue = valueOrDefault._minuteSelector.SelectedValue;
				int num2 = valueOrDefault._secondSelector?.SelectedValue ?? 0;
				int selectedValue2 = valueOrDefault._periodSelector.SelectedValue;
				if (ClockIdentifier == "12HourClock")
				{
					num = ((selectedValue2 != 1) ? ((selectedValue2 != 0 || num != 12) ? num : 0) : ((num == 12) ? 12 : (num + 12)));
				}
				SetCurrentValue(TimeProperty, new TimeSpan(num, selectedValue, UseSeconds ? num2 : 0));
			}
			base.OnConfirmed();
		}

		private void InitPicker()
		{
			TemplateItems? templateItems = _templateItems;
			if (templateItems.HasValue)
			{
				TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
				bool flag = ClockIdentifier == "12HourClock";
				valueOrDefault._hourSelector.MaximumValue = (flag ? 12 : 23);
				valueOrDefault._hourSelector.MinimumValue = (flag ? 1 : 0);
				valueOrDefault._hourSelector.ItemFormat = "%h";
				int hours = Time.Hours;
				valueOrDefault._hourSelector.SelectedValue = ((!flag) ? hours : ((hours > 12) ? (hours - 12) : ((hours == 0) ? 12 : hours)));
				valueOrDefault._minuteSelector.MaximumValue = 59;
				valueOrDefault._minuteSelector.MinimumValue = 0;
				valueOrDefault._minuteSelector.Increment = MinuteIncrement;
				valueOrDefault._minuteSelector.ItemFormat = "mm";
				valueOrDefault._minuteSelector.SelectedValue = Time.Minutes;
				DateTimePickerPanel secondSelector = valueOrDefault._secondSelector;
				if (secondSelector != null)
				{
					secondSelector.MaximumValue = 59;
					secondSelector.MinimumValue = 0;
					secondSelector.Increment = SecondIncrement;
					secondSelector.ItemFormat = "ss";
					secondSelector.SelectedValue = Time.Seconds;
				}
				valueOrDefault._periodSelector.MaximumValue = 1;
				valueOrDefault._periodSelector.MinimumValue = 0;
				valueOrDefault._periodSelector.SelectedValue = ((hours >= 12) ? 1 : 0);
				SetGrid(valueOrDefault);
				valueOrDefault._hourSelector.Focus(NavigationMethod.Pointer);
			}
		}

		private void SetGrid(TemplateItems items)
		{
			bool flag = ClockIdentifier == "24HourClock";
			ColumnDefinitions columnDefinitions = new ColumnDefinitions
			{
				new ColumnDefinition(GridLength.Star),
				new ColumnDefinition(GridLength.Auto),
				new ColumnDefinition(GridLength.Star)
			};
			if (items._secondHost != null && items._thirdSpacer != null)
			{
				if (UseSeconds)
				{
					columnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
					columnDefinitions.Add(new ColumnDefinition(GridLength.Star));
				}
				items._secondSpacer.IsVisible = UseSeconds;
				items._secondHost.IsVisible = UseSeconds;
				items._thirdSpacer.IsVisible = !flag;
				items._periodHost.IsVisible = !flag;
				int num = (UseSeconds ? 6 : 4);
				Grid.SetColumn(items._secondSpacer, UseSeconds ? 3 : 0);
				Grid.SetColumn(items._secondHost, UseSeconds ? 4 : 0);
				Grid.SetColumn(items._thirdSpacer, (!flag) ? (num - 1) : 0);
				Grid.SetColumn(items._periodHost, (!flag) ? num : 0);
			}
			else
			{
				items._secondSpacer.IsVisible = !flag;
				items._periodHost.IsVisible = !flag;
				Grid.SetColumn(items._secondSpacer, (!flag) ? 3 : 0);
				Grid.SetColumn(items._periodHost, (!flag) ? 4 : 0);
			}
			if (!flag)
			{
				columnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
				columnDefinitions.Add(new ColumnDefinition(GridLength.Star));
			}
			items._pickerContainer.ColumnDefinitions = columnDefinitions;
		}

		private void OnDismissButtonClicked(object? sender, RoutedEventArgs e)
		{
			OnDismiss();
		}

		private void OnAcceptButtonClicked(object? sender, RoutedEventArgs e)
		{
			OnConfirmed();
		}

		private void OnSelectorButtonClick(DateTimePickerPanelType type, SpinDirection direction)
		{
			DateTimePickerPanel dateTimePickerPanel = type switch
			{
				DateTimePickerPanelType.Hour => _templateItems?._hourSelector, 
				DateTimePickerPanelType.Minute => _templateItems?._minuteSelector, 
				DateTimePickerPanelType.Second => _templateItems?._secondSelector, 
				DateTimePickerPanelType.TimePeriod => _templateItems?._periodSelector, 
				_ => throw new NotImplementedException(), 
			};
			switch (direction)
			{
			case SpinDirection.Increase:
				dateTimePickerPanel?.ScrollDown();
				break;
			case SpinDirection.Decrease:
				dateTimePickerPanel?.ScrollUp();
				break;
			default:
				throw new NotImplementedException();
			}
		}

		internal double GetOffsetForPopup()
		{
			TemplateItems? templateItems = _templateItems;
			if (templateItems.HasValue)
			{
				TemplateItems valueOrDefault = templateItems.GetValueOrDefault();
				double height = valueOrDefault._acceptButton.Bounds.Height;
				return (0.0 - (base.MaxHeight - height)) / 2.0 - valueOrDefault._hourSelector.ItemHeight / 2.0;
			}
			return 0.0;
		}
	}
