		public TimePickerSelectedValueChangedEventArgs(TimeSpan? old, TimeSpan? newT)
		{
			OldTime = old;
			NewTime = newT;
		}
	}
	/// <summary>
	/// Base class for controls which decorate a single child control.
	/// </summary>
	public class Decorator : Control
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Decorator.Child" /> property.
		/// </summary>
		public static readonly StyledProperty<Control?> ChildProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Decorator.Padding" /> property.
		/// </summary>
		public static readonly StyledProperty<Thickness> PaddingProperty;

		/// <summary>
		/// Gets or sets the decorated control.
		/// </summary>
		[Content]
		public Control? Child
		{
			get
			{
				return GetValue(ChildProperty);
			}
			set
			{
				SetValue(ChildProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets the padding to place around the <see cref="P:Avalonia.Controls.Decorator.Child" /> control.
		/// </summary>
		public Thickness Padding
		{
			get
			{
				return GetValue(PaddingProperty);
			}
			set
			{
				SetValue(PaddingProperty, value);
			}
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.Decorator" /> class.
		/// </summary>
		static Decorator()
		{
			ChildProperty = AvaloniaProperty.Register<Decorator, Control>("Child");
			PaddingProperty = AvaloniaProperty.Register<Decorator, Thickness>("Padding");
			Layoutable.AffectsMeasure<Decorator>(new AvaloniaProperty[2] { ChildProperty, PaddingProperty });
			ChildProperty.Changed.AddClassHandler(delegate(Decorator x, AvaloniaPropertyChangedEventArgs e)
			{
				x.ChildChanged(e);
			});
		}

		/// <inheritdoc />
		protected override Size MeasureOverride(Size availableSize)
		{
			return LayoutHelper.MeasureChild(Child, availableSize, Padding);
		}

		/// <inheritdoc />
		protected override Size ArrangeOverride(Size finalSize)
		{
			return LayoutHelper.ArrangeChild(Child, finalSize, Padding);
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Decorator.Child" /> property changes.
		/// </summary>
		/// <param name="e">The event args.</param>
		private void ChildChanged(AvaloniaPropertyChangedEventArgs e)
		{
			Control control = (Control)e.OldValue;
			Control control2 = (Control)e.NewValue;
			if (control != null)
			{
				((ISetLogicalParent)control).SetParent((ILogical?)null);
				base.LogicalChildren.Clear();
				base.VisualChildren.Remove(control);
			}
			if (control2 != null)
			{
				((ISetLogicalParent)control2).SetParent((ILogical?)this);
				base.VisualChildren.Add(control2);
				base.LogicalChildren.Add(control2);
			}
		}
	}
	/// <summary>
	/// DefinitionBase provides core functionality used internally by Grid
	/// and ColumnDefinitionCollection / RowDefinitionCollection
	/// </summary>
	public abstract class DefinitionBase : AvaloniaObject
	{
		[Flags]
		private enum Flags : byte
		{
			UseSharedMinimum = 0x20,
			LayoutWasUpdated = 0x40
		}

		/// <summary>
		/// Collection of shared states objects for a single scope
		/// </summary>
		internal class SharedSizeScope
		{
			private Hashtable _registry = new Hashtable();

			/// <summary>
			/// Returns SharedSizeState object for a given group.
			/// Creates a new StatedState object if necessary.
			/// </summary>
			internal SharedSizeState EnsureSharedState(string sharedSizeGroup)
			{
				SharedSizeState sharedSizeState = _registry[sharedSizeGroup] as SharedSizeState;
				if (sharedSizeState == null)
				{
					sharedSizeState = new SharedSizeState(this, sharedSizeGroup);
					_registry[sharedSizeGroup] = sharedSizeState;
				}
				return sharedSizeState;
			}

			/// <summary>
			/// Removes an entry in the registry by the given key.
			/// </summary>
			internal void Remove(object key)
			{
				_registry.Remove(key);
			}
		}

		/// <summary>
		/// Implementation of per shared group state object
		/// </summary>
		internal class SharedSizeState
		{
			private readonly SharedSizeScope _sharedSizeScope;

			private readonly string _sharedSizeGroupId;

			private readonly List<DefinitionBase> _registry;

			private readonly EventHandler _layoutUpdated;

			private Control? _layoutUpdatedHost;

			private bool _broadcastInvalidation;

			private bool _userSizeValid;

			private GridLength _userSize;

			private double _minSize;

			/// <summary>
			/// DefinitionBase's specific code.
			/// </summary>
			internal double MinSize
			{
				get
				{
					if (!_userSizeValid)
					{
						EnsureUserSizeValid();
					}
					return _minSize;
				}
			}

			/// <summary>
			/// DefinitionBase's specific code.
			/// </summary>
			internal GridLength UserSize
			{
				get
				{
					if (!_userSizeValid)
					{
						EnsureUserSizeValid();
					}
					return _userSize;
				}
			}

			/// <summary>
			/// Default ctor.
			/// </summary>
			internal SharedSizeState(SharedSizeScope sharedSizeScope, string sharedSizeGroupId)
			{
				_sharedSizeScope = sharedSizeScope;
				_sharedSizeGroupId = sharedSizeGroupId;
				_registry = new List<DefinitionBase>();
				_layoutUpdated = OnLayoutUpdated;
				_broadcastInvalidation = true;
			}

			/// <summary>
			/// Adds / registers a definition instance.
			/// </summary>
			internal void AddMember(DefinitionBase member)
			{
				_registry.Add(member);
				Invalidate();
			}

			/// <summary>
			/// Removes / un-registers a definition instance.
			/// </summary>
			/// <remarks>
			/// If the collection of registered definitions becomes empty
			/// instantiates self removal from owner's collection.
			/// </remarks>
			internal void RemoveMember(DefinitionBase member)
			{
				Invalidate();
				_registry.Remove(member);
				if (_registry.Count == 0)
				{
					_sharedSizeScope.Remove(_sharedSizeGroupId);
				}
			}

			/// <summary>
			/// Propagates invalidations for all registered definitions.
			/// Resets its own state.
			/// </summary>
			internal void Invalidate()
			{
				_userSizeValid = false;
				if (_broadcastInvalidation)
				{
					int i = 0;
					for (int count = _registry.Count; i < count; i++)
					{
						_registry[i].Parent.Invalidate();
					}
					_broadcastInvalidation = false;
				}
			}

			/// <summary>
			/// Makes sure that one and only one layout updated handler is registered for this shared state.
			/// </summary>
			internal void EnsureDeferredValidation(Control layoutUpdatedHost)
			{
				if (_layoutUpdatedHost == null)
				{
					_layoutUpdatedHost = layoutUpdatedHost;
					_layoutUpdatedHost.LayoutUpdated += _layoutUpdated;
				}
			}

			private void EnsureUserSizeValid()
			{
				_userSize = new GridLength(1.0, GridUnitType.Auto);
				int i = 0;
				for (int count = _registry.Count; i < count; i++)
				{
					GridLength userSizeValueCache = _registry[i].UserSizeValueCache;
					if (userSizeValueCache.GridUnitType == GridUnitType.Pixel)
					{
						if (_userSize.GridUnitType == GridUnitType.Auto)
						{
							_userSize = userSizeValueCache;
						}
						else if (_userSize.Value < userSizeValueCache.Value)
						{
							_userSize = userSizeValueCache;
						}
					}
				}
				_minSize = (_userSize.IsAbsolute ? _userSize.Value : 0.0);
				_userSizeValid = true;
			}

			/// <summary>
			/// OnLayoutUpdated handler. Validates that all participating definitions
			/// have updated min size value. Forces another layout update cycle if needed.
			/// </summary>
			private void OnLayoutUpdated(object? sender, EventArgs e)
			{
				double num = 0.0;
				int i = 0;
				for (int count = _registry.Count; i < count; i++)
				{
					num = Math.Max(num, _registry[i].MinSize);
				}
				bool flag = !MathUtilities.AreClose(_minSize, num);
				int j = 0;
				for (int count2 = _registry.Count; j < count2; j++)
				{
					DefinitionBase definitionBase = _registry[j];
					bool flag2 = !MathUtilities.AreClose(definitionBase._minSize, num);
					if (!((!definitionBase.UseSharedMinimum) ? (!flag2) : ((!flag2) ? (definitionBase.LayoutWasUpdated && MathUtilities.GreaterThanOrClose(definitionBase._minSize, MinSize)) : (!flag))))
					{
						definitionBase.Parent.InvalidateMeasure();
					}
					else if (!MathUtilities.AreClose(num, definitionBase.SizeCache))
					{
						definitionBase.Parent.InvalidateArrange();
					}
					definitionBase.UseSharedMinimum = flag2;
					definitionBase.LayoutWasUpdated = false;
				}
				_minSize = num;
				_layoutUpdatedHost.LayoutUpdated -= _layoutUpdated;
				_layoutUpdatedHost = null;
				_broadcastInvalidation = true;
			}
		}

		private Flags _flags;

		internal int _parentIndex = -1;

		private Grid.LayoutTimeSizeType _sizeType;

