				return;
			}
			GridUnitType gridUnitType = ((GridLength)e.OldValue).GridUnitType;
			GridUnitType gridUnitType2 = ((GridLength)e.NewValue).GridUnitType;
			if (gridUnitType != gridUnitType2)
			{
