				control2.Measure(availableSize3);
				Size desiredSize2 = control2.DesiredSize;
				val2 = Math.Max(val2, num2 + desiredSize2.Height);
				val = Math.Max(val, num + desiredSize2.Width);
				num2 += desiredSize2.Height;
