					case Dock.Left:
					{
						double num3 = Math.Min(control.DesiredSize.Width, rect.Width);
						control.Arrange(rect.WithWidth(num3));
						num3 += HorizontalSpacing;
						rect = new Rect(rect.X + num3, rect.Y, Math.Max(0.0, rect.Width - num3), rect.Height);
						break;
					}
					case Dock.Top:
					{
						double num2 = Math.Min(control.DesiredSize.Height, rect.Height);
						control.Arrange(rect.WithHeight(num2));
						num2 += VerticalSpacing;
						rect = new Rect(rect.X, rect.Y + num2, rect.Width, Math.Max(0.0, rect.Height - num2));
						break;
					}
					case Dock.Right:
					{
						double num3 = Math.Min(control.DesiredSize.Width, rect.Width);
						control.Arrange(new Rect(rect.X + rect.Width - num3, rect.Y, num3, rect.Height));
						num3 += HorizontalSpacing;
						rect = rect.WithWidth(Math.Max(0.0, rect.Width - num3));
						break;
					}
					case Dock.Bottom:
					{
						double num2 = Math.Min(control.DesiredSize.Height, rect.Height);
						control.Arrange(new Rect(rect.X, rect.Y + rect.Height - num2, rect.Width, num2));
						num2 += VerticalSpacing;
						rect = rect.WithHeight(Math.Max(0.0, rect.Height - num2));
						break;
					}
					}
				}
			}
			if (LastChildFill && base.Children.Count > 0)
			{
				base.Children[base.Children.Count - 1].Arrange(new Rect(rect.X, rect.Y, rect.Width, rect.Height));
			}
			return finalSize;
		}
	}
