		/// </summary>
		public event EventHandler<RoutedEventArgs>? Collapsed
		{
			add
			{
				AddHandler(CollapsedEvent, value);
			}
			remove
			{
				RemoveHandler(CollapsedEvent, value);
			}
		}

		/// <summary>
		/// Occurs as the content area is closing.
		/// </summary>
		/// <remarks>
		/// The event args <see cref="P:Avalonia.Interactivity.CancelRoutedEventArgs.Cancel" /> property may be set to true to cancel the event
		/// and keep the control open (expanded).
		/// </remarks>
		public event EventHandler<CancelRoutedEventArgs>? Collapsing
		{
			add
			{
				AddHandler(CollapsingEvent, value);
			}
			remove
			{
				RemoveHandler(CollapsingEvent, value);
			}
		}

		/// <summary>
		/// Occurs after the <see cref="T:Avalonia.Controls.Expander" /> has opened to display both its header and content.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Expanded
		{
			add
			{
				AddHandler(ExpandedEvent, value);
			}
			remove
			{
				RemoveHandler(ExpandedEvent, value);
			}
		}

		/// <summary>
		/// Occurs as the content area is opening.
		/// </summary>
		/// <remarks>
		/// The event args <see cref="P:Avalonia.Interactivity.CancelRoutedEventArgs.Cancel" /> property may be set to true to cancel the event
		/// and keep the control closed (collapsed).
		/// </remarks>
		public event EventHandler<CancelRoutedEventArgs>? Expanding
		{
			add
			{
				AddHandler(ExpandingEvent, value);
			}
			remove
			{
				RemoveHandler(ExpandingEvent, value);
			}
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Expander" /> class.
		/// </summary>
		public Expander()
		{
			UpdatePseudoClasses();
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Expander.Collapsed" /> event.
		/// </summary>
		protected virtual void OnCollapsed(RoutedEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Expander.Collapsing" /> event.
		/// </summary>
		protected virtual void OnCollapsing(CancelRoutedEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Expander.Expanded" /> event.
		/// </summary>
		protected virtual void OnExpanded(RoutedEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Expander.Expanding" /> event.
		/// </summary>
		protected virtual void OnExpanding(CancelRoutedEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		/// <summary>
		/// Starts the content transition (if set) and invokes the <see cref="E:Avalonia.Controls.Expander.Expanded" />
		/// and <see cref="E:Avalonia.Controls.Expander.Collapsed" /> events when completed.
		/// </summary>
		private async void StartContentTransition()
		{
			if (base.Content != null && ContentTransition != null)
			{
				Visual presenter = base.Presenter;
				if (presenter != null)
				{
					bool flag = ExpandDirection == ExpandDirection.Left || ExpandDirection == ExpandDirection.Up;
					_lastTransitionCts?.Cancel();
					_lastTransitionCts = new CancellationTokenSource();
					if (!IsExpanded)
					{
						await ContentTransition.Start(presenter, null, !flag, _lastTransitionCts.Token);
					}
					else
					{
						await ContentTransition.Start(null, presenter, flag, _lastTransitionCts.Token);
					}
				}
			}
			Dispatcher.UIThread.Post(delegate
			{
				if (IsExpanded)
				{
					OnExpanded(new RoutedEventArgs(ExpandedEvent, this));
				}
				else
				{
					OnCollapsed(new RoutedEventArgs(CollapsedEvent, this));
				}
			});
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (!_ignorePropertyChanged)
			{
				if (change.Property == ExpandDirectionProperty)
				{
					UpdatePseudoClasses();
				}
				else if (change.Property == IsExpandedProperty)
				{
					StartContentTransition();
					UpdatePseudoClasses();
				}
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new ExpanderAutomationPeer(this);
		}

		/// <summary>
		/// Updates the visual state of the control by applying latest PseudoClasses.
		/// </summary>
		private void UpdatePseudoClasses()
		{
			ExpandDirection expandDirection = ExpandDirection;
			base.PseudoClasses.Set(":up", expandDirection == ExpandDirection.Up);
			base.PseudoClasses.Set(":down", expandDirection == ExpandDirection.Down);
			base.PseudoClasses.Set(":left", expandDirection == ExpandDirection.Left);
			base.PseudoClasses.Set(":right", expandDirection == ExpandDirection.Right);
			base.PseudoClasses.Set(":expanded", IsExpanded);
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Expander.IsExpanded" /> property has to be coerced.
		/// </summary>
		/// <param name="value">The value to coerce.</param>
		protected virtual bool OnCoerceIsExpanded(bool value)
		{
			CancelRoutedEventArgs e;
			if (value)
			{
				e = new CancelRoutedEventArgs(ExpandingEvent, this);
				OnExpanding(e);
			}
			else
			{
				e = new CancelRoutedEventArgs(CollapsingEvent, this);
				OnCollapsing(e);
			}
			if (e.Cancel)
			{
				_ignorePropertyChanged = true;
				RaisePropertyChanged(IsExpandedProperty, value, !value, BindingPriority.LocalValue, isEffectiveValue: true);
				_ignorePropertyChanged = false;
				return !value;
			}
			return value;
		}

		/// <summary>
		/// Coerces/validates the <see cref="P:Avalonia.Controls.Expander.IsExpanded" /> property value.
		/// </summary>
		/// <param name="instance">The <see cref="T:Avalonia.Controls.Expander" /> instance.</param>
		/// <param name="value">The value to coerce.</param>
		/// <returns>The coerced/validated value.</returns>
		private static bool CoerceIsExpanded(AvaloniaObject instance, bool value)
		{
			if (instance is Expander expander)
			{
				return expander.OnCoerceIsExpanded(value);
			}
			return value;
		}
	}
	public class ExperimentalAcrylicBorder : Decorator
	{
		public static readonly StyledProperty<CornerRadius> CornerRadiusProperty;

		public static readonly StyledProperty<ExperimentalAcrylicMaterial> MaterialProperty;

		private IDisposable? _subscription;

		private IDisposable? _materialSubscription;

		/// <summary>
		/// Gets or sets the radius of the border rounded corners.
		/// </summary>
		public CornerRadius CornerRadius
		{
			get
			{
				return GetValue(CornerRadiusProperty);
			}
			set
			{
				SetValue(CornerRadiusProperty, value);
			}
		}

		public ExperimentalAcrylicMaterial Material
		{
			get
			{
				return GetValue(MaterialProperty);
			}
			set
			{
				SetValue(MaterialProperty, value);
			}
		}

		static ExperimentalAcrylicBorder()
		{
			CornerRadiusProperty = Border.CornerRadiusProperty.AddOwner<ExperimentalAcrylicBorder>();
			MaterialProperty = AvaloniaProperty.Register<ExperimentalAcrylicBorder, ExperimentalAcrylicMaterial>("Material");
			Visual.AffectsRender<ExperimentalAcrylicBorder>(new AvaloniaProperty[2] { MaterialProperty, CornerRadiusProperty });
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			TopLevel tl = (TopLevel)e.Root;
			_subscription = tl.GetObservable(TopLevel.ActualTransparencyLevelProperty).Subscribe(delegate(WindowTransparencyLevel x)
			{
				if (tl.PlatformImpl != null)
				{
					if (x == WindowTransparencyLevel.Transparent || x == WindowTransparencyLevel.None)
					{
						Material.PlatformTransparencyCompensationLevel = tl.PlatformImpl.AcrylicCompensationLevels.TransparentLevel;
					}
					else if (x == WindowTransparencyLevel.Blur)
					{
						Material.PlatformTransparencyCompensationLevel = tl.PlatformImpl.AcrylicCompensationLevels.BlurLevel;
					}
					else if (x == WindowTransparencyLevel.AcrylicBlur)
					{
						Material.PlatformTransparencyCompensationLevel = tl.PlatformImpl.AcrylicCompensationLevels.AcrylicBlurLevel;
					}
				}
			});
			UpdateMaterialSubscription();
		}

		private void UpdateMaterialSubscription()
		{
			_materialSubscription?.Dispose();
			_materialSubscription = null;
			if (base.CompositionVisual != null && Material != null)
			{
				_materialSubscription = Observable.FromEventPattern(delegate(EventHandler<AvaloniaPropertyChangedEventArgs> h)
				{
					Material.PropertyChanged += h;
				}, delegate(EventHandler<AvaloniaPropertyChangedEventArgs> h)
				{
					Material.PropertyChanged -= h;
				}).Subscribe(delegate
				{
					UpdateMaterialSubscription();
				});
				SyncMaterial(base.CompositionVisual);
			}
		}

		private void SyncMaterial(CompositionVisual? visual)
		{
			if (visual is CompositionExperimentalAcrylicVisual compositionExperimentalAcrylicVisual)
			{
				compositionExperimentalAcrylicVisual.CornerRadius = CornerRadius;
				compositionExperimentalAcrylicVisual.Material = (ImmutableExperimentalAcrylicMaterial)(object)Material.ToImmutable();
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			if (change.Property == MaterialProperty)
			{
				UpdateMaterialSubscription();
			}
			if (change.Property == CornerRadiusProperty)
			{
				SyncMaterial(base.CompositionVisual);
			}
			base.OnPropertyChanged(change);
		}

		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			UpdateMaterialSubscription();
			_subscription?.Dispose();
		}

		private protected override CompositionDrawListVisual CreateCompositionVisual(Compositor compositor)
		{
			CompositionExperimentalAcrylicVisual compositionExperimentalAcrylicVisual = new CompositionExperimentalAcrylicVisual(compositor, this);
			SyncMaterial(compositionExperimentalAcrylicVisual);
			return compositionExperimentalAcrylicVisual;
		}

		/// <summary>
		/// Measures the control.
		/// </summary>
		/// <param name="availableSize">The available size.</param>
		/// <returns>The desired size of the control.</returns>
		protected override Size MeasureOverride(Size availableSize)
		{
			return LayoutHelper.MeasureChild(base.Child, availableSize, base.Padding);
		}

		/// <summary>
		/// Arranges the control's child.
		/// </summary>
		/// <param name="finalSize">The size allocated to the control.</param>
		/// <returns>The space taken.</returns>
		protected override Size ArrangeOverride(Size finalSize)
		{
			return LayoutHelper.ArrangeChild(base.Child, finalSize, base.Padding);
		}
	}
