		/// <summary>
		/// Returns *-weight, adjusted for scale computed during Phase 1
		/// </summary>
		private static double StarWeight(DefinitionBase def, double scale)
		{
			if (scale < 0.0)
			{
				if (!double.IsPositiveInfinity(def.UserSize.Value))
				{
