	/// Displays a <see cref="T:Avalonia.Media.Imaging.Bitmap" /> image.
	/// </summary>
	public class Image : Control
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Image.Source" /> property.
		/// </summary>
		public static readonly StyledProperty<IImage?> SourceProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Image.BlendMode" /> property.
		/// </summary>
		public static readonly StyledProperty<BitmapBlendingMode> BlendModeProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Image.Stretch" /> property.
		/// </summary>
		public static readonly StyledProperty<Stretch> StretchProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Image.StretchDirection" /> property.
		/// </summary>
		public static readonly StyledProperty<StretchDirection> StretchDirectionProperty;

		/// <summary>
		/// Gets or sets the image that will be displayed.
		/// </summary>
		[Content]
		public IImage? Source
		{
			get
			{
				return GetValue(SourceProperty);
			}
			set
			{
				SetValue(SourceProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets the blend mode for the image.
		/// </summary>
		public BitmapBlendingMode BlendMode
		{
			get
			{
				return GetValue(BlendModeProperty);
			}
			set
			{
				SetValue(BlendModeProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets a value controlling how the image will be stretched.
		/// </summary>
		public Stretch Stretch
		{
			get
			{
				return GetValue(StretchProperty);
			}
			set
			{
				SetValue(StretchProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets a value controlling in what direction the image will be stretched.
		/// </summary>
		public StretchDirection StretchDirection
		{
			get
			{
				return GetValue(StretchDirectionProperty);
			}
			set
			{
				SetValue(StretchDirectionProperty, value);
			}
		}

		/// <inheritdoc />
		protected override bool BypassFlowDirectionPolicies => true;

		static Image()
		{
			SourceProperty = AvaloniaProperty.Register<Image, IImage>("Source");
			BlendModeProperty = AvaloniaProperty.Register<Image, BitmapBlendingMode>("BlendMode", BitmapBlendingMode.Unspecified);
			StretchProperty = AvaloniaProperty.Register<Image, Stretch>("Stretch", Stretch.Uniform);
			StretchDirectionProperty = AvaloniaProperty.Register<Image, StretchDirection>("StretchDirection", StretchDirection.Both);
			Visual.AffectsRender<Image>(new AvaloniaProperty[4] { SourceProperty, StretchProperty, StretchDirectionProperty, BlendModeProperty });
			Layoutable.AffectsMeasure<Image>(new AvaloniaProperty[3] { SourceProperty, StretchProperty, StretchDirectionProperty });
			AutomationProperties.ControlTypeOverrideProperty.OverrideDefaultValue<Image>(AutomationControlType.Image);
		}

		/// <summary>
		/// Renders the control.
		/// </summary>
		/// <param name="context">The drawing context.</param>
		public sealed override void Render(DrawingContext context)
		{
			IImage source = Source;
			if (source != null && base.Bounds.Width > 0.0 && base.Bounds.Height > 0.0)
			{
				Rect rect = new Rect(base.Bounds.Size);
				Size size = source.Size;
				Vector vector = Stretch.CalculateScaling(base.Bounds.Size, size, StretchDirection);
				Size size2 = size * vector;
				Rect destRect = rect.CenterRect(new Rect(size2)).Intersect(rect);
				Rect sourceRect = new Rect(size).CenterRect(new Rect(destRect.Size / vector));
				using (context.PushRenderOptions(base.RenderOptions with
				{
					BitmapBlendingMode = BlendMode
				}))
				{
					context.DrawImage(source, sourceRect, destRect);
				}
			}
		}

		/// <summary>
		/// Measures the control.
		/// </summary>
		/// <param name="availableSize">The available size.</param>
		/// <returns>The desired size of the control.</returns>
		protected override Size MeasureOverride(Size availableSize)
		{
			IImage source = Source;
			Size result = default(Size);
			if (source != null)
			{
				return Stretch.CalculateSize(availableSize, source.Size, StretchDirection);
			}
			return result;
		}

		/// <inheritdoc />
		protected override Size ArrangeOverride(Size finalSize)
		{
			IImage source = Source;
			if (source != null)
			{
				Size size = source.Size;
				return Stretch.CalculateSize(finalSize, size);
			}
			return default(Size);
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new ImageAutomationPeer(this);
		}
	}
