		/// <inheritdoc />
		protected override void OnGotFocus(GotFocusEventArgs e)
		{
			if (HidePromptOnLeave && MaskProvider != null)
			{
				SetCurrentValue(TextBox.TextProperty, MaskProvider.ToDisplayString());
			}
			base.OnGotFocus(e);
		}

		/// <inheritdoc />
		protected override async void OnKeyDown(KeyEventArgs e)
		{
			if (MaskProvider == null)
			{
				base.OnKeyDown(e);
				return;
			}
			PlatformHotkeyConfiguration platformHotkeyConfiguration = Application.Current.PlatformSettings?.HotkeyConfiguration;
			if (platformHotkeyConfiguration != null && Match(platformHotkeyConfiguration.Paste))
			{
				IClipboard clipboard = TopLevel.GetTopLevel(this)?.Clipboard;
				if (clipboard == null)
				{
					return;
				}
				string text = null;
				try
				{
					text = await clipboard.TryGetTextAsync();
				}
				catch (TimeoutException)
				{
				}
				if (text == null)
				{
					return;
				}
				string text2 = text;
				foreach (char input in text2)
				{
					int nextCharacterPosition = GetNextCharacterPosition(base.CaretIndex);
					if (MaskProvider.InsertAt(input, nextCharacterPosition))
					{
						SetCurrentValue(TextBox.CaretIndexProperty, nextCharacterPosition + 1);
					}
				}
				SetCurrentValue(TextBox.TextProperty, MaskProvider.ToDisplayString());
				e.Handled = true;
				return;
			}
			if (e.Key != Key.Back)
			{
				base.OnKeyDown(e);
			}
			switch (e.Key)
			{
			case Key.Delete:
				if (base.CaretIndex < base.Text?.Length)
				{
					if (MaskProvider.RemoveAt(base.CaretIndex))
					{
						RefreshText(MaskProvider, base.CaretIndex);
					}
					e.Handled = true;
				}
				break;
			case Key.Space:
				if ((!MaskProvider.ResetOnSpace || string.IsNullOrEmpty(base.SelectedText)) && MaskProvider.InsertAt(" ", base.CaretIndex))
				{
					RefreshText(MaskProvider, base.CaretIndex);
				}
				e.Handled = true;
				break;
			case Key.Back:
				if (base.CaretIndex > 0)
				{
					MaskProvider.RemoveAt(base.CaretIndex - 1);
				}
				RefreshText(MaskProvider, base.CaretIndex - 1);
				e.Handled = true;
				break;
			}
			bool Match(List<KeyGesture> gestures)
			{
				return gestures.Any((KeyGesture g) => g.Matches(e));
			}
		}

		/// <inheritdoc />
		protected override void OnLostFocus(RoutedEventArgs e)
		{
			if (HidePromptOnLeave && MaskProvider != null)
			{
				SetCurrentValue(TextBox.TextProperty, MaskProvider.ToString(!HidePromptOnLeave, includeLiterals: true));
			}
			base.OnLostFocus(e);
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			if (change.Property == MaskProperty)
			{
				UpdateMaskProvider();
				if (!string.IsNullOrEmpty(Mask))
				{
					string mask = Mask;
					for (int i = 0; i < mask.Length; i++)
					{
						if (!MaskedTextProvider.IsValidMaskChar(mask[i]))
						{
							throw new ArgumentException("Specified mask contains characters that are not valid.");
						}
					}
				}
			}
			else if (change.Property == TextBox.PasswordCharProperty)
			{
				if (MaskProvider != null && MaskProvider.PasswordChar != base.PasswordChar)
				{
					UpdateMaskProvider();
				}
			}
			else if (change.Property == PromptCharProperty)
			{
				if (MaskProvider != null && MaskProvider.PromptChar != PromptChar)
				{
					UpdateMaskProvider();
				}
			}
			else if (change.Property == ResetOnPromptProperty)
			{
				if (MaskProvider != null)
				{
					bool newValue = change.GetNewValue<bool>();
					MaskProvider.ResetOnPrompt = newValue;
				}
			}
			else if (change.Property == ResetOnSpaceProperty)
			{
				if (MaskProvider != null)
				{
					bool newValue2 = change.GetNewValue<bool>();
					MaskProvider.ResetOnSpace = newValue2;
				}
			}
			else if ((change.Property == AsciiOnlyProperty && MaskProvider != null && MaskProvider.AsciiOnly != AsciiOnly) || (change.Property == CultureProperty && MaskProvider != null && !MaskProvider.Culture.Equals(Culture)))
			{
				UpdateMaskProvider();
			}
			base.OnPropertyChanged(change);
			void UpdateMaskProvider()
			{
				MaskProvider = new MaskedTextProvider(Mask, Culture, allowPromptAsInput: true, PromptChar, base.PasswordChar, AsciiOnly)
				{
					ResetOnSpace = ResetOnSpace,
					ResetOnPrompt = ResetOnPrompt
				};
				if (base.Text != null)
				{
					MaskProvider.Set(base.Text);
				}
				RefreshText(MaskProvider, 0);
			}
		}

		/// <inheritdoc />
		protected override void OnTextInput(TextInputEventArgs e)
		{
			_ignoreTextChanges = true;
			try
			{
				if (base.IsReadOnly)
				{
					e.Handled = true;
					base.OnTextInput(e);
					return;
				}
				if (MaskProvider == null)
				{
					base.OnTextInput(e);
					return;
				}
				if (((MaskProvider.ResetOnSpace && e.Text == " ") || (MaskProvider.ResetOnPrompt && e.Text == MaskProvider.PromptChar.ToString())) && !string.IsNullOrEmpty(base.SelectedText) && ((base.SelectionStart > base.SelectionEnd) ? MaskProvider.RemoveAt(base.SelectionEnd, base.SelectionStart - 1) : MaskProvider.RemoveAt(base.SelectionStart, base.SelectionEnd - 1)))
				{
					base.SelectedText = string.Empty;
				}
				if (base.CaretIndex < base.Text?.Length)
				{
					SetCurrentValue(TextBox.CaretIndexProperty, GetNextCharacterPosition(base.CaretIndex));
					if (MaskProvider.InsertAt(e.Text, base.CaretIndex))
					{
						base.CaretIndex++;
					}
					int nextCharacterPosition = GetNextCharacterPosition(base.CaretIndex);
					if (nextCharacterPosition != 0 && base.CaretIndex != base.Text.Length)
					{
						SetCurrentValue(TextBox.CaretIndexProperty, nextCharacterPosition);
					}
				}
				RefreshText(MaskProvider, base.CaretIndex);
				e.Handled = true;
				base.OnTextInput(e);
			}
			finally
			{
				_ignoreTextChanges = false;
			}
		}

		private int GetNextCharacterPosition(int startPosition)
		{
			if (MaskProvider != null)
			{
				int result = MaskProvider.FindEditPositionFrom(startPosition, direction: true);
				if (base.CaretIndex != -1)
				{
					return result;
				}
			}
			return startPosition;
		}

		private void RefreshText(MaskedTextProvider? provider, int position)
		{
			if (provider != null)
			{
				SetCurrentValue(TextBox.TextProperty, provider.ToDisplayString());
				SetCurrentValue(TextBox.CaretIndexProperty, position);
			}
		}

		/// <inheritdoc />
		protected override string? CoerceText(string? text)
		{
			if (!_ignoreTextChanges)
			{
				MaskedTextProvider maskProvider = MaskProvider;
				if (maskProvider != null)
				{
					if (string.IsNullOrEmpty(text))
					{
						maskProvider.Clear();
					}
					else
					{
						maskProvider.Set(text);
					}
					text = maskProvider.ToDisplayString();
				}
			}
			return base.CoerceText(text);
		}
	}
	/// <summary>
	/// A top-level menu control.
	/// </summary>
	public class Menu : MenuBase, IMainMenu
	{
		private IAccessKeyHandler? _accessKeyHandler;

		private static readonly FuncTemplate<Panel?> DefaultPanel;

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Menu" /> class.
		/// </summary>
		public Menu()
		{
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Menu" /> class.
		/// </summary>
		/// <param name="interactionHandler">The menu interaction handler.</param>
		public Menu(IMenuInteractionHandler interactionHandler)
			: base(interactionHandler)
		{
		}

		static Menu()
		{
			DefaultPanel = new FuncTemplate<Panel>(() => new StackPanel
			{
				Orientation = Orientation.Horizontal
			});
			ItemsControl.ItemsPanelProperty.OverrideDefaultValue(typeof(Menu), DefaultPanel);
			KeyboardNavigation.TabNavigationProperty.OverrideDefaultValue(typeof(Menu), KeyboardNavigationMode.Once);
			AutomationProperties.AccessibilityViewProperty.OverrideDefaultValue<Menu>(AccessibilityView.Control);
			AutomationProperties.ControlTypeOverrideProperty.OverrideDefaultValue<Menu>(AutomationControlType.Menu);
			AccessKeyHandler.AccessKeyPressedEvent.AddClassHandler<Menu>(OnAccessKeyPressed);
		}

		/// <inheritdoc cref="M:Avalonia.Input.IMainMenu.Close" />
		public override void Close()
		{
			if (!base.IsOpen)
			{
				return;
			}
			foreach (IMenuItem subItem in ((IMenuElement)this).SubItems)
			{
				subItem.Close();
			}
			base.IsOpen = false;
			base.SelectedIndex = -1;
			RaiseEvent(new RoutedEventArgs
			{
				RoutedEvent = MenuBase.ClosedEvent,
				Source = this
			});
		}

		/// <inheritdoc cref="M:Avalonia.Input.IMainMenu.Open" />
		public override void Open()
		{
			if (!base.IsOpen)
			{
				base.IsOpen = true;
				RaiseEvent(new RoutedEventArgs
				{
					RoutedEvent = MenuBase.OpenedEvent,
					Source = this
				});
			}
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			_accessKeyHandler = TopLevel.GetTopLevel(this)?.AccessKeyHandler;
			if (_accessKeyHandler != null)
			{
				_accessKeyHandler.MainMenu = this;
			}
		}

		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			if (_accessKeyHandler?.MainMenu == this)
			{
				_accessKeyHandler.MainMenu = null;
			}
			_accessKeyHandler = null;
			base.OnDetachedFromVisualTree(e);
		}

		protected internal override void PrepareContainerForItemOverride(Control element, object? item, int index)
		{
			base.PrepareContainerForItemOverride(element, item, index);
			if ((element as MenuItem)?.ItemContainerTheme == base.ItemContainerTheme)
			{
				element.ClearValue(ItemsControl.ItemContainerThemeProperty);
			}
		}

		private static void OnAccessKeyPressed(Menu sender, AccessKeyPressedEventArgs e)
		{
			if (!e.Handled && e.Source is StyledElement item)
			{
				e.Target = DefaultMenuInteractionHandler.GetMenuItemCore(item);
				e.Handled = true;
			}
		}
	}
	/// <summary>
	/// Base class for menu controls.
	/// </summary>
	public abstract class MenuBase : SelectingItemsControl, IFocusScope, IMenu, IMenuElement, IInputElement, ILogical
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.MenuBase.IsOpen" /> property.
		/// </summary>
		public static readonly DirectProperty<MenuBase, bool> IsOpenProperty;

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.MenuBase.Opened" /> event.
		/// </summary>
		public static readonly RoutedEvent<RoutedEventArgs> OpenedEvent;

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.MenuBase.Closed" /> event.
		/// </summary>
		public static readonly RoutedEvent<RoutedEventArgs> ClosedEvent;

		private bool _isOpen;

		/// <summary>
		/// Gets a value indicating whether the menu is open.
		/// </summary>
		public bool IsOpen
		{
			get
			{
				return _isOpen;
			}
			protected set
			{
				SetAndRaise(IsOpenProperty, ref _isOpen, value);
			}
		}

		/// <inheritdoc />
		IMenuInteractionHandler IMenu.InteractionHandler => InteractionHandler;

		IRenderRoot? IMenu.VisualRoot => base.VisualRoot;

		/// <inheritdoc />
		IMenuItem? IMenuElement.SelectedItem
		{
			get
			{
				int selectedIndex = base.SelectedIndex;
				if (selectedIndex == -1)
				{
					return null;
				}
				return (IMenuItem)ContainerFromIndex(selectedIndex);
			}
			set
			{
				base.SelectedIndex = ((value is Control container) ? IndexFromContainer(container) : (-1));
			}
		}

		/// <inheritdoc />
		IEnumerable<IMenuItem> IMenuElement.SubItems => base.LogicalChildren.OfType<IMenuItem>();

		/// <summary>
		/// Gets the interaction handler for the menu.
		/// </summary>
		protected internal IMenuInteractionHandler InteractionHandler { get; }

		/// <summary>
		/// Occurs when a <see cref="T:Avalonia.Controls.Menu" /> is opened.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Opened
		{
			add
			{
				AddHandler(OpenedEvent, value);
			}
			remove
			{
				RemoveHandler(OpenedEvent, value);
			}
		}

		/// <summary>
		/// Occurs when a <see cref="T:Avalonia.Controls.Menu" /> is closed.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Closed
		{
			add
			{
				AddHandler(ClosedEvent, value);
			}
			remove
			{
				RemoveHandler(ClosedEvent, value);
			}
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.MenuBase" /> class.
		/// </summary>
		protected MenuBase()
		{
			InteractionHandler = new DefaultMenuInteractionHandler(isContextMenu: false);
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.MenuBase" /> class.
		/// </summary>
		/// <param name="interactionHandler">The menu interaction handler.</param>
		protected MenuBase(IMenuInteractionHandler interactionHandler)
		{
			InteractionHandler = interactionHandler ?? throw new ArgumentNullException("interactionHandler");
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.MenuBase" /> class.
		/// </summary>
		static MenuBase()
		{
			IsOpenProperty = AvaloniaProperty.RegisterDirect("IsOpen", (MenuBase o) => o.IsOpen, null, unsetValue: false);
			OpenedEvent = RoutedEvent.Register<MenuBase, RoutedEventArgs>("Opened", RoutingStrategies.Bubble);
			ClosedEvent = RoutedEvent.Register<MenuBase, RoutedEventArgs>("Closed", RoutingStrategies.Bubble);
			MenuItem.SubmenuOpenedEvent.AddClassHandler(delegate(MenuBase x, RoutedEventArgs e)
			{
				x.OnSubmenuOpened(e);
			});
		}

		/// <summary>
		/// Closes the menu.
		/// </summary>
		public abstract void Close();

		/// <summary>
		/// Opens the menu.
		/// </summary>
		public abstract void Open();

		/// <inheritdoc />
		bool IMenuElement.MoveSelection(NavigationDirection direction, bool wrap)
		{
			return MoveSelection(direction, wrap);
		}

		protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
		{
			return new MenuItem();
		}

		protected internal override bool NeedsContainerOverride(object? item, int index, out object? recycleKey)
		{
			if ((item is MenuItem || item is Separator) ? true : false)
			{
				recycleKey = null;
				return false;
			}
			recycleKey = ItemsControl.DefaultRecycleKey;
			return true;
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			InteractionHandler.Attach(this);
		}

		/// <inheritdoc />
		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			InteractionHandler.Detach(this);
		}

		/// <summary>
		/// Called when a submenu opens somewhere in the menu.
		/// </summary>
		/// <param name="e">The event args.</param>
		protected virtual void OnSubmenuOpened(RoutedEventArgs e)
		{
			if (e.Source is MenuItem menuItem && menuItem.Parent == this)
			{
				foreach (MenuItem item in this.GetLogicalChildren().OfType<MenuItem>())
				{
					if (item != menuItem && item.IsSubMenuOpen)
					{
						item.IsSubMenuOpen = false;
					}
				}
			}
			IsOpen = true;
		}
	}
