		protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
		{
			return new MenuItem();
		}

		protected internal override bool NeedsContainerOverride(object? item, int index, out object? recycleKey)
		{
			if ((item is MenuItem || item is Separator) ? true : false)
			{
				recycleKey = null;
				return false;
			}
			recycleKey = ItemsControl.DefaultRecycleKey;
			return true;
		}

		protected override void OnPointerReleased(PointerReleasedEventArgs e)
		{
			base.OnPointerReleased(e);
			if (!_isEmbeddedInMenu)
			{
				RaiseEvent(new RoutedEventArgs(ClickEvent));
			}
		}

		protected override void OnAttachedToLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			if (_hotkey != null)
			{
				SetCurrentValue(HotKeyProperty, _hotkey);
			}
			base.OnAttachedToLogicalTree(e);
			ICommand? command = Command;
			object commandParameter = CommandParameter;
			ICommand command2 = command;
			if (command2 != null)
			{
				command2.CanExecuteChanged += CanExecuteChangedHandler;
			}
			TryUpdateCanExecute(command2, commandParameter);
			StyledElement parent = base.Parent;
			while (parent is MenuItem)
			{
				parent = parent.Parent;
			}
			_isEmbeddedInMenu = parent?.FindLogicalAncestorOfType<IMenu>(includeSelf: true) != null;
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			TryUpdateCanExecute();
		}

		protected override void OnDetachedFromLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			if (HotKey != null)
			{
				_hotkey = HotKey;
				SetCurrentValue(HotKeyProperty, null);
			}
			base.OnDetachedFromLogicalTree(e);
			if (Command != null)
			{
				Command.CanExecuteChanged -= CanExecuteChangedHandler;
			}
		}

		/// <summary>
		/// Invoked when an unhandled <see cref="F:Avalonia.Controls.MenuItem.ClickEvent" /> reaches an element in its 
		/// route that is derived from this class. Implement this method to add class handling 
		/// for this event.
		/// </summary>
		/// <param name="e">Data about the event.</param>
		protected virtual void OnClick(RoutedEventArgs e)
		{
			ICommand? command = Command;
			object commandParameter = CommandParameter;
			ICommand command2 = command;
			if (!e.Handled && command2 != null && command2.CanExecute(commandParameter))
			{
				command2.Execute(commandParameter);
				e.Handled = true;
			}
		}

		/// <inheritdoc />
		protected override void OnGotFocus(GotFocusEventArgs e)
		{
			base.OnGotFocus(e);
			e.Handled = UpdateSelectionFromEventSource(e.Source);
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
		}

		/// <inheritdoc />
		protected override void OnPointerEntered(PointerEventArgs e)
		{
			base.OnPointerEntered(e);
			RaiseEvent(new RoutedEventArgs(PointerEnteredItemEvent));
		}

		/// <inheritdoc />
		protected override void OnPointerExited(PointerEventArgs e)
		{
			base.OnPointerExited(e);
			RaiseEvent(new RoutedEventArgs(PointerExitedItemEvent));
		}

		/// <summary>
		/// Invoked when an unhandled <see cref="F:Avalonia.Controls.MenuItem.SubmenuOpenedEvent" /> reaches an element in its 
		/// route that is derived from this class. Implement this method to add class handling 
		/// for this event.
		/// </summary>
		/// <param name="e">Data about the event.</param>
		protected virtual void OnSubmenuOpened(RoutedEventArgs e)
		{
			if (!(e.Source is MenuItem menuItem) || menuItem.Parent != this)
			{
				return;
			}
			foreach (IMenuItem subItem in ((IMenuElement)this).SubItems)
			{
				if (subItem != menuItem && subItem.IsSubMenuOpen)
				{
					subItem.IsSubMenuOpen = false;
				}
			}
		}

		/// <inheritdoc />
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			if (_popup != null)
			{
				_popup.Opened -= PopupOpened;
				_popup.Closed -= PopupClosed;
				_popup.DependencyResolver = null;
			}
			_popup = e.NameScope.Find<Popup>("PART_Popup");
			if (_popup != null)
			{
				_popup.DependencyResolver = DependencyResolver.Instance;
				_popup.Opened += PopupOpened;
				_popup.Closed += PopupClosed;
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new MenuItemAutomationPeer(this);
		}

		protected override void UpdateDataValidation(AvaloniaProperty property, BindingValueType state, Exception? error)
		{
			base.UpdateDataValidation(property, state, error);
			if (property == CommandProperty)
			{
				_commandBindingError = state == BindingValueType.BindingError;
				if (_commandBindingError && _commandCanExecute)
				{
					_commandCanExecute = false;
					UpdateIsEffectivelyEnabled();
				}
			}
		}

		/// <summary>
		/// Closes all submenus of the menu item.
		/// </summary>
		private void CloseSubmenus()
		{
			foreach (IMenuItem subItem in ((IMenuElement)this).SubItems)
			{
				subItem.IsSubMenuOpen = false;
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.Command" /> property changes.
		/// </summary>
		/// <param name="e">The event args.</param>
		private static void CommandChanged(AvaloniaPropertyChangedEventArgs e)
		{
			ICommand command = e.NewValue as ICommand;
			if (!(e.Sender is MenuItem menuItem))
			{
				return;
			}
			if (((ILogical)menuItem).IsAttachedToLogicalTree)
			{
				if (e.OldValue is ICommand command2)
				{
					command2.CanExecuteChanged -= menuItem.CanExecuteChangedHandler;
				}
				if (command != null)
				{
					command.CanExecuteChanged += menuItem.CanExecuteChangedHandler;
				}
			}
			menuItem.TryUpdateCanExecute(command, menuItem.CommandParameter);
		}

		private static void OnAccessKeyPressed(MenuItem sender, AccessKeyPressedEventArgs e)
		{
			if (e != null && !e.Handled && e.Target == null)
			{
				e.Target = sender;
				e.Handled = true;
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.CommandParameter" /> property changes.
		/// </summary>
		/// <param name="e">The event args.</param>
		private static void CommandParameterChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Sender is MenuItem menuItem)
			{
				ICommand? command = menuItem.Command;
				object newValue = e.NewValue;
				ICommand command2 = command;
				menuItem.TryUpdateCanExecute(command2, newValue);
			}
		}

		/// <summary>
		/// Called when the <see cref="E:System.Windows.Input.ICommand.CanExecuteChanged" /> event fires.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void CanExecuteChanged(object? sender, EventArgs e)
		{
			TryUpdateCanExecute();
		}

		/// <summary>
		/// Tries to evaluate CanExecute value of a Command if menu is opened
		/// </summary>
		private void TryUpdateCanExecute()
		{
			TryUpdateCanExecute(Command, CommandParameter);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void TryUpdateCanExecute(ICommand? command, object? parameter)
		{
			if (command == null)
			{
				_commandCanExecute = !_commandBindingError;
				UpdateIsEffectivelyEnabled();
			}
			else if (((ILogical)this).IsAttachedToLogicalTree && !(base.Parent is MenuItem { IsSubMenuOpen: false }))
			{
				bool flag = command.CanExecute(parameter);
				if (flag != _commandCanExecute)
				{
					_commandCanExecute = flag;
					UpdateIsEffectivelyEnabled();
				}
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == HeaderedSelectingItemsControl.HeaderProperty)
			{
				HeaderChanged(change);
			}
			else if (change.Property == IconProperty)
			{
				IconChanged(change);
			}
			else if (change.Property == SelectingItemsControl.IsSelectedProperty)
			{
				IsSelectedChanged(change);
			}
			else if (change.Property == IsSubMenuOpenProperty)
			{
				SubMenuOpenChanged(change);
			}
			else if (change.Property == CommandProperty)
			{
				CommandChanged(change);
			}
			else if (change.Property == CommandParameterProperty)
			{
				CommandParameterChanged(change);
			}
			else if (change.Property == IsCheckedProperty)
			{
				IsCheckedChanged(change);
			}
			else if (change.Property == ToggleTypeProperty)
			{
				ToggleTypeChanged(change);
			}
			else if (change.Property == GroupNameProperty)
			{
				GroupNameChanged(change);
			}
			else if (change.Property == ItemsControl.ItemCountProperty)
			{
				var (num, num2) = change.GetOldAndNewValue<int>();
				if (num == 0 || num2 == 0)
				{
					UpdateIsEffectivelyEnabled();
				}
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.GroupName" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void GroupNameChanged(AvaloniaPropertyChangedEventArgs e)
		{
			(MenuInteractionHandler as DefaultMenuInteractionHandler)?.OnGroupOrTypeChanged(this, e.GetOldValue<string>());
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.ToggleType" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void ToggleTypeChanged(AvaloniaPropertyChangedEventArgs e)
		{
			MenuItemToggleType newValue = e.GetNewValue<MenuItemToggleType>();
			base.PseudoClasses.Set(":radio", newValue == MenuItemToggleType.Radio);
			base.PseudoClasses.Set(":toggle", newValue == MenuItemToggleType.CheckBox);
			(MenuInteractionHandler as DefaultMenuInteractionHandler)?.OnGroupOrTypeChanged(this, GroupName);
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.IsChecked" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void IsCheckedChanged(AvaloniaPropertyChangedEventArgs e)
		{
			bool newValue = e.GetNewValue<bool>();
			base.PseudoClasses.Set(":checked", newValue);
			if (newValue)
			{
				(MenuInteractionHandler as DefaultMenuInteractionHandler)?.OnCheckedChanged(this);
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Primitives.HeaderedSelectingItemsControl.Header" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void HeaderChanged(AvaloniaPropertyChangedEventArgs e)
		{
			(object oldValue, object newValue) oldAndNewValue = e.GetOldAndNewValue<object>();
			var (objA, _) = oldAndNewValue;
			if (object.Equals(oldAndNewValue.newValue, "-"))
			{
				base.PseudoClasses.Add(":separator");
				base.Focusable = false;
			}
			else if (object.Equals(objA, "-"))
			{
				base.PseudoClasses.Remove(":separator");
				base.Focusable = true;
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.Icon" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void IconChanged(AvaloniaPropertyChangedEventArgs e)
		{
			var (obj, obj2) = e.GetOldAndNewValue<object>();
			if (obj != null)
			{
				if (obj is ILogical item)
				{
					base.LogicalChildren.Remove(item);
				}
				base.PseudoClasses.Remove(":icon");
			}
			if (obj2 != null)
			{
				if (obj2 is ILogical item2)
				{
					base.LogicalChildren.Add(item2);
				}
				base.PseudoClasses.Add(":icon");
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.IsSelected" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void IsSelectedChanged(AvaloniaPropertyChangedEventArgs e)
		{
			Menu menu = base.Parent as Menu;
			if ((bool)e.NewValue && (menu == null || menu.IsOpen))
			{
				Focus();
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.MenuItem.IsSubMenuOpen" /> property changes.
		/// </summary>
		/// <param name="e">The property change event.</param>
		private void SubMenuOpenChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if ((bool)e.NewValue)
			{
				foreach (MenuItem item in base.ItemsView.OfType<MenuItem>())
				{
					item.TryUpdateCanExecute();
				}
				RaiseEvent(new RoutedEventArgs(SubmenuOpenedEvent));
				SetCurrentValue(SelectingItemsControl.IsSelectedProperty, value: true);
				base.PseudoClasses.Add(":open");
			}
			else
			{
				CloseSubmenus();
				base.SelectedIndex = -1;
				base.PseudoClasses.Remove(":open");
			}
		}

		/// <summary>
		/// Called when the submenu's <see cref="T:Avalonia.Controls.Primitives.Popup" /> is opened.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void PopupOpened(object? sender, EventArgs e)
		{
			ItemsPresenter? presenter = base.Presenter;
			if (presenter != null && !presenter.IsAttachedToVisualTree)
			{
				UpdateLayout();
			}
			int selectedIndex = base.SelectedIndex;
			if (selectedIndex != -1)
			{
				ContainerFromIndex(selectedIndex)?.Focus();
			}
		}

		/// <summary>
		/// Called when the submenu's <see cref="T:Avalonia.Controls.Primitives.Popup" /> is closed.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void PopupClosed(object? sender, EventArgs e)
		{
			base.SelectedItem = null;
		}

		void ICommandSource.CanExecuteChanged(object sender, EventArgs e)
		{
			CanExecuteChangedHandler(sender, e);
		}

		void IClickableControl.RaiseClick()
		{
			if (base.IsEffectivelyEnabled)
			{
				RaiseEvent(new RoutedEventArgs(ClickEvent));
			}
		}
	}
	/// <summary>
	/// Handles access keys within a <see cref="T:Avalonia.Controls.MenuItem" />
	/// </summary>
	internal class MenuItemAccessKeyHandler : AccessKeyHandler
	{
		protected override void OnSetOwner(IInputRoot owner)
		{
			owner.AddHandler(InputElement.TextInputEvent, new Action<object, TextInputEventArgs>(OnTextInput));
		}

		/// <summary>
		/// Handles a key being pressed in the menu.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		protected virtual void OnTextInput(object? sender, TextInputEventArgs e)
		{
			if (!string.IsNullOrWhiteSpace(e.Text))
			{
				string key = e.Text;
				AccessKeyRegistration accessKeyRegistration = base.Registrations.FirstOrDefault((AccessKeyRegistration x) => string.Equals(x.Key, key, StringComparison.OrdinalIgnoreCase));
				if (accessKeyRegistration != null)
				{
					e.Handled = ProcessKey(key, accessKeyRegistration.GetInputElement());
				}
			}
		}
	}
