	{
		/// <summary>
		/// Normal menu item.
		/// </summary>
		None,
		/// <summary>
		/// Toggleable menu item with a checkbox.
		/// </summary>
		CheckBox,
		/// <summary>
		/// Menu item representing single option of radio group. 
		/// </summary>
		Radio
	}
	public class NativeControlHost : Control
	{
		private TopLevel? _currentRoot;

		private INativeControlHostImpl? _currentHost;

		private INativeControlHostControlTopLevelAttachment? _attachment;

		private IPlatformHandle? _nativeControlHandle;

		private bool _queuedForDestruction;

		private bool _queuedForMoveResize;

		private readonly List<Visual> _propertyChangedSubscriptions = new List<Visual>();

		internal IPlatformHandle? NativeControlHandle
		{
			get
			{
				return _nativeControlHandle;
			}
			set
			{
				if (_nativeControlHandle != value)
				{
					_nativeControlHandle = value;
					this.NativeControlHandleChanged?.Invoke(this, EventArgs.Empty);
				}
			}
		}

		internal event EventHandler? NativeControlHandleChanged;

		static NativeControlHost()
		{
			Visual.FlowDirectionProperty.Changed.AddClassHandler<NativeControlHost>(OnFlowDirectionChanged);
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			_currentRoot = e.Root as TopLevel;
			for (Visual visual = this; visual != null; visual = visual.GetVisualParent())
			{
				visual.PropertyChanged += PropertyChangedHandler;
				_propertyChangedSubscriptions.Add(visual);
			}
			UpdateHost();
		}

		private static void OnFlowDirectionChanged(NativeControlHost nativeControlHost, AvaloniaPropertyChangedEventArgs propertyChangedEventArgs)
		{
			nativeControlHost.TryUpdateNativeControlPosition();
		}

		private void PropertyChangedHandler(object? sender, AvaloniaPropertyChangedEventArgs e)
		{
			if (e.IsEffectiveValueChange && (e.Property == Visual.BoundsProperty || e.Property == Visual.IsVisibleProperty))
			{
				EnqueueForMoveResize();
			}
		}

		/// <inheritdoc />
		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			_currentRoot = null;
			foreach (Visual propertyChangedSubscription in _propertyChangedSubscriptions)
			{
				propertyChangedSubscription.PropertyChanged -= PropertyChangedHandler;
			}
			_propertyChangedSubscriptions.Clear();
			UpdateHost();
		}

		private void UpdateHost()
		{
			_queuedForMoveResize = false;
			_currentHost = _currentRoot?.PlatformImpl?.TryGetFeature<INativeControlHostImpl>();
			if (_currentHost != null)
			{
				if (_attachment != null && _attachment.AttachedTo != _currentHost && _attachment != null)
				{
					if (_attachment.IsCompatibleWith(_currentHost))
					{
						_attachment.AttachedTo = _currentHost;
					}
					else
					{
						_attachment.Dispose();
						_attachment = null;
					}
				}
				if (_attachment == null && NativeControlHandle != null)
				{
					if (_currentHost.IsCompatibleWith(NativeControlHandle))
					{
						_attachment = _currentHost.CreateNewAttachment(NativeControlHandle);
					}
					else
					{
						DestroyNativeControl();
					}
				}
				if (NativeControlHandle == null)
				{
					_attachment = _currentHost.CreateNewAttachment((IPlatformHandle parent) => NativeControlHandle = CreateNativeControlCore(parent));
				}
			}
			else
			{
				if (_attachment != null)
				{
					_attachment.AttachedTo = null;
				}
				if (NativeControlHandle != null && !_queuedForDestruction)
				{
					_queuedForDestruction = true;
					Dispatcher.UIThread.Post(CheckDestruction, DispatcherPriority.Background);
				}
			}
			if (_attachment?.AttachedTo == _currentHost)
			{
				TryUpdateNativeControlPosition();
			}
		}

		private Rect? GetAbsoluteBounds()
		{
			Rect bounds = base.Bounds;
			Matrix? matrix = this.TransformToVisual(_currentRoot);
			if (!matrix.HasValue)
			{
				return null;
			}
			Rect value = new Rect(default(Point), bounds.Size).TransformToAABB(matrix.Value);
			if (base.UseLayoutRounding)
			{
				double layoutScale = LayoutHelper.GetLayoutScale(this);
				double x = LayoutHelper.RoundLayoutValue(value.X, layoutScale);
				double y = LayoutHelper.RoundLayoutValue(value.Y, layoutScale);
				double x2 = LayoutHelper.RoundLayoutValue(value.Right, layoutScale);
				double y2 = LayoutHelper.RoundLayoutValue(value.Bottom, layoutScale);
				value = new Rect(new Point(x, y), new Point(x2, y2));
			}
			return value;
		}

		private void EnqueueForMoveResize()
		{
			if (!_queuedForMoveResize)
			{
				_queuedForMoveResize = true;
				Dispatcher.UIThread.Post(UpdateHost, DispatcherPriority.AfterRender);
			}
		}

		public bool TryUpdateNativeControlPosition()
		{
			if (_currentHost == null)
			{
				return false;
			}
			Rect? absoluteBounds = GetAbsoluteBounds();
			if (base.IsEffectivelyVisible && absoluteBounds.HasValue)
			{
				if (absoluteBounds.Value.Width == 0.0 && absoluteBounds.Value.Height == 0.0)
				{
					return false;
				}
				_attachment?.ShowInBounds(absoluteBounds.Value);
			}
			else
			{
				_attachment?.HideWithSize(base.Bounds.Size);
			}
			return true;
		}

		private void CheckDestruction()
		{
			_queuedForDestruction = false;
			if (_currentRoot == null)
			{
				DestroyNativeControl();
			}
		}

		protected virtual IPlatformHandle CreateNativeControlCore(IPlatformHandle parent)
		{
			if (_currentHost == null)
			{
				throw new InvalidOperationException();
			}
			return _currentHost.CreateDefaultChild(parent);
		}

		private void DestroyNativeControl()
		{
			if (NativeControlHandle != null)
			{
				_attachment?.Dispose();
				_attachment = null;
				DestroyNativeControlCore(NativeControlHandle);
				NativeControlHandle = null;
			}
		}

		protected virtual void DestroyNativeControlCore(IPlatformHandle control)
		{
			if (control is INativeControlHostDestroyableControlHandle nativeControlHostDestroyableControlHandle)
			{
				nativeControlHostDestroyableControlHandle.Destroy();
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new NativeControlHostPeer(this);
		}
	}
