		{
			menuItem.SetValue(EnableMenuItemClickForwardingProperty, enable);
		}

		private static void OnMenuItemClick(object? sender, RoutedEventArgs e)
		{
			(((MenuItem)sender).DataContext as INativeMenuItemExporterEventsImplBridge)?.RaiseClicked();
		}

		private void SubscribeToToplevel(TopLevel topLevel, MenuBase menu)
		{
			_subscriptions?.Dispose();
			_subscriptions = new CompositeDisposable(menu.Bind(Visual.IsVisibleProperty, from v in topLevel.GetBindingObservable(NativeMenu.IsNativeMenuExportedProperty)
				select !v.GetValueOrDefault<bool>()), menu.Bind(ItemsControl.ItemsSourceProperty, from v in topLevel.GetBindingObservable(NativeMenu.MenuProperty)
