	internal class NativeMenuBarPresenter : Menu
	{
		private class NativeMenuItemPresenter : MenuItem
		{
			protected override Type StyleKeyOverride => typeof(MenuItem);

			protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
			{
				return CreateContainerForNativeItem(item, index, recycleKey) ?? base.CreateContainerForItemOverride(item, index, recycleKey);
			}
		}

		protected override Type StyleKeyOverride => typeof(Menu);

		internal static Control? CreateContainerForNativeItem(object? item, int index, object? recycleKey)
		{
			if (item is NativeMenuItemSeparator)
			{
				return new Separator();
			}
			NativeMenuItem nativeItem = item as NativeMenuItem;
			if (nativeItem != null)
			{
				NativeMenuItemPresenter obj = new NativeMenuItemPresenter
				{
					ItemsSource = nativeItem.Menu?.Items,
					[!HeaderedSelectingItemsControl.HeaderProperty] = nativeItem.GetObservable(NativeMenuItem.HeaderProperty).ToBinding(),
					[!MenuItem.IconProperty] = (from i in nativeItem.GetObservable(NativeMenuItem.IconProperty)
						select (i == null) ? null : new Image
						{
							Source = i
						}).ToBinding(),
					[!InputElement.IsEnabledProperty] = nativeItem.GetObservable(NativeMenuItem.IsEnabledProperty).ToBinding(),
					[!Visual.IsVisibleProperty] = nativeItem.GetObservable(NativeMenuItem.IsVisibleProperty).ToBinding(),
					[!MenuItem.CommandProperty] = nativeItem.GetObservable(NativeMenuItem.CommandProperty).ToBinding(),
					[!MenuItem.CommandParameterProperty] = nativeItem.GetObservable(NativeMenuItem.CommandParameterProperty).ToBinding(),
					[!MenuItem.InputGestureProperty] = nativeItem.GetObservable(NativeMenuItem.GestureProperty).ToBinding(),
					[!MenuItem.ToggleTypeProperty] = (from v in nativeItem.GetObservable(NativeMenuItem.ToggleTypeProperty)
						select (MenuItemToggleType)v).ToBinding(),
					[!ToolTip.TipProperty] = nativeItem.GetObservable(NativeMenuItem.ToolTipProperty).ToBinding()
				};
				BindingOperations.Apply(obj, MenuItem.IsCheckedProperty, InstancedBinding.TwoWay(nativeItem.GetObservable(NativeMenuItem.IsCheckedProperty).Select((Func<bool, object>)((bool v) => v)), new AnonymousObserver<object>(delegate(object? v)
				{
					nativeItem.SetValue(NativeMenuItem.IsCheckedProperty, v);
				})));
				obj.Click += MenuItemOnClick;
				return obj;
			}
			return null;
			static void MenuItemOnClick(object? sender, RoutedEventArgs e)
			{
				if (((MenuItem)sender).DataContext is NativeMenuItem { HasClickHandlers: not false } nativeMenuItem)
				{
					((INativeMenuItemExporterEventsImplBridge)nativeMenuItem)?.RaiseClicked();
				}
			}
		}

		protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
		{
			return CreateContainerForNativeItem(item, index, recycleKey) ?? base.CreateContainerForItemOverride(item, index, recycleKey);
		}
	}
