	/// <summary>
	/// Implements a <see cref="T:Avalonia.Controls.StackPanel" /> where the flow direction of its items can be reversed.
	/// </summary>
	public class ReversibleStackPanel : StackPanel
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ReversibleStackPanel.ReverseOrder" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> ReverseOrderProperty;

		/// <summary>
		/// Gets or sets if the child controls will be layed out in reverse order.
		/// </summary>
		public bool ReverseOrder
		{
			get
			{
				return GetValue(ReverseOrderProperty);
			}
			set
			{
				SetValue(ReverseOrderProperty, value);
			}
		}

		static ReversibleStackPanel()
		{
			ReverseOrderProperty = AvaloniaProperty.Register<ReversibleStackPanel, bool>("ReverseOrder", defaultValue: false);
			Layoutable.AffectsArrange<ReversibleStackPanel>(new AvaloniaProperty[1] { ReverseOrderProperty });
		}

		/// <inheritdoc />
		protected override Size ArrangeOverride(Size finalSize)
		{
			Orientation orientation = base.Orientation;
			double spacing = base.Spacing;
			Rect constraint = new Rect(finalSize);
			double num = 0.0;
			IEnumerable<Control> enumerable;
			if (!ReverseOrder)
			{
				IEnumerable<Control> children = base.Children;
				enumerable = children;
			}
			else
			{
				enumerable = base.Children.Reverse();
			}
			foreach (Control item in enumerable)
			{
				if (item.IsVisible)
				{
					double width = item.DesiredSize.Width;
					double height = item.DesiredSize.Height;
					if (orientation == Orientation.Vertical)
					{
						Rect rect = new Rect(0.0, num, width, height).Align(constraint, item.HorizontalAlignment, VerticalAlignment.Top);
						ArrangeChild(item, rect, finalSize, orientation);
						num += height + spacing;
					}
					else
					{
						Rect rect2 = new Rect(num, 0.0, width, height).Align(constraint, HorizontalAlignment.Left, item.VerticalAlignment);
						ArrangeChild(item, rect2, finalSize, orientation);
						num += width + spacing;
					}
				}
			}
			return finalSize;
		}
	}
