		{
			if (e.Pointer.Captured != Spinner)
			{
				Dispatcher.UIThread.InvokeAsync(delegate
				{
					e.Pointer.Capture(Spinner);
				}, DispatcherPriority.Input);
			}
		}

		private bool CommitInput(bool forceTextUpdate = false)
		{
			return SyncTextAndValueProperties(updateValueFromText: true, Text, forceTextUpdate);
		}

		/// <summary>
		/// Synchronize <see cref="P:Avalonia.Controls.NumericUpDown.Text" /> and <see cref="P:Avalonia.Controls.NumericUpDown.Value" /> properties.
		/// </summary>
		/// <param name="updateValueFromText">If value should be updated from text.</param>
		/// <param name="text">The text.</param>
		private bool SyncTextAndValueProperties(bool updateValueFromText, string? text)
		{
			return SyncTextAndValueProperties(updateValueFromText, text, forceTextUpdate: false);
		}

		/// <summary>
		/// Synchronize <see cref="P:Avalonia.Controls.NumericUpDown.Text" /> and <see cref="P:Avalonia.Controls.NumericUpDown.Value" /> properties.
		/// </summary>
		/// <param name="updateValueFromText">If value should be updated from text.</param>
		/// <param name="text">The text.</param>
		/// <param name="forceTextUpdate">Force text update.</param>
		private bool SyncTextAndValueProperties(bool updateValueFromText, string? text, bool forceTextUpdate)
		{
			if (_isSyncingTextAndValueProperties)
			{
				return true;
			}
			_isSyncingTextAndValueProperties = true;
			bool flag = true;
			try
			{
				if (updateValueFromText)
				{
					try
					{
						decimal? num = ConvertTextToValue(text);
						if (!object.Equals(num, Value))
						{
							SetValueInternal(num);
						}
					}
					catch
					{
						flag = false;
					}
				}
				if (!_isTextChangedFromUI)
				{
					if (forceTextUpdate)
					{
						string text2 = ConvertValueToText();
						if (!object.Equals(Text, text2))
						{
							SetCurrentValue(TextProperty, text2);
						}
					}
					if (TextBox != null)
					{
						TextBox.Text = Text;
					}
				}
				if (_isTextChangedFromUI && !flag)
				{
					if (Spinner != null)
					{
						Spinner.ValidSpinDirection = ValidSpinDirections.None;
					}
				}
				else
				{
					SetValidSpinDirection();
				}
			}
			finally
			{
				_isSyncingTextAndValueProperties = false;
			}
			return flag;
		}

		private decimal? ConvertTextToValueCore(string? currentValueText, string? text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			if (TextConverter != null)
			{
				return (decimal?)TextConverter.Convert(text, typeof(decimal?), null, CultureInfo.CurrentCulture);
			}
			decimal value;
			if (IsPercent(FormatString))
			{
				value = ParsePercent(text, NumberFormat);
			}
			else
			{
				if (!decimal.TryParse(text, ParsingNumberStyle, NumberFormat, out var result))
				{
					bool flag = true;
					if (!string.IsNullOrEmpty(currentValueText) && !decimal.TryParse(currentValueText, ParsingNumberStyle, NumberFormat, out var _))
					{
						IEnumerable<char> first = currentValueText.Where((char c2) => !char.IsDigit(c2));
						char[] array = text.Where((char c2) => !char.IsDigit(c2)).ToArray();
						if (!first.Except(array).Any())
						{
							char[] array2 = array;
							foreach (char c in array2)
							{
								text = text.Replace(c.ToString(), string.Empty);
							}
							if (decimal.TryParse(text, ParsingNumberStyle, NumberFormat, out result))
							{
								flag = false;
							}
						}
					}
					if (flag)
					{
						throw new InvalidDataException("Input string was not in a correct format.");
					}
				}
				value = result;
			}
			return value;
		}

		private void ValidateMinMax(decimal? value)
		{
			if (value.HasValue)
			{
				decimal? num = value;
				decimal minimum = Minimum;
				if ((num.GetValueOrDefault() < minimum) & num.HasValue)
				{
					throw new ArgumentOutOfRangeException("value", $"Value must be greater than Minimum value of {Minimum}");
				}
				num = value;
				minimum = Maximum;
				if ((num.GetValueOrDefault() > minimum) & num.HasValue)
				{
					throw new ArgumentOutOfRangeException("value", $"Value must be less than Maximum value of {Maximum}");
				}
			}
		}

		/// <summary>
		/// Parse percent format text
		/// </summary>
		/// <param name="text">Text to parse.</param>
		/// <param name="cultureInfo">The culture info.</param>
		private static decimal ParsePercent(string text, IFormatProvider? cultureInfo)
		{
			NumberFormatInfo instance = NumberFormatInfo.GetInstance(cultureInfo);
			text = text.Replace(instance.PercentSymbol, null);
			return decimal.Parse(text, NumberStyles.Any, instance) / 100m;
		}

		private bool IsPercent(string stringToTest)
		{
			int num = stringToTest.IndexOf("P", StringComparison.Ordinal);
			if (num >= 0)
			{
				return !stringToTest.Substring(0, num).Contains('\'') || !stringToTest.Substring(num, FormatString.Length - num).Contains('\'');
			}
			return false;
		}

		private void FocusChanged(bool hasFocus)
		{
			bool isFocused = _isFocused;
			_isFocused = hasFocus;
			if (hasFocus && !isFocused && TextBox != null)
			{
				TextBox.Focus();
				TextBox.SelectAll();
			}
		}
	}
	public class NumericUpDownValueChangedEventArgs : RoutedEventArgs
	{
		public decimal? OldValue { get; }

		public decimal? NewValue { get; }

		public NumericUpDownValueChangedEventArgs(RoutedEvent routedEvent, decimal? oldValue, decimal? newValue)
			: base(routedEvent)
		{
			OldValue = oldValue;
			NewValue = newValue;
		}
	}
	/// <summary>
	/// Base class for controls that can contain multiple children.
	/// </summary>
	/// <remarks>
	/// Controls can be added to a <see cref="T:Avalonia.Controls.Panel" /> by adding them to its <see cref="P:Avalonia.Controls.Panel.Children" />
	/// collection. All children are layed out to fill the panel.
	/// </remarks>
	public class Panel : Control, IChildIndexProvider
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Panel.Background" /> property.
		/// </summary>
		public static readonly StyledProperty<IBrush?> BackgroundProperty;

		private EventHandler<ChildIndexChangedEventArgs>? _childIndexChanged;

		/// <summary>
		/// Gets the children of the <see cref="T:Avalonia.Controls.Panel" />.
		/// </summary>
		[Content]
		public Controls Children { get; } = new Controls();

		/// <summary>
		/// Gets or Sets Panel background brush.
		/// </summary>
		public IBrush? Background
		{
			get
			{
				return GetValue(BackgroundProperty);
			}
			set
			{
				SetValue(BackgroundProperty, value);
			}
		}

		/// <summary>
		/// Gets whether the <see cref="T:Avalonia.Controls.Panel" /> hosts the items created by an <see cref="T:Avalonia.Controls.Presenters.ItemsPresenter" />.
		/// </summary>
		public bool IsItemsHost { get; internal set; }

		event EventHandler<ChildIndexChangedEventArgs>? IChildIndexProvider.ChildIndexChanged
		{
			add
			{
				if (_childIndexChanged == null)
				{
					Children.PropertyChanged += ChildrenPropertyChanged;
				}
				_childIndexChanged = (EventHandler<ChildIndexChangedEventArgs>)Delegate.Combine(_childIndexChanged, value);
			}
			remove
			{
				_childIndexChanged = (EventHandler<ChildIndexChangedEventArgs>)Delegate.Remove(_childIndexChanged, value);
				if (_childIndexChanged == null)
				{
					Children.PropertyChanged -= ChildrenPropertyChanged;
				}
			}
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.Panel" /> class.
		/// </summary>
		static Panel()
		{
			BackgroundProperty = Border.BackgroundProperty.AddOwner<Panel>();
			Visual.AffectsRender<Panel>(new AvaloniaProperty[1] { BackgroundProperty });
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Panel" /> class.
		/// </summary>
		public Panel()
		{
			Children.CollectionChanged += ChildrenChanged;
		}

		/// <summary>
		/// Renders the visual to a <see cref="T:Avalonia.Media.DrawingContext" />.
		/// </summary>
		/// <param name="context">The drawing context.</param>
		public sealed override void Render(DrawingContext context)
		{
			IBrush background = Background;
			if (background != null)
			{
				Size size = base.Bounds.Size;
				context.FillRectangle(background, new Rect(size));
			}
			base.Render(context);
		}

		/// <summary>
		/// Marks a property on a child as affecting the parent panel's arrangement.
		/// </summary>
		/// <param name="properties">The properties.</param>
		protected static void AffectsParentArrange<TPanel>(params AvaloniaProperty[] properties) where TPanel : Panel
		{
			AnonymousObserver<AvaloniaPropertyChangedEventArgs> observer = new AnonymousObserver<AvaloniaPropertyChangedEventArgs>(delegate(AvaloniaPropertyChangedEventArgs e)
			{
				AffectsParentArrangeInvalidate<TPanel>(e);
			});
			for (int num = 0; num < properties.Length; num++)
			{
				properties[num].Changed.Subscribe(observer);
			}
		}

		/// <summary>
		/// Marks a property on a child as affecting the parent panel's measurement.
		/// </summary>
		/// <param name="properties">The properties.</param>
		protected static void AffectsParentMeasure<TPanel>(params AvaloniaProperty[] properties) where TPanel : Panel
		{
			AnonymousObserver<AvaloniaPropertyChangedEventArgs> observer = new AnonymousObserver<AvaloniaPropertyChangedEventArgs>(delegate(AvaloniaPropertyChangedEventArgs e)
			{
				AffectsParentMeasureInvalidate<TPanel>(e);
			});
			for (int num = 0; num < properties.Length; num++)
			{
				properties[num].Changed.Subscribe(observer);
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Panel.Children" /> collection changes.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		protected virtual void ChildrenChanged(object? sender, NotifyCollectionChangedEventArgs e)
		{
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
				if (!IsItemsHost)
				{
					base.LogicalChildren.InsertRange(e.NewStartingIndex, e.NewItems.OfType<Control>().ToList());
				}
				base.VisualChildren.InsertRange(e.NewStartingIndex, e.NewItems.OfType<Visual>());
				break;
			case NotifyCollectionChangedAction.Move:
				if (!IsItemsHost)
				{
					base.LogicalChildren.MoveRange(e.OldStartingIndex, e.OldItems.Count, e.NewStartingIndex);
				}
				base.VisualChildren.MoveRange(e.OldStartingIndex, e.OldItems.Count, e.NewStartingIndex);
				break;
			case NotifyCollectionChangedAction.Remove:
				if (!IsItemsHost)
				{
					base.LogicalChildren.RemoveAll(e.OldItems.OfType<Control>().ToList());
				}
				base.VisualChildren.RemoveAll(e.OldItems.OfType<Visual>());
				break;
			case NotifyCollectionChangedAction.Replace:
			{
				for (int i = 0; i < e.OldItems.Count; i++)
				{
					int index = i + e.OldStartingIndex;
					Control value = (Control)e.NewItems[i];
					if (!IsItemsHost)
					{
						base.LogicalChildren[index] = value;
					}
					base.VisualChildren[index] = value;
				}
				break;
			}
			case NotifyCollectionChangedAction.Reset:
				throw new NotSupportedException();
			}
			_childIndexChanged?.Invoke(this, ChildIndexChangedEventArgs.ChildIndexesReset);
			InvalidateMeasureOnChildrenChanged();
		}

		private protected virtual void InvalidateMeasureOnChildrenChanged()
		{
			InvalidateMeasure();
		}

		private void ChildrenPropertyChanged(object? sender, PropertyChangedEventArgs e)
		{
			if (e.PropertyName == "Count" || e.PropertyName == null)
			{
				_childIndexChanged?.Invoke(this, ChildIndexChangedEventArgs.TotalCountChanged);
			}
		}

		private static void AffectsParentArrangeInvalidate<TPanel>(AvaloniaPropertyChangedEventArgs e) where TPanel : Panel
		{
			((e.Sender as Control)?.VisualParent as TPanel)?.InvalidateArrange();
		}

		private static void AffectsParentMeasureInvalidate<TPanel>(AvaloniaPropertyChangedEventArgs e) where TPanel : Panel
		{
			((e.Sender as Control)?.VisualParent as TPanel)?.InvalidateMeasure();
		}

		int IChildIndexProvider.GetChildIndex(ILogical child)
		{
			if (!(child is Control item))
			{
				return -1;
			}
			return Children.IndexOf(item);
		}

		/// <inheritdoc />
		bool IChildIndexProvider.TryGetTotalCount(out int count)
		{
			count = Children.Count;
			return true;
		}
	}
