			ProgressTextFormatProperty = AvaloniaProperty.Register<ProgressBar, string>("ProgressTextFormat", "{1:0}%");
			OrientationProperty = AvaloniaProperty.Register<ProgressBar, Orientation>("Orientation", Orientation.Horizontal);
			PercentageProperty = AvaloniaProperty.RegisterDirect("Percentage", (ProgressBar o) => o.Percentage, null, 0.0);
			RangeBase.ValueProperty.OverrideMetadata<ProgressBar>(new StyledPropertyMetadata<double>(default(Optional<double>), BindingMode.OneWay));
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.ProgressBar" /> class.
		/// </summary>
		public ProgressBar()
		{
			UpdatePseudoClasses(IsIndeterminate, Orientation);
		}

		/// <inheritdoc />
		protected override Size ArrangeOverride(Size finalSize)
		{
			Size result = base.ArrangeOverride(finalSize);
			UpdateIndicator();
			return result;
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == RangeBase.ValueProperty || change.Property == RangeBase.MinimumProperty || change.Property == RangeBase.MaximumProperty || change.Property == IsIndeterminateProperty || change.Property == OrientationProperty)
			{
				UpdateIndicator();
			}
			if (change.Property == IsIndeterminateProperty)
			{
				UpdatePseudoClasses(change.GetNewValue<bool>(), null);
			}
			else if (change.Property == OrientationProperty)
			{
				UpdatePseudoClasses(null, change.GetNewValue<Orientation>());
			}
		}

		/// <inheritdoc />
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			_trackSizeChangedListener?.Dispose();
			_indicator = e.NameScope.Get<Border>("PART_Indicator");
			_trackSizeChangedListener = _indicator.Parent?.GetPropertyChangedObservable(Visual.BoundsProperty).Subscribe(delegate
			{
				UpdateIndicator();
			});
			UpdateIndicator();
		}

		/// <inheritdoc />
		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new ProgressBarAutomationPeer(this);
		}

		private void UpdateIndicator()
		{
			Size size = _indicator?.VisualParent?.Bounds.Size ?? base.Bounds.Size;
			if (_indicator == null)
			{
				return;
			}
			if (IsIndeterminate)
			{
				double num = ((Orientation == Orientation.Horizontal) ? size.Width : size.Height);
				double num2 = num * 0.4;
				double num3 = num * 0.6;
				TemplateSettings.ContainerWidth = num2;
				TemplateSettings.Container2Width = num3;
				TemplateSettings.ContainerAnimationStartPosition = num2 * -1.8;
				TemplateSettings.ContainerAnimationEndPosition = num2 * 3.0;
				TemplateSettings.Container2AnimationStartPosition = num3 * -1.5;
				TemplateSettings.Container2AnimationEndPosition = num3 * 1.66;
				TemplateSettings.IndeterminateStartingOffset = 0.0 - num;
				TemplateSettings.IndeterminateEndingOffset = num;
			}
			else
			{
				double num4 = ((Math.Abs(base.Maximum - base.Minimum) < double.Epsilon) ? 1.0 : ((base.Value - base.Minimum) / (base.Maximum - base.Minimum)));
				if (Orientation == Orientation.Horizontal)
				{
					double num5 = (size.Width - _indicator.Margin.Left - _indicator.Margin.Right) * num4;
					_indicator.Width = ((num5 > 0.0) ? num5 : 0.0);
					_indicator.Height = double.NaN;
				}
				else
				{
					_indicator.Width = double.NaN;
					double num6 = (size.Height - _indicator.Margin.Top - _indicator.Margin.Bottom) * num4;
					_indicator.Height = ((num6 > 0.0) ? num6 : 0.0);
				}
				Percentage = num4 * 100.0;
			}
		}

		private void UpdatePseudoClasses(bool? isIndeterminate, Orientation? o)
		{
			if (isIndeterminate.HasValue)
			{
				base.PseudoClasses.Set(":indeterminate", isIndeterminate.Value);
			}
			if (o.HasValue)
			{
				base.PseudoClasses.Set(":vertical", o == Orientation.Vertical);
				base.PseudoClasses.Set(":horizontal", o == Orientation.Horizontal);
			}
		}
	}
	/// <summary>
	/// Deferral class for notify that a work done in RefreshRequested event is done.
	/// </summary>
	public class RefreshCompletionDeferral
	{
		private Action _deferredAction;

		private int _deferCount;

		public RefreshCompletionDeferral(Action deferredAction)
		{
			_deferredAction = deferredAction;
		}

		public void Complete()
		{
			Interlocked.Decrement(ref _deferCount);
			if (_deferCount == 0)
			{
				_deferredAction?.Invoke();
			}
		}

		public RefreshCompletionDeferral Get()
		{
			Interlocked.Increment(ref _deferCount);
			return this;
		}
	}
	/// <summary>
	/// Represents a container control that provides a <see cref="T:Avalonia.Controls.RefreshVisualizer" /> and pull-to-refresh functionality for scrollable content.
	/// </summary>
	public class RefreshContainer : ContentControl
	{
		internal const int DefaultPullDimensionSize = 100;

		private bool _hasDefaultRefreshInfoProviderAdapter;

		private ScrollViewerIRefreshInfoProviderAdapter? _refreshInfoProviderAdapter;

		private RefreshInfoProvider? _refreshInfoProvider;

		private IDisposable? _visualizerSizeSubscription;

		private Grid? _visualizerPresenter;

		private RefreshVisualizer? _refreshVisualizer;

		private bool _hasDefaultRefreshVisualizer;

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.RefreshContainer.RefreshRequested" /> event.
		/// </summary>
		public static readonly RoutedEvent<RefreshRequestedEventArgs> RefreshRequestedEvent = RoutedEvent.Register<RefreshContainer, RefreshRequestedEventArgs>("RefreshRequested", RoutingStrategies.Bubble);

		internal static readonly DirectProperty<RefreshContainer, ScrollViewerIRefreshInfoProviderAdapter?> RefreshInfoProviderAdapterProperty = AvaloniaProperty.RegisterDirect("RefreshInfoProviderAdapter", (RefreshContainer s) => s.RefreshInfoProviderAdapter, delegate(RefreshContainer s, ScrollViewerIRefreshInfoProviderAdapter? o)
		{
			s.RefreshInfoProviderAdapter = o;
		});

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.RefreshContainer.Visualizer" /> event.
		/// </summary>
		public static readonly DirectProperty<RefreshContainer, RefreshVisualizer?> VisualizerProperty = AvaloniaProperty.RegisterDirect("Visualizer", (RefreshContainer s) => s.Visualizer, delegate(RefreshContainer s, RefreshVisualizer? o)
		{
			s.Visualizer = o;
		});

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.RefreshContainer.PullDirection" /> event.
		/// </summary>
		public static readonly StyledProperty<PullDirection> PullDirectionProperty = AvaloniaProperty.Register<RefreshContainer, PullDirection>("PullDirection", PullDirection.TopToBottom);

		internal ScrollViewerIRefreshInfoProviderAdapter? RefreshInfoProviderAdapter
		{
			get
			{
				return _refreshInfoProviderAdapter;
			}
			set
			{
				_hasDefaultRefreshInfoProviderAdapter = false;
				SetAndRaise(RefreshInfoProviderAdapterProperty, ref _refreshInfoProviderAdapter, value);
			}
		}

		/// <summary>
		/// Gets or sets the <see cref="T:Avalonia.Controls.RefreshVisualizer" /> for this container.
		/// </summary>
		public RefreshVisualizer? Visualizer
		{
			get
			{
				return _refreshVisualizer;
			}
			set
			{
				if (_refreshVisualizer != null)
				{
					_visualizerSizeSubscription?.Dispose();
					_refreshVisualizer.RefreshRequested -= Visualizer_RefreshRequested;
				}
				SetAndRaise(VisualizerProperty, ref _refreshVisualizer, value);
			}
		}

		/// <summary>
		/// Gets or sets a value that specifies the direction to pull to initiate a refresh.
		/// </summary>
		public PullDirection PullDirection
		{
			get
			{
				return GetValue(PullDirectionProperty);
			}
			set
			{
				SetValue(PullDirectionProperty, value);
			}
		}

		/// <summary>
		/// Occurs when an update of the content has been initiated.
		/// </summary>
		public event EventHandler<RefreshRequestedEventArgs>? RefreshRequested
		{
			add
			{
				AddHandler(RefreshRequestedEvent, value);
			}
			remove
			{
				RemoveHandler(RefreshRequestedEvent, value);
			}
		}

		public RefreshContainer()
		{
			_hasDefaultRefreshInfoProviderAdapter = true;
			_refreshInfoProviderAdapter = new ScrollViewerIRefreshInfoProviderAdapter(PullDirection);
			RaisePropertyChanged(RefreshInfoProviderAdapterProperty, null, _refreshInfoProviderAdapter);
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_visualizerPresenter = e.NameScope.Find<Grid>("PART_RefreshVisualizerPresenter");
			if (_refreshVisualizer == null)
			{
				_hasDefaultRefreshVisualizer = true;
				Visualizer = new RefreshVisualizer();
			}
			else
			{
				_hasDefaultRefreshVisualizer = false;
				RaisePropertyChanged(VisualizerProperty, null, _refreshVisualizer);
			}
			OnPullDirectionChanged();
		}

		private void OnVisualizerSizeChanged(Rect obj)
		{
			if (_hasDefaultRefreshInfoProviderAdapter)
			{
				_refreshInfoProviderAdapter = new ScrollViewerIRefreshInfoProviderAdapter(PullDirection);
				RaisePropertyChanged(RefreshInfoProviderAdapterProperty, null, _refreshInfoProviderAdapter);
			}
		}

		private void Visualizer_RefreshRequested(object? sender, RefreshRequestedEventArgs e)
		{
			RefreshRequestedEventArgs e2 = new RefreshRequestedEventArgs(e.GetDeferral(), RefreshRequestedEvent);
			RaiseEvent(e2);
			e2.DecrementCount();
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == RefreshInfoProviderAdapterProperty)
			{
				if (_refreshVisualizer == null)
				{
					return;
				}
				if (_refreshInfoProvider != null)
				{
					_refreshVisualizer.RefreshInfoProvider = _refreshInfoProvider;
				}
				else if (RefreshInfoProviderAdapter != null && _refreshVisualizer != null)
				{
					_refreshInfoProvider = RefreshInfoProviderAdapter?.AdaptFromTree(this, _refreshVisualizer.Bounds.Size);
					if (_refreshInfoProvider != null)
					{
						_refreshVisualizer.RefreshInfoProvider = _refreshInfoProvider;
						RefreshInfoProviderAdapter?.SetAnimations(_refreshVisualizer);
					}
				}
			}
			else if (change.Property == VisualizerProperty)
			{
				if (_visualizerPresenter != null)
				{
					_visualizerPresenter.Children.Clear();
					if (_refreshVisualizer != null)
					{
						_visualizerPresenter.Children.Add(_refreshVisualizer);
					}
				}
				if (_refreshVisualizer != null)
				{
					_refreshVisualizer.RefreshRequested += Visualizer_RefreshRequested;
					_visualizerSizeSubscription = _refreshVisualizer.GetObservable(Visual.BoundsProperty).Subscribe(OnVisualizerSizeChanged);
				}
			}
			else if (change.Property == PullDirectionProperty)
			{
				OnPullDirectionChanged();
			}
		}

		private void OnPullDirectionChanged()
		{
			if (_visualizerPresenter == null || _refreshVisualizer == null)
			{
				return;
			}
			switch (PullDirection)
			{
			case PullDirection.TopToBottom:
				_visualizerPresenter.VerticalAlignment = VerticalAlignment.Top;
				_visualizerPresenter.HorizontalAlignment = HorizontalAlignment.Stretch;
				if (_hasDefaultRefreshVisualizer)
				{
					_refreshVisualizer.PullDirection = PullDirection.TopToBottom;
					_refreshVisualizer.Height = 100.0;
					_refreshVisualizer.Width = double.NaN;
				}
				break;
			case PullDirection.BottomToTop:
				_visualizerPresenter.VerticalAlignment = VerticalAlignment.Bottom;
				_visualizerPresenter.HorizontalAlignment = HorizontalAlignment.Stretch;
				if (_hasDefaultRefreshVisualizer)
				{
					_refreshVisualizer.PullDirection = PullDirection.BottomToTop;
					_refreshVisualizer.Height = 100.0;
					_refreshVisualizer.Width = double.NaN;
				}
				break;
			case PullDirection.LeftToRight:
				_visualizerPresenter.VerticalAlignment = VerticalAlignment.Stretch;
				_visualizerPresenter.HorizontalAlignment = HorizontalAlignment.Left;
				if (_hasDefaultRefreshVisualizer)
				{
					_refreshVisualizer.PullDirection = PullDirection.LeftToRight;
					_refreshVisualizer.Width = 100.0;
					_refreshVisualizer.Height = double.NaN;
				}
				break;
			case PullDirection.RightToLeft:
				_visualizerPresenter.VerticalAlignment = VerticalAlignment.Stretch;
				_visualizerPresenter.HorizontalAlignment = HorizontalAlignment.Right;
				if (_hasDefaultRefreshVisualizer)
				{
					_refreshVisualizer.PullDirection = PullDirection.RightToLeft;
					_refreshVisualizer.Width = 100.0;
					_refreshVisualizer.Height = double.NaN;
				}
				break;
			}
			if (_hasDefaultRefreshInfoProviderAdapter && _hasDefaultRefreshVisualizer && _refreshVisualizer.Bounds.Height == 100.0 && _refreshVisualizer.Bounds.Width == 100.0)
			{
				_refreshInfoProviderAdapter = new ScrollViewerIRefreshInfoProviderAdapter(PullDirection);
				RaisePropertyChanged(RefreshInfoProviderAdapterProperty, null, _refreshInfoProviderAdapter);
			}
		}

		/// <summary>
		/// Initiates an update of the content.
		/// </summary>
		public void RequestRefresh()
		{
			_refreshVisualizer?.RequestRefresh();
		}
	}
	/// <summary>
	/// Provides event data for RefreshRequested events.
	/// </summary>
	public class RefreshRequestedEventArgs : RoutedEventArgs
	{
		private RefreshCompletionDeferral _refreshCompletionDeferral;

		/// <summary>
		/// Gets a deferral object for managing the work done in the RefreshRequested event handler.
		/// </summary>
		/// <returns>A <see cref="T:Avalonia.Controls.RefreshCompletionDeferral" /> object</returns>
		public RefreshCompletionDeferral GetDeferral()
		{
			return _refreshCompletionDeferral.Get();
		}

		public RefreshRequestedEventArgs(Action deferredAction, RoutedEvent? routedEvent)
			: base(routedEvent)
		{
			_refreshCompletionDeferral = new RefreshCompletionDeferral(deferredAction);
		}

		public RefreshRequestedEventArgs(RefreshCompletionDeferral completionDeferral, RoutedEvent? routedEvent)
			: base(routedEvent)
		{
			_refreshCompletionDeferral = completionDeferral;
		}

		internal void IncrementCount()
		{
			_refreshCompletionDeferral?.Get();
		}

		internal void DecrementCount()
		{
			_refreshCompletionDeferral?.Complete();
		}
	}
