			{
				OnOrientationChanged();
				if (_root != null && _content != null)
				{
					_root.Children.Insert(0, _content);
					_content.VerticalAlignment = VerticalAlignment.Center;
					_content.HorizontalAlignment = HorizontalAlignment.Center;
					UpdateContent();
