		private void OnContentLoaded(object? s, RoutedEventArgs e)
		{
			if (_content != null)
			{
				CompositionVisual elementVisual = ElementComposition.GetElementVisual(_content);
				if (elementVisual != null)
				{
					Compositor compositor = elementVisual.Compositor;
					elementVisual.Opacity = 0f;
					ScalarKeyFrameAnimation scalarKeyFrameAnimation = compositor.CreateScalarKeyFrameAnimation();
					scalarKeyFrameAnimation.Target = "RotationAngle";
					scalarKeyFrameAnimation.InsertExpressionKeyFrame(1f, "this.FinalValue", new LinearEasing());
					scalarKeyFrameAnimation.Duration = TimeSpan.FromMilliseconds(100.0);
					ScalarKeyFrameAnimation scalarKeyFrameAnimation2 = compositor.CreateScalarKeyFrameAnimation();
					scalarKeyFrameAnimation2.Target = "Opacity";
					scalarKeyFrameAnimation2.InsertExpressionKeyFrame(1f, "this.FinalValue", new LinearEasing());
					scalarKeyFrameAnimation2.Duration = TimeSpan.FromMilliseconds(100.0);
					Vector3KeyFrameAnimation vector3KeyFrameAnimation = compositor.CreateVector3KeyFrameAnimation();
					vector3KeyFrameAnimation.Target = "Offset";
					vector3KeyFrameAnimation.InsertExpressionKeyFrame(1f, "this.FinalValue", new LinearEasing());
					vector3KeyFrameAnimation.Duration = TimeSpan.FromMilliseconds(150.0);
					Vector3KeyFrameAnimation vector3KeyFrameAnimation2 = compositor.CreateVector3KeyFrameAnimation();
					vector3KeyFrameAnimation2.Target = "Scale";
					vector3KeyFrameAnimation2.InsertExpressionKeyFrame(1f, "this.FinalValue", new LinearEasing());
					vector3KeyFrameAnimation2.Duration = TimeSpan.FromMilliseconds(100.0);
					ImplicitAnimationCollection implicitAnimationCollection = compositor.CreateImplicitAnimationCollection();
					implicitAnimationCollection["RotationAngle"] = scalarKeyFrameAnimation;
					implicitAnimationCollection["Offset"] = vector3KeyFrameAnimation;
					implicitAnimationCollection["Scale"] = vector3KeyFrameAnimation2;
					implicitAnimationCollection["Opacity"] = scalarKeyFrameAnimation2;
					elementVisual.ImplicitAnimations = implicitAnimationCollection;
					UpdateContent();
				}
			}
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			UpdateContent();
		}

		private void UpdateContent()
		{
			if (_content == null || _root == null)
			{
				return;
			}
			Grid root = _root;
			CompositionVisual compositionVisual = _refreshInfoProvider?.Visual;
			CompositionVisual elementVisual = ElementComposition.GetElementVisual(_content);
			CompositionVisual elementVisual2 = ElementComposition.GetElementVisual(this);
			if (compositionVisual == null || elementVisual == null || elementVisual2 == null)
			{
				return;
			}
			elementVisual.CenterPoint = new Vector3D(_content.Bounds.Width / 2.0, _content.Bounds.Height / 2.0, 0.0);
			Vector3D vector3D;
			switch (RefreshVisualizerState)
			{
			case RefreshVisualizerState.Idle:
				_played = false;
				if (_rotateAnimation != null)
				{
					_rotateAnimation.IterationBehavior = AnimationIterationBehavior.Count;
					_rotateAnimation = null;
				}
				elementVisual.Opacity = 0.4f;
				elementVisual.RotationAngle = _startingRotationAngle;
				elementVisual2.Offset = (IsPullDirectionVertical ? new Vector3D(elementVisual2.Offset.X, 0.0, 0.0) : new Vector3D(0.0, elementVisual2.Offset.Y, 0.0));
				compositionVisual.Offset = elementVisual2.Offset;
				_content.InvalidateMeasure();
				break;
			case RefreshVisualizerState.Interacting:
				_played = false;
				elementVisual.Opacity = 0.4f;
				elementVisual.RotationAngle = (float)((double)_startingRotationAngle + _interactionRatio * 2.0 * Math.PI);
				vector3D = default(Vector3D);
				vector3D = (compositionVisual.Offset = ((!IsPullDirectionVertical) ? new Vector3D(_interactionRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Width, 0.0, 0.0) : new Vector3D(0.0, _interactionRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Height, 0.0)));
				elementVisual2.Offset = (IsPullDirectionVertical ? new Vector3D(elementVisual2.Offset.X, vector3D.Y, 0.0) : new Vector3D(vector3D.X, elementVisual2.Offset.Y, 0.0));
				break;
			case RefreshVisualizerState.Pending:
				elementVisual.Opacity = 1f;
				elementVisual.RotationAngle = _startingRotationAngle + (float)Math.PI * 2f;
				vector3D = (compositionVisual.Offset = ((!IsPullDirectionVertical) ? new Vector3D(_interactionRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Width, 0.0, 0.0) : new Vector3D(0.0, _interactionRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Height, 0.0)));
				elementVisual2.Offset = (IsPullDirectionVertical ? new Vector3D(elementVisual2.Offset.X, vector3D.Y, 0.0) : new Vector3D(vector3D.X, elementVisual2.Offset.Y, 0.0));
				if (!_played)
				{
					_played = true;
					Vector3KeyFrameAnimation vector3KeyFrameAnimation = elementVisual.Compositor.CreateVector3KeyFrameAnimation();
					vector3KeyFrameAnimation.Target = "Scale";
					vector3KeyFrameAnimation.InsertKeyFrame(0.5f, new Vector3(1.5f, 1.5f, 1f));
					vector3KeyFrameAnimation.InsertKeyFrame(1f, new Vector3(1f, 1f, 1f));
					vector3KeyFrameAnimation.Duration = TimeSpan.FromSeconds(0.3);
					elementVisual.StartAnimation("Scale", vector3KeyFrameAnimation);
				}
				break;
			case RefreshVisualizerState.Refreshing:
			{
				_rotateAnimation = elementVisual.Compositor.CreateScalarKeyFrameAnimation();
				_rotateAnimation.Target = "RotationAngle";
				_rotateAnimation.InsertKeyFrame(0f, _startingRotationAngle, new LinearEasing());
				_rotateAnimation.InsertKeyFrame(1f, _startingRotationAngle + (float)Math.PI * 2f, new LinearEasing());
				_rotateAnimation.IterationBehavior = AnimationIterationBehavior.Forever;
				_rotateAnimation.StopBehavior = AnimationStopBehavior.LeaveCurrentValue;
				_rotateAnimation.Duration = TimeSpan.FromSeconds(0.5);
				elementVisual.StartAnimation("RotationAngle", _rotateAnimation);
				elementVisual.Opacity = 1f;
				float num = (float)((_refreshInfoProvider != null) ? ((1.0 - _refreshInfoProvider.ExecutionRatio) * 0.5) : 1.0) * (IsPullDirectionFar ? (-1f) : 1f);
				vector3D = (compositionVisual.Offset = ((!IsPullDirectionVertical) ? new Vector3D(_executingRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Width, 0.0, 0.0) : new Vector3D(0.0, _executingRatio * (double)((!IsPullDirectionFar) ? 1 : (-1)) * root.Bounds.Height, 0.0)));
				elementVisual.Offset += (IsPullDirectionVertical ? new Vector3D(0.0, (double)num * root.Bounds.Height, 0.0) : new Vector3D((double)num * root.Bounds.Width, 0.0, 0.0));
				elementVisual2.Offset = (IsPullDirectionVertical ? new Vector3D(elementVisual2.Offset.X, vector3D.Y, 0.0) : new Vector3D(vector3D.X, elementVisual2.Offset.Y, 0.0));
				break;
			}
			case RefreshVisualizerState.Peeking:
				elementVisual.Opacity = 1f;
				elementVisual.RotationAngle = _startingRotationAngle;
				break;
			}
		}

		/// <summary>
		/// Initiates an update of the content.
		/// </summary>
		public void RequestRefresh()
		{
			RefreshVisualizerState = RefreshVisualizerState.Refreshing;
			RefreshInfoProvider?.OnRefreshStarted();
			RaiseRefreshRequested();
		}

		private void RefreshCompleted()
		{
			RefreshVisualizerState = RefreshVisualizerState.Idle;
			RefreshInfoProvider?.OnRefreshCompleted();
		}

		private void RaiseRefreshRequested()
		{
			RefreshRequestedEventArgs e = new RefreshRequestedEventArgs(RefreshCompleted, RefreshRequestedEvent);
			e.IncrementCount();
			RaiseEvent(e);
			e.DecrementCount();
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == RefreshInfoProviderProperty)
			{
				OnRefreshInfoProviderChanged();
			}
			else if (change.Property == ContentControl.ContentProperty)
			{
				if (change.OldValue is Control control)
				{
					control.Loaded -= OnContentLoaded;
					_root?.Children.Remove(control);
				}
				_content = change.NewValue as Control;
				if (_content != null)
				{
					_content.Loaded += OnContentLoaded;
				}
				if (_root != null && _content != null)
				{
					_root.Children.Insert(0, _content);
					_content.VerticalAlignment = VerticalAlignment.Center;
					_content.HorizontalAlignment = HorizontalAlignment.Center;
					UpdateContent();
				}
			}
			else if (change.Property == OrientationProperty)
			{
				OnOrientationChanged();
				UpdateContent();
			}
			else if (change.Property == Visual.BoundsProperty)
			{
				switch (PullDirection)
				{
				case PullDirection.TopToBottom:
					base.RenderTransform = new TranslateTransform(0.0, 0.0 - base.Bounds.Height);
					break;
				case PullDirection.BottomToTop:
					base.RenderTransform = new TranslateTransform(0.0, base.Bounds.Height);
					break;
				case PullDirection.LeftToRight:
					base.RenderTransform = new TranslateTransform(0.0 - base.Bounds.Width, 0.0);
					break;
				case PullDirection.RightToLeft:
					base.RenderTransform = new TranslateTransform(base.Bounds.Width, 0.0);
					break;
				}
				UpdateContent();
			}
			else if (change.Property == PullDirectionProperty)
			{
				OnOrientationChanged();
				UpdateContent();
			}
		}

		private void OnOrientationChanged()
		{
			switch (_orientation)
			{
			case RefreshVisualizerOrientation.Auto:
				switch (PullDirection)
				{
				case PullDirection.TopToBottom:
				case PullDirection.BottomToTop:
					_startingRotationAngle = 0f;
					break;
				case PullDirection.LeftToRight:
					_startingRotationAngle = -(float)Math.PI / 2f;
					break;
				case PullDirection.RightToLeft:
					_startingRotationAngle = (float)Math.PI / 2f;
					break;
				}
				break;
			case RefreshVisualizerOrientation.Normal:
				_startingRotationAngle = 0f;
				break;
			case RefreshVisualizerOrientation.Rotate90DegreesCounterclockwise:
				_startingRotationAngle = (float)Math.PI / 2f;
				break;
			case RefreshVisualizerOrientation.Rotate270DegreesCounterclockwise:
				_startingRotationAngle = -(float)Math.PI / 2f;
				break;
			}
		}

		private void OnRefreshInfoProviderChanged()
		{
			_isInteractingSubscription?.Dispose();
			_isInteractingSubscription = null;
			_interactionRatioSubscription?.Dispose();
			_interactionRatioSubscription = null;
			if (RefreshInfoProvider != null)
			{
				_isInteractingSubscription = RefreshInfoProvider.GetObservable(Avalonia.Controls.PullToRefresh.RefreshInfoProvider.IsInteractingForRefreshProperty).Subscribe(InteractingForRefreshObserver);
				_interactionRatioSubscription = RefreshInfoProvider.GetObservable(Avalonia.Controls.PullToRefresh.RefreshInfoProvider.InteractionRatioProperty).Subscribe(InteractionRatioObserver);
				_executingRatio = RefreshInfoProvider.ExecutionRatio;
			}
			else
			{
				_executingRatio = 1.0;
			}
		}

		private void InteractionRatioObserver(double obj)
		{
			bool flag = _interactionRatio == 0.0;
			_interactionRatio = obj;
			if (_isInteractingForRefresh)
			{
				if (RefreshVisualizerState == RefreshVisualizerState.Idle)
				{
					if (flag)
					{
						if (_interactionRatio > _executingRatio)
						{
							RefreshVisualizerState = RefreshVisualizerState.Pending;
						}
						else if (_interactionRatio > 0.0)
						{
							RefreshVisualizerState = RefreshVisualizerState.Interacting;
						}
					}
					else if (_interactionRatio > 0.0)
					{
						RefreshVisualizerState = RefreshVisualizerState.Peeking;
					}
				}
				else if (RefreshVisualizerState == RefreshVisualizerState.Interacting)
				{
					if (_interactionRatio <= 0.0)
					{
						RefreshVisualizerState = RefreshVisualizerState.Idle;
					}
					else if (_interactionRatio > _executingRatio)
					{
						RefreshVisualizerState = RefreshVisualizerState.Pending;
					}
					else
					{
						UpdateContent();
					}
				}
				else if (RefreshVisualizerState == RefreshVisualizerState.Pending)
				{
					if (_interactionRatio <= _executingRatio)
					{
						RefreshVisualizerState = RefreshVisualizerState.Interacting;
					}
					else if (_interactionRatio <= 0.0)
					{
						RefreshVisualizerState = RefreshVisualizerState.Idle;
					}
					else
					{
						UpdateContent();
					}
				}
			}
			else if (RefreshVisualizerState != RefreshVisualizerState.Refreshing)
			{
				if (_interactionRatio > 0.0)
				{
					RefreshVisualizerState = RefreshVisualizerState.Peeking;
				}
				else
				{
					RefreshVisualizerState = RefreshVisualizerState.Idle;
				}
			}
		}

		private void InteractingForRefreshObserver(bool obj)
		{
			_isInteractingForRefresh = obj;
			if (!_isInteractingForRefresh)
			{
				switch (_refreshVisualizerState)
				{
				case RefreshVisualizerState.Pending:
					RequestRefresh();
					break;
				default:
					RefreshVisualizerState = RefreshVisualizerState.Idle;
					break;
				case RefreshVisualizerState.Refreshing:
					break;
				}
			}
		}
	}
	/// <summary>
	/// Defines constants that specify the orientation of a RefreshVisualizer.
	/// </summary>
	public enum RefreshVisualizerOrientation
	{
		Auto,
		Normal,
		Rotate90DegreesCounterclockwise,
		Rotate270DegreesCounterclockwise
	}
	/// <summary>
	/// Defines constants that specify the state of a RefreshVisualizer
	/// </summary>
	public enum RefreshVisualizerState
	{
		Idle,
		Peeking,
		Interacting,
		Pending,
		Refreshing
	}
	/// <summary>
	/// Represents a button that allows a user to select a single option from a group of options.
	/// </summary>
	public class RadioButton : ToggleButton, IRadioButton, ILogical
	{
		/// <summary>
		/// Identifies the GroupName dependency property.
		/// </summary>
		public static readonly StyledProperty<string?> GroupNameProperty = AvaloniaProperty.Register<RadioButton, string>("GroupName");

		private RadioButtonGroupManager? _groupManager;

		/// <summary>
		/// Gets or sets the name that specifies which RadioButton controls are mutually exclusive.
		/// </summary>
		public string? GroupName
		{
			get
			{
				return GetValue(GroupNameProperty);
			}
			set
			{
				SetValue(GroupNameProperty, value);
			}
		}

		bool IRadioButton.IsChecked
		{
			get
			{
				return base.IsChecked == true;
			}
			set
			{
				SetCurrentValue(ToggleButton.IsCheckedProperty, value);
			}
		}

		MenuItemToggleType IRadioButton.ToggleType => MenuItemToggleType.Radio;

		protected override void Toggle()
		{
			if (base.IsChecked != true)
			{
				SetCurrentValue(ToggleButton.IsCheckedProperty, true);
			}
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			_groupManager?.Remove(this, GroupName);
			EnsureRadioGroupManager(e.Root);
			base.OnAttachedToVisualTree(e);
		}

		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			_groupManager?.Remove(this, GroupName);
			_groupManager = null;
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new RadioButtonAutomationPeer(this);
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == ToggleButton.IsCheckedProperty)
			{
				IsCheckedChanged(change.GetNewValue<bool?>());
			}
			else if (change.Property == GroupNameProperty)
			{
				var (oldGroupName, newGroupName) = change.GetOldAndNewValue<string>();
				OnGroupNameChanged(oldGroupName, newGroupName);
			}
		}

		private void OnGroupNameChanged(string? oldGroupName, string? newGroupName)
		{
			if (!string.IsNullOrEmpty(oldGroupName))
			{
				_groupManager?.Remove(this, oldGroupName);
			}
			if (!string.IsNullOrEmpty(newGroupName))
			{
				EnsureRadioGroupManager();
			}
		}

		private new void IsCheckedChanged(bool? value)
		{
			if (value == true)
			{
				EnsureRadioGroupManager();
				_groupManager.OnCheckedChanged(this);
			}
		}

		[MemberNotNull("_groupManager")]
		private void EnsureRadioGroupManager(IRenderRoot? root = null)
		{
			_groupManager = RadioButtonGroupManager.GetOrCreateForRoot(root ?? this.GetVisualRoot());
			_groupManager.Add(this);
		}
	}
	internal interface IRadioButton : ILogical
	{
		string? GroupName { get; }

		MenuItemToggleType ToggleType { get; }

		bool IsChecked { get; set; }
	}
	internal class RadioButtonGroupManager
	{
		private static readonly RadioButtonGroupManager s_default = new RadioButtonGroupManager();

		private static readonly ConditionalWeakTable<IRenderRoot, RadioButtonGroupManager> s_registeredVisualRoots = new ConditionalWeakTable<IRenderRoot, RadioButtonGroupManager>();

		private readonly Dictionary<string, List<WeakReference<IRadioButton>>> _registeredGroups = new Dictionary<string, List<WeakReference<IRadioButton>>>();

		private bool _ignoreCheckedChanges;

		public static RadioButtonGroupManager GetOrCreateForRoot(IRenderRoot? root)
		{
			if (root == null)
			{
				return s_default;
			}
			return s_registeredVisualRoots.GetValue(root, (IRenderRoot key) => new RadioButtonGroupManager());
		}

		public void Add(IRadioButton radioButton)
		{
			string groupName = radioButton.GroupName;
			if (groupName != null && radioButton.ToggleType == MenuItemToggleType.Radio)
			{
				if (!_registeredGroups.TryGetValue(groupName, out List<WeakReference<IRadioButton>> value))
				{
					value = new List<WeakReference<IRadioButton>>();
					_registeredGroups.Add(groupName, value);
				}
				value.Add(new WeakReference<IRadioButton>(radioButton));
			}
		}

		public void Remove(IRadioButton radioButton, string? oldGroupName)
		{
			if (string.IsNullOrEmpty(oldGroupName) || !_registeredGroups.TryGetValue(oldGroupName, out List<WeakReference<IRadioButton>> value))
			{
				return;
			}
			int num = 0;
			while (num < value.Count)
			{
				if (!value[num].TryGetTarget(out var target) || target == radioButton)
				{
					value.RemoveAt(num);
				}
				else
				{
					num++;
				}
			}
			if (value.Count == 0)
			{
				_registeredGroups.Remove(oldGroupName);
			}
		}

		public void OnCheckedChanged(IRadioButton radioButton)
		{
			if (_ignoreCheckedChanges || radioButton.ToggleType != MenuItemToggleType.Radio)
			{
				return;
			}
			_ignoreCheckedChanges = true;
			try
			{
				string groupName = radioButton.GroupName;
				if (!string.IsNullOrEmpty(groupName))
				{
					if (!_registeredGroups.TryGetValue(groupName, out List<WeakReference<IRadioButton>> value))
					{
						return;
					}
					int num = 0;
					while (num < value.Count)
					{
						if (!value[num].TryGetTarget(out var target))
						{
							value.RemoveAt(num);
							continue;
						}
						if (target != radioButton && target.IsChecked)
						{
							target.IsChecked = false;
						}
						num++;
					}
					if (value.Count == 0)
					{
						_registeredGroups.Remove(groupName);
					}
					IRadioButton radioButton2 = radioButton.LogicalParent as IRadioButton;
					while (radioButton2 != null && radioButton2.GroupName == groupName)
					{
						radioButton2.IsChecked = true;
						radioButton2 = radioButton2.LogicalParent as IRadioButton;
					}
					return;
				}
				ILogical logicalParent = radioButton.LogicalParent;
				if (logicalParent == null)
				{
					return;
				}
				foreach (ILogical logicalChild in logicalParent.LogicalChildren)
				{
					if (logicalChild != radioButton && logicalChild is IRadioButton { ToggleType: MenuItemToggleType.Radio } radioButton3 && string.IsNullOrEmpty(radioButton3.GroupName) && radioButton3.IsChecked)
					{
						radioButton3.IsChecked = false;
					}
				}
			}
			finally
			{
				_ignoreCheckedChanges = false;
			}
		}
	}
	/// <summary>
	/// Defines an area within which you can position and align child objects in relation to each other or the parent panel.
	/// </summary>
	public class RelativePanel : Panel
	{
		private class GraphNode
		{
			public bool Measured { get; set; }

			public Layoutable Element { get; }

			private bool HorizontalOffsetFlag { get; set; }

			private bool VerticalOffsetFlag { get; set; }

			private Size BoundingSize { get; set; }

			public Size OriginDesiredSize { get; set; }

			public double Left { get; set; } = double.NaN;

			public double Top { get; set; } = double.NaN;

			public double Right { get; set; } = double.NaN;

			public double Bottom { get; set; } = double.NaN;

			public HashSet<GraphNode> OutgoingNodes { get; }

			public GraphNode? AlignLeftWithNode { get; set; }

			public GraphNode? AlignTopWithNode { get; set; }

			public GraphNode? AlignRightWithNode { get; set; }

			public GraphNode? AlignBottomWithNode { get; set; }

			public GraphNode? LeftOfNode { get; set; }

			public GraphNode? AboveNode { get; set; }

			public GraphNode? RightOfNode { get; set; }

			public GraphNode? BelowNode { get; set; }

			public GraphNode? AlignHorizontalCenterWith { get; set; }

			public GraphNode? AlignVerticalCenterWith { get; set; }

			public GraphNode(Layoutable element)
			{
				OutgoingNodes = new HashSet<GraphNode>();
				Element = element;
			}

			public void Arrange(Size arrangeSize)
			{
				Element.Arrange(new Rect(Left, Top, Math.Max(arrangeSize.Width - Left - Right, 0.0), Math.Max(arrangeSize.Height - Top - Bottom, 0.0)));
			}

			public void Reset(bool clearPos)
			{
				if (clearPos)
				{
					Left = double.NaN;
					Top = double.NaN;
					Right = double.NaN;
					Bottom = double.NaN;
				}
				Measured = false;
			}

			public Size GetBoundingSize()
			{
				if (Left < 0.0 || Top < 0.0)
				{
					return default(Size);
				}
				if (Measured)
				{
					return BoundingSize;
				}
				if (!OutgoingNodes.Any())
				{
					BoundingSize = Element.DesiredSize;
					Measured = true;
				}
				else
				{
					BoundingSize = GetBoundingSize(this, Element.DesiredSize, OutgoingNodes);
					Measured = true;
				}
				return BoundingSize;
			}

			private static Size GetBoundingSize(GraphNode prevNode, Size prevSize, IEnumerable<GraphNode> nodes)
			{
				foreach (GraphNode node in nodes)
				{
					if (node.Measured || !node.OutgoingNodes.Any())
					{
						if ((prevNode.LeftOfNode != null && prevNode.LeftOfNode == node) || (prevNode.RightOfNode != null && prevNode.RightOfNode == node))
						{
							prevSize = prevSize.WithWidth(prevSize.Width + node.BoundingSize.Width);
							if (GetAlignHorizontalCenterWithPanel(node.Element) || node.HorizontalOffsetFlag)
							{
								prevSize = prevSize.WithWidth(prevSize.Width + prevNode.OriginDesiredSize.Width);
								prevNode.HorizontalOffsetFlag = true;
							}
							if (node.VerticalOffsetFlag)
							{
								prevNode.VerticalOffsetFlag = true;
							}
						}
						if ((prevNode.AboveNode != null && prevNode.AboveNode == node) || (prevNode.BelowNode != null && prevNode.BelowNode == node))
						{
							prevSize = prevSize.WithHeight(prevSize.Height + node.BoundingSize.Height);
							if (GetAlignVerticalCenterWithPanel(node.Element) || node.VerticalOffsetFlag)
							{
								prevSize = prevSize.WithHeight(prevSize.Height + node.OriginDesiredSize.Height);
								prevNode.VerticalOffsetFlag = true;
							}
							if (node.HorizontalOffsetFlag)
							{
								prevNode.HorizontalOffsetFlag = true;
							}
						}
						continue;
					}
					return GetBoundingSize(node, prevSize, node.OutgoingNodes);
				}
				return prevSize;
			}
		}

		private class Graph
		{
			private readonly Dictionary<AvaloniaObject, GraphNode> _nodeDic;

			private Size AvailableSize { get; set; }

			public Graph()
			{
				_nodeDic = new Dictionary<AvaloniaObject, GraphNode>();
			}

			public IEnumerable<GraphNode> GetNodes()
			{
				return _nodeDic.Values;
			}

			public void Clear()
			{
				AvailableSize = default(Size);
				_nodeDic.Clear();
			}

			public void Reset(bool clearPos = true)
			{
				_nodeDic.Values.Do(delegate(GraphNode node)
				{
					node.Reset(clearPos);
				});
			}

			public GraphNode? AddLink(GraphNode from, Layoutable? to)
			{
				if (to == null)
				{
					return null;
				}
				GraphNode graphNode;
				if (_nodeDic.ContainsKey(to))
				{
					graphNode = _nodeDic[to];
				}
				else
				{
					graphNode = new GraphNode(to);
					_nodeDic[to] = graphNode;
				}
				from.OutgoingNodes.Add(graphNode);
				return graphNode;
			}

			public GraphNode AddNode(Layoutable value)
			{
				if (!_nodeDic.ContainsKey(value))
				{
					GraphNode graphNode = new GraphNode(value);
					_nodeDic.Add(value, graphNode);
					return graphNode;
				}
				return _nodeDic[value];
			}

			public void Measure(Size availableSize)
			{
				AvailableSize = availableSize;
				Measure(_nodeDic.Values, null);
			}

			private void Measure(IEnumerable<GraphNode> nodes, HashSet<AvaloniaObject>? set)
			{
				if (set == null)
				{
					set = new HashSet<AvaloniaObject>();
				}
				foreach (GraphNode node in nodes)
				{
					if (!node.Measured && !node.OutgoingNodes.Any())
					{
						MeasureChild(node);
						continue;
					}
					if (node.OutgoingNodes.All((GraphNode item) => item.Measured))
					{
						MeasureChild(node);
						continue;
					}
					if (!set.Add(node.Element))
					{
						throw new Exception("RelativePanel error: Circular dependency detected. Layout could not complete.");
					}
					Measure(node.OutgoingNodes, set);
					if (!node.Measured)
					{
						MeasureChild(node);
					}
				}
			}

			private void MeasureChild(GraphNode node)
			{
				Layoutable element = node.Element;
				element.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
				node.OriginDesiredSize = element.DesiredSize;
				bool alignLeftWithPanel = GetAlignLeftWithPanel(element);
				bool alignTopWithPanel = GetAlignTopWithPanel(element);
				bool alignRightWithPanel = GetAlignRightWithPanel(element);
				bool alignBottomWithPanel = GetAlignBottomWithPanel(element);
				if (alignLeftWithPanel)
				{
					node.Left = 0.0;
				}
				if (alignTopWithPanel)
				{
					node.Top = 0.0;
				}
				if (alignRightWithPanel)
				{
					node.Right = 0.0;
				}
				if (alignBottomWithPanel)
				{
					node.Bottom = 0.0;
				}
				if (node.AlignLeftWithNode != null)
				{
					node.Left = (node.Left.IsNaN() ? node.AlignLeftWithNode.Left : (node.AlignLeftWithNode.Left * 0.5));
				}
				if (node.AlignTopWithNode != null)
				{
					node.Top = (node.Top.IsNaN() ? node.AlignTopWithNode.Top : (node.AlignTopWithNode.Top * 0.5));
				}
				if (node.AlignRightWithNode != null)
				{
					node.Right = (node.Right.IsNaN() ? node.AlignRightWithNode.Right : (node.AlignRightWithNode.Right * 0.5));
				}
				if (node.AlignBottomWithNode != null)
				{
					node.Bottom = (node.Bottom.IsNaN() ? node.AlignBottomWithNode.Bottom : (node.AlignBottomWithNode.Bottom * 0.5));
				}
				if (node.BelowNode != null && node.Top.IsNaN())
				{
					node.Top = AvailableSize.Height - node.BelowNode.Bottom;
				}
				if (node.RightOfNode != null && node.Left.IsNaN())
				{
					node.Left = AvailableSize.Width - node.RightOfNode.Right;
				}
				double num = AvailableSize.Height - node.Top - node.Bottom;
				if (num.IsNaN())
				{
					num = AvailableSize.Height;
					if (!node.Top.IsNaN() && node.Bottom.IsNaN())
					{
						num -= node.Top;
					}
					else if (node.Top.IsNaN() && !node.Bottom.IsNaN())
					{
						num -= node.Bottom;
					}
				}
				double num2 = AvailableSize.Width - node.Left - node.Right;
				if (num2.IsNaN())
				{
					num2 = AvailableSize.Width;
					if (!node.Left.IsNaN() && node.Right.IsNaN())
					{
						num2 -= node.Left;
					}
					else if (node.Left.IsNaN() && !node.Right.IsNaN())
					{
						num2 -= node.Right;
					}
				}
				element.Measure(new Size(Math.Max(num2, 0.0), Math.Max(num, 0.0)));
				Size desiredSize = element.DesiredSize;
				if (node.LeftOfNode != null && node.Left.IsNaN())
				{
					node.Left = node.LeftOfNode.Left - desiredSize.Width;
				}
				if (node.AboveNode != null && node.Top.IsNaN())
				{
					node.Top = node.AboveNode.Top - desiredSize.Height;
				}
				if (node.RightOfNode != null && node.Right.IsNaN())
				{
					node.Right = node.RightOfNode.Right - desiredSize.Width;
				}
				if (node.BelowNode != null && node.Bottom.IsNaN())
				{
					node.Bottom = node.BelowNode.Bottom - desiredSize.Height;
				}
				if (node.AlignHorizontalCenterWith != null)
				{
					double num3 = (AvailableSize.Width + node.AlignHorizontalCenterWith.Left - node.AlignHorizontalCenterWith.Right - desiredSize.Width) * 0.5;
					double num4 = (AvailableSize.Width - node.AlignHorizontalCenterWith.Left + node.AlignHorizontalCenterWith.Right - desiredSize.Width) * 0.5;
					if (node.Left.IsNaN())
					{
						node.Left = num3;
					}
					else
					{
						node.Left = (node.Left + num3) * 0.5;
					}
					if (node.Right.IsNaN())
					{
						node.Right = num4;
					}
					else
					{
						node.Right = (node.Right + num4) * 0.5;
					}
				}
				if (node.AlignVerticalCenterWith != null)
				{
					double num5 = (AvailableSize.Height + node.AlignVerticalCenterWith.Top - node.AlignVerticalCenterWith.Bottom - desiredSize.Height) * 0.5;
					double num6 = (AvailableSize.Height - node.AlignVerticalCenterWith.Top + node.AlignVerticalCenterWith.Bottom - desiredSize.Height) * 0.5;
					if (node.Top.IsNaN())
					{
						node.Top = num5;
					}
					else
					{
						node.Top = (node.Top + num5) * 0.5;
					}
					if (node.Bottom.IsNaN())
					{
						node.Bottom = num6;
					}
					else
					{
						node.Bottom = (node.Bottom + num6) * 0.5;
					}
				}
				if (GetAlignHorizontalCenterWithPanel(element))
				{
					double num7 = (AvailableSize.Width - desiredSize.Width) * 0.5;
					if (node.Left.IsNaN())
					{
						node.Left = num7;
					}
					else
					{
						node.Left = (node.Left + num7) * 0.5;
					}
					if (node.Right.IsNaN())
					{
						node.Right = num7;
					}
					else
					{
						node.Right = (node.Right + num7) * 0.5;
					}
				}
				if (GetAlignVerticalCenterWithPanel(element))
				{
					double num8 = (AvailableSize.Height - desiredSize.Height) * 0.5;
					if (node.Top.IsNaN())
					{
						node.Top = num8;
					}
					else
					{
						node.Top = (node.Top + num8) * 0.5;
					}
					if (node.Bottom.IsNaN())
					{
						node.Bottom = num8;
					}
					else
					{
						node.Bottom = (node.Bottom + num8) * 0.5;
					}
				}
				if (node.Left.IsNaN())
				{
					if (!node.Right.IsNaN())
					{
						node.Left = AvailableSize.Width - node.Right - desiredSize.Width;
					}
					else
					{
						node.Left = 0.0;
						node.Right = AvailableSize.Width - desiredSize.Width;
					}
				}
				else if (!node.Left.IsNaN() && node.Right.IsNaN())
				{
					node.Right = AvailableSize.Width - node.Left - desiredSize.Width;
				}
				if (node.Top.IsNaN())
				{
					if (!node.Bottom.IsNaN())
					{
						node.Top = AvailableSize.Height - node.Bottom - desiredSize.Height;
					}
					else
					{
						node.Top = 0.0;
						node.Bottom = AvailableSize.Height - desiredSize.Height;
					}
				}
				else if (!node.Top.IsNaN() && node.Bottom.IsNaN())
				{
					node.Bottom = AvailableSize.Height - node.Top - desiredSize.Height;
				}
				node.Measured = true;
			}

			public Size GetBoundingSize(bool calcWidth, bool calcHeight)
			{
				Size size = default(Size);
				foreach (GraphNode value in _nodeDic.Values)
				{
					Size boundingSize = value.GetBoundingSize();
					size = size.WithWidth(Math.Max(size.Width, boundingSize.Width));
					size = size.WithHeight(Math.Max(size.Height, boundingSize.Height));
				}
				double num = (double.IsInfinity(AvailableSize.Width) ? size.Width : AvailableSize.Width);
				double num2 = (double.IsInfinity(AvailableSize.Height) ? size.Height : AvailableSize.Height);
				size = size.WithWidth(calcWidth ? size.Width : num);
				return size.WithHeight(calcHeight ? size.Height : num2);
			}
		}

