		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.RowDefinitions" /> class.
		/// </summary>
		/// <param name="s">A string representation of the row definitions.</param>
		public RowDefinitions(string s)
			: this()
		{
			AddRange(from x in GridLength.ParseLengths(s)
				select new RowDefinition(x));
		}

		public override string ToString()
		{
			return string.Join(",", this.Select((RowDefinition x) => x.Height));
		}

		/// <summary>
		/// Parses a string representation of row definitions collection.
		/// </summary>
		/// <param name="s">The row definitions string.</param>
		/// <returns>The <see cref="T:Avalonia.Controls.RowDefinitions" />.</returns>
		public static RowDefinitions Parse(string s)
		{
			return new RowDefinitions(s);
		}
	}
	/// <summary>
	/// Represents all screens available on a device.
	/// </summary>
	public class Screens
	{
		private readonly IScreenImpl _iScreenImpl;

		private EventHandler? _changedHandlers;

		/// <summary>
		/// Gets the total number of screens available on the device.
		/// </summary>
		public int ScreenCount => _iScreenImpl.ScreenCount;

		/// <summary>
		/// Gets the list of all screens available on the device.
		/// </summary>
		public IReadOnlyList<Screen> All => _iScreenImpl.AllScreens;

		/// <summary>
		/// Gets the primary screen on the device.
		/// </summary>
		public Screen? Primary => All.FirstOrDefault((Screen x) => x.IsPrimary);

		/// <summary>
		/// Event raised when any screen was changed.
		/// </summary>
		public event EventHandler? Changed
		{
			add
			{
				if (_changedHandlers == null)
				{
					IScreenImpl iScreenImpl = _iScreenImpl;
					iScreenImpl.Changed = (Action)Delegate.Combine(iScreenImpl.Changed, new Action(ImplChanged));
				}
				_changedHandlers = (EventHandler)Delegate.Combine(_changedHandlers, value);
			}
			remove
			{
				_changedHandlers = (EventHandler)Delegate.Remove(_changedHandlers, value);
				if (_changedHandlers == null)
				{
					IScreenImpl iScreenImpl = _iScreenImpl;
					iScreenImpl.Changed = (Action)Delegate.Remove(iScreenImpl.Changed, new Action(ImplChanged));
				}
			}
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Screens" /> class.
		/// </summary>
		[PrivateApi]
		public Screens(IScreenImpl iScreenImpl)
		{
			_iScreenImpl = iScreenImpl;
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the rectangle.
		/// </summary>
		/// <remarks>
		/// On mobile, this method always returns null.
		/// </remarks>
		/// <param name="bounds">Bounds that specifies the area for which to retrieve the display.</param>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		public Screen? ScreenFromBounds(PixelRect bounds)
		{
			return _iScreenImpl.ScreenFromRect(bounds);
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the specified <see cref="T:Avalonia.Controls.WindowBase" />.
		/// </summary>
		/// <param name="window">The window for which to retrieve the Screen.</param>
		/// <exception cref="T:System.ObjectDisposedException">Window platform implementation was already disposed.</exception>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		public Screen? ScreenFromWindow(WindowBase window)
		{
			if (window == null)
			{
				throw new ArgumentNullException("window");
			}
			if (window.PlatformImpl == null)
			{
				throw new ObjectDisposedException("Window platform implementation was already disposed.");
			}
			return _iScreenImpl.ScreenFromWindow(window.PlatformImpl);
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the specified <see cref="T:Avalonia.Controls.TopLevel" />.
		/// </summary>
		/// <param name="topLevel">The top level for which to retrieve the Screen.</param>
		/// <exception cref="T:System.ObjectDisposedException">TopLevel platform implementation was already disposed.</exception>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		public Screen? ScreenFromTopLevel(TopLevel topLevel)
		{
			if (topLevel == null)
			{
				throw new ArgumentNullException("topLevel");
			}
			if (topLevel.PlatformImpl == null)
			{
				throw new ObjectDisposedException("Window platform implementation was already disposed.");
			}
			return _iScreenImpl.ScreenFromTopLevel(topLevel.PlatformImpl);
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the specified <see cref="T:Avalonia.Platform.IWindowBaseImpl" />.
		/// </summary>
		/// <param name="window">The window impl for which to retrieve the Screen.</param>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		[Obsolete("Use ScreenFromWindow(WindowBase) overload.", true)]
		[EditorBrowsable(EditorBrowsableState.Never)]
		public Screen? ScreenFromWindow(IWindowBaseImpl window)
		{
			return _iScreenImpl.ScreenFromWindow(window);
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the specified point.
		/// </summary>
		/// <remarks>
		/// On mobile, this method always returns null.
		/// </remarks>
		/// <param name="point">A Point that specifies the location for which to retrieve a Screen.</param>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		public Screen? ScreenFromPoint(PixelPoint point)
		{
			return _iScreenImpl.ScreenFromPoint(point);
		}

		/// <summary>
		/// Retrieves a Screen for the display that contains the specified <see cref="T:Avalonia.Visual" />.
		/// </summary>
		/// <param name="visual">A Visual for which to retrieve a Screen.</param>
		/// <returns>The <see cref="T:Avalonia.Platform.Screen" />.</returns>
		public Screen? ScreenFromVisual(Visual visual)
		{
			if (visual == null)
			{
				throw new ArgumentNullException("visual");
			}
			TopLevel topLevel = TopLevel.GetTopLevel(visual);
			if (topLevel == null)
			{
				throw new ArgumentException("Control does not belong to a visual tree.", "visual");
			}
			if (topLevel is WindowBase)
			{
				PixelPoint topLeft = visual.PointToScreen(visual.Bounds.TopLeft);
				PixelPoint bottomRight = visual.PointToScreen(visual.Bounds.BottomRight);
				return ScreenFromBounds(new PixelRect(topLeft, bottomRight)) ?? ScreenFromTopLevel(topLevel);
			}
			return ScreenFromTopLevel(topLevel);
		}

		/// <summary>
		/// Asks underlying platform to provide detailed screen information.
		/// On some platforms it might include non-primary screens, as well as display names.
		/// </summary>
		/// <remarks>
		/// This method is async and might show a dialog to the user asking for a permission.
		/// </remarks>
		/// <returns>True, if detailed screen information was provided. False, if denied by the platform or user.</returns>
		public Task<bool> RequestScreenDetails()
		{
			return _iScreenImpl.RequestScreenDetails();
		}

		private void ImplChanged()
		{
			_changedHandlers?.Invoke(this, EventArgs.Empty);
		}
	}
	/// <summary>
	/// Describes a change in scrolling state.
	/// </summary>
	public class ScrollChangedEventArgs : RoutedEventArgs
