		/// Defines the <see cref="E:Avalonia.Controls.SplitButton.Click" /> event.
		/// </summary>
		public static readonly RoutedEvent<RoutedEventArgs> ClickEvent = RoutedEvent.Register<SplitButton, RoutedEventArgs>("Click", RoutingStrategies.Bubble);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.SplitButton.Command" /> property.
		/// </summary>
		public static readonly StyledProperty<ICommand?> CommandProperty = Button.CommandProperty.AddOwner<SplitButton>();

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.SplitButton.CommandParameter" /> property.
		/// </summary>
		public static readonly StyledProperty<object?> CommandParameterProperty = Button.CommandParameterProperty.AddOwner<SplitButton>();

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.SplitButton.Flyout" /> property
		/// </summary>
		public static readonly StyledProperty<FlyoutBase?> FlyoutProperty = Button.FlyoutProperty.AddOwner<SplitButton>();

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.SplitButton.HotKey" /> property.
		/// </summary>
		public static readonly StyledProperty<KeyGesture?> HotKeyProperty = Button.HotKeyProperty.AddOwner<SplitButton>();

		private Button? _primaryButton;

		private Button? _secondaryButton;

		private KeyGesture? _hotkey;

		private bool _commandCanExecute = true;

		private bool _isAttachedToLogicalTree;

		private bool _isFlyoutOpen;

		private bool _isKeyboardPressed;

		private IDisposable? _flyoutPropertyChangedDisposable;

		/// <summary>
		/// Gets or sets the <see cref="T:System.Windows.Input.ICommand" /> invoked when the primary part is pressed.
		/// </summary>
		public ICommand? Command
		{
			get
			{
				return GetValue(CommandProperty);
			}
			set
			{
				SetValue(CommandProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets a parameter to be passed to the <see cref="P:Avalonia.Controls.SplitButton.Command" />.
		/// </summary>
		public object? CommandParameter
		{
			get
			{
				return GetValue(CommandParameterProperty);
			}
			set
			{
				SetValue(CommandParameterProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets the <see cref="T:Avalonia.Controls.Primitives.FlyoutBase" /> that is shown when the secondary part is pressed.
		/// </summary>
		public FlyoutBase? Flyout
		{
			get
			{
				return GetValue(FlyoutProperty);
			}
			set
			{
				SetValue(FlyoutProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets an <see cref="T:Avalonia.Input.KeyGesture" /> associated with this control
		/// </summary>
		public KeyGesture? HotKey
		{
			get
			{
