		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.SplitButton" /> class.
		/// </summary>
		public SplitButton()
		{
		}

		/// <inheritdoc />
		void ICommandSource.CanExecuteChanged(object sender, EventArgs e)
		{
			CanExecuteChanged(sender, e);
		}

		/// <inheritdoc cref="M:Avalonia.Input.ICommandSource.CanExecuteChanged(System.Object,System.EventArgs)" />
		private void CanExecuteChanged(object? sender, EventArgs e)
		{
			ICommand? command = Command;
			object commandParameter = CommandParameter;
			ICommand command2 = command;
			CanExecuteChanged(command2, commandParameter);
		}

		private void CanExecuteChanged(ICommand? command, object? parameter)
		{
			if (((ILogical)this).IsAttachedToLogicalTree)
			{
				bool flag = command?.CanExecute(parameter) ?? true;
				if (flag != _commandCanExecute)
				{
					_commandCanExecute = flag;
					UpdateIsEffectivelyEnabled();
				}
			}
		}

		/// <summary>
		/// Updates the visual state of the control by applying latest PseudoClasses.
		/// </summary>
		protected void UpdatePseudoClasses()
		{
			base.PseudoClasses.Set(":flyout-open", _isFlyoutOpen);
			base.PseudoClasses.Set(":pressed", _isKeyboardPressed);
			base.PseudoClasses.Set(":checked", InternalIsChecked);
		}

		/// <summary>
		/// Opens the secondary button's flyout.
		/// </summary>
		protected void OpenFlyout()
		{
			Flyout?.ShowAt(this);
		}

		/// <summary>
		/// Closes the secondary button's flyout.
		/// </summary>
		protected void CloseFlyout()
		{
			Flyout?.Hide();
		}

		/// <summary>
		/// Registers all flyout events.
		/// </summary>
		/// <param name="flyout">The flyout to connect events to.</param>
		private void RegisterFlyoutEvents(FlyoutBase? flyout)
		{
			if (flyout != null)
			{
				flyout.Opened += Flyout_Opened;
				flyout.Closed += Flyout_Closed;
				_flyoutPropertyChangedDisposable = flyout.GetPropertyChangedObservable(Popup.PlacementProperty).Subscribe(Flyout_PlacementPropertyChanged);
			}
		}

		/// <summary>
		/// Explicitly unregisters all flyout events.
		/// </summary>
		/// <param name="flyout">The flyout to disconnect events from.</param>
		private void UnregisterFlyoutEvents(FlyoutBase? flyout)
		{
			if (flyout != null)
			{
				flyout.Opened -= Flyout_Opened;
				flyout.Closed -= Flyout_Closed;
				_flyoutPropertyChangedDisposable?.Dispose();
				_flyoutPropertyChangedDisposable = null;
			}
		}

		/// <summary>
		/// Explicitly unregisters all events related to the two buttons in OnApplyTemplate().
		/// </summary>
		private void UnregisterEvents()
		{
			if (_primaryButton != null)
			{
				_primaryButton.Click -= PrimaryButton_Click;
			}
			if (_secondaryButton != null)
			{
				_secondaryButton.Click -= SecondaryButton_Click;
				_secondaryButton.RemoveHandler(InputElement.PointerPressedEvent, SecondaryButton_PreviewPointerPressed);
			}
		}

		/// <inheritdoc />
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			UnregisterEvents();
			UnregisterFlyoutEvents(Flyout);
			_primaryButton = e.NameScope.Find<Button>("PART_PrimaryButton");
			_secondaryButton = e.NameScope.Find<Button>("PART_SecondaryButton");
			if (_primaryButton != null)
			{
				_primaryButton.Click += PrimaryButton_Click;
			}
			if (_secondaryButton != null)
			{
				_secondaryButton.Click += SecondaryButton_Click;
				_secondaryButton.AddHandler(InputElement.PointerPressedEvent, SecondaryButton_PreviewPointerPressed, RoutingStrategies.Tunnel);
			}
			RegisterFlyoutEvents(Flyout);
			UpdatePseudoClasses();
		}

		/// <inheritdoc />
		protected override void OnAttachedToLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			base.OnAttachedToLogicalTree(e);
			SetCurrentValue(HotKeyProperty, _hotkey);
			if (Command != null)
			{
				Command.CanExecuteChanged += CanExecuteChanged;
				CanExecuteChanged(this, EventArgs.Empty);
			}
			_isAttachedToLogicalTree = true;
		}

		/// <inheritdoc />
		protected override void OnDetachedFromLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromLogicalTree(e);
			_hotkey = HotKey;
			SetCurrentValue(HotKeyProperty, null);
			if (Command != null)
			{
				Command.CanExecuteChanged -= CanExecuteChanged;
			}
			_isAttachedToLogicalTree = false;
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Property == CommandProperty)
			{
				var (command, command2) = e.GetOldAndNewValue<ICommand>();
				if (_isAttachedToLogicalTree)
				{
					if (command != null)
					{
						ICommand command3 = command;
						command3.CanExecuteChanged -= CanExecuteChanged;
					}
					if (command2 != null)
					{
						ICommand command4 = command2;
						command4.CanExecuteChanged += CanExecuteChanged;
					}
				}
				CanExecuteChanged(command2, CommandParameter);
			}
			else if (e.Property == CommandParameterProperty && base.IsLoaded)
			{
				CanExecuteChanged(Command, e.NewValue);
			}
			else if (e.Property == FlyoutProperty)
			{
				var (flyoutBase, flyout) = e.GetOldAndNewValue<FlyoutBase>();
				if (flyoutBase != null && flyoutBase.IsOpen)
				{
					flyoutBase.Hide();
				}
				UnregisterFlyoutEvents(flyoutBase);
				RegisterFlyoutEvents(flyout);
				UpdatePseudoClasses();
			}
			base.OnPropertyChanged(e);
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
			Key key = e.Key;
			if ((base.IsFocused && key == Key.Space) || key == Key.Return)
			{
				_isKeyboardPressed = true;
				UpdatePseudoClasses();
			}
			base.OnKeyDown(e);
		}

		/// <inheritdoc />
		protected override void OnKeyUp(KeyEventArgs e)
		{
			Key key = e.Key;
			if ((base.IsFocused && key == Key.Space) || key == Key.Return)
			{
				_isKeyboardPressed = false;
				UpdatePseudoClasses();
				if (base.IsEffectivelyEnabled)
				{
					OnClickPrimary(null);
					e.Handled = true;
				}
			}
			else if (key == Key.Down && e.KeyModifiers.HasAllFlags(KeyModifiers.Alt) && base.IsEffectivelyEnabled && !this.IsAllowedXYNavigationMode(e.KeyDeviceType))
			{
				OpenFlyout();
				e.Handled = true;
			}
			else if (key == Key.F4 && base.IsEffectivelyEnabled)
			{
				OpenFlyout();
				e.Handled = true;
			}
			else if (e.Key == Key.Escape && _isFlyoutOpen)
			{
				CloseFlyout();
				e.Handled = true;
			}
			base.OnKeyUp(e);
		}

		/// <summary>
		/// Invokes the <see cref="E:Avalonia.Controls.SplitButton.Click" /> event when the primary button part is clicked.
		/// </summary>
		/// <param name="e">The event args from the internal Click event.</param>
		protected virtual void OnClickPrimary(RoutedEventArgs? e)
		{
			ICommand? command = Command;
			object commandParameter = CommandParameter;
			ICommand command2 = command;
			if (base.IsEffectivelyEnabled)
			{
				RoutedEventArgs e2 = new RoutedEventArgs(ClickEvent);
				RaiseEvent(e2);
				if (!e2.Handled && command2 != null && command2.CanExecute(commandParameter))
				{
					command2.Execute(commandParameter);
					e2.Handled = true;
				}
			}
		}

		/// <summary>
		/// Invoked when the secondary button part is clicked.
		/// </summary>
		/// <param name="e">The event args from the internal Click event.</param>
		protected virtual void OnClickSecondary(RoutedEventArgs? e)
		{
			if (base.IsEffectivelyEnabled)
			{
				if (_isFlyoutOpen)
				{
					CloseFlyout();
				}
				else
				{
					OpenFlyout();
				}
			}
		}

		/// <summary>
		/// Invoked when the split button's flyout is opened.
		/// </summary>
		protected virtual void OnFlyoutOpened()
		{
		}

		/// <summary>
		/// Invoked when the split button's flyout is closed.
		/// </summary>
		protected virtual void OnFlyoutClosed()
		{
		}

		/// <summary>
		/// Event handler for when the internal primary button part is clicked.
		/// </summary>
		private void PrimaryButton_Click(object? sender, RoutedEventArgs e)
		{
			e.Handled = true;
			OnClickPrimary(e);
		}

		/// <summary>
		/// Event handler for when the internal secondary button part is clicked.
		/// </summary>
		private void SecondaryButton_Click(object? sender, RoutedEventArgs e)
		{
			e.Handled = true;
			OnClickSecondary(e);
		}

		/// <summary>
		/// Event handler for when the internal secondary button part is pressed.
		/// </summary>
		private void SecondaryButton_PreviewPointerPressed(object? sender, PointerPressedEventArgs e)
		{
			if (_isFlyoutOpen)
			{
				Button? secondaryButton = _secondaryButton;
				if (secondaryButton != null && secondaryButton.IsEffectivelyEnabled && e.GetCurrentPoint(_secondaryButton).Properties.IsLeftButtonPressed)
				{
					e.Handled = true;
					OnClickSecondary(e);
				}
			}
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Primitives.PopupFlyoutBase.Placement" /> property changes.
		/// </summary>
		private void Flyout_PlacementPropertyChanged(AvaloniaPropertyChangedEventArgs e)
		{
			UpdatePseudoClasses();
		}

		/// <summary>
		/// Event handler for when the split button's flyout is opened.
		/// </summary>
		private void Flyout_Opened(object? sender, EventArgs e)
		{
			if ((sender as FlyoutBase)?.Target == this)
			{
				_isFlyoutOpen = true;
				UpdatePseudoClasses();
				OnFlyoutOpened();
			}
		}

		/// <summary>
		/// Event handler for when the split button's flyout is closed.
		/// </summary>
		private void Flyout_Closed(object? sender, EventArgs e)
		{
			if ((sender as FlyoutBase)?.Target == this)
			{
				_isFlyoutOpen = false;
				UpdatePseudoClasses();
				OnFlyoutClosed();
			}
		}

		void IClickableControl.RaiseClick()
		{
			((IClickableControl)_primaryButton)?.RaiseClick();
		}
	}
