		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.TabItem" /> class.
		/// </summary>
		static TabItem()
		{
			TabStripPlacementProperty = AvaloniaProperty.RegisterDirect("TabStripPlacement", (TabItem o) => o.TabStripPlacement);
			IsSelectedProperty = SelectingItemsControl.IsSelectedProperty.AddOwner<TabItem>();
			SelectableMixin.Attach<TabItem>(IsSelectedProperty);
			PressedMixin.Attach<TabItem>();
			InputElement.FocusableProperty.OverrideDefaultValue(typeof(TabItem), defaultValue: true);
			StyledElement.DataContextProperty.Changed.AddClassHandler(delegate(TabItem x, AvaloniaPropertyChangedEventArgs e)
			{
				x.UpdateHeader(e);
			});
			AutomationProperties.ControlTypeOverrideProperty.OverrideDefaultValue<TabItem>(AutomationControlType.TabItem);
			AutomationProperties.IsOffscreenBehaviorProperty.OverrideDefaultValue<TabItem>(IsOffscreenBehavior.FromClip);
			AccessKeyHandler.AccessKeyPressedEvent.AddClassHandler<TabItem>(OnAccessKeyPressed);
		}

		/// <inheritdoc />
		protected override void OnAccessKey(RoutedEventArgs e)
		{
			Focus();
			SetCurrentValue(IsSelectedProperty, value: true);
			e.Handled = true;
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new ListItemAutomationPeer(this);
		}

		[Obsolete("Owner manages its children properties by itself")]
		protected void SubscribeToOwnerProperties(AvaloniaObject owner)
		{
		}

		private static void OnAccessKeyPressed(TabItem tabItem, AccessKeyPressedEventArgs e)
		{
			if (!e.Handled && (e.Target == null || !tabItem.IsSelected))
			{
				e.Target = tabItem;
				e.Handled = true;
			}
		}

		private void UpdateHeader(AvaloniaPropertyChangedEventArgs obj)
		{
			if (base.Header == null)
			{
				if (obj.NewValue is IHeadered headered)
				{
					if (base.Header != headered.Header)
					{
						SetCurrentValue(HeaderedContentControl.HeaderProperty, headered.Header);
					}
				}
				else if (!(obj.NewValue is Control))
				{
					SetCurrentValue(HeaderedContentControl.HeaderProperty, obj.NewValue);
				}
			}
			else if (base.Header == obj.OldValue)
			{
				SetCurrentValue(HeaderedContentControl.HeaderProperty, obj.NewValue);
			}
		}
	}
