	/// <summary>
	/// A control that displays a block of text.
	/// </summary>
	public class TextBlock : Control, IInlineHost, ILogical
	{
		protected readonly record struct SimpleTextSource : ITextSource
		{
			private readonly string _text;

			private readonly TextRunProperties _defaultProperties;

			public SimpleTextSource(string text, TextRunProperties defaultProperties)
			{
				_text = text;
				_defaultProperties = defaultProperties;
			}

			public TextRun? GetTextRun(int textSourceIndex)
			{
				if (textSourceIndex > _text.Length)
				{
					return new TextEndOfParagraph();
				}
				ReadOnlyMemory<char> text = _text.AsMemory(textSourceIndex);
				if (text.IsEmpty)
				{
					return new TextEndOfParagraph();
				}
				return new TextCharacters(text, _defaultProperties);
			}

			[CompilerGenerated]
			private bool PrintMembers(StringBuilder builder)
			{
				return false;
			}
		}

		protected readonly struct InlinesTextSource : ITextSource
		{
			private readonly IReadOnlyList<TextRun> _textRuns;

			private readonly IReadOnlyList<ValueSpan<TextRunProperties>>? _textModifier;

			public IReadOnlyList<TextRun> TextRuns => _textRuns;

			public InlinesTextSource(IReadOnlyList<TextRun> textRuns, IReadOnlyList<ValueSpan<TextRunProperties>>? textModifier = null)
			{
				_textRuns = textRuns;
				_textModifier = textModifier;
			}

			public TextRun? GetTextRun(int textSourceIndex)
			{
				int num = 0;
				foreach (TextRun textRun in _textRuns)
				{
					if (textRun.Length == 0)
					{
						continue;
					}
					if (textSourceIndex >= num + textRun.Length)
					{
						num += textRun.Length;
						continue;
					}
					if (textRun is TextCharacters textCharacters)
					{
						int start = Math.Max(0, textSourceIndex - num);
						ValueSpan<TextRunProperties> valueSpan = FormattedTextSource.CreateTextStyleRun(textRun.Text.Slice(start).Span, textSourceIndex, textCharacters.Properties, _textModifier);
						return new TextCharacters(textRun.Text.Slice(start, valueSpan.Length), valueSpan.Value);
					}
					return textRun;
				}
				return new TextEndOfParagraph();
			}
		}

