		}

		/// <summary>
		/// Creates the <see cref="P:Avalonia.Controls.TextBlock.TextLayout" /> used to render the text.
		/// </summary>
		/// <returns>A <see cref="P:Avalonia.Controls.TextBlock.TextLayout" /> object.</returns>
		protected virtual TextLayout CreateTextLayout(string? text)
		{
			GenericTextRunProperties genericTextRunProperties = new GenericTextRunProperties(new Typeface(FontFamily, FontStyle, FontWeight, FontStretch), FontFeatures, FontSize, TextDecorations, Foreground);
			GenericTextParagraphProperties paragraphProperties = new GenericTextParagraphProperties(base.FlowDirection, base.IsMeasureValid ? TextAlignment : TextAlignment.Left, firstLineInParagraph: true, alwaysCollapsible: false, genericTextRunProperties, TextWrapping, LineHeight, 0.0, LetterSpacing)
			{
				LineSpacing = LineSpacing
			};
			ITextSource textSource = (ITextSource)((_textRuns == null) ? ((object)new SimpleTextSource(text ?? "", genericTextRunProperties)) : ((object)new InlinesTextSource(_textRuns)));
			Size maxSizeFromConstraint = GetMaxSizeFromConstraint();
			return new TextLayout(textSource, paragraphProperties, TextTrimming, maxSizeFromConstraint.Width, maxSizeFromConstraint.Height, MaxLines);
		}

		/// <summary>
		/// Invalidates <see cref="P:Avalonia.Controls.TextBlock.TextLayout" />.
		/// </summary>
		protected void InvalidateTextLayout()
		{
			InvalidateVisual();
			InvalidateMeasure();
		}

		protected override void OnMeasureInvalidated()
		{
			_textLayout?.Dispose();
			_textLayout = null;
			_textRuns = null;
			base.OnMeasureInvalidated();
		}

		protected override Size MeasureOverride(Size availableSize)
		{
			double layoutScale = LayoutHelper.GetLayoutScale(this);
			Thickness thickness = LayoutHelper.RoundLayoutThickness(Padding, layoutScale);
			Size size = availableSize.Deflate(thickness);
			if (_constraint != size)
			{
				_textLayout?.Dispose();
				_textLayout = null;
				_constraint = size;
				InvalidateArrange();
			}
			InlineCollection inlines = Inlines;
			if (HasComplexContent)
			{
				List<TextRun> textRuns = new List<TextRun>();
				foreach (Inline item in inlines)
				{
					item.BuildTextRun(textRuns, size);
				}
				_textRuns = textRuns;
			}
			TextLayout textLayout = TextLayout;
			return LayoutHelper.RoundLayoutSizeUp(new Size(textLayout.WidthIncludingTrailingWhitespace, textLayout.Height).Inflate(thickness), 1.0);
		}

		protected override Size ArrangeOverride(Size finalSize)
		{
			double num = 1.0;
			Thickness thickness = Padding;
			if (base.UseLayoutRounding)
			{
				num = LayoutHelper.GetLayoutScale(this);
				thickness = LayoutHelper.RoundLayoutThickness(Padding, num);
			}
			Size constraint = finalSize.Deflate(thickness);
			_textLayout?.Dispose();
			_textLayout = null;
			_constraint = constraint;
			TextLayout textLayout = TextLayout;
			if (HasComplexContent)
			{
				base.VisualChildren.Clear();
				double num2 = thickness.Top;
				foreach (TextLine textLine in textLayout.TextLines)
				{
					double num3 = thickness.Left + textLine.Start;
					foreach (TextRun textRun in textLine.TextRuns)
					{
						if (!(textRun is DrawableTextRun drawableTextRun))
						{
							continue;
						}
						if (drawableTextRun is EmbeddedControlRun embeddedControlRun)
						{
							Control control = embeddedControlRun.Control;
							if (control != null)
							{
								base.VisualChildren.Add(control);
								double baselineOffset = TextLineImpl.GetBaselineOffset(textLine, drawableTextRun);
								control.Arrange(new Rect(new Point(num3, num2 + baselineOffset), control.DesiredSize));
							}
						}
						num3 += drawableTextRun.Size.Width;
					}
					num2 += textLine.Height;
				}
			}
			return finalSize;
		}

