		private static bool IsValidMaxLines(int maxLines)
		{
			return maxLines >= 0;
		}

		private static bool IsValidLineHeight(double lineHeight)
		{
			if (!double.IsNaN(lineHeight))
			{
				return lineHeight > 0.0;
			}
			return true;
		}

		private static bool IsValidLineSpacing(double lineSpacing)
		{
			if (!double.IsNaN(lineSpacing))
			{
				return !double.IsInfinity(lineSpacing);
			}
			return false;
		}

		private void OnInlinesChanged(InlineCollection? oldValue, InlineCollection? newValue)
		{
			base.VisualChildren.Clear();
			if (oldValue != null)
			{
				oldValue.LogicalChildren = null;
				oldValue.InlineHost = null;
				oldValue.Invalidated -= Invalidated;
			}
			if (newValue != null)
			{
				newValue.LogicalChildren = base.LogicalChildren;
				newValue.InlineHost = this;
				newValue.Invalidated += Invalidated;
			}
			void Invalidated(object? sender, EventArgs e)
			{
				InvalidateMeasure();
			}
		}

		void IInlineHost.Invalidate()
		{
			InvalidateMeasure();
		}

		internal override void BuildDebugDisplay(StringBuilder builder, bool includeContent)
		{
