			int selectionStart = SelectionStart;
			int selectionEnd = SelectionEnd;
			int num = Math.Min(selectionStart, selectionEnd);
			int num2 = Math.Max(selectionStart, selectionEnd);
			if (num == num2 || (Text?.Length ?? 0) < num2)
