					}
					Thickness value = visual.GetValue(Layoutable.MarginProperty);
					Thickness value2 = visual.GetValue(Decorator.PaddingProperty);
					num += value.Top + value2.Top + value2.Bottom + value.Bottom;
					visual = visual.VisualParent;
