		/// <summary>
		/// Draw ticks.
		/// Ticks can be draw in 8 different ways depends on Placement property and IsDirectionReversed property.
		///
		/// This function also draw selection-tick(s) if IsSelectionRangeEnabled is 'true' and
		/// SelectionStart and SelectionEnd are valid.
		///
		/// The primary ticks (for Minimum and Maximum value) height will be 100% of TickBar's render size (use Width or Height
		/// depends on Placement property).
		///
		/// The secondary ticks (all other ticks, including selection-tics) height will be 75% of TickBar's render size.
		///
		/// Brush that use to fill ticks is specified by Fill property.
		/// </summary>
		public sealed override void Render(DrawingContext dc)
		{
			Size size = new Size(base.Bounds.Width, base.Bounds.Height);
			double num = Maximum - Minimum;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 1.0;
			Point point = default(Point);
			Point point2 = default(Point);
			double num5 = ((Orientation == Orientation.Horizontal) ? ReservedSpace.Width : ReservedSpace.Height);
			double num6 = num5 * 0.5;
			switch (Placement)
			{
			case TickBarPlacement.Top:
				if (MathUtilities.GreaterThanOrClose(num5, size.Width))
				{
					return;
				}
				size = new Size(size.Width - num5, size.Height);
				num2 = 0.0 - size.Height;
				point = new Point(num6, size.Height);
				point2 = new Point(num6 + size.Width, size.Height);
				num4 = size.Width / num;
				break;
			case TickBarPlacement.Bottom:
				if (MathUtilities.GreaterThanOrClose(num5, size.Width))
				{
					return;
				}
				size = new Size(size.Width - num5, size.Height);
				num2 = size.Height;
				point = new Point(num6, 0.0);
				point2 = new Point(num6 + size.Width, 0.0);
				num4 = size.Width / num;
				break;
			case TickBarPlacement.Left:
				if (MathUtilities.GreaterThanOrClose(num5, size.Height))
				{
					return;
				}
				size = new Size(size.Width, size.Height - num5);
				num2 = 0.0 - size.Width;
				point = new Point(size.Width, size.Height + num6);
				point2 = new Point(size.Width, num6);
				num4 = size.Height / num * -1.0;
				break;
			case TickBarPlacement.Right:
				if (MathUtilities.GreaterThanOrClose(num5, size.Height))
				{
					return;
				}
				size = new Size(size.Width, size.Height - num5);
				num2 = size.Width;
				point = new Point(0.0, size.Height + num6);
				point2 = new Point(0.0, num6);
				num4 = size.Height / num * -1.0;
				break;
			}
			num3 = num2 * 0.75;
			if (IsDirectionReversed)
			{
				num4 *= -1.0;
				Point point3 = point;
				point = point2;
				point2 = point3;
			}
			ImmutablePen pen = new ImmutablePen(Fill?.ToImmutable());
			if (Placement == TickBarPlacement.Left || Placement == TickBarPlacement.Right)
			{
				double num7 = TickFrequency;
				if (num7 > 0.0)
				{
					double num8 = (Maximum - Minimum) / size.Height;
					if (num7 < num8)
					{
						num7 = num8;
					}
				}
				dc.DrawLine(pen, point, new Point(point.X + num2, point.Y));
				dc.DrawLine(pen, new Point(point.X, point2.Y), new Point(point.X + num2, point2.Y));
				AvaloniaList<double> avaloniaList = Ticks ?? null;
				if (avaloniaList != null && avaloniaList.Count > 0)
				{
					for (int i = 0; i < avaloniaList.Count; i++)
					{
						if (!MathUtilities.LessThanOrClose(avaloniaList[i], Minimum) && !MathUtilities.GreaterThanOrClose(avaloniaList[i], Maximum))
						{
							double y = (avaloniaList[i] - Minimum) * num4 + point.Y;
							dc.DrawLine(pen, new Point(point.X, y), new Point(point.X + num3, y));
						}
					}
				}
				else if (num7 > 0.0)
				{
					for (double num9 = num7; num9 < num; num9 += num7)
					{
						double y2 = num9 * num4 + point.Y;
						dc.DrawLine(pen, new Point(point.X, y2), new Point(point.X + num3, y2));
					}
				}
				return;
			}
			double num10 = TickFrequency;
			if (num10 > 0.0)
			{
				double num11 = (Maximum - Minimum) / size.Width;
				if (num10 < num11)
				{
					num10 = num11;
				}
			}
			dc.DrawLine(pen, point, new Point(point.X, point.Y + num2));
			dc.DrawLine(pen, new Point(point2.X, point.Y), new Point(point2.X, point.Y + num2));
			AvaloniaList<double> avaloniaList2 = Ticks ?? null;
			if (avaloniaList2 != null && avaloniaList2.Count > 0)
			{
				for (int j = 0; j < avaloniaList2.Count; j++)
				{
					if (!MathUtilities.LessThanOrClose(avaloniaList2[j], Minimum) && !MathUtilities.GreaterThanOrClose(avaloniaList2[j], Maximum))
					{
						double x = (avaloniaList2[j] - Minimum) * num4 + point.X;
						dc.DrawLine(pen, new Point(x, point.Y), new Point(x, point.Y + num3));
					}
				}
			}
			else if (num10 > 0.0)
			{
				for (double num12 = num10; num12 < num; num12 += num10)
				{
					double x2 = num12 * num4 + point.X;
					dc.DrawLine(pen, new Point(x2, point.Y), new Point(x2, point.Y + num3));
				}
			}
		}
	}
	/// <summary>
	/// A Toggle Switch control.
	/// </summary>
	[TemplatePart("PART_MovingKnobs", typeof(Panel), IsRequired = true)]
	[TemplatePart("PART_OffContentPresenter", typeof(ContentPresenter))]
	[TemplatePart("PART_OnContentPresenter", typeof(ContentPresenter))]
	[TemplatePart("PART_SwitchKnob", typeof(Panel))]
	[PseudoClasses(new string[] { ":dragging" })]
	public class ToggleSwitch : ToggleButton
	{
		private Panel? _knobsPanel;

		private Panel? _switchKnob;

		private bool _knobsPanelPressed;

		private Point _switchStartPoint;

		private double _initLeft = -1.0;

		private bool _isDragging;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ToggleSwitch.OffContent" /> property.
		/// </summary>
		public static readonly StyledProperty<object?> OffContentProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ToggleSwitch.OffContentTemplate" /> property.
		/// </summary>
		public static readonly StyledProperty<IDataTemplate?> OffContentTemplateProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ToggleSwitch.OnContent" /> property.
		/// </summary>
		public static readonly StyledProperty<object?> OnContentProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ToggleSwitch.OnContentTemplate" /> property.
		/// </summary>
		public static readonly StyledProperty<IDataTemplate?> OnContentTemplateProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.ToggleSwitch.KnobTransitions" /> property.
		/// </summary>
		public static readonly StyledProperty<Transitions> KnobTransitionsProperty;

		/// <summary>
		/// Gets or Sets the Content that is displayed when in the On State.
		/// </summary>
		public object? OnContent
		{
			get
			{
				return GetValue(OnContentProperty);
			}
			set
			{
				SetValue(OnContentProperty, value);
			}
		}

		/// <summary>
		/// Gets or Sets the Content that is displayed when in the Off State.
		/// </summary>
		public object? OffContent
		{
			get
			{
				return GetValue(OffContentProperty);
			}
			set
			{
				SetValue(OffContentProperty, value);
			}
		}

		public ContentPresenter? OffContentPresenter { get; private set; }

		public ContentPresenter? OnContentPresenter { get; private set; }

		/// <summary>
		/// Gets or Sets the <see cref="T:Avalonia.Controls.Templates.IDataTemplate" /> used to display the <see cref="P:Avalonia.Controls.ToggleSwitch.OffContent" />.
		/// </summary>
		public IDataTemplate? OffContentTemplate
		{
			get
			{
				return GetValue(OffContentTemplateProperty);
			}
			set
			{
				SetValue(OffContentTemplateProperty, value);
			}
		}

		/// <summary>
		/// Gets or Sets the <see cref="T:Avalonia.Controls.Templates.IDataTemplate" /> used to display the <see cref="P:Avalonia.Controls.ToggleSwitch.OnContent" />.
		/// </summary>
		public IDataTemplate? OnContentTemplate
		{
			get
			{
				return GetValue(OnContentTemplateProperty);
			}
			set
			{
				SetValue(OnContentTemplateProperty, value);
			}
		}

		/// <summary>
		/// Gets or Sets the <see cref="T:Avalonia.Animation.Transitions" /> of switching knob. 
		/// </summary>
		public Transitions KnobTransitions
		{
			get
			{
				return GetValue(KnobTransitionsProperty);
			}
			set
			{
				SetValue(KnobTransitionsProperty, value);
			}
		}

		static ToggleSwitch()
		{
			OffContentProperty = AvaloniaProperty.Register<ToggleSwitch, object>("OffContent", "Off");
			OffContentTemplateProperty = AvaloniaProperty.Register<ToggleSwitch, IDataTemplate>("OffContentTemplate");
			OnContentProperty = AvaloniaProperty.Register<ToggleSwitch, object>("OnContent", "On");
			OnContentTemplateProperty = AvaloniaProperty.Register<ToggleSwitch, IDataTemplate>("OnContentTemplate");
			KnobTransitionsProperty = AvaloniaProperty.Register<ToggleSwitch, Transitions>("KnobTransitions");
			OffContentProperty.Changed.AddClassHandler(delegate(ToggleSwitch x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OffContentChanged(e);
			});
			OnContentProperty.Changed.AddClassHandler(delegate(ToggleSwitch x, AvaloniaPropertyChangedEventArgs e)
			{
				x.OnContentChanged(e);
			});
			ToggleButton.IsCheckedProperty.Changed.AddClassHandler(delegate(ToggleSwitch x, AvaloniaPropertyChangedEventArgs e)
			{
				if (e.NewValue != null && e.NewValue is bool value)
				{
					x.UpdateKnobPos(value);
				}
			});
			Visual.BoundsProperty.Changed.AddClassHandler(delegate(ToggleSwitch x, AvaloniaPropertyChangedEventArgs e)
			{
				if (x.IsChecked.HasValue)
				{
					x.UpdateKnobPos(x.IsChecked.Value);
				}
			});
			KnobTransitionsProperty.Changed.AddClassHandler(delegate(ToggleSwitch x, AvaloniaPropertyChangedEventArgs e)
			{
				x.UpdateKnobTransitions();
			});
		}

		private void OffContentChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (e.OldValue is ILogical item)
			{
				base.LogicalChildren.Remove(item);
			}
			if (e.NewValue is ILogical item2)
			{
				base.LogicalChildren.Add(item2);
			}
		}

		private void OnContentChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (e.OldValue is ILogical item)
			{
				base.LogicalChildren.Remove(item);
			}
			if (e.NewValue is ILogical item2)
			{
				base.LogicalChildren.Add(item2);
			}
		}

		protected override bool RegisterContentPresenter(ContentPresenter presenter)
		{
			bool result = base.RegisterContentPresenter(presenter);
			if (presenter.Name == "Part_OnContentPresenter")
			{
				OnContentPresenter = presenter;
				result = true;
			}
			else if (presenter.Name == "PART_OffContentPresenter")
			{
				OffContentPresenter = presenter;
				result = true;
			}
			return result;
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_switchKnob = e.NameScope.Find<Panel>("PART_SwitchKnob");
			_knobsPanel = e.NameScope.Get<Panel>("PART_MovingKnobs");
			_knobsPanel.PointerPressed += KnobsPanel_PointerPressed;
			_knobsPanel.PointerReleased += KnobsPanel_PointerReleased;
			_knobsPanel.PointerMoved += KnobsPanel_PointerMoved;
			if (base.IsChecked.HasValue)
			{
				UpdateKnobPos(base.IsChecked.Value);
			}
		}

		/// <inheritdoc />
		protected override void OnLoaded(RoutedEventArgs e)
		{
			base.OnLoaded(e);
			UpdateKnobTransitions();
		}

		private void UpdateKnobTransitions()
		{
			if (_knobsPanel != null)
			{
				_knobsPanel.Transitions = KnobTransitions;
			}
		}

		private void KnobsPanel_PointerPressed(object? sender, PointerPressedEventArgs e)
		{
			_switchStartPoint = e.GetPosition(_switchKnob);
			_initLeft = Canvas.GetLeft(_knobsPanel);
			_isDragging = false;
			_knobsPanelPressed = true;
		}

		private void KnobsPanel_PointerReleased(object? sender, PointerReleasedEventArgs e)
		{
			if (_isDragging)
			{
				e.Handled = true;
				bool flag = Canvas.GetLeft(_knobsPanel) >= _switchKnob.Bounds.Width / 2.0;
				_knobsPanel.ClearValue(Canvas.LeftProperty);
				base.PseudoClasses.Set(":dragging", value: false);
				if (flag == base.IsChecked)
				{
					UpdateKnobPos(flag);
				}
				else
				{
					SetCurrentValue(ToggleButton.IsCheckedProperty, flag);
				}
				UpdateKnobTransitions();
			}
			_isDragging = false;
			_knobsPanelPressed = false;
		}

		private void KnobsPanel_PointerMoved(object? sender, PointerEventArgs e)
		{
			if (!_knobsPanelPressed)
			{
				return;
			}
			Point point = e.GetPosition(_switchKnob) - _switchStartPoint;
			if (!_isDragging && Math.Abs(point.X) > 3.0)
			{
				if (_knobsPanel != null)
				{
					_knobsPanel.Transitions = null;
				}
				_isDragging = true;
				base.PseudoClasses.Set(":dragging", value: true);
			}
			if (_isDragging)
			{
				Canvas.SetLeft(_knobsPanel, Math.Min(_switchKnob.Bounds.Width, Math.Max(0.0, _initLeft + point.X)));
			}
		}

		private void UpdateKnobPos(bool value)
		{
			if (_switchKnob != null && _knobsPanel != null)
			{
				if (value)
				{
					Canvas.SetLeft(_knobsPanel, _switchKnob.Bounds.Width);
				}
				else
				{
					Canvas.SetLeft(_knobsPanel, 0.0);
				}
			}
		}
	}
