		private static void IsOpenChanged(AvaloniaPropertyChangedEventArgs e)
		{
			Control control = (Control)e.Sender;
			if ((bool)e.NewValue)
			{
				CancelRoutedEventArgs e2 = new CancelRoutedEventArgs(ToolTipOpeningEvent);
				control.RaiseEvent(e2);
				if (e2.Cancel)
				{
					control.SetCurrentValue(IsOpenProperty, value: false);
					return;
				}
				object tip = GetTip(control);
				if (tip == null)
				{
					control.SetCurrentValue(IsOpenProperty, value: false);
					return;
				}
				ToolTip toolTip = control.GetValue(ToolTipProperty);
				if (toolTip == null || (tip != toolTip && tip != toolTip.Content))
				{
					toolTip?.Close();
					toolTip = (tip as ToolTip) ?? new ToolTip
					{
						Content = tip
					};
					control.SetValue(ToolTipProperty, toolTip);
				}
				toolTip.AdornedControl = control;
				toolTip.Open(control);
			}
			else
			{
				ToolTip value = control.GetValue(ToolTipProperty);
				if (value != null)
				{
					value.AdornedControl = null;
					value.Close();
				}
			}
		}

		private void Open(Control control)
		{
			Close();
			if (_popup == null)
			{
				_popup = new Popup();
				_popup.Child = this;
				_popup.TakesFocusFromNativeControl = false;
				_popup.WindowManagerAddShadowHint = false;
				_popup.Opened += OnPopupOpened;
				_popup.Closed += OnPopupClosed;
			}
			_subscriptions = new CompositeDisposable(_popup.Bind(Popup.HorizontalOffsetProperty, control.GetBindingObservable(HorizontalOffsetProperty)), _popup.Bind(Popup.VerticalOffsetProperty, control.GetBindingObservable(VerticalOffsetProperty)), _popup.Bind(Popup.PlacementProperty, control.GetBindingObservable(PlacementProperty)), _popup.Bind(Popup.CustomPopupPlacementCallbackProperty, control.GetBindingObservable(CustomPopupPlacementCallbackProperty)));
			_popup.PlacementTarget = control;
			_popup.SetPopupParent(control);
			_popup.IsOpen = true;
		}

		private void Close()
		{
			Control adornedControl = AdornedControl;
			if (adornedControl != null && GetIsOpen(adornedControl))
			{
				RoutedEventArgs e = new RoutedEventArgs(ToolTipClosingEvent);
				adornedControl.RaiseEvent(e);
			}
			if (_popup != null)
			{
				_popup.IsOpen = false;
				_popup.SetPopupParent(null);
				_popup.PlacementTarget = null;
			}
			_subscriptions?.Dispose();
		}

		private void OnPopupClosed(object? sender, EventArgs e)
		{
			Control adornedControl = AdornedControl;
			if (adornedControl != null && GetIsOpen(adornedControl))
			{
				adornedControl.SetCurrentValue(IsOpenProperty, value: false);
			}
			_popupHostChangedHandler?.Invoke(null);
			UpdatePseudoClasses(newValue: false);
			this.Closed?.Invoke(this, EventArgs.Empty);
		}

		private void OnPopupOpened(object? sender, EventArgs e)
		{
			_popupHostChangedHandler?.Invoke(((Popup)sender).Host);
			UpdatePseudoClasses(newValue: true);
		}

		private void UpdatePseudoClasses(bool newValue)
		{
			base.PseudoClasses.Set(":open", newValue);
		}
	}
	/// <summary>
	/// Handles <see cref="T:Avalonia.Controls.ToolTip" /> interaction with controls.
	/// </summary>
	internal sealed class ToolTipService : IToolTipService, IDisposable
	{
		private readonly IDisposable _subscriptions;

		private Control? _tipControl;

		private long _lastTipCloseTime;

		private DispatcherTimer? _timer;

		private ulong _lastTipEventTime;

		private ulong _lastWindowEventTime;

		public ToolTipService(IInputManager inputManager)
		{
			_subscriptions = new CompositeDisposable(inputManager.Process.Subscribe(InputManager_OnProcess), ToolTip.ServiceEnabledProperty.Changed.Subscribe(ServiceEnabledChanged), ToolTip.TipProperty.Changed.Subscribe(TipChanged));
		}

		public void Dispose()
		{
			StopTimer();
			_subscriptions.Dispose();
		}

		private void InputManager_OnProcess(RawInputEventArgs e)
		{
			if (!(e is RawPointerEventArgs e2))
			{
				return;
			}
			bool flag = false;
			ToolTip toolTip = _tipControl?.GetValue(ToolTip.ToolTipProperty);
			if (toolTip != null && e.Root == toolTip.PopupHost)
			{
				flag = true;
				_lastTipEventTime = e2.Timestamp;
			}
			else if (e.Root == _tipControl?.VisualRoot)
			{
				_lastWindowEventTime = e2.Timestamp;
			}
			switch (e2.Type)
			{
			case RawPointerEventType.Move:
				Update(e2.Root, e2.InputHitTestResult.element as Visual);
				break;
			case RawPointerEventType.LeaveWindow:
				if ((e.Root == _tipControl?.VisualRoot && _lastTipEventTime != e.Timestamp) || (flag && _lastWindowEventTime != e.Timestamp))
				{
					ClearTip();
					_tipControl = null;
				}
				break;
			case RawPointerEventType.LeftButtonDown:
			case RawPointerEventType.RightButtonDown:
			case RawPointerEventType.MiddleButtonDown:
			case RawPointerEventType.XButton1Down:
			case RawPointerEventType.XButton2Down:
				ClearTip();
				break;
			case RawPointerEventType.LeftButtonUp:
			case RawPointerEventType.RightButtonUp:
			case RawPointerEventType.MiddleButtonUp:
			case RawPointerEventType.XButton1Up:
			case RawPointerEventType.XButton2Up:
				break;
			}
			void ClearTip()
			{
				StopTimer();
				_tipControl?.ClearValue(ToolTip.IsOpenProperty);
			}
		}

		public void Update(IInputRoot root, Visual? candidateToolTipHost)
		{
			ToolTip toolTip = _tipControl?.GetValue(ToolTip.ToolTipProperty);
			if (root == toolTip?.PopupHost?.HostedVisualTreeRoot)
			{
				return;
			}
			while (candidateToolTipHost != null)
			{
				if (candidateToolTipHost == toolTip)
				{
					return;
				}
				if (candidateToolTipHost is Control control)
				{
					if (!ToolTip.GetServiceEnabled(control))
					{
						return;
					}
					if (ToolTip.GetTip(control) != null && (control.IsEffectivelyEnabled || ToolTip.GetShowOnDisabled(control)))
					{
						break;
					}
				}
				candidateToolTipHost = candidateToolTipHost?.VisualParent;
			}
			Control control2 = candidateToolTipHost as Control;
			if (control2 != _tipControl)
			{
				OnTipControlChanged(_tipControl, control2);
				_tipControl = control2;
			}
		}

		private void ServiceEnabledChanged(AvaloniaPropertyChangedEventArgs<bool> args)
		{
			if (args.Sender == _tipControl && !ToolTip.GetServiceEnabled(_tipControl))
			{
				StopTimer();
			}
		}

		/// <summary>
		/// called when the <see cref="F:Avalonia.Controls.ToolTip.TipProperty" /> property changes on a control.
		/// </summary>
		/// <param name="e">The event args.</param>
		private void TipChanged(AvaloniaPropertyChangedEventArgs e)
		{
			Control control = (Control)e.Sender;
			if (!ToolTip.GetIsOpen(control) || e.NewValue == e.OldValue || e.NewValue is ToolTip)
			{
				return;
			}
			if (e.NewValue == null)
			{
				Close(control);
				return;
			}
			ToolTip value = control.GetValue(ToolTip.ToolTipProperty);
			if (value != null)
			{
				value.Content = e.NewValue;
			}
		}

		private void OnTipControlChanged(Control? oldValue, Control? newValue)
		{
			StopTimer();
			bool flag = false;
			if (oldValue != null && ToolTip.GetIsOpen(oldValue))
			{
				Close(oldValue);
				flag = true;
			}
			if (newValue != null && !ToolTip.GetIsOpen(newValue))
			{
				int betweenShowDelay = ToolTip.GetBetweenShowDelay(newValue);
				int num = ((betweenShowDelay < 0 || (!flag && DateTime.UtcNow.Ticks - _lastTipCloseTime > (long)betweenShowDelay * 10000L)) ? ToolTip.GetShowDelay(newValue) : 0);
				if (num == 0)
				{
					Open(newValue);
				}
				else
				{
					StartShowTimer(num, newValue);
				}
			}
		}

		private void ToolTipClosed(object? sender, EventArgs e)
		{
			_lastTipCloseTime = DateTime.UtcNow.Ticks;
			if (sender is ToolTip toolTip)
			{
				toolTip.Closed -= ToolTipClosed;
				toolTip.PointerExited -= ToolTipPointerExited;
			}
		}

		private void ToolTipPointerExited(object? sender, PointerEventArgs e)
		{
			if (sender is ToolTip toolTip)
			{
				Control adornedControl = toolTip.AdornedControl;
				if (adornedControl != null && adornedControl != _tipControl)
				{
					Close(adornedControl);
				}
			}
		}

		private void StartShowTimer(int showDelay, Control control)
		{
			_timer = new DispatcherTimer
			{
				Interval = TimeSpan.FromMilliseconds(showDelay),
				Tag = (this, control)
			};
			_timer.Tick += delegate
			{
				if (_timer != null)
				{
					Open(control);
				}
			};
			_timer.Start();
		}

		private void Open(Control control)
		{
			StopTimer();
			if (!control.IsAttachedToVisualTree)
			{
				return;
			}
			ToolTip.SetIsOpen(control, value: true);
			if (ToolTip.GetIsOpen(control))
			{
				ToolTip value = control.GetValue(ToolTip.ToolTipProperty);
				if (value != null)
				{
					value.Closed += ToolTipClosed;
					value.PointerExited += ToolTipPointerExited;
				}
			}
		}

		private void Close(Control control)
		{
			ToolTip.SetIsOpen(control, value: false);
		}

		private void StopTimer()
		{
			_timer?.Stop();
			_timer = null;
		}
	}
	/// <summary>
	/// Base class for top-level widgets.
	/// </summary>
	/// <remarks>
	/// This class acts as a base for top level widget.
	/// It handles scheduling layout, styling and rendering as well as
	/// tracking the widget's <see cref="P:Avalonia.Controls.TopLevel.ClientSize" />.
	/// </remarks>
	[TemplatePart("PART_TransparencyFallback", typeof(Border))]
