		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.TopLevel" /> class.
		/// </summary>
		/// <param name="impl">The platform-specific window implementation.</param>
		/// <param name="dependencyResolver">
		/// The dependency resolver to use. If null the default dependency resolver will be used.
		/// </param>
		public TopLevel(ITopLevelImpl impl, IAvaloniaDependencyResolver? dependencyResolver)
		{
			PlatformImpl = impl ?? throw new InvalidOperationException("Could not create window implementation: maybe no windowing subsystem was initialized?");
			_scaling = ValidateScaling(impl.RenderScaling);
			_actualTransparencyLevel = PlatformImpl.TransparencyLevel;
			if (dependencyResolver == null)
			{
				dependencyResolver = AvaloniaLocator.Current;
			}
			_accessKeyHandler = TryGetService<IAccessKeyHandler>(dependencyResolver);
			_inputManager = TryGetService<IInputManager>(dependencyResolver);
			_tooltipService = TryGetService<IToolTipService>(dependencyResolver);
			_keyboardNavigationHandler = TryGetService<IKeyboardNavigationHandler>(dependencyResolver);
			_globalStyles = TryGetService<IGlobalStyles>(dependencyResolver);
			_applicationThemeHost = TryGetService<IThemeVariantHost>(dependencyResolver);
			Renderer = new CompositingRenderer(this, impl.Compositor, () => PlatformImpl.Surfaces ?? Array.Empty<object>());
			Renderer.SceneInvalidated += SceneInvalidated;
			impl.SetInputRoot(this);
			impl.Closed = HandleClosed;
			impl.Input = HandleInput;
			impl.Paint = HandlePaint;
			impl.Resized = HandleResized;
			impl.ScalingChanged = HandleScalingChanged;
			impl.TransparencyLevelChanged = HandleTransparencyLevelChanged;
			CreatePlatformImplBinding(TransparencyLevelHintProperty, delegate(IReadOnlyList<WindowTransparencyLevel> hint)
			{
				PlatformImpl.SetTransparencyLevelHint(hint ?? Array.Empty<WindowTransparencyLevel>());
			});
			CreatePlatformImplBinding(ActualThemeVariantProperty, delegate(ThemeVariant variant)
			{
				if ((object)variant == null)
				{
					variant = ThemeVariant.Default;
				}
				PlatformImpl?.SetFrameThemeVariant(((PlatformThemeVariant?)variant).GetValueOrDefault());
			});
			_keyboardNavigationHandler?.SetOwner(this);
			_accessKeyHandler?.SetOwner(this);
			if (_globalStyles != null)
			{
				_globalStyles.GlobalStylesAdded += ((IStyleHost)this).StylesAdded;
				_globalStyles.GlobalStylesRemoved += ((IStyleHost)this).StylesRemoved;
			}
			if (_applicationThemeHost != null)
			{
				SetValue(ActualThemeVariantProperty, _applicationThemeHost.ActualThemeVariant, BindingPriority.Template);
				_applicationThemeHost.ActualThemeVariantChanged += GlobalActualThemeVariantChanged;
			}
			ClientSize = impl.ClientSize;
			IStyleHost stylingParent = ((IStyleHost)this).StylingParent;
			if (stylingParent is IResourceHost2 target)
			{
				_resourcesChangesSubscriber2 = new TargetWeakEventSubscriber<TopLevel, ResourcesChangedToken>(this, delegate(TopLevel topLevel, object? _, WeakEvent _, ResourcesChangedToken token)
				{
					topLevel.NotifyResourcesChanged(token);
				});
				ResourcesChanged2WeakEvent.Subscribe(target, _resourcesChangesSubscriber2);
			}
			else if (stylingParent is IResourceHost target2)
			{
				_resourcesChangesSubscriber = new TargetWeakEventSubscriber<TopLevel, ResourcesChangedEventArgs>(this, delegate(TopLevel topLevel, object? _, WeakEvent _, ResourcesChangedEventArgs _)
				{
					topLevel.NotifyResourcesChanged(ResourcesChangedToken.Create());
				});
				ResourcesChangedWeakEvent.Subscribe(target2, _resourcesChangesSubscriber);
			}
			impl.LostFocus = (Action)Delegate.Combine(impl.LostFocus, new Action(PlatformImpl_LostFocus));
			_pointerOverPreProcessor = new PointerOverPreProcessor(this);
			_pointerOverPreProcessorSubscription = _inputManager?.PreProcess.Subscribe(_pointerOverPreProcessor);
			ISystemNavigationManagerImpl systemNavigationManagerImpl = impl.TryGetFeature<ISystemNavigationManagerImpl>();
			if (systemNavigationManagerImpl != null)
			{
				systemNavigationManagerImpl.BackRequested += delegate(object? _, RoutedEventArgs e)
				{
					e.RoutedEvent = BackRequestedEvent;
					Dispatcher.UIThread.Send(delegate
					{
						RaiseEvent(e);
					});
				};
			}
			_backGestureSubscription = _inputManager?.PreProcess.Subscribe(delegate(RawInputEventArgs e)
			{
				if (e.Root == this)
				{
					bool flag = false;
					if (e is RawKeyEventArgs { Type: RawKeyEventType.KeyDown } e2)
					{
						List<KeyGesture> list = PlatformSettings?.HotkeyConfiguration.Back;
						if (list != null)
						{
							KeyEventArgs keyEvent = new KeyEventArgs
							{
								KeyModifiers = (KeyModifiers)e2.Modifiers,
								Key = e2.Key,
								PhysicalKey = e2.PhysicalKey,
								KeyDeviceType = e2.KeyDeviceType,
								KeySymbol = e2.KeySymbol
							};
							flag = list.Any((KeyGesture key) => key.Matches(keyEvent));
						}
					}
					else if (e is RawPointerEventArgs e3)
					{
						flag = e3.Type == RawPointerEventType.XButton1Down;
					}
					if (flag)
					{
						RoutedEventArgs backRequestedEventArgs = new RoutedEventArgs(BackRequestedEvent);
						Dispatcher.UIThread.Send(delegate
						{
							RaiseEvent(backRequestedEventArgs);
						});
						e.Handled = backRequestedEventArgs.Handled;
					}
				}
			});
		}

