		private protected void CreatePlatformImplBinding<TValue>(StyledProperty<TValue> property, Action<TValue> onValue)
		{
			_platformImplBindings.TryGetValue(property, out Action value);
			_platformImplBindings[property] = (Action)Delegate.Combine(value, new Action(UpdatePlatformImpl));
			UpdatePlatformImpl();
			void UpdatePlatformImpl()
			{
				if (PlatformImpl != null)
				{
					onValue(GetValue(property));
				}
			}
		}

