		/// <summary>
		/// Tries to get a service from an <see cref="T:Avalonia.IAvaloniaDependencyResolver" />, logging a
		/// warning if not found.
		/// </summary>
		/// <typeparam name="T">The service type.</typeparam>
		/// <param name="resolver">The resolver.</param>
		/// <returns>The service.</returns>
		private T? TryGetService<T>(IAvaloniaDependencyResolver resolver) where T : class
		{
			T? service = resolver.GetService<T>();
			if (service == null)
			{
				ParametrizedLogger? parametrizedLogger = Logger.TryGet(LogEventLevel.Warning, "Control");
				if (!parametrizedLogger.HasValue)
				{
					return service;
				}
				parametrizedLogger.GetValueOrDefault().Log(this, "Could not create {Service} : maybe Application.RegisterServices() wasn't called?", typeof(T));
			}
			return service;
		}

		/// <summary>
		/// Handles input from <see cref="P:Avalonia.Platform.ITopLevelImpl.Input" />.
		/// </summary>
		/// <param name="e">The event args.</param>
		private void HandleInput(RawInputEventArgs e)
		{
			if (PlatformImpl != null)
			{
				Dispatcher.UIThread.Send(delegate(object? state)
				{
					using (Diagnostic.BeginLayoutInputPass())
					{
						var (topLevel, e2) = ((TopLevel, RawInputEventArgs))state;
						if (e2 is RawPointerEventArgs e3)
						{
							IInputElement inputElement = topLevel.InputHitTest(e3.Position, enabledElementsOnly: false);
							e3.InputHitTestResult = (element: inputElement, firstEnabledAncestor: FirstEnabledAncestor(inputElement));
						}
						topLevel._inputManager?.ProcessInput(e2);
					}
				}, (this, e));
			}
			else
			{
				Logger.TryGet(LogEventLevel.Warning, "Control")?.Log(this, "PlatformImpl is null, couldn't handle input.");
			}
		}

		private static IInputElement? FirstEnabledAncestor(IInputElement? hitTestElement)
		{
			IInputElement inputElement = hitTestElement;
			while (inputElement != null && !inputElement.IsEffectivelyEnabled)
			{
				inputElement = (inputElement as Visual)?.VisualParent as IInputElement;
			}
			return inputElement;
		}

		private void UpdateCursor()
		{
			PlatformImpl?.SetCursor(_cursorOverride?.PlatformImpl ?? _cursor?.PlatformImpl);
		}

		private void SetCursor(Cursor? cursor)
		{
			_cursor = cursor;
			UpdateCursor();
		}

		/// <summary>
		/// This should only be used by InProcessDragSource
		/// </summary>
		internal void SetCursorOverride(Cursor? cursor)
		{
			_cursorOverride = cursor;
			UpdateCursor();
		}

		private void PointerOverElementOnPropertyChanged(object? sender, AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Property == InputElement.CursorProperty && sender is InputElement inputElement)
			{
				SetCursor(inputElement.Cursor);
			}
		}

		private void GlobalActualThemeVariantChanged(object? sender, EventArgs e)
		{
			SetValue(ActualThemeVariantProperty, ((IThemeVariantHost)sender).ActualThemeVariant, BindingPriority.Template);
		}

		private void SceneInvalidated(object? sender, SceneInvalidatedEventArgs e)
		{
			_pointerOverPreProcessor?.SceneInvalidated(e.DirtyRect);
			UpdateToolTip(e.DirtyRect);
		}

		private static void OnToolTipServiceEnabledChanged(AvaloniaPropertyChangedEventArgs<bool> args)
		{
			if (args.GetNewValue<bool>() && args.Priority != BindingPriority.Inherited && args.Sender is Visual visual)
			{
				TopLevel topLevel = GetTopLevel(visual);
				topLevel?.UpdateToolTip(visual.Bounds.Translate(visual.TranslatePoint(default(Point), topLevel).Value));
			}
		}

		private void UpdateToolTip(Rect dirtyRect)
		{
			if (_tooltipService == null || !base.IsPointerOver)
			{
				return;
			}
			PixelPoint? pixelPoint = _pointerOverPreProcessor?.LastPosition;
			if (pixelPoint.HasValue)
			{
				PixelPoint valueOrDefault = pixelPoint.GetValueOrDefault();
				Point p = this.PointToClient(valueOrDefault);
				if (dirtyRect.Contains(p))
				{
					_tooltipService.Update(this, this.InputHitTest(p, enabledElementsOnly: false) as Visual);
				}
			}
		}

		private void PlatformImpl_LostFocus()
		{
			Visual visual = (Visual)(FocusManager?.GetFocusedElement());
			if (visual != null)
			{
				while (visual.VisualParent != null)
				{
					visual = visual.VisualParent;
				}
				if (visual == this)
				{
					KeyboardDevice.Instance?.SetFocusedElement(null, NavigationMethod.Unspecified, KeyModifiers.None);
				}
			}
		}

		protected internal override void InvalidateMirrorTransform()
		{
		}

		private double ValidateScaling(double scaling)
		{
			if (MathUtilities.IsNegativeOrNonFinite(scaling) || MathUtilities.IsZero(scaling))
			{
				throw new InvalidOperationException($"Invalid {"RenderScaling"} value {scaling} returned from {PlatformImpl?.GetType()}");
			}
			if (MathUtilities.IsOne(scaling))
			{
				return 1.0;
			}
			return scaling;
		}
	}
	/// <summary>
	/// Represents the event arguments for <see cref="F:Avalonia.Controls.TransitioningContentControl.TransitionCompletedEvent" />.
	/// </summary>
	public class TransitionCompletedEventArgs : RoutedEventArgs
	{
		/// <summary>
		/// Gets the content that was transitioned from.
		/// </summary>
		public object? From { get; }

		/// <summary>
		/// Gets the content that was transitioned to.
		/// </summary>
		public object? To { get; }

		/// <summary>
		/// Gets whether the transition ran to completion.
		/// If false, the transition may have completed instantly or been cancelled.
		/// </summary>
		public bool HasRunToCompletion { get; }

		/// <summary>
		/// Initializes a new instance of <see cref="T:Avalonia.Controls.TransitionCompletedEventArgs" />.
		/// </summary>
		/// <param name="from">The content that was transitioned from.</param>
		/// <param name="to">The content that was transitioned to.</param>
		/// <param name="hasRunToCompletion">Whether the transition ran to completion.</param>
		public TransitionCompletedEventArgs(object? from, object? to, bool hasRunToCompletion)
			: base(TransitioningContentControl.TransitionCompletedEvent)
		{
			From = from;
			To = to;
			HasRunToCompletion = hasRunToCompletion;
		}
	}
	/// <summary>
	/// Displays <see cref="P:Avalonia.Controls.ContentControl.Content" /> according to an <see cref="T:Avalonia.Controls.Templates.IDataTemplate" />,
	/// using a <see cref="P:Avalonia.Controls.TransitioningContentControl.PageTransition" /> to move between the old and new content. 
	/// </summary>
	public class TransitioningContentControl : ContentControl
	{
		private class ImmutableCrossFade : IPageTransition
		{
			private readonly CrossFade _inner;

			public ImmutableCrossFade(TimeSpan duration)
			{
				_inner = new CrossFade(duration);
			}

			public Task Start(Visual? from, Visual? to, bool forward, CancellationToken cancellationToken)
			{
				return _inner.Start(from, to, cancellationToken);
			}
		}

		private CancellationTokenSource? _currentTransition;

		private ContentPresenter? _lastPresenter;

		private ContentPresenter? _presenter2;

		private bool _isFirstFull;

		private bool _shouldAnimate;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.TransitioningContentControl.PageTransition" /> property.
		/// </summary>
		public static readonly StyledProperty<IPageTransition?> PageTransitionProperty = AvaloniaProperty.Register<TransitioningContentControl, IPageTransition>("PageTransition", new ImmutableCrossFade(TimeSpan.FromMilliseconds(125.0)));

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.TransitioningContentControl.IsTransitionReversed" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> IsTransitionReversedProperty = AvaloniaProperty.Register<TransitioningContentControl, bool>("IsTransitionReversed", defaultValue: false);

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.TransitioningContentControl.TransitionCompleted" /> routed event.
		/// </summary>
		public static readonly RoutedEvent<TransitionCompletedEventArgs> TransitionCompletedEvent = RoutedEvent.Register<TransitioningContentControl, TransitionCompletedEventArgs>("TransitionCompleted", RoutingStrategies.Direct);

		/// <summary>
		/// Gets or sets the animation played when content appears and disappears.
		/// </summary>
		public IPageTransition? PageTransition
		{
			get
			{
				return GetValue(PageTransitionProperty);
			}
			set
			{
				SetValue(PageTransitionProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets a value indicating whether the control will be animated in the reverse direction.
		/// </summary>
		/// <remarks>May not apply to all transitions.</remarks>
		public bool IsTransitionReversed
		{
			get
			{
				return GetValue(IsTransitionReversedProperty);
			}
			set
			{
				SetValue(IsTransitionReversedProperty, value);
			}
		}

		/// <summary>
		/// Raised when the old content isn't needed anymore by the control, because the transition has completed.
		/// </summary>
		public event EventHandler<TransitionCompletedEventArgs> TransitionCompleted
		{
			add
			{
				AddHandler(TransitionCompletedEvent, value);
			}
			remove
			{
				RemoveHandler(TransitionCompletedEvent, value);
			}
		}

		protected override Size ArrangeOverride(Size finalSize)
		{
			Size result = base.ArrangeOverride(finalSize);
			if (_shouldAnimate)
			{
				_currentTransition?.Cancel();
				if (_presenter2 != null)
				{
					ContentPresenter presenter = base.Presenter;
					if (presenter != null)
					{
						IPageTransition pageTransition = PageTransition;
						if (pageTransition != null)
						{
							_shouldAnimate = false;
							CancellationTokenSource cancel = new CancellationTokenSource();
							_currentTransition = cancel;
							ContentPresenter contentPresenter = (_isFirstFull ? _presenter2 : presenter);
							ContentPresenter contentPresenter2 = (_isFirstFull ? presenter : _presenter2);
							object fromContent = contentPresenter.Content;
							object toContent = contentPresenter2.Content;
							pageTransition.Start(contentPresenter, contentPresenter2, !IsTransitionReversed, cancel.Token).ContinueWith(delegate(Task task)
							{
								OnTransitionCompleted(new TransitionCompletedEventArgs(fromContent, toContent, task.Status == TaskStatus.RanToCompletion && !cancel.IsCancellationRequested));
								if (!cancel.IsCancellationRequested)
								{
									HideOldPresenter();
								}
							}, TaskScheduler.FromCurrentSynchronizationContext());
						}
					}
				}
				_shouldAnimate = false;
			}
			return result;
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			UpdateContent(withTransition: false);
		}

		protected override bool RegisterContentPresenter(ContentPresenter presenter)
		{
			if (base.RegisterContentPresenter(presenter))
			{
				return true;
			}
			if (presenter != null)
			{
				if (presenter.Name == "PART_ContentPresenter2")
				{
					_presenter2 = presenter;
					_presenter2.IsVisible = false;
					UpdateContent(withTransition: false);
					return true;
				}
			}
			return false;
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			if (change.Property == ContentControl.ContentProperty)
			{
				UpdateContent(withTransition: true);
			}
			else
			{
				base.OnPropertyChanged(change);
			}
		}

		private void UpdateContent(bool withTransition)
		{
			if (base.VisualRoot != null && _presenter2 != null && base.Presenter != null)
			{
				ContentPresenter contentPresenter = (_isFirstFull ? _presenter2 : base.Presenter);
				object obj = _lastPresenter?.Content;
				object content = base.Content;
				if (_lastPresenter != null && _lastPresenter != contentPresenter && _lastPresenter.Content == content)
				{
					_lastPresenter.Content = null;
				}
				contentPresenter.Content = content;
				contentPresenter.IsVisible = true;
				_lastPresenter = contentPresenter;
				_isFirstFull = !_isFirstFull;
				if (PageTransition != null && withTransition)
				{
					_shouldAnimate = true;
					InvalidateArrange();
				}
				else
				{
					HideOldPresenter();
					OnTransitionCompleted(new TransitionCompletedEventArgs(obj, content, hasRunToCompletion: false));
				}
			}
		}

		private void HideOldPresenter()
		{
			ContentPresenter contentPresenter = (_isFirstFull ? _presenter2 : base.Presenter);
			if (contentPresenter != null)
			{
				contentPresenter.Content = null;
				contentPresenter.IsVisible = false;
			}
		}

		private void OnTransitionCompleted(TransitionCompletedEventArgs e)
		{
			RaiseEvent(e);
		}
	}
