		private protected override void OnItemsViewCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
		{
			base.OnItemsViewCollectionChanged(sender, e);
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Remove:
			case NotifyCollectionChangedAction.Replace:
			{
				foreach (object oldItem in e.OldItems)
				{
					SelectedItems.Remove(oldItem);
				}
				break;
			}
			case NotifyCollectionChangedAction.Reset:
				SelectedItems.Clear();
				break;
			}
		}

		/// <summary>
		/// Subscribes to the <see cref="P:Avalonia.Controls.TreeView.SelectedItems" /> CollectionChanged event, if any.
		/// </summary>
		private void SubscribeToSelectedItems()
		{
			if (_selectedItems is INotifyCollectionChanged notifyCollectionChanged)
			{
				notifyCollectionChanged.CollectionChanged += SelectedItemsCollectionChanged;
			}
			SelectedItemsCollectionChanged(_selectedItems, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset));
		}

		private void SelectSingleItem(object item)
		{
			object selectedItem = _selectedItem;
			_syncingSelectedItems = true;
			SelectedItems.Clear();
			_selectedItem = item;
			SelectedItems.Add(item);
			_syncingSelectedItems = false;
			RaisePropertyChanged(SelectedItemProperty, selectedItem, _selectedItem);
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.TreeView.SelectedItems" /> CollectionChanged event is raised.
		/// </summary>
		/// <param name="sender">The event sender.</param>
		/// <param name="e">The event args.</param>
		private void SelectedItemsCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
		{
			IList list = null;
			IList list2 = null;
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
			{
				SelectedItemsAdded(e.NewItems.Cast<object>().ToArray());
				object selectedItem2 = SelectedItem;
				if (AutoScrollToSelectedItem && selectedItem2 != null && e.NewItems[0] == selectedItem2)
				{
					TreeContainerFromItem(selectedItem2)?.BringIntoView();
				}
				list = e.NewItems;
				break;
			}
			case NotifyCollectionChangedAction.Remove:
				if (!_syncingSelectedItems)
				{
					if (SelectedItems.Count == 0)
					{
						SelectedItem = null;
					}
					else if (SelectedItems.IndexOf(_selectedItem) == -1)
					{
						object selectedItem3 = _selectedItem;
						_selectedItem = SelectedItems[0];
						RaisePropertyChanged(SelectedItemProperty, selectedItem3, _selectedItem);
					}
				}
				foreach (object oldItem in e.OldItems)
				{
					MarkItemSelected(oldItem, selected: false);
				}
				list2 = e.OldItems;
				break;
			case NotifyCollectionChangedAction.Reset:
				foreach (Control realizedTreeContainer in GetRealizedTreeContainers())
				{
					MarkContainerSelected(realizedTreeContainer, selected: false);
				}
				if (SelectedItems.Count > 0)
				{
					SelectedItemsAdded(SelectedItems);
					list = SelectedItems;
				}
				else if (!_syncingSelectedItems)
				{
					SelectedItem = null;
				}
				break;
			case NotifyCollectionChangedAction.Replace:
				foreach (object oldItem2 in e.OldItems)
				{
					MarkItemSelected(oldItem2, selected: false);
				}
				foreach (object newItem in e.NewItems)
				{
					MarkItemSelected(newItem, selected: true);
				}
				if (SelectedItem != SelectedItems[0] && !_syncingSelectedItems)
				{
					object selectedItem = SelectedItem;
					RaisePropertyChanged(newValue: _selectedItem = SelectedItems[0], property: SelectedItemProperty, oldValue: selectedItem);
				}
				list = e.NewItems;
				list2 = e.OldItems;
				break;
			}
			if ((list != null && list.Count > 0) || (list2 != null && list2.Count > 0))
			{
				SelectionChangedEventArgs e2 = new SelectionChangedEventArgs(SelectingItemsControl.SelectionChangedEvent, list2 ?? Empty, list ?? Empty);
				RaiseEvent(e2);
			}
		}

		private void MarkItemSelected(object item, bool selected)
		{
			Control control = TreeContainerFromItem(item);
			if (control != null)
			{
				MarkContainerSelected(control, selected);
			}
		}

		private void SelectedItemsAdded(IList items)
		{
			if (items.Count == 0)
			{
				return;
			}
			foreach (object item in items)
			{
				MarkItemSelected(item, selected: true);
			}
			if (SelectedItem == null && !_syncingSelectedItems)
			{
				SetAndRaise(SelectedItemProperty, ref _selectedItem, items[0]);
			}
		}

		/// <summary>
		/// Unsubscribes from the <see cref="P:Avalonia.Controls.TreeView.SelectedItems" /> CollectionChanged event, if any.
		/// </summary>
		private void UnsubscribeFromSelectedItems()
		{
			if (_selectedItems is INotifyCollectionChanged notifyCollectionChanged)
			{
				notifyCollectionChanged.CollectionChanged -= SelectedItemsCollectionChanged;
			}
		}

		(bool handled, IInputElement? next) ICustomKeyboardNavigation.GetNext(IInputElement element, NavigationDirection direction)
		{
			if (direction == NavigationDirection.Next || direction == NavigationDirection.Previous)
			{
				if (!this.IsVisualAncestorOf((Visual)element))
				{
					Control control = ((_selectedItem != null) ? TreeContainerFromItem(_selectedItem) : ContainerFromIndex(0));
					return (handled: control != null, next: control);
				}
				return (handled: true, next: null);
			}
			return (handled: false, next: null);
		}

		protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
		{
			return new TreeViewItem();
		}

		protected internal override bool NeedsContainerOverride(object? item, int index, out object? recycleKey)
		{
			return NeedsContainer<TreeViewItem>(item, out recycleKey);
		}

		protected internal override void ContainerForItemPreparedOverride(Control container, object? item, int index)
		{
			base.ContainerForItemPreparedOverride(container, item, index);
			if (container.IsSet(SelectingItemsControl.IsSelectedProperty))
			{
				bool isSelected = SelectingItemsControl.GetIsSelected(container);
				UpdateSelectionFromContainer(container, isSelected, rangeModifier: false, toggleModifier: true);
			}
			MarkContainerSelected(container, SelectedItems.Contains(item));
			if (AutoScrollToSelectedItem && SelectedItem == item)
			{
				Dispatcher.UIThread.Post(container.BringIntoView, DispatcherPriority.Loaded);
			}
		}

		/// <inheritdoc />
		protected override void OnGotFocus(GotFocusEventArgs e)
		{
			if (e.NavigationMethod == NavigationMethod.Directional)
			{
				e.Handled = UpdateSelectionFromEventSource(e.Source, select: true, e.KeyModifiers.HasAllFlags(KeyModifiers.Shift));
			}
		}

		protected override void OnKeyDown(KeyEventArgs e)
		{
			NavigationDirection? navigationDirection = e.Key.ToNavigationDirection();
			if (navigationDirection.HasValue && navigationDirection.GetValueOrDefault().IsDirectional() && !e.Handled)
			{
				if (SelectedItem != null)
				{
					TreeViewItem containerInDirection = GetContainerInDirection(GetContainerFromEventSource(e.Source), navigationDirection.Value, intoChildren: true);
					if (containerInDirection != null)
					{
						e.Handled = containerInDirection.Focus(NavigationMethod.Directional);
					}
				}
				else
				{
					SelectedItem = base.ItemsView[0];
				}
			}
			if (!e.Handled)
			{
				PlatformHotkeyConfiguration hotkeyConfiguration = Application.Current.PlatformSettings.HotkeyConfiguration;
				if (SelectionMode == SelectionMode.Multiple && Match(hotkeyConfiguration?.SelectAll))
				{
					SelectAll();
					e.Handled = true;
				}
			}
			bool Match(List<KeyGesture>? gestures)
			{
				return gestures?.Any((KeyGesture g) => g.Matches(e)) ?? false;
			}
		}

		private TreeViewItem? GetContainerInDirection(TreeViewItem? from, NavigationDirection direction, bool intoChildren)
		{
			StyledElement styledElement = from?.Parent;
			ItemsControl itemsControl = ((styledElement is TreeView treeView) ? ((ItemsControl)treeView) : ((ItemsControl)((!(styledElement is TreeViewItem treeViewItem)) ? null : treeViewItem)));
			ItemsControl itemsControl2 = itemsControl;
			if (itemsControl2 == null)
			{
				return null;
			}
			int num = ((from != null) ? itemsControl2.IndexFromContainer(from) : (-1));
			ItemsControl itemsControl3 = from?.Parent as ItemsControl;
			TreeViewItem result = null;
			switch (direction)
			{
			case NavigationDirection.Up:
				if (num > 0)
				{
					TreeViewItem treeViewItem3 = (TreeViewItem)itemsControl2.ContainerFromIndex(num - 1);
					result = ((treeViewItem3.IsExpanded && treeViewItem3.ItemCount > 0) ? ((TreeViewItem)treeViewItem3.ContainerFromIndex(treeViewItem3.ItemCount - 1)) : treeViewItem3);
				}
				else
				{
					result = from?.Parent as TreeViewItem;
				}
				break;
			case NavigationDirection.Right:
			case NavigationDirection.Down:
				if ((from?.IsExpanded ?? false) && intoChildren && from.ItemCount > 0)
				{
					result = (TreeViewItem)from.ContainerFromIndex(0);
				}
				else if (num < ((itemsControl3 != null) ? new int?(itemsControl3.ItemCount - 1) : ((int?)null)))
				{
					result = (TreeViewItem)itemsControl2.ContainerFromIndex(num + 1);
				}
				else if (itemsControl3 is TreeViewItem treeViewItem2)
				{
					return GetContainerInDirection(treeViewItem2, direction, intoChildren: false);
				}
				break;
			}
			return result;
		}

		/// <inheritdoc />
		protected override void OnPointerPressed(PointerPressedEventArgs e)
		{
			base.OnPointerPressed(e);
			if (e.Source is Visual relativeTo)
			{
				PointerPoint currentPoint = e.GetCurrentPoint(relativeTo);
				if (currentPoint.Properties.IsLeftButtonPressed || currentPoint.Properties.IsRightButtonPressed)
				{
					PlatformHotkeyConfiguration hotkeyConfiguration = Application.Current.PlatformSettings.HotkeyConfiguration;
					e.Handled = UpdateSelectionFromEventSource(e.Source, select: true, e.KeyModifiers.HasAllFlags(KeyModifiers.Shift), e.KeyModifiers.HasAllFlags(hotkeyConfiguration.CommandModifiers), currentPoint.Properties.IsRightButtonPressed);
				}
			}
		}

		/// <summary>
		/// Updates the selection for an item based on user interaction.
		/// </summary>
		/// <param name="container">The container.</param>
		/// <param name="select">Whether the item should be selected or unselected.</param>
		/// <param name="rangeModifier">Whether the range modifier is enabled (i.e. shift key).</param>
		/// <param name="toggleModifier">Whether the toggle modifier is enabled (i.e. ctrl key).</param>
		/// <param name="rightButton">Whether the event is a right-click.</param>
		protected void UpdateSelectionFromContainer(Control container, bool select = true, bool rangeModifier = false, bool toggleModifier = false, bool rightButton = false)
		{
			object obj = TreeItemFromContainer(container);
			if (obj == null)
			{
				return;
			}
			Control control = null;
			if (SelectedItem != null)
			{
				control = TreeContainerFromItem(SelectedItem);
			}
			SelectionMode selectionMode = SelectionMode;
			bool flag = toggleModifier || selectionMode.HasAllFlags(SelectionMode.Toggle);
			bool flag2 = selectionMode.HasAllFlags(SelectionMode.Multiple);
			bool flag3 = flag2 && rangeModifier && control != null;
			if (!select)
			{
				SelectedItems.Remove(obj);
			}
			else if (rightButton)
			{
				if (!SelectedItems.Contains(obj))
				{
					SelectSingleItem(obj);
				}
			}
			else if (!flag && !flag3)
			{
				SelectSingleItem(obj);
			}
			else if (flag2 && flag3)
			{
				SynchronizeItems(SelectedItems, GetItemsInRange(control as TreeViewItem, container as TreeViewItem));
			}
			else if (SelectedItems.IndexOf(obj) != -1)
			{
				SelectedItems.Remove(obj);
			}
			else if (flag2)
			{
				SelectedItems.Add(obj);
			}
			else
			{
				SelectedItem = obj;
			}
		}

		[Obsolete]
		[EditorBrowsable(EditorBrowsableState.Never)]
		private protected override ItemContainerGenerator CreateItemContainerGenerator()
		{
			return new TreeItemContainerGenerator(this);
		}

		/// <summary>
		/// Find which node is first in hierarchy.
		/// </summary>
		/// <param name="treeView">Search root.</param>
		/// <param name="nodeA">Nodes to find.</param>
		/// <param name="nodeB">Node to find.</param>
		/// <returns>Found first node.</returns>
		private static TreeViewItem? FindFirstNode(TreeView treeView, TreeViewItem nodeA, TreeViewItem nodeB)
		{
			return FindInContainers(treeView, nodeA, nodeB);
		}

		private static TreeViewItem? FindInContainers(ItemsControl itemsControl, TreeViewItem nodeA, TreeViewItem nodeB)
		{
			foreach (Control realizedContainer in itemsControl.GetRealizedContainers())
			{
				TreeViewItem treeViewItem = FindFirstNode(realizedContainer as TreeViewItem, nodeA, nodeB);
				if (treeViewItem != null)
				{
					return treeViewItem;
				}
			}
			return null;
		}

		private static TreeViewItem? FindFirstNode(TreeViewItem? node, TreeViewItem nodeA, TreeViewItem nodeB)
		{
			if (node == null)
			{
				return null;
			}
			TreeViewItem treeViewItem = ((node == nodeA) ? nodeA : ((node == nodeB) ? nodeB : null));
			if (treeViewItem != null)
			{
				return treeViewItem;
			}
			return FindInContainers(node, nodeA, nodeB);
		}

		/// <summary>
		/// Returns all items that belong to containers between <paramref name="from" /> and <paramref name="to" />.
		/// The range is inclusive.
		/// </summary>
		/// <param name="from">From container.</param>
		/// <param name="to">To container.</param>
		private List<object> GetItemsInRange(TreeViewItem? from, TreeViewItem? to)
		{
			List<object> list = new List<object>();
			if (from == null || to == null)
			{
				return list;
			}
			TreeViewItem treeViewItem = FindFirstNode(this, from, to);
			if (treeViewItem == null)
			{
				return list;
			}
			bool flag = false;
			if (treeViewItem == to)
			{
				TreeViewItem? treeViewItem2 = from;
				from = to;
				to = treeViewItem2;
				flag = true;
			}
			TreeViewItem treeViewItem3 = from;
			while (treeViewItem3 != null && treeViewItem3 != to)
			{
				object obj = TreeItemFromContainer(treeViewItem3);
				if (obj != null)
				{
					list.Add(obj);
				}
				treeViewItem3 = GetContainerInDirection(treeViewItem3, NavigationDirection.Down, intoChildren: true);
			}
			object obj2 = TreeItemFromContainer(to);
			if (obj2 != null)
			{
				list.Add(obj2);
			}
			if (flag)
			{
				list.Reverse();
			}
			return list;
		}

		/// <summary>
		/// Updates the selection based on an event that may have originated in a container that 
		/// belongs to the control.
		/// </summary>
		/// <param name="eventSource">The control that raised the event.</param>
		/// <param name="select">Whether the container should be selected or unselected.</param>
		/// <param name="rangeModifier">Whether the range modifier is enabled (i.e. shift key).</param>
		/// <param name="toggleModifier">Whether the toggle modifier is enabled (i.e. ctrl key).</param>
		/// <param name="rightButton">Whether the event is a right-click.</param>
		/// <returns>
		/// True if the event originated from a container that belongs to the control; otherwise
		/// false.
		/// </returns>
		protected bool UpdateSelectionFromEventSource(object eventSource, bool select = true, bool rangeModifier = false, bool toggleModifier = false, bool rightButton = false)
		{
			TreeViewItem containerFromEventSource = GetContainerFromEventSource(eventSource);
			if (containerFromEventSource != null)
			{
				UpdateSelectionFromContainer(containerFromEventSource, select, rangeModifier, toggleModifier, rightButton);
				return true;
			}
			return false;
		}

		/// <summary>
		/// Tries to get the container that was the source of an event.
		/// </summary>
		/// <param name="eventSource">The control that raised the event.</param>
		/// <returns>The container or null if the event did not originate in a container.</returns>
		protected TreeViewItem? GetContainerFromEventSource(object eventSource)
		{
			TreeViewItem treeViewItem = ((Visual)eventSource).GetSelfAndVisualAncestors().OfType<TreeViewItem>().FirstOrDefault();
			if (treeViewItem?.TreeViewOwner != this)
			{
				return null;
			}
			return treeViewItem;
		}

		/// <summary>
		/// Called when a container raises the 
		/// <see cref="F:Avalonia.Controls.Primitives.SelectingItemsControl.IsSelectedChangedEvent" />.
		/// </summary>
		/// <param name="e">The event.</param>
		private void ContainerSelectionChanged(RoutedEventArgs e)
		{
			if (e.Source is TreeViewItem treeViewItem && treeViewItem.TreeViewOwner == this)
			{
				object obj = TreeItemFromContainer(treeViewItem);
				if (obj != null)
				{
					bool isSelected = SelectingItemsControl.GetIsSelected(treeViewItem);
					bool flag = SelectedItems.Contains(obj);
					if (isSelected != flag)
					{
						if (isSelected)
						{
							SelectedItems.Add(obj);
						}
						else
						{
							SelectedItems.Remove(obj);
						}
					}
				}
			}
			if (e.Source != this)
			{
				e.Handled = true;
			}
		}

		/// <summary>
		/// Sets a container's 'selected' class or <see cref="P:Avalonia.Controls.ISelectable.IsSelected" />.
		/// </summary>
		/// <param name="container">The container.</param>
		/// <param name="selected">Whether the control is selected</param>
		private void MarkContainerSelected(Control container, bool selected)
		{
			container.SetCurrentValue(SelectingItemsControl.IsSelectedProperty, selected);
		}

		/// <summary>
		/// Makes a list of objects equal another (though doesn't preserve order).
		/// </summary>
		/// <param name="items">The items collection.</param>
		/// <param name="desired">The desired items.</param>
		private static void SynchronizeItems(IList items, List<object> desired)
		{
			int count = items.Count;
			if (desired == null)
			{
				return;
			}
			int count2 = desired.Count;
			if (count == 0 && count2 > 0)
			{
				foreach (object item in desired)
				{
					items.Add(item);
				}
				return;
			}
			if (count > 0 && count2 == 0)
			{
				items.Clear();
				return;
			}
			object[] array = new object[items.Count];
			items.CopyTo(array, 0);
			object[] array2 = array.Except(desired).ToArray();
			object[] array3 = desired.Except(array).ToArray();
			object[] array4 = array2;
			foreach (object value in array4)
			{
				items.Remove(value);
			}
			array4 = array3;
			foreach (object value2 in array4)
			{
				items.Add(value2);
			}
		}
	}
	/// <summary>
	/// An item in a <see cref="T:Avalonia.Controls.TreeView" />.
	/// </summary>
	[TemplatePart("PART_Header", typeof(Control))]
	[PseudoClasses(new string[] { ":pressed", ":selected" })]
	public class TreeViewItem : HeaderedItemsControl, ISelectable
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.TreeViewItem.IsExpanded" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> IsExpandedProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.TreeViewItem.IsSelected" /> property.
		/// </summary>
		public static readonly StyledProperty<bool> IsSelectedProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.TreeViewItem.Level" /> property.
		/// </summary>
		public static readonly DirectProperty<TreeViewItem, int> LevelProperty;

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.TreeViewItem.Expanded" /> event.
		/// </summary>
		public static readonly RoutedEvent<RoutedEventArgs> ExpandedEvent;

		/// <summary>
		/// Defines the <see cref="E:Avalonia.Controls.TreeViewItem.Collapsed" /> event.
		/// </summary>
		public static readonly RoutedEvent<RoutedEventArgs> CollapsedEvent;

		private static readonly FuncTemplate<Panel?> DefaultPanel;

		private TreeView? _treeView;

		private Control? _header;

		private Control? _headerPresenter;

		private int _level;

		private bool _templateApplied;

		private bool _deferredBringIntoViewFlag;

		/// <summary>
		/// Gets or sets a value indicating whether the item is expanded to show its children.
		/// </summary>
		public bool IsExpanded
		{
			get
			{
				return GetValue(IsExpandedProperty);
			}
			set
			{
				SetValue(IsExpandedProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets the selection state of the item.
		/// </summary>
		public bool IsSelected
		{
			get
			{
				return GetValue(IsSelectedProperty);
			}
			set
			{
				SetValue(IsSelectedProperty, value);
			}
		}

		/// <summary>
		/// Gets the level/indentation of the item.
		/// </summary>
		public int Level
		{
			get
			{
				return _level;
			}
			private set
			{
				SetAndRaise(LevelProperty, ref _level, value);
			}
		}

		internal TreeView? TreeViewOwner => _treeView;

		/// <summary>
		/// Occurs after the <see cref="T:Avalonia.Controls.TreeViewItem" /> has expanded to show its children.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Expanded
		{
			add
			{
				AddHandler(ExpandedEvent, value);
			}
			remove
			{
				RemoveHandler(ExpandedEvent, value);
			}
		}

		/// <summary>
		/// Occurs after the <see cref="T:Avalonia.Controls.TreeViewItem" /> has collapsed to hide its children.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Collapsed
		{
			add
			{
				AddHandler(CollapsedEvent, value);
			}
			remove
			{
				RemoveHandler(CollapsedEvent, value);
			}
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.TreeViewItem" /> class.
		/// </summary>
		static TreeViewItem()
		{
			IsExpandedProperty = AvaloniaProperty.Register<TreeViewItem, bool>("IsExpanded", defaultValue: false, inherits: false, BindingMode.TwoWay);
			IsSelectedProperty = SelectingItemsControl.IsSelectedProperty.AddOwner<TreeViewItem>();
			LevelProperty = AvaloniaProperty.RegisterDirect("Level", (TreeViewItem o) => o.Level, null, 0);
			ExpandedEvent = RoutedEvent.Register<TreeViewItem, RoutedEventArgs>("Expanded", RoutingStrategies.Tunnel | RoutingStrategies.Bubble);
			CollapsedEvent = RoutedEvent.Register<TreeViewItem, RoutedEventArgs>("Collapsed", RoutingStrategies.Tunnel | RoutingStrategies.Bubble);
			DefaultPanel = new FuncTemplate<Panel>(() => new StackPanel());
			SelectableMixin.Attach<TreeViewItem>(IsSelectedProperty);
			PressedMixin.Attach<TreeViewItem>();
			InputElement.FocusableProperty.OverrideDefaultValue<TreeViewItem>(defaultValue: true);
			ItemsControl.ItemsPanelProperty.OverrideDefaultValue<TreeViewItem>(DefaultPanel);
			AutomationProperties.IsOffscreenBehaviorProperty.OverrideDefaultValue<TreeViewItem>(IsOffscreenBehavior.FromClip);
			Control.RequestBringIntoViewEvent.AddClassHandler(delegate(TreeViewItem x, RequestBringIntoViewEventArgs e)
			{
				x.OnRequestBringIntoView(e);
			});
			IsExpandedProperty.Changed.AddClassHandler(delegate(TreeViewItem x, AvaloniaPropertyChangedEventArgs<bool> e)
			{
				x.OnIsExpandedChanged(e);
			});
		}

		private void OnIsExpandedChanged(AvaloniaPropertyChangedEventArgs<bool> args)
		{
			RoutedEvent<RoutedEventArgs> routedEvent = (args.NewValue.Value ? ExpandedEvent : CollapsedEvent);
			RoutedEventArgs e = new RoutedEventArgs
			{
				RoutedEvent = routedEvent,
				Source = this
			};
			RaiseEvent(e);
		}

		/// <inheritdoc />
		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new TreeViewItemAutomationPeer(this);
		}

		protected internal override Control CreateContainerForItemOverride(object? item, int index, object? recycleKey)
		{
			return EnsureTreeView().CreateContainerForItemOverride(item, index, recycleKey);
		}

		protected internal override bool NeedsContainerOverride(object? item, int index, out object? recycleKey)
		{
			return EnsureTreeView().NeedsContainerOverride(item, index, out recycleKey);
		}

		protected internal override void PrepareContainerForItemOverride(Control container, object? item, int index)
		{
			EnsureTreeView().PrepareContainerForItemOverride(container, item, index);
		}

		protected internal override void ContainerForItemPreparedOverride(Control container, object? item, int index)
		{
			EnsureTreeView().ContainerForItemPreparedOverride(container, item, index);
		}

		/// <inheritdoc />
		protected override void OnAttachedToLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			base.OnAttachedToLogicalTree(e);
			_treeView = this.GetLogicalAncestors().OfType<TreeView>().FirstOrDefault();
			Level = CalculateDistanceFromLogicalParent<TreeView>(this) - 1;
			if (base.ItemTemplate == null && _treeView?.ItemTemplate != null)
			{
				SetCurrentValue(ItemsControl.ItemTemplateProperty, _treeView.ItemTemplate);
			}
			if (base.ItemContainerTheme == null && _treeView?.ItemContainerTheme != null)
			{
				SetCurrentValue(ItemsControl.ItemContainerThemeProperty, _treeView.ItemContainerTheme);
			}
		}

		protected virtual void OnRequestBringIntoView(RequestBringIntoViewEventArgs e)
		{
			if (e.TargetObject != this)
			{
				return;
			}
			if (!_templateApplied)
			{
				_deferredBringIntoViewFlag = true;
			}
			else if (_header != null)
			{
				Matrix? matrix = _header.TransformToVisual(this);
				if (matrix.HasValue)
				{
					Rect rect = new Rect(_header.Bounds.Size);
					Rect targetRect = rect.TransformToAABB(matrix.Value);
					e.TargetRect = targetRect;
				}
			}
		}

		/// <inheritdoc />
		protected override void OnKeyDown(KeyEventArgs e)
		{
			if (!e.Handled)
			{
				Func<TreeViewItem, bool> func = e.Key switch
				{
					Key.Left => ApplyToItemOrRecursivelyIfCtrl(FocusAwareCollapseItem, e.KeyModifiers), 
					Key.Right => ApplyToItemOrRecursivelyIfCtrl(ExpandItem, e.KeyModifiers), 
					Key.Return => ApplyToItemOrRecursivelyIfCtrl(IsExpanded ? new Func<TreeViewItem, bool>(CollapseItem) : new Func<TreeViewItem, bool>(ExpandItem), e.KeyModifiers), 
					Key.Subtract => FocusAwareCollapseItem, 
					Key.Add => ExpandItem, 
					Key.Divide => ApplyToSubtree(CollapseItem), 
					Key.Multiply => ApplyToSubtree(ExpandItem), 
					_ => null, 
				};
				if (func != null)
				{
					e.Handled = func(this);
				}
			}
			static Func<TreeViewItem, bool> ApplyToItemOrRecursivelyIfCtrl(Func<TreeViewItem, bool> f, KeyModifiers keyModifiers)
			{
				if (keyModifiers.HasAllFlags(KeyModifiers.Control))
				{
					return ApplyToSubtree(f);
				}
				return f;
			}
			static Func<TreeViewItem, bool> ApplyToSubtree(Func<TreeViewItem, bool> f)
			{
				return (TreeViewItem t) => (from treeViewItem in SubTree(t).ToList()
					select f(treeViewItem)).Aggregate(seed: false, (bool p, bool c) => p || c);
			}
			static bool CollapseItem(TreeViewItem treeViewItem)
			{
				if (treeViewItem.ItemCount > 0 && treeViewItem.IsExpanded)
				{
					treeViewItem.SetCurrentValue(IsExpandedProperty, value: false);
					return true;
				}
				return false;
			}
			static bool ExpandItem(TreeViewItem treeViewItem)
			{
				if (treeViewItem.ItemCount > 0 && !treeViewItem.IsExpanded)
				{
					treeViewItem.SetCurrentValue(IsExpandedProperty, value: true);
					return true;
				}
				return false;
			}
			static bool FocusAwareCollapseItem(TreeViewItem treeViewItem)
			{
				if (treeViewItem.ItemCount > 0 && treeViewItem.IsExpanded)
				{
					if (treeViewItem.IsFocused)
					{
						treeViewItem.SetCurrentValue(IsExpandedProperty, value: false);
					}
					else
					{
						treeViewItem.Focus(NavigationMethod.Directional);
					}
					return true;
				}
				return false;
			}
			static IEnumerable<TreeViewItem> SubTree(TreeViewItem treeViewItem)
			{
				return new TreeViewItem[1] { treeViewItem }.Concat(treeViewItem.LogicalChildren.OfType<TreeViewItem>().SelectMany((TreeViewItem child) => SubTree(child)));
			}
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			InputElement headerPresenter = _headerPresenter;
			if (headerPresenter != null)
			{
				headerPresenter.DoubleTapped -= HeaderDoubleTapped;
			}
			_header = e.NameScope.Find<Control>("PART_Header");
			_headerPresenter = e.NameScope.Find<Control>("PART_HeaderPresenter");
			_templateApplied = true;
			InputElement headerPresenter2 = _headerPresenter;
			if (headerPresenter2 != null)
			{
				headerPresenter2.DoubleTapped += HeaderDoubleTapped;
			}
			if (_deferredBringIntoViewFlag)
			{
				_deferredBringIntoViewFlag = false;
				Dispatcher.UIThread.Post(((Control)this).BringIntoView);
			}
		}

		/// <summary>
		/// Invoked when the <see cref="E:Avalonia.Input.InputElement.DoubleTapped" /> event occurs in the header.
		/// </summary>
		protected virtual void OnHeaderDoubleTapped(TappedEventArgs e)
		{
			if (base.ItemCount > 0)
			{
				SetCurrentValue(IsExpandedProperty, !IsExpanded);
				e.Handled = true;
			}
		}

		private protected override void OnItemsViewCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
		{
			base.OnItemsViewCollectionChanged(sender, e);
			if (_treeView == null)
			{
				return;
			}
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Remove:
			case NotifyCollectionChangedAction.Replace:
			{
				foreach (object oldItem in e.OldItems)
				{
					_treeView.SelectedItems.Remove(oldItem);
				}
				break;
			}
			case NotifyCollectionChangedAction.Reset:
			{
				foreach (Control realizedContainer in GetRealizedContainers())
				{
					if (realizedContainer is TreeViewItem { IsSelected: not false })
					{
						_treeView.SelectedItems.Remove(realizedContainer.DataContext);
					}
				}
				break;
			}
			}
		}

		private static int CalculateDistanceFromLogicalParent<T>(ILogical? logical, int @default = -1) where T : class
		{
			int num = 0;
			while (logical != null && !(logical is T))
			{
				num++;
				logical = logical.LogicalParent;
			}
			if (logical == null)
			{
				return @default;
			}
			return num;
		}

		private TreeView EnsureTreeView()
		{
			return _treeView ?? throw new InvalidOperationException("The TreeViewItem is not part of a TreeView.");
		}

		private void HeaderDoubleTapped(object? sender, TappedEventArgs e)
		{
			OnHeaderDoubleTapped(e);
		}
	}
