				Control realized = _realized;
				if (realized != null)
				{
					IPageTransition transition = GetTransition();
					if (transition != null)
					{
						_transition = new CancellationTokenSource();
						bool flag = _realizedIndex > _transitionFromIndex;
						if (base.Items.Count > 2)
						{
							flag = (flag || (_transitionFromIndex == base.Items.Count - 1 && _realizedIndex == 0)) && (_transitionFromIndex != 0 || _realizedIndex != base.Items.Count - 1);
						}
						transition.Start(_transitionFrom, realized, flag, _transition.Token).ContinueWith(TransitionFinished, TaskScheduler.FromCurrentSynchronizationContext());
					}
				}
			}
			return result;
		}

