		protected override IInputElement? GetControl(NavigationDirection direction, IInputElement? from, bool wrap)
		{
			int count = base.Items.Count;
			Control control = from as Control;
			if (count == 0 || (control == null && direction != NavigationDirection.First && direction != NavigationDirection.Last))
			{
				return null;
			}
			bool flag = Orientation == Orientation.Horizontal;
			int num = ((control != null) ? IndexFromContainer(control) : (-1));
			int num2 = num;
			switch (direction)
			{
			case NavigationDirection.First:
				num2 = 0;
				break;
			case NavigationDirection.Last:
				num2 = count - 1;
				break;
			case NavigationDirection.Next:
				num2++;
				break;
			case NavigationDirection.Previous:
				num2--;
				break;
			case NavigationDirection.Left:
				if (flag)
				{
					num2--;
				}
				break;
			case NavigationDirection.Right:
				if (flag)
				{
					num2++;
				}
				break;
			case NavigationDirection.Up:
				if (!flag)
				{
					num2--;
				}
				break;
			case NavigationDirection.Down:
				if (!flag)
				{
					num2++;
				}
				break;
			default:
				return null;
			}
			if (num == num2)
			{
				return from;
			}
			if (wrap)
			{
				if (num2 < 0)
				{
					num2 = count - 1;
				}
				else if (num2 >= count)
				{
					num2 = 0;
				}
			}
			return ScrollIntoView(num2);
		}

