				Control control = (_realizingElement = GetOrCreateElement(items, num));
				control.Measure(availableSize);
				double num3 = (flag ? control.DesiredSize.Width : control.DesiredSize.Height);
				double val = (flag ? control.DesiredSize.Height : control.DesiredSize.Width);
				_measureElements.Add(num, control, num2, num3);
				viewport.measuredV = Math.Max(viewport.measuredV, val);
				num2 += num3;
				num++;
				_realizingIndex = -1;
				_realizingElement = null;
			}
			while (num2 < viewport.viewportUEnd && num < items.Count);
			_hasReachedEnd = num >= items.Count;
			viewport.lastIndex = num - 1;
			viewport.realizedEndU = num2;
			_realizedElements.RecycleElementsAfter(viewport.lastIndex, _recycleElement);
			num = viewport.anchorIndex - 1;
			num2 = viewport.anchorU;
			while (num2 > viewport.viewportUStart && num >= 0)
			{
				Control orCreateElement = GetOrCreateElement(items, num);
				orCreateElement.Measure(availableSize);
				double num4 = (flag ? orCreateElement.DesiredSize.Width : orCreateElement.DesiredSize.Height);
				double val2 = (flag ? orCreateElement.DesiredSize.Height : orCreateElement.DesiredSize.Width);
				num2 -= num4;
				_measureElements.Add(num, orCreateElement, num2, num4);
				viewport.measuredV = Math.Max(viewport.measuredV, val2);
				num--;
			}
			_hasReachedStart = num < 0;
			_realizedElements.RecycleElementsBefore(num + 1, _recycleElement);
		}

		private Control GetOrCreateElement(IReadOnlyList<object?> items, int index)
		{
			Control control = GetRealizedElement(index) ?? GetRealizedElement(index, ref _focusedIndex, ref _focusedElement) ?? GetRealizedElement(index, ref _scrollToIndex, ref _scrollToElement);
			if (control != null)
			{
				return control;
			}
			object item = items[index];
			if (base.ItemContainerGenerator.NeedsContainer(item, index, out object recycleKey))
			{
				return GetRecycledElement(item, index, recycleKey) ?? CreateElement(item, index, recycleKey);
			}
			return GetItemAsOwnContainer(item, index);
		}

		private Control? GetRealizedElement(int index)
		{
			return _realizedElements?.GetElement(index);
		}

		private static Control? GetRealizedElement(int index, ref int specialIndex, ref Control? specialElement)
		{
			if (specialIndex == index)
			{
				Control? result = specialElement;
				specialIndex = -1;
				specialElement = null;
				return result;
			}
			return null;
		}

		private Control GetItemAsOwnContainer(object? item, int index)
		{
			Control control = (Control)item;
			ItemContainerGenerator itemContainerGenerator = base.ItemContainerGenerator;
			if (!control.IsSet(RecycleKeyProperty))
			{
				itemContainerGenerator.PrepareItemContainer(control, control, index);
				AddInternalChild(control);
				control.SetValue(RecycleKeyProperty, s_itemIsItsOwnContainer);
				itemContainerGenerator.ItemContainerPrepared(control, item, index);
			}
			control.SetCurrentValue(Visual.IsVisibleProperty, value: true);
			return control;
		}

		private Control? GetRecycledElement(object? item, int index, object? recycleKey)
		{
			if (recycleKey == null)
			{
				return null;
			}
			ItemContainerGenerator itemContainerGenerator = base.ItemContainerGenerator;
			Dictionary<object, Stack<Control>>? recyclePool = _recyclePool;
			if (recyclePool != null && recyclePool.TryGetValue(recycleKey, out Stack<Control> value) && value.Count > 0)
			{
				Control control = value.Pop();
				control.SetCurrentValue(Visual.IsVisibleProperty, value: true);
				itemContainerGenerator.PrepareItemContainer(control, item, index);
				AddInternalChild(control);
				itemContainerGenerator.ItemContainerPrepared(control, item, index);
				return control;
			}
			return null;
		}

		private Control CreateElement(object? item, int index, object? recycleKey)
		{
			ItemContainerGenerator? itemContainerGenerator = base.ItemContainerGenerator;
			Control control = itemContainerGenerator.CreateContainer(item, index, recycleKey);
			control.SetValue(RecycleKeyProperty, recycleKey);
			itemContainerGenerator.PrepareItemContainer(control, item, index);
			AddInternalChild(control);
			itemContainerGenerator.ItemContainerPrepared(control, item, index);
			return control;
		}

		private void RecycleElement(Control element, int index)
		{
			_scrollAnchorProvider?.UnregisterAnchorCandidate(element);
			object value = element.GetValue(RecycleKeyProperty);
			if (value == null)
			{
				base.ItemContainerGenerator.ClearItemContainer(element);
				RemoveInternalChild(element);
				return;
			}
			if (value == s_itemIsItsOwnContainer)
			{
				element.SetCurrentValue(Visual.IsVisibleProperty, value: false);
				return;
			}
			if (KeyboardNavigation.GetTabOnceActiveElement(base.ItemsControl) == element)
			{
				_focusedElement = element;
				_focusedIndex = index;
				return;
			}
			base.ItemContainerGenerator.ClearItemContainer(element);
			PushToRecyclePool(value, element);
			element.SetCurrentValue(Visual.IsVisibleProperty, value: false);
			RemoveInternalChild(element);
		}

		private void RecycleElementOnItemRemoved(Control element)
		{
			_scrollAnchorProvider?.UnregisterAnchorCandidate(element);
			object value = element.GetValue(RecycleKeyProperty);
			if (value == null)
			{
				base.ItemContainerGenerator.ClearItemContainer(element);
				RemoveInternalChild(element);
				return;
			}
			if (value == s_itemIsItsOwnContainer)
			{
				RemoveInternalChild(element);
				return;
			}
			base.ItemContainerGenerator.ClearItemContainer(element);
			PushToRecyclePool(value, element);
			element.SetCurrentValue(Visual.IsVisibleProperty, value: false);
			RemoveInternalChild(element);
		}

		private void RecycleFocusedElement()
		{
			if (_focusedElement != null)
			{
				RecycleElementOnItemRemoved(_focusedElement);
			}
			_focusedElement = null;
			_focusedIndex = -1;
		}

		private void RecycleScrollToElement()
		{
			if (_scrollToElement != null)
			{
				RecycleElementOnItemRemoved(_scrollToElement);
			}
			_scrollToElement = null;
			_scrollToIndex = -1;
		}

		private void PushToRecyclePool(object recycleKey, Control element)
		{
			if (_recyclePool == null)
			{
				_recyclePool = new Dictionary<object, Stack<Control>>();
			}
			if (!_recyclePool.TryGetValue(recycleKey, out Stack<Control> value))
			{
				value = new Stack<Control>();
				_recyclePool.Add(recycleKey, value);
			}
			value.Push(element);
		}

		private void UpdateElementIndex(Control element, int oldIndex, int newIndex)
		{
			base.ItemContainerGenerator.ItemContainerIndexChanged(element, oldIndex, newIndex);
		}

		private Rect CalculateExtendedViewport(bool vertical, double viewportSize, double bufferSize)
		{
			double num = (vertical ? Math.Max(0.0, _viewport.Top - bufferSize) : Math.Max(0.0, _viewport.Left - bufferSize));
			double num2 = (vertical ? Math.Min(base.Bounds.Height, _viewport.Bottom + bufferSize) : Math.Min(base.Bounds.Width, _viewport.Right + bufferSize));
			if (vertical)
			{
				double num3 = _viewport.Top - bufferSize;
				double num4 = base.Bounds.Height - (_viewport.Bottom + bufferSize);
				if (num3 < 0.0 && num4 >= 0.0)
				{
					num2 = Math.Min(base.Bounds.Height, num2 + Math.Abs(num3));
				}
				if (num3 >= 0.0 && num4 < 0.0)
				{
					num = Math.Max(0.0, num - Math.Abs(num4));
				}
			}
			else
			{
				double num5 = _viewport.Left - bufferSize;
				double num6 = base.Bounds.Width - (_viewport.Right + bufferSize);
				if (num5 < 0.0 && num6 >= 0.0)
				{
					num2 = Math.Min(base.Bounds.Width, num2 + Math.Abs(num5));
				}
				if (num5 >= 0.0 && num6 < 0.0)
				{
					num = Math.Max(0.0, num - Math.Abs(num6));
				}
			}
			if (vertical)
			{
				return new Rect(_viewport.X, num, _viewport.Width, num2 - num);
			}
			return new Rect(num, _viewport.Y, num2 - num, _viewport.Height);
		}

		private void OnEffectiveViewportChanged(object? sender, EffectiveViewportChangedEventArgs e)
		{
			bool flag = Orientation == Orientation.Vertical;
			double num = (flag ? _viewport.Top : _viewport.Left);
			double num2 = (flag ? _viewport.Bottom : _viewport.Right);
			double num3 = (flag ? _lastMeasuredExtendedViewport.Top : _lastMeasuredExtendedViewport.Left);
			double num4 = (flag ? _lastMeasuredExtendedViewport.Bottom : _lastMeasuredExtendedViewport.Right);
			_viewport = e.EffectiveViewport.Intersect(new Rect(base.Bounds.Size));
			_isWaitingForViewportUpdate = false;
			double num5 = (flag ? _viewport.Height : _viewport.Width);
			double num6 = num5 * _bufferFactor;
			Rect rect = CalculateExtendedViewport(flag, num5, num6);
			double num7 = (flag ? _viewport.Top : _viewport.Left);
			double num8 = (flag ? _viewport.Bottom : _viewport.Right);
			double num9 = (flag ? rect.Top : rect.Left);
			double num10 = (flag ? rect.Bottom : rect.Right);
			bool flag2 = false;
			if (!MathUtilities.AreClose(num, num7) || !MathUtilities.AreClose(num2, num8))
			{
				if (num7 < num3 || num8 > num4)
				{
					flag2 = true;
				}
				else if (!MathUtilities.AreClose(num3, num9) || !MathUtilities.AreClose(num4, num10))
				{
					bool flag3 = false;
					if (_realizedElements != null)
					{
						_ = _realizedElements.StartU;
						double num11 = _realizedElements.StartU;
						for (int i = 0; i < _realizedElements.Count; i++)
						{
							num11 += _realizedElements.SizeU[i];
						}
						if (num7 < num && num7 - num9 < num6)
						{
							flag3 = !_hasReachedStart;
						}
						if (num8 > num2 && num10 - num8 < num6)
						{
							flag3 = !_hasReachedEnd;
						}
					}
					else
					{
						flag3 = true;
					}
					flag2 = flag3;
				}
			}
			if (!flag2)
			{
				double num12 = (flag ? _lastKnownExtendedViewport.Top : _lastKnownExtendedViewport.Left);
				double num13 = (flag ? _lastKnownExtendedViewport.Bottom : _lastKnownExtendedViewport.Right);
				if (num7 < num12 || num8 > num13)
				{
					flag2 = true;
				}
			}
			_lastKnownExtendedViewport = rect;
			if (flag2)
			{
				_lastMeasuredExtendedViewport = rect;
				InvalidateMeasure();
			}
		}

		private void OnItemsControlPropertyChanged(object? sender, AvaloniaPropertyChangedEventArgs e)
		{
			if (_focusedElement != null && e.Property == KeyboardNavigation.TabOnceActiveElementProperty && e.GetOldValue<IInputElement>() == _focusedElement)
			{
				RecycleElement(_focusedElement, _focusedIndex);
				_focusedElement = null;
				_focusedIndex = -1;
			}
		}

		private void OnCacheLengthChanged(AvaloniaPropertyChangedEventArgs e)
		{
			double newValue = e.GetNewValue<double>();
			_bufferFactor = newValue;
			InvalidateMeasure();
		}

		/// <inheritdoc />
		public IReadOnlyList<double> GetIrregularSnapPoints(Orientation orientation, SnapPointsAlignment snapPointsAlignment)
		{
			if (_realizedElements == null)
			{
				return new List<double>();
			}
			return new VirtualizingSnapPointsList(_realizedElements, (base.ItemsControl?.ItemsSource?.Count()).GetValueOrDefault(), orientation, Orientation, snapPointsAlignment, EstimateElementSizeU());
		}

		/// <inheritdoc />
		public double GetRegularSnapPoints(Orientation orientation, SnapPointsAlignment snapPointsAlignment, out double offset)
		{
			offset = 0.0;
			Control control = _realizedElements?.Elements.FirstOrDefault();
			if (control == null)
			{
				return 0.0;
			}
			double result = 0.0;
			switch (Orientation)
			{
			case Orientation.Horizontal:
				if (!AreHorizontalSnapPointsRegular)
				{
					throw new InvalidOperationException();
				}
				result = control.Bounds.Width;
				switch (snapPointsAlignment)
				{
				case SnapPointsAlignment.Near:
					offset = 0.0;
					break;
				case SnapPointsAlignment.Center:
					offset = (control.Bounds.Right - control.Bounds.Left) / 2.0;
					break;
				case SnapPointsAlignment.Far:
					offset = control.Bounds.Width;
					break;
				}
				break;
			case Orientation.Vertical:
				if (!AreVerticalSnapPointsRegular)
				{
					throw new InvalidOperationException();
				}
				result = control.Bounds.Height;
				switch (snapPointsAlignment)
				{
				case SnapPointsAlignment.Near:
					offset = 0.0;
					break;
				case SnapPointsAlignment.Center:
					offset = (control.Bounds.Bottom - control.Bounds.Top) / 2.0;
					break;
				case SnapPointsAlignment.Far:
					offset = control.Bounds.Height;
					break;
				}
				break;
			}
			return result;
		}
	}
