		private protected virtual bool HandleClosing(WindowCloseReason reason)
		{
			if (!ShouldCancelClose(new WindowClosingEventArgs(reason, isProgrammatic: false)))
			{
				CloseInternal();
				return false;
			}
			return true;
		}

		private void CloseInternal()
