						{
							flag = false;
						}
					}
				}
				if (flag)
				{
					OnClosing(args);
					return args.Cancel;
				}
				return true;
			}
			case WindowClosingBehavior.OwnerWindowOnly:
				OnClosing(args);
				return args.Cancel;
			default:
				return false;
			}
		}

