		/// <summary>
		/// Sorts the windows ascending by their Z order - the topmost window will be the last in the list.
		/// </summary>
		/// <param name="windows"></param>
		public static void SortWindowsByZOrder(Window[] windows)
		{
			if (windows.Length != 0)
			{
				IWindowImpl platformImpl = windows[0].PlatformImpl;
				if (platformImpl == null)
				{
					throw new InvalidOperationException("Window.PlatformImpl is null");
				}
				Span<long> span = stackalloc long[windows.Length];
				platformImpl.GetWindowsZOrder(windows, span);
				span.Sort(windows.AsSpan());
			}
		}

		private void UpdateEnabled()
		{
			bool enabled = true;
			foreach (var child in _children)
			{
				if (child.isDialog)
				{
					enabled = false;
					break;
				}
			}
			PlatformImpl?.SetEnabled(enabled);
		}

		private void AddChild(Window window, bool isDialog)
		{
			_children.Add((window, isDialog));
			UpdateEnabled();
		}

		private void RemoveChild(Window window)
		{
			for (int num = _children.Count - 1; num >= 0; num--)
			{
				if (_children[num].child == window)
				{
					_children.RemoveAt(num);
				}
			}
			UpdateEnabled();
		}

		private void OnGotInputWhenDisabled()
		{
			Window window = null;
			foreach (var child in _children)
			{
				var (window2, _) = child;
				if (child.isDialog)
				{
					window = window2;
					break;
				}
			}
			if (window != null)
			{
				window.OnGotInputWhenDisabled();
			}
			else
			{
				Activate();
			}
		}

		private void SetExpectedScaling(WindowBase? owner)
		{
			if (_wasShownBefore)
			{
				return;
			}
			switch (GetEffectiveWindowStartupLocation(owner))
			{
			case WindowStartupLocation.CenterOwner:
				base.DesktopScalingOverride = owner?.DesktopScaling;
				break;
			case WindowStartupLocation.CenterScreen:
			{
				double? desktopScalingOverride;
				if (owner == null)
				{
					Screen? screen = base.Screens.ScreenFromPoint(Position);
					desktopScalingOverride = (((object)screen != null) ? new double?(screen.Scaling) : base.Screens.Primary?.Scaling);
				}
				else
				{
					desktopScalingOverride = owner.DesktopScaling;
				}
				base.DesktopScalingOverride = desktopScalingOverride;
				break;
			}
			case WindowStartupLocation.Manual:
				base.DesktopScalingOverride = base.Screens.ScreenFromPoint(Position)?.Scaling;
				break;
			}
		}

		private WindowStartupLocation GetEffectiveWindowStartupLocation(WindowBase? owner)
		{
			WindowStartupLocation windowStartupLocation = WindowStartupLocation;
			if (windowStartupLocation == WindowStartupLocation.CenterOwner && (owner == null || owner is Window { WindowState: WindowState.Minimized }))
			{
				windowStartupLocation = WindowStartupLocation.CenterScreen;
			}
			return windowStartupLocation;
		}

