			IWindowImpl? platformImpl = PlatformImpl;
			PixelRect rect;
			if (platformImpl != null && platformImpl.FrameSize.HasValue)
			{
				Size size = PlatformImpl.FrameSize.Value - PlatformImpl.ClientSize;
				rect = new PixelRect(PixelSize.FromSize(base.ClientSize + size, base.DesktopScaling));
			}
			else
			{
				rect = new PixelRect(PixelSize.FromSize(base.ClientSize, base.DesktopScaling));
			}
			switch (effectiveWindowStartupLocation)
			{
			case WindowStartupLocation.CenterScreen:
			{
				Screen screen = null;
				if (owner != null)
				{
					screen = base.Screens.ScreenFromWindow(owner) ?? base.Screens.ScreenFromPoint(owner.Position);
				}
				if ((object)screen == null)
				{
					screen = base.Screens.ScreenFromPoint(Position);
				}
				if ((object)screen == null)
				{
					screen = base.Screens.Primary;
				}
				if ((object)screen != null)
				{
					PixelRect childRect2 = screen.WorkingArea.CenterRect(rect);
					if (base.Screens.ScreenFromPoint(childRect2.Position) == null)
					{
						childRect2 = ApplyScreenConstraint(screen, childRect2);
					}
					Position = childRect2.Position;
				}
				break;
			}
			case WindowStartupLocation.CenterOwner:
			{
				Size size2 = owner.FrameSize ?? owner.ClientSize;
				PixelRect childRect = new PixelRect(owner.Position, PixelSize.FromSize(size2, owner.DesktopScaling)).CenterRect(rect);
				Position = ApplyScreenConstraint(base.Screens.ScreenFromWindow(owner), childRect).Position;
				break;
			}
			}
			if (!_positionWasSet && base.DesktopScaling != PlatformImpl?.DesktopScaling)
			{
				PlatformImpl?.Move(Position);
			}
			PixelRect ApplyScreenConstraint(Screen? screen2, PixelRect result)
			{
				PixelRect? pixelRect = screen2?.WorkingArea;
				if (pixelRect.HasValue)
				{
					PixelRect valueOrDefault = pixelRect.GetValueOrDefault();
					int num = valueOrDefault.Right - rect.Width;
					int num2 = valueOrDefault.Bottom - rect.Height;
					if (valueOrDefault.X <= num)
					{
						result = result.WithX(MathUtilities.Clamp(result.X, valueOrDefault.X, num));
					}
					if (valueOrDefault.Y <= num2)
					{
						result = result.WithY(MathUtilities.Clamp(result.Y, valueOrDefault.Y, num2));
					}
				}
				return result;
			}
		}

		protected override Size MeasureOverride(Size availableSize)
		{
			SizeToContent sizeToContent = SizeToContent;
			Size clientSize = base.ClientSize;
			Size size = PlatformImpl?.MaxAutoSizeHint ?? Size.Infinity;
			bool flag = sizeToContent.HasAllFlags(SizeToContent.Width);
			bool flag2 = sizeToContent.HasAllFlags(SizeToContent.Height);
			Size availableSize2 = new Size((flag || double.IsInfinity(availableSize.Width)) ? clientSize.Width : availableSize.Width, (flag2 || double.IsInfinity(availableSize.Height)) ? clientSize.Height : availableSize.Height);
			if (base.MaxWidth > 0.0 && base.MaxWidth < size.Width)
			{
				size = size.WithWidth(base.MaxWidth);
			}
			if (base.MaxHeight > 0.0 && base.MaxHeight < size.Height)
			{
				size = size.WithHeight(base.MaxHeight);
			}
			if (flag)
			{
				availableSize2 = availableSize2.WithWidth(size.Width);
			}
			if (flag2)
			{
				availableSize2 = availableSize2.WithHeight(size.Height);
			}
			Size result = base.MeasureOverride(availableSize2);
			if (!flag)
			{
				result = (double.IsInfinity(availableSize.Width) ? result.WithWidth(clientSize.Width) : result.WithWidth(availableSize.Width));
			}
			if (!flag2)
			{
				result = (double.IsInfinity(availableSize.Height) ? result.WithHeight(clientSize.Height) : result.WithHeight(availableSize.Height));
			}
			return result;
		}

		protected sealed override Size ArrangeSetBounds(Size size)
		{
			_arrangeBounds = size;
			if (_canHandleResized)
			{
				PlatformImpl?.Resize(size, WindowResizeReason.Layout);
			}
			return base.ClientSize;
		}

		private protected sealed override void HandleClosed()
		{
			_shown = false;
			base.HandleClosed();
			RaiseEvent(new RoutedEventArgs(WindowClosedEvent));
			base.Owner = null;
		}

		/// <inheritdoc />
		internal override void HandleResized(Size clientSize, WindowResizeReason reason)
		{
			if (_canHandleResized && (base.ClientSize != clientSize || double.IsNaN(base.Width) || double.IsNaN(base.Height)))
			{
				SizeToContent sizeToContent = SizeToContent;
				if ((sizeToContent != SizeToContent.Manual && CanResize && reason == WindowResizeReason.Unspecified) || reason == WindowResizeReason.User)
				{
					if (clientSize.Width != base.ClientSize.Width)
					{
						sizeToContent &= ~SizeToContent.Width;
					}
					if (clientSize.Height != base.ClientSize.Height)
					{
						sizeToContent &= ~SizeToContent.Height;
					}
					SizeToContent = sizeToContent;
				}
				base.Width = clientSize.Width;
				base.Height = clientSize.Height;
			}
			base.HandleResized(clientSize, reason);
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Window.Closing" /> event.
		/// </summary>
		/// <param name="e">The event args.</param>
		/// <remarks>
		/// A type that derives from <see cref="T:Avalonia.Controls.Window" />  may override <see cref="M:Avalonia.Controls.Window.OnClosing(Avalonia.Controls.WindowClosingEventArgs)" />. The
		/// overridden method must call <see cref="M:Avalonia.Controls.Window.OnClosing(Avalonia.Controls.WindowClosingEventArgs)" /> on the base class if the
		/// <see cref="E:Avalonia.Controls.Window.Closing" /> event needs to be raised.
		/// </remarks>
		protected virtual void OnClosing(WindowClosingEventArgs e)
		{
			this.Closing?.Invoke(this, e);
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == SystemDecorationsProperty)
			{
				SystemDecorations item = change.GetOldAndNewValue<SystemDecorations>().newValue;
				PlatformImpl?.SetSystemDecorations(item);
			}
			else if (change.Property == WindowBase.OwnerProperty)
			{
				Window obj = change.OldValue as Window;
				Window window = change.NewValue as Window;
				obj?.RemoveChild(this);
				window?.AddChild(this, _showingAsDialog);
				PlatformImpl?.SetParent((!_showingAsDialog) ? (window?.PlatformImpl ?? null) : window?.PlatformImpl);
			}
			else if (change.Property == CanResizeProperty)
			{
				CoerceValue(CanMaximizeProperty);
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new WindowAutomationPeer(this);
		}

		private static WindowIcon? LoadDefaultIcon()
		{
			IAssetLoader service = AvaloniaLocator.Current.GetService<IAssetLoader>();
			if (service != null)
			{
				string text = Assembly.GetEntryAssembly()?.GetName()?.Name;
				if (text != null && Uri.TryCreate("avares://" + text + "/!__AvaloniaDefaultWindowIcon", UriKind.Absolute, out Uri result) && service.Exists(result))
				{
					using (Stream stream = service.Open(result))
					{
						return new WindowIcon(stream);
					}
				}
			}
			return null;
		}

		private void SetEffectiveIcon(WindowIcon? icon)
		{
			if (icon == null)
			{
				icon = (_shown ? s_defaultIcon.Value : null);
			}
			PlatformImpl?.SetIcon(icon?.PlatformImpl);
		}

		private static bool CoerceCanMaximize(AvaloniaObject target, bool value)
		{
			if (value)
			{
				return !(target is Window window) || window.CanResize;
			}
			return false;
		}
	}
	/// <summary>
	/// Base class for top-level windows.
	/// </summary>
	/// <remarks>
	/// This class acts as a base for top level windows such as <see cref="T:Avalonia.Controls.Window" /> and
	/// <see cref="T:Avalonia.Controls.Primitives.PopupRoot" />. It handles scheduling layout, styling and rendering as well as
	/// tracking the window <see cref="P:Avalonia.Controls.TopLevel.ClientSize" /> and <see cref="P:Avalonia.Controls.WindowBase.IsActive" /> state.
	/// </remarks>
	public class WindowBase : TopLevel
	{
		private readonly struct IgnoreVisibilityChangesDisposable : IDisposable
		{
			private readonly WindowBase _windowBase;

			public IgnoreVisibilityChangesDisposable(WindowBase windowBase)
			{
				_windowBase = windowBase;
				_windowBase._ignoreVisibilityChanges++;
			}

			public void Dispose()
			{
				_windowBase._ignoreVisibilityChanges--;
			}
		}

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.WindowBase.IsActive" /> property.
		/// </summary>
		public static readonly DirectProperty<WindowBase, bool> IsActiveProperty;

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.WindowBase.Owner" /> property.
		/// </summary>
		public static readonly DirectProperty<WindowBase, WindowBase?> OwnerProperty;

		public static readonly StyledProperty<bool> TopmostProperty;

		private bool _hasExecutedInitialLayoutPass;

		private bool _isActive;

		private int _ignoreVisibilityChanges;

		private WindowBase? _owner;

		protected bool IgnoreVisibilityChanges => _ignoreVisibilityChanges > 0;

		public new IWindowBaseImpl? PlatformImpl => (IWindowBaseImpl)base.PlatformImpl;

		/// <summary>
		/// Gets a value that indicates whether the window is active.
		/// </summary>
		public bool IsActive
		{
			get
			{
				return _isActive;
			}
			private set
			{
				SetAndRaise(IsActiveProperty, ref _isActive, value);
			}
		}

		/// <inheritdoc cref="P:Avalonia.Controls.TopLevel.Screens" />
		public new Screens Screens => base.Screens ?? throw new InvalidOperationException("Windowing backend wasn't properly initialized.");

		/// <summary>
		/// Gets or sets the owner of the window.
		/// </summary>
		public WindowBase? Owner
		{
			get
			{
				return _owner;
			}
			protected set
			{
				SetAndRaise(OwnerProperty, ref _owner, value);
			}
		}

		/// <summary>
		/// Gets or sets whether this window appears on top of all other windows
		/// </summary>
		public bool Topmost
		{
			get
			{
				return GetValue(TopmostProperty);
			}
			set
			{
				SetValue(TopmostProperty, value);
			}
		}

		/// <summary>
		/// Gets the scaling factor for Window positioning and sizing.
		/// </summary>
		public double DesktopScaling => DesktopScalingOverride ?? PlatformImpl?.DesktopScaling ?? 1.0;

		private protected double? DesktopScalingOverride { get; set; }

		/// <summary>
		/// Fired when the window is activated.
		/// </summary>
		public event EventHandler? Activated;

		/// <summary>
		/// Fired when the window is deactivated.
		/// </summary>
		public event EventHandler? Deactivated;

		/// <summary>
		/// Fired when the window position is changed.
		/// </summary>
		public event EventHandler<PixelPointEventArgs>? PositionChanged;

		/// <summary>
		/// Occurs when the window is resized.
		/// </summary>
		/// <remarks>
		/// Although this event is similar to the <see cref="E:Avalonia.Controls.Control.SizeChanged" /> event, they are
		/// conceptually different:
		///
		/// - <see cref="E:Avalonia.Controls.WindowBase.Resized" /> is a window-level event, fired when a resize notification arrives
		///   from the platform windowing subsystem. The event args contain details of the source of
		///   the resize event in the <see cref="P:Avalonia.Controls.WindowResizedEventArgs.Reason" /> property. This
		///   event is raised before layout has been run on the window's content.
		/// - <see cref="E:Avalonia.Controls.Control.SizeChanged" /> is a layout-level event, fired when a layout pass
		///   completes on a control. <see cref="E:Avalonia.Controls.Control.SizeChanged" /> is present on all controls
		///   and is fired when the control's size changes for any reason, including a
		///   <see cref="E:Avalonia.Controls.WindowBase.Resized" /> event in the case of a Window.
		/// </remarks>
		public event EventHandler<WindowResizedEventArgs>? Resized;

		static WindowBase()
		{
			IsActiveProperty = AvaloniaProperty.RegisterDirect("IsActive", (WindowBase o) => o.IsActive, null, unsetValue: false);
			OwnerProperty = AvaloniaProperty.RegisterDirect("Owner", (WindowBase o) => o.Owner);
			TopmostProperty = AvaloniaProperty.Register<WindowBase, bool>("Topmost", defaultValue: false);
			Visual.IsVisibleProperty.OverrideDefaultValue<WindowBase>(defaultValue: false);
		}

		public WindowBase(IWindowBaseImpl impl)
			: this(impl, AvaloniaLocator.Current)
		{
			CreatePlatformImplBinding(TopmostProperty, delegate(bool topmost)
			{
				PlatformImpl.SetTopmost(topmost);
			});
			base.FrameSize = impl.FrameSize;
		}

		public WindowBase(IWindowBaseImpl impl, IAvaloniaDependencyResolver? dependencyResolver)
			: base(impl, dependencyResolver)
		{
			impl.Activated = HandleActivated;
			impl.Deactivated = HandleDeactivated;
			impl.PositionChanged = HandlePositionChanged;
		}

		private protected IDisposable FreezeVisibilityChangeHandling()
		{
			return new IgnoreVisibilityChangesDisposable(this);
		}

		/// <summary>
		/// Activates the window.
		/// </summary>
		public void Activate()
		{
			PlatformImpl?.Activate();
		}

		/// <summary>
		/// Hides the popup.
		/// </summary>
		public virtual void Hide()
		{
			using (FreezeVisibilityChangeHandling())
			{
				StopRendering();
				PlatformImpl?.Hide();
				base.IsVisible = false;
			}
		}

		/// <summary>
		/// Shows the window.
		/// </summary>
		public virtual void Show()
		{
			using (FreezeVisibilityChangeHandling())
			{
				EnsureInitialized();
				ApplyStyling();
				base.IsVisible = true;
				if (!_hasExecutedInitialLayoutPass)
				{
					base.LayoutManager.ExecuteInitialLayoutPass();
					_hasExecutedInitialLayoutPass = true;
				}
				PlatformImpl?.Show(activate: true, isDialog: false);
				StartRendering();
				OnOpened(EventArgs.Empty);
			}
		}

		/// <summary>
		/// Ensures that the window is initialized.
		/// </summary>
		protected void EnsureInitialized()
		{
			if (!base.IsInitialized)
			{
				((ISupportInitialize)this).BeginInit();
				((ISupportInitialize)this).EndInit();
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == Visual.IsVisibleProperty)
			{
				IsVisibleChanged(change);
			}
		}

		/// <inheritdoc />
		protected override void OnClosed(EventArgs e)
		{
			OnUnloadedCore();
			base.OnClosed(e);
		}

		/// <inheritdoc />
		protected override void OnOpened(EventArgs e)
		{
			base.FrameSize = PlatformImpl?.FrameSize;
			ScheduleOnLoadedCore();
			base.OnOpened(e);
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.WindowBase.Resized" /> event.
		/// </summary>
		/// <param name="e">An <see cref="T:System.EventArgs" /> that contains the event data.</param>
		protected virtual void OnResized(WindowResizedEventArgs e)
		{
			this.Resized?.Invoke(this, e);
		}

		private protected override void HandleClosed()
		{
			using (FreezeVisibilityChangeHandling())
			{
				base.IsVisible = false;
				if (this is IFocusScope scope)
				{
					((FocusManager)base.FocusManager)?.RemoveFocusRoot(scope);
				}
				base.HandleClosed();
			}
		}

		/// <summary>
		/// Handles a resize notification from <see cref="P:Avalonia.Platform.ITopLevelImpl.Resized" />.
		/// </summary>
		/// <param name="clientSize">The new client size.</param>
		/// <param name="reason">The reason for the resize.</param>
		internal override void HandleResized(Size clientSize, WindowResizeReason reason)
		{
			base.FrameSize = PlatformImpl?.FrameSize;
			bool num = base.ClientSize != clientSize;
			base.ClientSize = clientSize;
			OnResized(new WindowResizedEventArgs(clientSize, reason));
			if (num)
			{
				base.LayoutManager.ExecuteLayoutPass();
				base.Renderer.Resized(clientSize);
			}
		}

		/// <summary>
		/// Overrides the core measure logic for windows.
		/// </summary>
		/// <param name="availableSize">The available size.</param>
		/// <returns>The measured size.</returns>
		/// <remarks>
		/// The layout logic for top-level windows is different than for other controls because
		/// they don't have a parent, meaning that many layout properties handled by the default
		/// MeasureCore (such as margins and alignment) make no sense.
		/// </remarks>
		protected override Size MeasureCore(Size availableSize)
		{
			ApplyStyling();
			ApplyTemplate();
			Size availableSize2 = LayoutHelper.ApplyLayoutConstraints(this, availableSize);
			Avalonia.Styling.Container.GetQueryProvider(this)?.SetSize(availableSize2.Width, availableSize2.Height, Avalonia.Styling.Container.GetSizing(this));
			return MeasureOverride(availableSize2);
		}

		/// <summary>
		/// Overrides the core arrange logic for windows.
		/// </summary>
		/// <param name="finalRect">The final arrange rect.</param>
		/// <remarks>
		/// The layout logic for top-level windows is different than for other controls because
		/// they don't have a parent, meaning that many layout properties handled by the default
		/// ArrangeCore (such as margins and alignment) make no sense.
		/// </remarks>
		protected override void ArrangeCore(Rect finalRect)
		{
			Size finalSize = ArrangeSetBounds(finalRect.Size);
			Size size = ArrangeOverride(finalSize);
			base.Bounds = new Rect(size);
		}

		/// <summary>
		/// Called during the arrange pass to set the size of the window.
		/// </summary>
		/// <param name="size">The requested size of the window.</param>
		/// <returns>The actual size of the window.</returns>
		protected virtual Size ArrangeSetBounds(Size size)
		{
			return size;
		}

		/// <summary>
		/// Handles a window position change notification from 
		/// <see cref="P:Avalonia.Platform.IWindowBaseImpl.PositionChanged" />.
		/// </summary>
		/// <param name="pos">The window position.</param>
		private void HandlePositionChanged(PixelPoint pos)
		{
			this.PositionChanged?.Invoke(this, new PixelPointEventArgs(pos));
		}

		/// <summary>
		/// Handles an activated notification from <see cref="P:Avalonia.Platform.IWindowBaseImpl.Activated" />.
		/// </summary>
		private void HandleActivated()
		{
			this.Activated?.Invoke(this, EventArgs.Empty);
			if (this is IFocusScope focusScope)
			{
				((FocusManager)base.FocusManager)?.SetFocusScope(focusScope);
			}
			IsActive = true;
		}

		/// <summary>
		/// Handles a deactivated notification from <see cref="P:Avalonia.Platform.IWindowBaseImpl.Deactivated" />.
		/// </summary>
		private void HandleDeactivated()
		{
			IsActive = false;
			this.Deactivated?.Invoke(this, EventArgs.Empty);
		}

		protected virtual void IsVisibleChanged(AvaloniaPropertyChangedEventArgs e)
		{
			if (_ignoreVisibilityChanges == 0)
			{
				if ((bool)e.NewValue)
				{
					Show();
				}
				else
				{
					Hide();
				}
			}
		}
	}
	/// <summary>
	/// Specifies the reason that a window was closed.
