	public static class AncestorFinder
	{
		private class FinderNode : IDisposable
		{
			private readonly StyledElement _control;

			private readonly Type _ancestorType;

			private readonly LightweightSubject<StyledElement?> _subject = new LightweightSubject<StyledElement>();

			private FinderNode? _child;

			private IDisposable? _disposable;

			public IObservable<StyledElement?> Observable => _subject;

			public FinderNode(StyledElement control, Type ancestorType)
			{
				_control = control;
				_ancestorType = ancestorType;
			}

			public void Init()
			{
				_disposable = _control.GetObservable(StyledElement.ParentProperty).Subscribe(OnValueChanged);
			}

			private void OnValueChanged(StyledElement? next)
			{
				if (next == null || _ancestorType.IsInstanceOfType(next))
				{
					_subject.OnNext(next);
					return;
				}
				_child?.Dispose();
				_child = new FinderNode(next, _ancestorType);
				_child.Observable.Subscribe(_subject);
				_child.Init();
			}

			public void Dispose()
			{
				_child?.Dispose();
				_subject.OnCompleted();
				_disposable?.Dispose();
			}
		}

		public static IObservable<T?> Create<T>(StyledElement control) where T : StyledElement
		{
			return from x in Create(control, typeof(T))
				select (T)x;
		}

		public static IObservable<StyledElement?> Create(StyledElement control, Type ancestorType)
		{
			return Observable.Create(delegate(IObserver<StyledElement?> observer)
			{
				FinderNode finder = new FinderNode(control, ancestorType);
				IDisposable subscription = finder.Observable.Subscribe(observer);
				finder.Init();
				return Disposable.Create(delegate
				{
					subscription.Dispose();
					finder.Dispose();
				});
			});
		}
	}
	/// <summary>
	/// Helper class for evaluating a binding from an Item and IBinding instance
	/// </summary>
	internal sealed class BindingEvaluator<T> : StyledElement, IDisposable
	{
		private BindingExpressionBase? _expression;

		private IBinding? _lastBinding;

		public static readonly StyledProperty<T> ValueProperty = AvaloniaProperty.Register<BindingEvaluator<T>, T>("Value");

		/// <summary>
		/// Gets or sets the data item value.
		/// </summary>
