			}
			set
			{
				SetValue(ValueProperty, value);
			}
		}

		public T Evaluate(object? dataContext)
		{
			if (!object.Equals(dataContext, base.DataContext))
			{
				base.DataContext = dataContext;
			}
			return GetValue(ValueProperty);
		}

		public void UpdateBinding(IBinding binding)
		{
			if (binding != _lastBinding)
			{
				_expression?.Dispose();
				_expression = Bind(ValueProperty, binding);
				_lastBinding = binding;
			}
		}

		public void ClearDataContext()
		{
			base.DataContext = null;
		}

		public void Dispose()
		{
			_expression?.Dispose();
			_expression = null;
			_lastBinding = null;
			base.DataContext = null;
		}

		[return: NotNullIfNotNull("binding")]
		public static BindingEvaluator<T>? TryCreate(IBinding? binding)
		{
			if (binding == null)
			{
				return null;
			}
			BindingEvaluator<T> bindingEvaluator = new BindingEvaluator<T>();
			bindingEvaluator.UpdateBinding(binding);
			return bindingEvaluator;
		}
	}
	/// <summary>
	/// Contains helper methods for rendering a <see cref="T:Avalonia.Controls.Border" />'s background and border to a given context.
	/// </summary>
	internal class BorderRenderHelper
	{
		private bool _useComplexRendering;

		private bool? _backendSupportsIndividualCorners;

		private Geometry? _backgroundGeometryCache;

		private Geometry? _borderGeometryCache;

		private Size _size;

		private Thickness _borderThickness;

		private CornerRadius _cornerRadius;

		private BackgroundSizing _backgroundSizing;

		private bool _initialized;

		private IPen? _cachedPen;

		private void Update(Size finalSize, Thickness borderThickness, CornerRadius cornerRadius, BackgroundSizing backgroundSizing)
		{
			bool valueOrDefault = _backendSupportsIndividualCorners == true;
			if (!_backendSupportsIndividualCorners.HasValue)
			{
				valueOrDefault = AvaloniaLocator.Current.GetRequiredService<IPlatformRenderInterface>().SupportsIndividualRoundRects;
				_backendSupportsIndividualCorners = valueOrDefault;
			}
			_size = finalSize;
			_borderThickness = borderThickness;
			_cornerRadius = cornerRadius;
			_backgroundSizing = backgroundSizing;
			_initialized = true;
			if (borderThickness.IsUniform && (cornerRadius.IsUniform || _backendSupportsIndividualCorners == true) && backgroundSizing == BackgroundSizing.CenterBorder)
			{
				_backgroundGeometryCache = null;
				_borderGeometryCache = null;
				_useComplexRendering = false;
				return;
			}
			_useComplexRendering = true;
			Rect outerBounds = new Rect(finalSize);
			Rect rect = outerBounds.Deflate(borderThickness);
			if (rect.Width != 0.0 && rect.Height != 0.0)
			{
				GeometryBuilder.RoundedRectKeypoints keypoints = GeometryBuilder.CalculateRoundedCornersRectangleWinUI(outerBounds, borderThickness, cornerRadius, backgroundSizing);
				StreamGeometry streamGeometry = new StreamGeometry();
				using (StreamGeometryContext context = streamGeometry.Open())
				{
					GeometryBuilder.DrawRoundedCornersRectangle(context, ref keypoints);
				}
				_backgroundGeometryCache = streamGeometry;
			}
			else
			{
				_backgroundGeometryCache = null;
			}
			if (outerBounds.Width != 0.0 && outerBounds.Height != 0.0)
			{
				GeometryBuilder.RoundedRectKeypoints keypoints2 = GeometryBuilder.CalculateRoundedCornersRectangleWinUI(outerBounds, borderThickness, cornerRadius, BackgroundSizing.InnerBorderEdge);
				GeometryBuilder.RoundedRectKeypoints keypoints3 = GeometryBuilder.CalculateRoundedCornersRectangleWinUI(outerBounds, borderThickness, cornerRadius, BackgroundSizing.OuterBorderEdge);
				StreamGeometry streamGeometry2 = new StreamGeometry();
				using (StreamGeometryContext context2 = streamGeometry2.Open())
				{
					GeometryBuilder.DrawRoundedCornersRectangle(context2, ref keypoints2);
				}
				StreamGeometry streamGeometry3 = new StreamGeometry();
				using (StreamGeometryContext context3 = streamGeometry3.Open())
				{
					GeometryBuilder.DrawRoundedCornersRectangle(context3, ref keypoints3);
				}
				_borderGeometryCache = new CombinedGeometry(GeometryCombineMode.Exclude, streamGeometry3, streamGeometry2);
			}
			else
			{
				_borderGeometryCache = null;
			}
		}

		public void Render(DrawingContext context, Size finalSize, Thickness borderThickness, CornerRadius cornerRadius, BackgroundSizing backgroundSizing, IBrush? background, IBrush? borderBrush, BoxShadows boxShadows)
		{
			if (_size != finalSize || _borderThickness != borderThickness || _cornerRadius != cornerRadius || _backgroundSizing != backgroundSizing || !_initialized)
			{
				Update(finalSize, borderThickness, cornerRadius, backgroundSizing);
			}
			if (_useComplexRendering)
			{
				if (_backgroundGeometryCache != null)
				{
					context.DrawGeometry(background, null, _backgroundGeometryCache);
				}
				if (_borderGeometryCache != null)
				{
					context.DrawGeometry(borderBrush, null, _borderGeometryCache);
				}
			}
			else
			{
				double top = _borderThickness.Top;
				Pen.TryModifyOrCreate(ref _cachedPen, borderBrush, top);
				Rect rect = new Rect(_size);
				if (!MathUtilities.IsZero(top))
				{
					rect = rect.Deflate(top * 0.5);
				}
				context.DrawRectangle(rrect: new RoundedRect(rect, _cornerRadius.TopLeft, _cornerRadius.TopRight, _cornerRadius.BottomRight, _cornerRadius.BottomLeft), brush: background, pen: _cachedPen, boxShadows: boxShadows);
			}
		}
	}
