	{
		private class FastRepeat<T> : ICollection<T>, IEnumerable<T>, IEnumerable
		{
			public static readonly FastRepeat<T> Instance = new FastRepeat<T>();

			public int Count { get; set; }

			public bool IsReadOnly => true;

			public T Item
			{
				get; [param: AllowNull]
				set;
