	/// <summary>
	/// Stores the realized element state for a virtualizing panel that arranges its children
	/// in a stack layout, such as <see cref="T:Avalonia.Controls.VirtualizingStackPanel" />.
	/// </summary>
	internal class RealizedStackElements
	{
		private int _firstIndex;

		private List<Control?>? _elements;

		private List<double>? _sizes;

		private double _startU;

		private bool _startUUnstable;

		/// <summary>
		/// Gets the number of realized elements.
		/// </summary>
		public int Count => _elements?.Count ?? 0;

		/// <summary>
		/// Gets the index of the first realized element, or -1 if no elements are realized.
		/// </summary>
		public int FirstIndex
		{
			get
			{
				List<Control?>? elements = _elements;
				if (elements == null || elements.Count <= 0)
				{
					return -1;
				}
				return _firstIndex;
			}
		}

		/// <summary>
		/// Gets the index of the last realized element, or -1 if no elements are realized.
		/// </summary>
		public int LastIndex
		{
			get
			{
				List<Control?>? elements = _elements;
				if (elements == null || elements.Count <= 0)
				{
					return -1;
				}
				return _firstIndex + _elements.Count - 1;
			}
		}

		/// <summary>
		/// Gets the elements.
		/// </summary>
		public IReadOnlyList<Control?> Elements => _elements ?? (_elements = new List<Control>());

		/// <summary>
		/// Gets the sizes of the elements on the primary axis.
		/// </summary>
		public IReadOnlyList<double> SizeU => _sizes ?? (_sizes = new List<double>());

		/// <summary>
		/// Gets the position of the first element on the primary axis, or NaN if the position is
		/// unstable.
		/// </summary>
		public double StartU
		{
			get
			{
				if (!_startUUnstable)
				{
					return _startU;
				}
				return double.NaN;
			}
		}

		/// <summary>
		/// Adds a newly realized element to the collection.
		/// </summary>
		/// <param name="index">The index of the element.</param>
		/// <param name="element">The element.</param>
		/// <param name="u">The position of the element on the primary axis.</param>
		/// <param name="sizeU">The size of the element on the primary axis.</param>
		public void Add(int index, Control element, double u, double sizeU)
		{
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			if (_elements == null)
			{
				_elements = new List<Control>();
			}
			if (_sizes == null)
			{
				_sizes = new List<double>();
			}
			if (Count == 0)
			{
				_elements.Add(element);
				_sizes.Add(sizeU);
				_startU = u;
				_firstIndex = index;
				return;
			}
			if (index == LastIndex + 1)
			{
				_elements.Add(element);
				_sizes.Add(sizeU);
				return;
			}
			if (index == FirstIndex - 1)
			{
				_firstIndex--;
				_elements.Insert(0, element);
				_sizes.Insert(0, sizeU);
				_startU = u;
				return;
			}
			throw new NotSupportedException("Can only add items to the beginning or end of realized elements.");
		}

		/// <summary>
		/// Gets the element at the specified index, if realized.
		/// </summary>
		/// <param name="index">The index in the source collection of the element to get.</param>
		/// <returns>The element if realized; otherwise null.</returns>
		public Control? GetElement(int index)
		{
			int num = index - FirstIndex;
			if (num >= 0 && num < _elements?.Count)
			{
				return _elements[num];
			}
			return null;
		}

		/// <summary>
		/// Gets the position of the element with the requested index on the primary axis, if realized.
		/// </summary>
		/// <returns>
		/// The position of the element, or NaN if the element is not realized.
		/// </returns>
		public double GetElementU(int index)
		{
			if (index < FirstIndex || _sizes == null)
			{
				return double.NaN;
			}
			int num = index - FirstIndex;
			if (num >= _sizes.Count)
			{
				return double.NaN;
			}
			double num2 = StartU;
			for (int i = 0; i < num; i++)
			{
				num2 += _sizes[i];
			}
			return num2;
		}

		/// <summary>
		/// Gets the index of the specified element.
		/// </summary>
		/// <param name="element">The element.</param>
		/// <returns>The index or -1 if the element is not present in the collection.</returns>
		public int GetIndex(Control element)
		{
			int? num = _elements?.IndexOf(element);
			if (num.HasValue)
			{
				int valueOrDefault = num.GetValueOrDefault();
				if (valueOrDefault >= 0)
				{
					return valueOrDefault + FirstIndex;
				}
			}
			return -1;
		}

		/// <summary>
		/// Updates the elements in response to items being inserted into the source collection.
		/// </summary>
		/// <param name="index">The index in the source collection of the insert.</param>
		/// <param name="count">The number of items inserted.</param>
		/// <param name="updateElementIndex">A method used to update the element indexes.</param>
		public void ItemsInserted(int index, int count, Action<Control, int, int> updateElementIndex)
		{
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			if (_elements == null || _elements.Count == 0)
			{
				return;
			}
			int firstIndex = FirstIndex;
			int num = index - firstIndex;
			if (num >= Count)
			{
				return;
			}
			int count2 = _elements.Count;
			for (int i = Math.Max(num, 0); i < count2; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					int num2 = i + firstIndex;
					updateElementIndex(control, num2, num2 + count);
				}
			}
			if (num < 0)
			{
				_firstIndex += count;
				_startUUnstable = true;
			}
			else
			{
				_elements.InsertMany(num, null, count);
				_sizes.InsertMany(num, double.NaN, count);
			}
		}

		/// <summary>
		/// Updates the elements in response to items being removed from the source collection.
		/// </summary>
		/// <param name="index">The index in the source collection of the remove.</param>
		/// <param name="count">The number of items removed.</param>
		/// <param name="updateElementIndex">A method used to update the element indexes.</param>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void ItemsRemoved(int index, int count, Action<Control, int, int> updateElementIndex, Action<Control> recycleElement)
		{
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			if (_elements == null || _elements.Count == 0)
			{
				return;
			}
			int num = FirstIndex;
			int lastIndex = LastIndex;
			int num2 = index - num;
			int num3 = index + count - num;
			if (num3 < 0)
			{
				_firstIndex -= count;
				_startUUnstable = true;
				int num4 = _firstIndex;
				for (int i = 0; i < _elements.Count; i++)
				{
					Control control = _elements[i];
					if (control != null)
					{
						updateElementIndex(control, num4 + count, num4);
					}
					num4++;
				}
			}
			else
			{
				if (num2 >= _elements.Count)
				{
					return;
				}
				int num5 = Math.Max(num2, 0);
				int num6 = Math.Min(num3, _elements.Count);
				for (int j = num5; j < num6; j++)
				{
					Control control2 = _elements[j];
					if (control2 != null)
					{
						_elements[j] = null;
						recycleElement(control2);
					}
				}
				_elements.RemoveRange(num5, num6 - num5);
				_sizes.RemoveRange(num5, num6 - num5);
				if (num2 <= 0 && num6 < lastIndex)
				{
					num = (_firstIndex = index);
					_startUUnstable = true;
				}
				num6 = _elements.Count;
				int num7 = num + num5;
				for (int k = num5; k < num6; k++)
				{
					Control control3 = _elements[k];
					if (control3 != null)
					{
						updateElementIndex(control3, num7 + count, num7);
					}
					num7++;
				}
			}
		}

		/// <summary>
		/// Updates the elements in response to items being replaced in the source collection.
		/// </summary>
		/// <param name="index">The index in the source collection of the remove.</param>
		/// <param name="count">The number of items removed.</param>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void ItemsReplaced(int index, int count, Action<Control> recycleElement)
		{
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			if (_elements == null || _elements.Count == 0)
			{
				return;
			}
			int num = index - FirstIndex;
			int num2 = Math.Min(num + count, Count);
			if (num < 0 || num2 <= num)
			{
				return;
			}
			for (int i = num; i < num2; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					recycleElement(control);
					_elements[i] = null;
					_sizes[i] = double.NaN;
				}
			}
		}

		/// <summary>
		/// Recycles all elements in response to the source collection being reset.
		/// </summary>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void ItemsReset(Action<Control> recycleElement)
		{
			if (_elements == null || _elements.Count == 0)
			{
				return;
			}
			for (int i = 0; i < _elements.Count; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					_elements[i] = null;
					recycleElement(control);
				}
			}
			_startU = (_firstIndex = 0);
			_elements?.Clear();
			_sizes?.Clear();
		}

		/// <summary>
		/// Recycles elements before a specific index.
		/// </summary>
		/// <param name="index">The index in the source collection of new first element.</param>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void RecycleElementsBefore(int index, Action<Control, int> recycleElement)
		{
			if (index <= FirstIndex || _elements == null || _elements.Count == 0)
			{
				return;
			}
			if (index > LastIndex)
			{
				RecycleAllElements(recycleElement);
				return;
			}
			int num = index - FirstIndex;
			for (int i = 0; i < num; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					_elements[i] = null;
					recycleElement(control, i + FirstIndex);
				}
			}
			_elements.RemoveRange(0, num);
			_sizes.RemoveRange(0, num);
			_firstIndex = index;
		}

		/// <summary>
		/// Recycles elements after a specific index.
		/// </summary>
		/// <param name="index">The index in the source collection of new last element.</param>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void RecycleElementsAfter(int index, Action<Control, int> recycleElement)
		{
			if (index >= LastIndex || _elements == null || _elements.Count == 0)
			{
				return;
			}
			if (index < FirstIndex)
			{
				RecycleAllElements(recycleElement);
				return;
			}
			int num = index + 1 - FirstIndex;
			int count = _elements.Count;
			for (int i = num; i < count; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					_elements[i] = null;
					recycleElement(control, i + FirstIndex);
				}
			}
			_elements.RemoveRange(num, _elements.Count - num);
			_sizes.RemoveRange(num, _sizes.Count - num);
		}

		/// <summary>
		/// Recycles all realized elements.
		/// </summary>
		/// <param name="recycleElement">A method used to recycle elements.</param>
		public void RecycleAllElements(Action<Control, int> recycleElement)
		{
			if (_elements == null || _elements.Count == 0)
			{
				return;
			}
			for (int i = 0; i < _elements.Count; i++)
			{
				Control control = _elements[i];
				if (control != null)
				{
					_elements[i] = null;
					recycleElement(control, i + FirstIndex);
				}
			}
			_startU = (_firstIndex = 0);
			_elements?.Clear();
			_sizes?.Clear();
		}

		/// <summary>
		/// Resets the element list and prepares it for reuse.
		/// </summary>
		public void ResetForReuse()
		{
			_startU = (_firstIndex = 0);
			_startUUnstable = false;
			_elements?.Clear();
			_sizes?.Clear();
		}

		/// <summary>
		/// Validates that <see cref="P:Avalonia.Controls.Utils.RealizedStackElements.StartU" /> is still valid.
		/// </summary>
		/// <param name="orientation">The panel orientation.</param>
		/// <remarks>
		/// If the U size of any element in the realized elements has changed, then the value of
		/// <see cref="P:Avalonia.Controls.Utils.RealizedStackElements.StartU" /> should be considered unstable.
		/// </remarks>
		public void ValidateStartU(Orientation orientation)
		{
			if (_elements == null || _sizes == null || _startUUnstable)
			{
				return;
			}
			for (int i = 0; i < _elements.Count; i++)
			{
				Control control = _elements[i];
				if (control != null && ((orientation == Orientation.Horizontal) ? control.DesiredSize.Width : control.DesiredSize.Height) != _sizes[i])
				{
					_startUUnstable = true;
					break;
				}
			}
		}
	}
	/// <summary>
	/// Represents the selection adapter contained in the drop-down portion of
	/// an <see cref="T:Avalonia.Controls.AutoCompleteBox" /> control.
	/// </summary>
	public class SelectingItemsControlSelectionAdapter : ISelectionAdapter
	{
		/// <summary>
		/// The SelectingItemsControl instance.
		/// </summary>
		private SelectingItemsControl? _selector;

		/// <summary>
		/// Gets or sets a value indicating whether the selection change event 
		/// should not be fired.
		/// </summary>
		private bool IgnoringSelectionChanged { get; set; }

		/// <summary>
		/// Gets or sets the underlying
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.
		/// </summary>
		/// <value>The underlying
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.</value>
		public SelectingItemsControl? SelectorControl
		{
			get
			{
				return _selector;
			}
			set
			{
				if (_selector != null)
				{
					_selector.SelectionChanged -= OnSelectionChanged;
					_selector.PointerReleased -= OnSelectorPointerReleased;
				}
				_selector = value;
				if (_selector != null)
				{
					_selector.SelectionChanged += OnSelectionChanged;
					_selector.PointerReleased += OnSelectorPointerReleased;
				}
			}
		}

		/// <summary>
		/// Gets or sets the selected item of the selection adapter.
		/// </summary>
		/// <value>The selected item of the underlying selection adapter.</value>
		public object? SelectedItem
		{
			get
			{
				return SelectorControl?.SelectedItem;
			}
			set
			{
				IgnoringSelectionChanged = true;
				if (SelectorControl != null)
				{
					SelectorControl.SelectedItem = value;
				}
				if (value == null)
				{
					ResetScrollViewer();
				}
				IgnoringSelectionChanged = false;
			}
		}

		/// <summary>
		/// Gets or sets a collection that is used to generate the content of
		/// the selection adapter.
		/// </summary>
		/// <value>The collection used to generate content for the selection
		/// adapter.</value>
		public IEnumerable? ItemsSource
		{
			get
			{
				return SelectorControl?.ItemsSource;
			}
			set
			{
				if (SelectorControl != null)
				{
					SelectorControl.ItemsSource = value;
				}
			}
		}

		/// <summary>
		/// Occurs when the
		/// <see cref="P:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapter.SelectedItem" />
		/// property value changes.
		/// </summary>
		public event EventHandler<SelectionChangedEventArgs>? SelectionChanged;

		/// <summary>
		/// Occurs when an item is selected and is committed to the underlying
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Commit;

		/// <summary>
		/// Occurs when a selection is canceled before it is committed.
		/// </summary>
		public event EventHandler<RoutedEventArgs>? Cancel;

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapter" />
		/// class.
		/// </summary>
		public SelectingItemsControlSelectionAdapter()
		{
		}

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapterr" />
		/// class with the specified
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.
		/// </summary>
		/// <param name="selector">The
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" /> control
		/// to wrap as a
		/// <see cref="T:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapter" />.</param>
		public SelectingItemsControlSelectionAdapter(SelectingItemsControl selector)
		{
			SelectorControl = selector;
		}

		/// <summary>
		/// If the control contains a ScrollViewer, this will reset the viewer 
		/// to be scrolled to the top.
		/// </summary>
		private void ResetScrollViewer()
		{
			if (SelectorControl != null)
			{
				ScrollViewer scrollViewer = SelectorControl.GetLogicalDescendants().OfType<ScrollViewer>().FirstOrDefault();
				if (scrollViewer != null)
				{
					scrollViewer.Offset = new Vector(0.0, 0.0);
				}
			}
		}

		/// <summary>
		/// Handles the mouse left button up event on the selector control.
		/// </summary>
		/// <param name="sender">The source object.</param>
		/// <param name="e">The event data.</param>
		private void OnSelectorPointerReleased(object? sender, PointerReleasedEventArgs e)
		{
			if (e.InitialPressMouseButton == MouseButton.Left)
			{
				OnCommit();
			}
		}

		/// <summary>
		/// Handles the SelectionChanged event on the SelectingItemsControl control.
		/// </summary>
		/// <param name="sender">The source object.</param>
		/// <param name="e">The selection changed event data.</param>
		private void OnSelectionChanged(object? sender, SelectionChangedEventArgs e)
		{
			if (!IgnoringSelectionChanged)
			{
				this.SelectionChanged?.Invoke(sender, e);
			}
		}

		/// <summary>
		/// Increments the
		/// <see cref="P:Avalonia.Controls.Primitives.SelectingItemsControl.SelectedIndex" />
		/// property of the underlying
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.
		/// </summary>
		protected void SelectedIndexIncrement()
		{
			if (SelectorControl != null)
			{
				SelectorControl.SelectedIndex = ((SelectorControl.SelectedIndex + 1 >= SelectorControl.ItemCount) ? (-1) : (SelectorControl.SelectedIndex + 1));
			}
		}

		/// <summary>
		/// Decrements the
		/// <see cref="P:Avalonia.Controls.Primitives.SelectingItemsControl.SelectedIndex" />
		/// property of the underlying
		/// <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />
		/// control.
		/// </summary>
		protected void SelectedIndexDecrement()
		{
			if (SelectorControl != null)
			{
				int selectedIndex = SelectorControl.SelectedIndex;
				if (selectedIndex >= 0)
				{
					SelectorControl.SelectedIndex--;
				}
				else if (selectedIndex == -1)
				{
					SelectorControl.SelectedIndex = SelectorControl.ItemCount - 1;
				}
			}
		}

		/// <summary>
		/// Provides handling for the
		/// <see cref="E:Avalonia.Input.InputElement.KeyDown" /> event that occurs
		/// when a key is pressed while the drop-down portion of the
		/// <see cref="T:Avalonia.Controls.AutoCompleteBox" /> has focus.
		/// </summary>
		/// <param name="e">A <see cref="T:Avalonia.Input.KeyEventArgs" />
		/// that contains data about the
		/// <see cref="E:Avalonia.Input.InputElement.KeyDown" /> event.</param>
		public void HandleKeyDown(KeyEventArgs e)
		{
			switch (e.Key)
			{
			case Key.Return:
				OnCommit();
				e.Handled = true;
				break;
			case Key.Up:
				SelectedIndexDecrement();
				e.Handled = true;
				break;
			case Key.Down:
				if ((e.KeyModifiers & KeyModifiers.Alt) == 0)
				{
					SelectedIndexIncrement();
					e.Handled = true;
				}
				break;
			case Key.Escape:
				OnCancel();
				e.Handled = true;
				break;
			}
		}

		/// <summary>
		/// Raises the
		/// <see cref="E:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapter.Commit" />
		/// event.
		/// </summary>
		protected virtual void OnCommit()
		{
			OnCommit(this, new RoutedEventArgs());
		}

		/// <summary>
		/// Fires the Commit event.
		/// </summary>
		/// <param name="sender">The source object.</param>
		/// <param name="e">The event data.</param>
		private void OnCommit(object? sender, RoutedEventArgs e)
		{
			this.Commit?.Invoke(sender, e);
			AfterAdapterAction();
		}

		/// <summary>
		/// Raises the
		/// <see cref="E:Avalonia.Controls.Utils.SelectingItemsControlSelectionAdapter.Cancel" />
		/// event.
		/// </summary>
		protected virtual void OnCancel()
		{
			OnCancel(this, new RoutedEventArgs());
		}

		/// <summary>
		/// Fires the Cancel event.
		/// </summary>
		/// <param name="sender">The source object.</param>
		/// <param name="e">The event data.</param>
		private void OnCancel(object? sender, RoutedEventArgs e)
		{
			this.Cancel?.Invoke(sender, e);
			AfterAdapterAction();
		}

		/// <summary>
		/// Change the selection after the actions are complete.
		/// </summary>
		private void AfterAdapterAction()
		{
			IgnoringSelectionChanged = true;
			if (SelectorControl != null)
			{
				SelectorControl.SelectedItem = null;
				SelectorControl.SelectedIndex = -1;
			}
			IgnoringSelectionChanged = false;
		}
	}
	internal static class StringUtils
	{
		private enum CharClass
		{
			CharClassUnknown,
			CharClassWhitespace,
			CharClassAlphaNumeric
		}

		public static bool IsEol(char c)
		{
			if (c != '\r')
			{
				return c == '\n';
			}
			return true;
		}

		public static bool IsStartOfWord(string text, int index)
		{
			if (index >= text.Length)
			{
				return false;
			}
			Codepoint codepoint = new Codepoint(text[index]);
			if (index > 0)
			{
				Codepoint codepoint2 = new Codepoint(text[index - 1]);
				if (!codepoint2.IsWhiteSpace)
				{
					return false;
				}
				if (codepoint2.IsBreakChar)
				{
					return true;
				}
			}
			switch (codepoint.GeneralCategory)
			{
			case GeneralCategory.LowercaseLetter:
			case GeneralCategory.TitlecaseLetter:
			case GeneralCategory.UppercaseLetter:
			case GeneralCategory.DecimalNumber:
			case GeneralCategory.LetterNumber:
			case GeneralCategory.OtherNumber:
			case GeneralCategory.DashPunctuation:
			case GeneralCategory.InitialPunctuation:
			case GeneralCategory.OpenPunctuation:
			case GeneralCategory.CurrencySymbol:
			case GeneralCategory.MathSymbol:
				return true;
			default:
				return false;
			}
		}

		public static bool IsEndOfWord(string text, int index)
		{
			if (index >= text.Length)
			{
				return true;
			}
			Codepoint codepoint = new Codepoint(text[index]);
			if (!codepoint.IsWhiteSpace)
			{
				return false;
			}
			if (index > 0)
			{
				if (index + 1 >= text.Length)
				{
					return true;
				}
				if (new Codepoint(text[index + 1]).IsBreakChar)
				{
					return true;
				}
			}
			switch (codepoint.GeneralCategory)
			{
			case GeneralCategory.LowercaseLetter:
			case GeneralCategory.TitlecaseLetter:
			case GeneralCategory.UppercaseLetter:
			case GeneralCategory.DecimalNumber:
			case GeneralCategory.LetterNumber:
			case GeneralCategory.OtherNumber:
			case GeneralCategory.DashPunctuation:
			case GeneralCategory.InitialPunctuation:
			case GeneralCategory.OpenPunctuation:
			case GeneralCategory.CurrencySymbol:
			case GeneralCategory.MathSymbol:
				return false;
			default:
				return true;
			}
		}

		public static int PreviousWord(string text, int cursor)
		{
			if (string.IsNullOrEmpty(text))
			{
				return 0;
			}
			cursor = Math.Min(cursor, text.Length);
			int num = LineBegin(text, cursor) - 1;
			int num2 = ((num <= 0 || text[num] != '\n' || text[num - 1] != '\r') ? num : (num - 1));
			if (cursor - 1 == num)
			{
				if (num2 <= 0)
				{
					return 0;
				}
				return num2;
			}
			CharClass charClass = GetCharClass(text[cursor - 1]);
			int num3 = num + 1;
			int num4 = cursor;
			while (num4 > num3 && GetCharClass(text[num4 - 1]) == charClass)
			{
				num4--;
			}
			if (charClass == CharClass.CharClassWhitespace && num4 > num3)
			{
				charClass = GetCharClass(text[num4 - 1]);
				while (num4 > num3 && GetCharClass(text[num4 - 1]) == charClass)
				{
					num4--;
				}
			}
			return num4;
		}

		public static int NextWord(string text, int cursor)
		{
			int num = LineEnd(text, cursor);
			if (cursor >= text.Length)
			{
				return cursor;
			}
			int num2 = ((num >= text.Length || text[num] != '\r' || num + 1 >= text.Length || text[num + 1] != '\n') ? num : (num + 1));
			if (cursor == num || cursor == num2)
			{
				if (num2 < text.Length)
				{
					return num2 + 1;
				}
				return cursor;
			}
			int i;
			for (i = cursor; i < num && char.IsWhiteSpace(text[i]); i++)
			{
			}
			if (i >= num)
			{
				return i;
			}
			for (CharClass charClass = GetCharClass(text[i]); i < num && GetCharClass(text[i]) == charClass; i++)
			{
			}
			return i;
		}

		private static CharClass GetCharClass(char c)
		{
			if (char.IsWhiteSpace(c))
			{
				return CharClass.CharClassWhitespace;
			}
			if (char.IsLetterOrDigit(c))
			{
				return CharClass.CharClassAlphaNumeric;
			}
			return CharClass.CharClassUnknown;
		}

		private static int LineBegin(string text, int pos)
		{
			while (pos > 0 && !IsEol(text[pos - 1]))
			{
				pos--;
			}
			return pos;
		}

		private static int LineEnd(string text, int cursor, bool include = false)
		{
			while (cursor < text.Length && !IsEol(text[cursor]))
			{
				cursor++;
			}
			if (include && cursor < text.Length)
			{
				cursor = ((text[cursor] != '\r' || text[cursor + 1] != '\n') ? (cursor + 1) : (cursor + 2));
			}
			return cursor;
		}
	}
	internal static class TimeUtils
	{
		public static string GetPMDesignator()
		{
			if (string.IsNullOrEmpty(CultureInfo.CurrentCulture.DateTimeFormat.PMDesignator))
			{
				return CultureInfo.InvariantCulture.DateTimeFormat.PMDesignator;
			}
			return CultureInfo.CurrentCulture.DateTimeFormat.PMDesignator;
		}

		public static string GetAMDesignator()
		{
			if (string.IsNullOrEmpty(CultureInfo.CurrentCulture.DateTimeFormat.AMDesignator))
			{
				return CultureInfo.InvariantCulture.DateTimeFormat.AMDesignator;
			}
			return CultureInfo.CurrentCulture.DateTimeFormat.AMDesignator;
		}
	}
	internal class UndoRedoHelper<TState>
	{
		public interface IUndoRedoHost
		{
			TState UndoRedoState { get; set; }

			void OnUndoStackChanged();

			void OnRedoStackChanged();
		}

		public const int DefaultUndoLimit = 10;

		private readonly IUndoRedoHost _host;

		private readonly LinkedList<TState> _states = new LinkedList<TState>();

		private LinkedListNode<TState>? _currentNode;

		/// <summary>
		/// Maximum number of states this helper can store for undo/redo.
		/// If -1, no limit is imposed.
		/// </summary>
		public int Limit { get; set; } = 10;

		public bool CanUndo => _currentNode?.Previous != null;

		public bool CanRedo => _currentNode?.Next != null;

		public bool IsLastState
		{
			get
			{
				if (_currentNode != null)
				{
					return _currentNode.Next == null;
				}
				return false;
			}
		}

		public bool HasState => _currentNode != null;

		public UndoRedoHelper(IUndoRedoHost host)
		{
			_host = host;
		}

		public void Undo()
		{
			if (_currentNode?.Previous != null)
			{
				_currentNode = _currentNode.Previous;
				_host.UndoRedoState = _currentNode.Value;
				_host.OnUndoStackChanged();
				_host.OnRedoStackChanged();
			}
		}

		public bool TryGetLastState(out TState? _state)
		{
			_state = default(TState);
			if (!IsLastState)
			{
				return false;
			}
			_state = _currentNode.Value;
			return true;
		}

		public void UpdateLastState(TState state)
		{
			if (_states.Last != null)
			{
				_states.Last.Value = state;
			}
		}

		public void UpdateLastState()
		{
			UpdateLastState(_host.UndoRedoState);
		}

		public void DiscardRedo()
		{
			while (_currentNode?.Next != null)
			{
				_states.Remove(_currentNode.Next);
			}
			_host.OnRedoStackChanged();
		}

		public void Redo()
		{
			if (_currentNode?.Next != null)
			{
				_currentNode = _currentNode.Next;
				_host.UndoRedoState = _currentNode.Value;
				_host.OnRedoStackChanged();
				_host.OnUndoStackChanged();
			}
		}

		public void Snapshot()
		{
			TState undoRedoState = _host.UndoRedoState;
			if (_currentNode == null || !_currentNode.Value.Equals(undoRedoState))
			{
				if (_currentNode?.Next != null)
				{
					DiscardRedo();
				}
				_states.AddLast(undoRedoState);
				_currentNode = _states.Last;
				if (Limit != -1 && _states.Count > Limit)
				{
					_states.RemoveFirst();
				}
				_host.OnUndoStackChanged();
				_host.OnRedoStackChanged();
			}
		}

		public void Clear()
		{
			_states.Clear();
			_currentNode = null;
			_host.OnUndoStackChanged();
			_host.OnRedoStackChanged();
		}
	}
	internal class VirtualizingSnapPointsList : IReadOnlyList<double>, IEnumerable<double>, IEnumerable, IReadOnlyCollection<double>
	{
		private const int ExtraCount = 2;

		private readonly RealizedStackElements _realizedElements;

		private readonly Orientation _orientation;

		private readonly Orientation _parentOrientation;

		private readonly SnapPointsAlignment _snapPointsAlignment;

		private readonly double _size;

		private readonly int _start = -1;

		private readonly int _end;

		public double this[int index]
		{
			get
			{
				if (index < 0 || index >= Count)
				{
					throw new ArgumentOutOfRangeException("index");
				}
				index += _start;
				double num = 0.0;
				double size = _size;
				switch (_orientation)
				{
				case Orientation.Horizontal:
				{
					Control element = _realizedElements.GetElement(index);
					if (element != null)
					{
						switch (_snapPointsAlignment)
						{
						case SnapPointsAlignment.Near:
							num = element.Bounds.Left;
							break;
						case SnapPointsAlignment.Center:
							num = element.Bounds.Center.X;
							break;
						case SnapPointsAlignment.Far:
							num = element.Bounds.Right;
							break;
						}
						break;
					}
					int num3 = index;
					if (index > _realizedElements.LastIndex)
					{
						num3 -= _realizedElements.LastIndex + 1;
					}
					num = (double)num3 * size;
					switch (_snapPointsAlignment)
					{
					case SnapPointsAlignment.Center:
						num += size / 2.0;
						break;
					case SnapPointsAlignment.Far:
						num += size;
						break;
					}
					if (index > _realizedElements.LastIndex)
					{
						Control element3 = _realizedElements.GetElement(_realizedElements.LastIndex);
						if (element3 != null)
						{
							num += element3.Bounds.Right;
						}
					}
					break;
				}
				case Orientation.Vertical:
				{
					Control element = _realizedElements.GetElement(index);
					if (element != null)
					{
						switch (_snapPointsAlignment)
						{
						case SnapPointsAlignment.Near:
							num = element.Bounds.Top;
							break;
						case SnapPointsAlignment.Center:
							num = element.Bounds.Center.Y;
							break;
						case SnapPointsAlignment.Far:
							num = element.Bounds.Bottom;
							break;
						}
						break;
					}
					int num2 = index;
					if (index > _realizedElements.LastIndex)
					{
						num2 -= _realizedElements.LastIndex + 1;
					}
					num = (double)num2 * size;
					switch (_snapPointsAlignment)
					{
					case SnapPointsAlignment.Center:
						num += size / 2.0;
						break;
					case SnapPointsAlignment.Far:
						num += size;
						break;
					}
					if (index > _realizedElements.LastIndex)
					{
						Control element2 = _realizedElements.GetElement(_realizedElements.LastIndex);
						if (element2 != null)
						{
							num += element2.Bounds.Bottom;
						}
					}
					break;
				}
				}
				return num;
			}
		}

		public int Count
		{
			get
			{
				if (_parentOrientation == _orientation)
				{
					return _end - _start + 1;
				}
				return 0;
			}
		}

		public VirtualizingSnapPointsList(RealizedStackElements realizedElements, int count, Orientation orientation, Orientation parentOrientation, SnapPointsAlignment snapPointsAlignment, double size)
		{
			_realizedElements = realizedElements;
			_orientation = orientation;
			_parentOrientation = parentOrientation;
			_snapPointsAlignment = snapPointsAlignment;
			_size = size;
			if (parentOrientation == orientation)
			{
				_start = Math.Max(0, _realizedElements.FirstIndex - 2);
				_end = Math.Min(count - 1, _realizedElements.LastIndex + 2);
			}
		}

		public IEnumerator<double> GetEnumerator()
		{
			for (int i = 0; i < Count; i++)
			{
				yield return this[i];
			}
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
}
namespace Avalonia.Controls.Templates
{
	/// <summary>
	/// Defines extension methods for working with <see cref="T:Avalonia.Controls.Templates.IDataTemplate" />s.
	/// </summary>
	public static class DataTemplateExtensions
	{
		/// <summary>
		/// Find a data template that matches a piece of data.
		/// </summary>
		/// <param name="control">The control searching for the data template.</param>
		/// <param name="data">The data.</param>
		/// <param name="primary">
		/// An optional primary template that can will be tried before the DataTemplates in the
		/// tree are searched.
		/// </param>
		/// <returns>The data template or null if no matching data template was found.</returns>
		public static IDataTemplate? FindDataTemplate(this Control control, object? data, IDataTemplate? primary = null)
		{
			if (primary != null && primary.Match(data))
			{
				return primary;
			}
			for (ILogical logical = control; logical != null; logical = logical.LogicalParent)
			{
				if (logical is IDataTemplateHost { IsDataTemplatesInitialized: not false } dataTemplateHost)
				{
					foreach (IDataTemplate dataTemplate in dataTemplateHost.DataTemplates)
					{
						if (dataTemplate.Match(data))
						{
							return dataTemplate;
						}
					}
				}
			}
			IGlobalDataTemplates service = AvaloniaLocator.Current.GetService<IGlobalDataTemplates>();
			if (service != null && service.IsDataTemplatesInitialized)
			{
				foreach (IDataTemplate dataTemplate2 in service.DataTemplates)
				{
					if (dataTemplate2.Match(data))
					{
						return dataTemplate2;
					}
				}
			}
			return null;
		}
	}
	/// <summary>
	/// A collection of <see cref="T:Avalonia.Controls.Templates.IDataTemplate" />s.
