	/// </summary>
	public abstract class Shape : Control
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.Fill" /> property.
		/// </summary>
		public static readonly StyledProperty<IBrush?> FillProperty = AvaloniaProperty.Register<Shape, IBrush>("Fill");

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.Stretch" /> property.
		/// </summary>
		public static readonly StyledProperty<Stretch> StretchProperty = AvaloniaProperty.Register<Shape, Stretch>("Stretch", Stretch.None);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.Stroke" /> property.
		/// </summary>
		public static readonly StyledProperty<IBrush?> StrokeProperty = AvaloniaProperty.Register<Shape, IBrush>("Stroke");

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeDashArray" /> property.
		/// </summary>
		public static readonly StyledProperty<AvaloniaList<double>?> StrokeDashArrayProperty = AvaloniaProperty.Register<Shape, AvaloniaList<double>>("StrokeDashArray");

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeDashOffset" /> property.
		/// </summary>
		public static readonly StyledProperty<double> StrokeDashOffsetProperty = AvaloniaProperty.Register<Shape, double>("StrokeDashOffset", 0.0);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeThickness" /> property.
		/// </summary>
		public static readonly StyledProperty<double> StrokeThicknessProperty = AvaloniaProperty.Register<Shape, double>("StrokeThickness", 0.0);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeLineCap" /> property.
		/// </summary>
		public static readonly StyledProperty<PenLineCap> StrokeLineCapProperty = AvaloniaProperty.Register<Shape, PenLineCap>("StrokeLineCap", PenLineCap.Flat);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeJoin" /> property.
		/// </summary>
		public static readonly StyledProperty<PenLineJoin> StrokeJoinProperty = AvaloniaProperty.Register<Shape, PenLineJoin>("StrokeJoin", PenLineJoin.Miter);

		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeMiterLimit" /> property.
		/// </summary>
		public static readonly StyledProperty<double> StrokeMiterLimitProperty = AvaloniaProperty.Register<Shape, double>("StrokeMiterLimit", 10.0);

		private Matrix _transform = Matrix.Identity;

		private Geometry? _definingGeometry;

		private Geometry? _renderedGeometry;

		private IPen? _strokePen;

		private EventHandler? _geometryChangedHandler;

		/// <summary>
		/// Gets a value that represents the <see cref="T:Avalonia.Media.Geometry" /> of the shape.
		/// </summary>
		public Geometry? DefiningGeometry
		{
			get
			{
				if (_definingGeometry == null)
				{
					_definingGeometry = CreateDefiningGeometry();
					if (_definingGeometry != null && base.VisualRoot != null)
					{
						_definingGeometry.Changed += GeometryChangedHandler;
					}
				}
				return _definingGeometry;
			}
		}

		/// <summary>
		/// Gets a value that represents the final rendered <see cref="T:Avalonia.Media.Geometry" /> of the shape.
		/// </summary>
		public Geometry? RenderedGeometry
		{
			get
			{
				if (_renderedGeometry == null && DefiningGeometry != null)
				{
					if (_transform == Matrix.Identity)
					{
						_renderedGeometry = DefiningGeometry;
					}
					else
					{
						_renderedGeometry = DefiningGeometry.Clone();
						if (_renderedGeometry.Transform == null || _renderedGeometry.Transform.Value == Matrix.Identity)
						{
							_renderedGeometry.Transform = new MatrixTransform(_transform);
						}
						else
						{
							_renderedGeometry.Transform = new MatrixTransform(_renderedGeometry.Transform.Value * _transform);
						}
					}
				}
				return _renderedGeometry;
			}
		}

		/// <summary>
		/// Gets or sets the <see cref="T:Avalonia.Media.IBrush" /> that specifies how the shape's interior is painted.
