			{
				SetValue(StrokeJoinProperty, value);
			}
		}

		/// <summary>
		/// Gets or sets the limit on the ratio of the miter length to half the <see cref="P:Avalonia.Controls.Shapes.Shape.StrokeThickness" /> of the pen.
		/// </summary>
		public double StrokeMiterLimit
		{
			get
			{
				return GetValue(StrokeMiterLimitProperty);
			}
			set
			{
				SetValue(StrokeMiterLimitProperty, value);
			}
		}

		private EventHandler GeometryChangedHandler => _geometryChangedHandler ?? (_geometryChangedHandler = OnGeometryChanged);

		public sealed override void Render(DrawingContext context)
		{
			Geometry renderedGeometry = RenderedGeometry;
			if (renderedGeometry != null)
			{
				context.DrawGeometry(Fill, _strokePen, renderedGeometry);
			}
		}

		/// <summary>
		/// Marks a property as affecting the shape's geometry.
		/// </summary>
		/// <param name="properties">The properties.</param>
		/// <remarks>
		/// After a call to this method in a control's static constructor, any change to the
		/// property will cause <see cref="M:Avalonia.Controls.Shapes.Shape.InvalidateGeometry" /> to be called on the element.
		/// </remarks>
		protected static void AffectsGeometry<TShape>(params AvaloniaProperty[] properties) where TShape : Shape
		{
			for (int i = 0; i < properties.Length; i++)
			{
				properties[i].Changed.Subscribe(delegate(AvaloniaPropertyChangedEventArgs e)
				{
					if (e.Sender is TShape control)
					{
						AffectsGeometryInvalidate(control, e);
					}
				});
			}
		}

		/// <summary>
		/// Creates the shape's defining geometry.
		/// </summary>
		/// <returns>Defining <see cref="T:Avalonia.Media.Geometry" /> of the shape.</returns>
		protected abstract Geometry? CreateDefiningGeometry();

		/// <summary>
		/// Called when the underlying <see cref="T:Avalonia.Media.Geometry" /> changed
		/// </summary>
		/// <param name="sender"></param>
		/// <param name="e"></param>
		protected virtual void OnGeometryChanged(object? sender, EventArgs e)
		{
			_renderedGeometry = null;
			InvalidateMeasure();
		}

		/// <summary>
		/// Invalidates the geometry of this shape.
		/// </summary>
		protected void InvalidateGeometry()
		{
			if (_definingGeometry != null)
			{
				_definingGeometry.Changed -= GeometryChangedHandler;
			}
			_renderedGeometry = null;
			_definingGeometry = null;
			InvalidateMeasure();
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == StrokeProperty || change.Property == StrokeThicknessProperty || change.Property == StrokeDashArrayProperty || change.Property == StrokeDashOffsetProperty || change.Property == StrokeLineCapProperty || change.Property == StrokeJoinProperty || change.Property == StrokeMiterLimitProperty)
			{
				if (change.Property == StrokeProperty || change.Property == StrokeThicknessProperty)
				{
					InvalidateMeasure();
				}
				if (Pen.TryModifyOrCreate(ref _strokePen, Stroke, StrokeThickness, StrokeDashArray, StrokeDashOffset, StrokeLineCap, StrokeJoin, StrokeMiterLimit))
				{
					InvalidateVisual();
				}
			}
			else if (change.Property == FillProperty)
			{
				InvalidateVisual();
			}
		}

		protected override Size MeasureOverride(Size availableSize)
		{
			if (DefiningGeometry == null)
			{
				return default(Size);
			}
			return CalculateSizeAndTransform(availableSize, DefiningGeometry.Bounds, Stretch).size;
		}

		protected override Size ArrangeOverride(Size finalSize)
		{
			if (DefiningGeometry != null)
			{
				Matrix item = CalculateSizeAndTransform(finalSize, DefiningGeometry.Bounds, Stretch).transform;
				if (_transform != item)
				{
					_transform = item;
					_renderedGeometry = null;
				}
				return finalSize;
			}
			return default(Size);
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			if (_definingGeometry != null)
			{
				_definingGeometry.Changed += GeometryChangedHandler;
			}
		}

		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			if (_definingGeometry != null)
			{
				_definingGeometry.Changed -= GeometryChangedHandler;
			}
		}

		internal static (Size size, Matrix transform) CalculateSizeAndTransform(Size availableSize, Rect shapeBounds, Stretch Stretch)
		{
			Size size = new Size(shapeBounds.Right, shapeBounds.Bottom);
			Matrix matrix = Matrix.Identity;
			double width = availableSize.Width;
			double height = availableSize.Height;
			double num = 0.0;
			double num2 = 0.0;
			if (Stretch != Stretch.None)
			{
				size = shapeBounds.Size;
				matrix = Matrix.CreateTranslation(-(Vector)shapeBounds.Position);
			}
			if (double.IsInfinity(availableSize.Width))
			{
				width = size.Width;
			}
			if (double.IsInfinity(availableSize.Height))
			{
				height = size.Height;
			}
			if (shapeBounds.Width > 0.0)
			{
				num = width / size.Width;
			}
			if (shapeBounds.Height > 0.0)
			{
				num2 = height / size.Height;
			}
			if (double.IsInfinity(availableSize.Width))
			{
				num = num2;
			}
			if (double.IsInfinity(availableSize.Height))
			{
				num2 = num;
			}
			switch (Stretch)
			{
			case Stretch.Uniform:
				num = (num2 = Math.Min(num, num2));
				break;
			case Stretch.UniformToFill:
				num = (num2 = Math.Max(num, num2));
				break;
			case Stretch.Fill:
				if (double.IsInfinity(availableSize.Width))
				{
					num = 1.0;
				}
				if (double.IsInfinity(availableSize.Height))
				{
					num2 = 1.0;
				}
				break;
			default:
				num = (num2 = 1.0);
				break;
			}
			Matrix item = matrix * Matrix.CreateScale(num, num2);
			return (size: new Size(size.Width * num, size.Height * num2), transform: item);
		}

		private static void AffectsGeometryInvalidate(Shape control, AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Property == Visual.BoundsProperty)
			{
				Rect rect = (Rect)e.OldValue;
				Rect rect2 = (Rect)e.NewValue;
				if (rect.Size == rect2.Size)
				{
					return;
				}
			}
			control.InvalidateGeometry();
		}
	}
}
namespace Avalonia.Controls.Selection
{
	internal readonly struct IndexRange : IEquatable<IndexRange>
	{
		private static readonly IndexRange s_invalid = new IndexRange(int.MinValue, int.MinValue);

		public int Begin { get; }

		public int End { get; }

		public int Count => End - Begin + 1;

		public IndexRange(int index)
		{
			Begin = index;
			End = index;
		}

		public IndexRange(int begin, int end)
