	/// <summary>
	/// Presents items inside an <see cref="T:Avalonia.Controls.ItemsControl" />.
	/// </summary>
	public class ItemsPresenter : Control, ILogicalScrollable, IScrollable
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Presenters.ItemsPresenter.ItemsPanel" /> property.
		/// </summary>
		public static readonly StyledProperty<ITemplate<Panel?>> ItemsPanelProperty = Avalonia.Controls.ItemsControl.ItemsPanelProperty.AddOwner<ItemsPresenter>();

		private PanelContainerGenerator? _generator;

		private ILogicalScrollable? _logicalScrollable;

		private EventHandler? _scrollInvalidated;

		/// <summary>
		/// Gets or sets a template which creates the <see cref="P:Avalonia.Controls.Presenters.ItemsPresenter.Panel" /> used to display the items.
		/// </summary>
		public ITemplate<Panel?> ItemsPanel
		{
			get
			{
				return GetValue(ItemsPanelProperty);
			}
			set
			{
				SetValue(ItemsPanelProperty, value);
			}
		}

		/// <summary>
		/// Gets the panel used to display the items.
		/// </summary>
		public Panel? Panel { get; private set; }

		/// <summary>
		/// Gets the owner <see cref="P:Avalonia.Controls.Presenters.ItemsPresenter.ItemsControl" />.
		/// </summary>
		internal ItemsControl? ItemsControl { get; private set; }

		bool ILogicalScrollable.CanHorizontallyScroll
		{
			get
			{
				return _logicalScrollable?.CanHorizontallyScroll ?? false;
			}
			set
			{
				if (_logicalScrollable != null)
				{
					_logicalScrollable.CanHorizontallyScroll = value;
				}
			}
		}

		bool ILogicalScrollable.CanVerticallyScroll
		{
			get
			{
				return _logicalScrollable?.CanVerticallyScroll ?? false;
			}
			set
			{
				if (_logicalScrollable != null)
				{
					_logicalScrollable.CanVerticallyScroll = value;
				}
			}
		}

		Vector IScrollable.Offset
		{
			get
			{
				return _logicalScrollable?.Offset ?? default(Vector);
			}
			set
			{
				if (_logicalScrollable != null)
				{
					_logicalScrollable.Offset = value;
				}
			}
		}

		bool ILogicalScrollable.IsLogicalScrollEnabled => _logicalScrollable?.IsLogicalScrollEnabled ?? false;

		Size ILogicalScrollable.ScrollSize => _logicalScrollable?.ScrollSize ?? default(Size);

		Size ILogicalScrollable.PageScrollSize => _logicalScrollable?.PageScrollSize ?? default(Size);

		Size IScrollable.Extent => _logicalScrollable?.Extent ?? default(Size);

		Size IScrollable.Viewport => _logicalScrollable?.Viewport ?? default(Size);

		event EventHandler? ILogicalScrollable.ScrollInvalidated
		{
			add
			{
				_scrollInvalidated = (EventHandler)Delegate.Combine(_scrollInvalidated, value);
			}
			remove
			{
				_scrollInvalidated = (EventHandler)Delegate.Remove(_scrollInvalidated, value);
			}
		}

		public sealed override void ApplyTemplate()
		{
			if (Panel != null || ItemsControl == null)
			{
				return;
			}
			if (_logicalScrollable != null)
			{
				_logicalScrollable.ScrollInvalidated -= OnLogicalScrollInvalidated;
			}
			Panel = ItemsPanel.Build();
			if (Panel != null)
			{
				Panel.TemplatedParent = base.TemplatedParent;
				Panel.IsItemsHost = true;
				base.LogicalChildren.Add(Panel);
				base.VisualChildren.Add(Panel);
				if (Panel is VirtualizingPanel virtualizingPanel)
				{
					virtualizingPanel.Attach(ItemsControl);
				}
				else
				{
					CreateSimplePanelGenerator();
				}
				_logicalScrollable = Panel as ILogicalScrollable;
				if (_logicalScrollable != null)
				{
					_logicalScrollable.ScrollInvalidated += OnLogicalScrollInvalidated;
				}
			}
		}

		bool ILogicalScrollable.BringIntoView(Control target, Rect targetRect)
		{
			return _logicalScrollable?.BringIntoView(target, targetRect) ?? false;
		}

		Control? ILogicalScrollable.GetControlInDirection(NavigationDirection direction, Control? from)
		{
			return _logicalScrollable?.GetControlInDirection(direction, from);
		}

		void ILogicalScrollable.RaiseScrollInvalidated(EventArgs e)
		{
			_scrollInvalidated?.Invoke(this, e);
		}

		internal void ScrollIntoView(int index)
		{
			if (Panel is VirtualizingPanel virtualizingPanel)
			{
				virtualizingPanel.ScrollIntoView(index);
			}
			else if (index >= 0 && index < Panel?.Children.Count)
			{
				Panel.Children[index].BringIntoView();
			}
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property == StyledElement.TemplatedParentProperty)
			{
				ResetState();
				ItemsControl = null;
				if (change.NewValue is ItemsControl itemsControl)
				{
					ItemsControl = itemsControl;
					ItemsControl.RegisterItemsPresenter(this);
				}
			}
			else if (change.Property == ItemsPanelProperty)
			{
				ResetState();
				InvalidateMeasure();
			}
		}

		internal void Refresh()
		{
			if (Panel is VirtualizingPanel virtualizingPanel)
			{
				virtualizingPanel.Refresh();
			}
			else
			{
				_generator?.Refresh();
			}
		}

		private void ResetState()
		{
			_generator?.Dispose();
			_generator = null;
			base.LogicalChildren.Clear();
			base.VisualChildren.Clear();
			(Panel as VirtualizingPanel)?.Detach();
			Panel = null;
		}

		private void CreateSimplePanelGenerator()
		{
			if (ItemsControl != null && Panel != null)
			{
				_generator?.Dispose();
				_generator = new PanelContainerGenerator(this);
			}
		}

		internal Control? ContainerFromIndex(int index)
		{
			if (Panel is VirtualizingPanel virtualizingPanel)
			{
				return virtualizingPanel.ContainerFromIndex(index);
			}
			if (index < 0 || !(index < Panel?.Children.Count))
			{
				return null;
			}
			return Panel.Children[index];
		}

		internal IEnumerable<Control>? GetRealizedContainers()
		{
			if (Panel is VirtualizingPanel virtualizingPanel)
			{
				return virtualizingPanel.GetRealizedContainers();
			}
			return Panel?.Children;
		}

		internal int IndexFromContainer(Control container)
		{
			if (Panel is VirtualizingPanel virtualizingPanel)
			{
				return virtualizingPanel.IndexFromContainer(container);
			}
			return Panel?.Children.IndexOf(container) ?? (-1);
		}

		private void OnLogicalScrollInvalidated(object? sender, EventArgs e)
		{
			_scrollInvalidated?.Invoke(this, e);
		}
	}
	/// <summary>
	/// Generates containers for <see cref="T:Avalonia.Controls.Presenters.ItemsPresenter" />s that have non-virtualizing panels.
	/// </summary>
	internal class PanelContainerGenerator : IDisposable
	{
		private static readonly AttachedProperty<bool> ItemIsOwnContainerProperty = AvaloniaProperty.RegisterAttached<PanelContainerGenerator, Control, bool>("ItemIsOwnContainer", defaultValue: false);

		private readonly ItemsPresenter _presenter;

		public PanelContainerGenerator(ItemsPresenter presenter)
		{
			_presenter = presenter;
			_presenter.ItemsControl.ItemsView.PostCollectionChanged += OnItemsChanged;
			OnItemsChanged(null, CollectionUtils.ResetEventArgs);
		}

		public void Dispose()
		{
			ItemsControl itemsControl = _presenter.ItemsControl;
			if (itemsControl != null)
			{
				itemsControl.ItemsView.PostCollectionChanged -= OnItemsChanged;
				ClearItemsControlLogicalChildren();
			}
			_presenter.Panel?.Children.Clear();
		}

		internal void Refresh()
		{
			OnItemsChanged(null, CollectionUtils.ResetEventArgs);
		}

		private void OnItemsChanged(object? sender, NotifyCollectionChangedEventArgs e)
		{
			if (_presenter.Panel == null || _presenter.ItemsControl == null)
			{
				return;
			}
			ItemsControl itemsControl = _presenter.ItemsControl;
			ItemContainerGenerator generator = itemsControl.ItemContainerGenerator;
			Controls children = _presenter.Panel.Children;
			switch (e.Action)
			{
			default:
				return;
			case NotifyCollectionChangedAction.Add:
				Add(e.NewStartingIndex, e.NewItems);
				return;
			case NotifyCollectionChangedAction.Remove:
				Remove(e.OldStartingIndex, e.OldItems.Count);
				return;
			case NotifyCollectionChangedAction.Replace:
				if (e.OldStartingIndex >= 0)
				{
					Remove(e.OldStartingIndex, e.OldItems.Count);
					Add(e.NewStartingIndex, e.NewItems);
					return;
				}
				break;
			case NotifyCollectionChangedAction.Move:
				if (e.OldStartingIndex >= 0)
				{
					Remove(e.OldStartingIndex, e.OldItems.Count);
					int num = e.NewStartingIndex;
					if (e.NewStartingIndex > e.OldStartingIndex)
					{
						num -= e.OldItems.Count - 1;
					}
					Add(num, e.NewItems);
					return;
				}
				break;
			case NotifyCollectionChangedAction.Reset:
				break;
			}
			ClearItemsControlLogicalChildren();
			children.Clear();
			Add(0, _presenter.ItemsControl.ItemsView);
			void Add(int index, IEnumerable items)
			{
				int i = index;
				foreach (object item in items)
				{
					InsertContainer(itemsControl, children, item, i++);
				}
				int count = children.Count;
				int num2 = i - index;
				for (; i < count; i++)
				{
					generator.ItemContainerIndexChanged(children[i], i - num2, i);
				}
			}
			void Remove(int index, int count)
			{
				for (int i = 0; i < count; i++)
				{
					Control control = children[index + i];
					itemsControl.RemoveLogicalChild(children[i + index]);
					if (!control.IsSet(ItemIsOwnContainerProperty))
					{
						generator.ClearItemContainer(control);
					}
				}
				children.RemoveRange(index, count);
				int count2 = children.Count;
				for (int j = index; j < count2; j++)
				{
					generator.ItemContainerIndexChanged(children[j], j + count, j);
				}
			}
		}

		private static void InsertContainer(ItemsControl itemsControl, Controls children, object? item, int index)
		{
			ItemContainerGenerator itemContainerGenerator = itemsControl.ItemContainerGenerator;
			Control control;
			if (itemContainerGenerator.NeedsContainer(item, index, out object recycleKey))
			{
				control = itemContainerGenerator.CreateContainer(item, index, recycleKey);
			}
			else
			{
				control = (Control)item;
				control.SetValue(ItemIsOwnContainerProperty, value: true);
			}
			itemContainerGenerator.PrepareItemContainer(control, item, index);
			itemsControl.AddLogicalChild(control);
			children.Insert(index, control);
			itemContainerGenerator.ItemContainerPrepared(control, item, index);
		}

		private void ClearItemsControlLogicalChildren()
		{
			if (_presenter.Panel == null || _presenter.ItemsControl == null)
			{
				return;
			}
			ItemsControl itemsControl = _presenter.ItemsControl;
			ItemContainerGenerator itemContainerGenerator = itemsControl.ItemContainerGenerator;
			foreach (Control child in _presenter.Panel.Children)
			{
				itemsControl.RemoveLogicalChild(child);
				if (!child.IsSet(ItemIsOwnContainerProperty))
				{
					itemContainerGenerator.ClearItemContainer(child);
				}
			}
		}
	}
