				if (color.HasValue)
				{
					byte r = (byte)(~color.Value.R);
					byte g = (byte)(~color.Value.G);
					byte b = (byte)(~color.Value.B);
					immutableBrush = new ImmutableSolidColorBrush(Color.FromRgb(r, g, b));
				}
