			double num = Math.Floor(_caretBounds.X) + 0.5;
			double y = Math.Floor(_caretBounds.Y) + 0.5;
			double y2 = Math.Ceiling(_caretBounds.Bottom) - 0.5;
			if (_caretBounds.X > 0.0 && _caretBounds.X >= textLine.WidthIncludingTrailingWhitespace)
			{
				num -= 1.0;
			}
			return (new Point(num, y), new Point(num, y2));
		}

		public void ShowCaret()
		{
			EnsureCaretTimer();
			EnsureTextSelectionLayer();
			_caretBlink = true;
			_caretTimer?.Start();
			InvalidateVisual();
		}

		public void HideCaret()
		{
			_caretBlink = false;
			RemoveTextSelectionCanvas();
			_caretTimer?.Stop();
			InvalidateTextLayout();
		}

		internal void CaretChanged()
		{
			if (this.GetVisualParent() == null)
			{
				return;
			}
			EnsureCaretTimer();
			DispatcherTimer? caretTimer = _caretTimer;
			if (caretTimer != null && caretTimer.IsEnabled)
			{
				_caretBlink = true;
				_caretTimer?.Stop();
				_caretTimer?.Start();
				InvalidateVisual();
			}
			else
			{
				_caretTimer?.Start();
				InvalidateVisual();
				_caretTimer?.Stop();
			}
			if (base.IsMeasureValid)
			{
				this.BringIntoView(_caretBounds);
				return;
			}
			Dispatcher.UIThread.Post(delegate
			{
				this.BringIntoView(_caretBounds);
			}, DispatcherPriority.AfterRender);
		}

		/// <summary>
		/// Creates the <see cref="P:Avalonia.Controls.Presenters.TextPresenter.TextLayout" /> used to render the text.
		/// </summary>
