	internal interface IInlineHost : ILogical
	{
		IAvaloniaList<Visual> VisualChildren { get; }

		void Invalidate();
	}
	/// <summary>
	/// Inline element.
	/// </summary>
	public abstract class Inline : TextElement
	{
		/// <summary>
		/// AvaloniaProperty for <see cref="P:Avalonia.Controls.Documents.Inline.TextDecorations" /> property.
		/// </summary>
		public static readonly StyledProperty<TextDecorationCollection?> TextDecorationsProperty = AvaloniaProperty.RegisterAttached<Inline, Inline, TextDecorationCollection>("TextDecorations", null, inherits: true);

		/// <summary>
		/// AvaloniaProperty for <see cref="P:Avalonia.Controls.Documents.Inline.BaselineAlignment" /> property.
		/// </summary>
		public static readonly StyledProperty<BaselineAlignment> BaselineAlignmentProperty = AvaloniaProperty.Register<Inline, BaselineAlignment>("BaselineAlignment", BaselineAlignment.Baseline);

		/// <summary>
		/// The TextDecorations property specifies decorations that are added to the text of an element.
		/// </summary>
		public TextDecorationCollection? TextDecorations
		{
			get
			{
				return GetValue(TextDecorationsProperty);
			}
			set
			{
				SetValue(TextDecorationsProperty, value);
			}
		}

		/// <summary>
		/// Describes how the baseline for a text-based element is positioned on the vertical axis,
		/// relative to the established baseline for text.
		/// </summary>
		public BaselineAlignment BaselineAlignment
		{
			get
			{
				return GetValue(BaselineAlignmentProperty);
			}
			set
			{
				SetValue(BaselineAlignmentProperty, value);
			}
		}

		/// <summary>
		/// Gets the value of the attached <see cref="F:Avalonia.Controls.Documents.Inline.TextDecorationsProperty" /> on a control.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <returns>The font style.</returns>
		public static TextDecorationCollection? GetTextDecorations(Control control)
		{
			return control.GetValue(TextDecorationsProperty);
		}

		/// <summary>
		/// Sets the value of the attached <see cref="F:Avalonia.Controls.Documents.Inline.TextDecorationsProperty" /> on a control.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <param name="value">The property value to set.</param>
		public static void SetTextDecorations(Control control, TextDecorationCollection? value)
		{
			control.SetValue(TextDecorationsProperty, value);
		}

		internal abstract void BuildTextRun(IList<TextRun> textRuns, Size blockSize);

		internal abstract void AppendText(StringBuilder stringBuilder);

		protected TextRunProperties CreateTextRunProperties()
		{
			IBrush backgroundBrush = base.Background ?? FindParentBackground();
			return new GenericTextRunProperties(new Typeface(base.FontFamily, base.FontStyle, base.FontWeight, base.FontStretch), base.FontFeatures, base.FontSize, TextDecorations, base.Foreground, backgroundBrush, BaselineAlignment);
		}

		/// <summary>
		/// Searches for the next parent inline element with a non-null Background and returns its Background brush.
		/// </summary>
		/// <returns>The first non-null Background brush found in parent inline elements, or null if none is found.</returns>
		private IBrush? FindParentBackground()
		{
			for (StyledElement parent = base.Parent; parent is Inline inline; parent = inline.Parent)
			{
				if (inline.Background != null)
				{
					return inline.Background;
				}
			}
			return null;
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			string name = change.Property.Name;
			if (name == "TextDecorations" || name == "BaselineAlignment")
			{
				base.InlineHost?.Invalidate();
			}
		}
	}
	/// <summary>
	/// A collection of <see cref="T:Avalonia.Controls.Documents.Inline" />s.
	/// </summary>
	[WhitespaceSignificantCollection]
	public class InlineCollection : AvaloniaList<Inline>
	{
		private IAvaloniaList<ILogical>? _logicalChildren;

		private IInlineHost? _inlineHost;

		internal IAvaloniaList<ILogical>? LogicalChildren
		{
			get
			{
				return _logicalChildren;
			}
			set
			{
				IAvaloniaList<ILogical> logicalChildren = _logicalChildren;
				_logicalChildren = value;
				OnParentChanged(logicalChildren, value);
			}
		}

		internal IInlineHost? InlineHost
		{
			get
			{
				return _inlineHost;
			}
			set
			{
				IInlineHost inlineHost = _inlineHost;
				_inlineHost = value;
				OnInlineHostChanged(inlineHost, value);
			}
		}

		/// <summary>
		/// Gets or adds the text held by the inlines collection.
		/// <remarks>
		/// Can be null for complex content.
		/// </remarks>
		/// </summary>
		public string? Text
		{
			get
			{
				if (base.Count == 0)
				{
					return null;
				}
				StringBuilder stringBuilder = StringBuilderCache.Acquire();
				using (AvaloniaList<Inline>.Enumerator enumerator = GetEnumerator())
				{
					while (enumerator.MoveNext())
					{
						enumerator.Current.AppendText(stringBuilder);
					}
				}
				return StringBuilderCache.GetStringAndRelease(stringBuilder);
			}
		}

		/// <summary>
		/// Raised when an inline in the collection changes.
		/// </summary>
		public event EventHandler? Invalidated;

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Documents.InlineCollection" /> class.
		/// </summary>
		public InlineCollection()
		{
			base.ResetBehavior = ResetBehavior.Remove;
			this.ForEachItem(OnAdd, OnRemove, delegate
			{
				throw new NotSupportedException();
			});
		}

		public override void Add(Inline inline)
		{
			if (InlineHost is TextBlock textBlock && !string.IsNullOrEmpty(textBlock.Text))
			{
				base.Add(new Run(textBlock.Text));
				textBlock.ClearTextInternal();
			}
			base.Add(inline);
		}

		/// <summary>
		/// Adds a text segment to the collection.
		/// <remarks>
		/// For non-complex content this appends the text to the end of currently held text.
		/// For complex content this adds a <see cref="T:Avalonia.Controls.Documents.Run" /> to the collection.
		/// </remarks>
		/// </summary>
		/// <param name="text">The to be added text.</param>
		public void Add(string text)
		{
			if (InlineHost is TextBlock { HasComplexContent: false } textBlock)
			{
				textBlock.Text += text;
			}
			else
			{
				Add(new Run(text));
			}
		}

		/// <summary>
		/// Adds a control wrapped inside a <see cref="T:Avalonia.Controls.Documents.InlineUIContainer" /> to the collection.
		/// </summary>
		/// <param name="control">The to be added control.</param>
		public void Add(Control control)
		{
			Add(new InlineUIContainer(control));
		}

		/// <summary>
		/// Raises the <see cref="E:Avalonia.Controls.Documents.InlineCollection.Invalidated" /> event.
		/// </summary>
		protected void Invalidate()
		{
			InlineHost?.Invalidate();
			this.Invalidated?.Invoke(this, EventArgs.Empty);
		}

		private void OnParentChanged(ICollection<ILogical>? oldValue, ICollection<ILogical>? newValue)
		{
			using (AvaloniaList<Inline>.Enumerator enumerator = GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					Inline current = enumerator.Current;
					if (!object.Equals(oldValue, newValue))
					{
						oldValue?.Remove(current);
						newValue?.Add(current);
					}
				}
			}
			Invalidate();
		}

		private void OnInlineHostChanged(IInlineHost? oldValue, IInlineHost? newValue)
		{
			using (AvaloniaList<Inline>.Enumerator enumerator = GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					enumerator.Current.InlineHost = newValue;
				}
			}
			Invalidate();
		}

		private void OnAdd(TextElement inline)
		{
			inline.InlineHost = InlineHost;
			LogicalChildren?.Add(inline);
			Invalidate();
		}

		private void OnRemove(TextElement inline)
		{
			LogicalChildren?.Remove(inline);
			inline.InlineHost = null;
			Invalidate();
		}
	}
	internal class EmbeddedControlRun : DrawableTextRun
	{
		public Control Control { get; }

		public override TextRunProperties? Properties { get; }

		public override Size Size => Control.DesiredSize;

		public override double Baseline
		{
			get
			{
				double result = Size.Height;
				double value = Control.GetValue(TextBlock.BaselineOffsetProperty);
				if (!MathUtilities.IsZero(value))
				{
					result = value;
				}
				return result;
			}
		}

