	/// <summary>
	/// A terminal element in text flow hierarchy - contains a uniformatted run of unicode characters
	/// </summary>
	public class Run : Inline
	{
		/// <summary>
		/// Dependency property backing Text.
		/// </summary>
		/// <remarks>
		/// Note that when a TextRange that intersects with this Run gets modified (e.g. by editing 
		/// a selection in RichTextBox), we will get two changes to this property since we delete 
		/// and then insert when setting the content of a TextRange.
		/// </remarks>
		public static readonly StyledProperty<string?> TextProperty = AvaloniaProperty.Register<Run, string>("Text", null, inherits: false, BindingMode.TwoWay);

		/// <summary>
		/// The content spanned by this TextElement.
		/// </summary>
		[Content]
		public string? Text
		{
			get
			{
				return GetValue(TextProperty);
			}
			set
			{
				SetValue(TextProperty, value);
			}
		}

		/// <summary>
		/// Initializes an instance of Run class.
		/// </summary>
		public Run()
		{
		}

		/// <summary>
		/// Initializes an instance of Run class specifying its text content.
		/// </summary>
		/// <param name="text">
		/// Text content assigned to the Run.
		/// </param>
		public Run(string? text)
		{
			Text = text;
		}

		internal override void BuildTextRun(IList<TextRun> textRuns, Size blockSize)
		{
			string text = Text ?? "";
			if (!string.IsNullOrEmpty(text))
			{
				TextRunProperties textRunProperties = CreateTextRunProperties();
				TextCharacters item = new TextCharacters(text, textRunProperties);
				textRuns.Add(item);
			}
		}

		internal override void AppendText(StringBuilder stringBuilder)
		{
			string value = Text ?? "";
			stringBuilder.Append(value);
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property.Name == "Text")
			{
				base.InlineHost?.Invalidate();
			}
		}
	}
	/// <summary>
	/// Span element used for grouping other Inline elements.
	/// </summary>
	public class Span : Inline, IAddChild<Inline>, IAddChild<Control>, IAddChild<string>
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Documents.Span.Inlines" /> property.
		/// </summary>
		public static readonly StyledProperty<InlineCollection> InlinesProperty = AvaloniaProperty.Register<Span, InlineCollection>("Inlines");

		/// <summary>
		/// Gets or sets the inlines.
		/// </summary>
		[Content]
		public InlineCollection Inlines
		{
			get
			{
				return GetValue(InlinesProperty);
			}
			set
			{
				SetValue(InlinesProperty, value);
			}
		}

		public Span()
		{
			Inlines = new InlineCollection
			{
				LogicalChildren = base.LogicalChildren
			};
		}

		internal override void BuildTextRun(IList<TextRun> textRuns, Size blockSize)
		{
			foreach (Inline inline in Inlines)
			{
				inline.BuildTextRun(textRuns, blockSize);
			}
		}

		internal override void AppendText(StringBuilder stringBuilder)
		{
			foreach (Inline inline in Inlines)
			{
				inline.AppendText(stringBuilder);
			}
		}

		/// <inheritdoc />
		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			if (change.Property.Name == "InlinesProperty")
			{
				OnInlinesChanged(change.OldValue as InlineCollection, change.NewValue as InlineCollection);
				base.InlineHost?.Invalidate();
			}
		}

		internal override void OnInlineHostChanged(IInlineHost? oldValue, IInlineHost? newValue)
		{
			base.OnInlineHostChanged(oldValue, newValue);
			Inlines.InlineHost = newValue;
		}

		private void OnInlinesChanged(InlineCollection? oldValue, InlineCollection? newValue)
		{
			if (oldValue != null)
			{
				oldValue.LogicalChildren = null;
				oldValue.InlineHost = null;
				oldValue.Invalidated -= OnInlinesInvalidated;
			}
			if (newValue != null)
			{
				newValue.LogicalChildren = base.LogicalChildren;
				newValue.InlineHost = base.InlineHost;
				newValue.Invalidated += OnInlinesInvalidated;
			}
			void OnInlinesInvalidated(object? sender, EventArgs e)
			{
				base.InlineHost?.Invalidate();
			}
		}

		void IAddChild<Inline>.AddChild(Inline inline)
		{
			Inlines?.Add(inline);
		}

		void IAddChild<Control>.AddChild(Control child)
		{
			Inlines?.Add(new InlineUIContainer(child));
		}

		void IAddChild<string>.AddChild(string text)
		{
			Inlines?.Add(new Run(text));
		}
	}
