		internal virtual void OnInlineHostChanged(IInlineHost? oldValue, IInlineHost? newValue)
		{
		}

		protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
		{
			base.OnPropertyChanged(change);
			string name = change.Property.Name;
			if (name == null)
			{
				return;
			}
			switch (name.Length)
			{
			case 10:
				switch (name[2])
				{
				default:
					return;
				case 'c':
					if (!(name == "Background"))
					{
						return;
					}
					break;
				case 'n':
					if (!(name == "FontFamily") && !(name == "FontWeight"))
					{
						return;
					}
					break;
				case 'r':
					if (!(name == "Foreground"))
					{
						return;
					}
					break;
				}
				goto IL_00b1;
			case 8:
				if (!(name == "FontSize"))
				{
					break;
				}
				goto IL_00b1;
			case 9:
				if (!(name == "FontStyle"))
				{
					break;
				}
				goto IL_00b1;
			case 11:
				{
					if (!(name == "FontStretch"))
					{
						break;
					}
					goto IL_00b1;
				}
				IL_00b1:
				InlineHost?.Invalidate();
				break;
			}
		}
	}
