{
	/// <summary>
	/// Converts an existing CornerRadius struct to a new CornerRadius struct,
	/// with filters applied to extract only the specified corners, leaving the others set to 0.
	/// </summary>
	public class CornerRadiusFilterConverter : IValueConverter
	{
		/// <summary>
		/// Gets or sets the corners to filter by.
		/// Only the specified corners will be included in the converted <see cref="T:Avalonia.CornerRadius" />.
		/// </summary>
		public Corners Filter { get; set; }

		/// <summary>
		/// Gets or sets the scale multiplier applied uniformly to each corner.
		/// </summary>
		public double Scale { get; set; } = 1.0;

		/// <inheritdoc />
		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (!(value is CornerRadius cornerRadius))
			{
				return value;
			}
			return new CornerRadius(Filter.HasAllFlags(Corners.TopLeft) ? (cornerRadius.TopLeft * Scale) : 0.0, Filter.HasAllFlags(Corners.TopRight) ? (cornerRadius.TopRight * Scale) : 0.0, Filter.HasAllFlags(Corners.BottomRight) ? (cornerRadius.BottomRight * Scale) : 0.0, Filter.HasAllFlags(Corners.BottomLeft) ? (cornerRadius.BottomLeft * Scale) : 0.0);
		}

		/// <inheritdoc />
		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	/// <summary>
	/// Converts one corner of a <see cref="T:Avalonia.CornerRadius" /> to its double value.
	/// </summary>
	public class CornerRadiusToDoubleConverter : IValueConverter
	{
		/// <summary>
		/// Gets or sets the specific corner of the <see cref="T:Avalonia.CornerRadius" /> to convert to double.
		/// </summary>
		public Corners Corner { get; set; }

		/// <inheritdoc />
		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (!(value is CornerRadius cornerRadius))
			{
				return AvaloniaProperty.UnsetValue;
			}
			return Corner switch
			{
				Corners.TopLeft => cornerRadius.TopLeft, 
				Corners.TopRight => cornerRadius.TopRight, 
				Corners.BottomRight => cornerRadius.BottomRight, 
				Corners.BottomLeft => cornerRadius.BottomLeft, 
				_ => 0.0, 
			};
		}

		/// <inheritdoc />
		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	/// <summary>
	/// Defines constants that specify one or more corners of a <see cref="T:Avalonia.CornerRadius" />.
	/// </summary>
	[Flags]
	public enum Corners
	{
		/// <summary>
		/// No corner.
		/// </summary>
		None = 0,
		/// <summary>
		/// The TopLeft corner.
		/// </summary>
		TopLeft = 1,
		/// <summary>
		/// The TopRight corner.
		/// </summary>
		TopRight = 2,
		/// <summary>
		/// The BottomLeft corner.
		/// </summary>
		BottomLeft = 4,
		/// <summary>
		/// The BottomRight corner.
		/// </summary>
		BottomRight = 8
	}
	/// <summary>
	/// Converter to convert an enum value to bool by comparing to the given parameter.
	/// Both value and parameter must be of the same enum type.
	/// </summary>
	/// <remarks>
	/// This converter is useful to enable binding of radio buttons with a selected enum value.
	/// </remarks>
	public class EnumToBoolConverter : IValueConverter
	{
		/// <inheritdoc />
		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (value == null && parameter == null)
			{
				return true;
			}
			if (value == null || parameter == null)
			{
				return false;
			}
			return value.Equals(parameter);
		}

		/// <inheritdoc />
		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (value is bool && (bool)value)
			{
				return parameter;
			}
			return BindingOperations.DoNothing;
		}
	}
	public class MarginMultiplierConverter : IValueConverter
	{
		public double Indent { get; set; }

		public bool Left { get; set; }

		public bool Top { get; set; }

		public bool Right { get; set; }

		public bool Bottom { get; set; }

		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (value is int num)
			{
				return new Thickness(Left ? (Indent * (double)num) : 0.0, Top ? (Indent * (double)num) : 0.0, Right ? (Indent * (double)num) : 0.0, Bottom ? (Indent * (double)num) : 0.0);
			}
			if (value is Thickness thickness)
			{
				return new Thickness(Left ? (Indent * thickness.Left) : 0.0, Top ? (Indent * thickness.Top) : 0.0, Right ? (Indent * thickness.Right) : 0.0, Bottom ? (Indent * thickness.Bottom) : 0.0);
			}
			return new Thickness(0.0);
		}

		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class MenuScrollingVisibilityConverter : IMultiValueConverter
	{
		public static readonly MenuScrollingVisibilityConverter Instance = new MenuScrollingVisibilityConverter();

		public object? Convert(IList<object?> values, Type targetType, object? parameter, CultureInfo culture)
		{
			if (parameter == null || values.Count != 4 || !(values[0] is ScrollBarVisibility scrollBarVisibility) || !(values[1] is double num) || !(values[2] is double num2) || !(values[3] is double num3))
			{
				return AvaloniaProperty.UnsetValue;
			}
			switch (scrollBarVisibility)
			{
			case ScrollBarVisibility.Auto:
			{
				if (MathUtilities.AreClose(num2, num3))
				{
					return false;
				}
				double value;
				if (parameter is double num4)
				{
					value = num4;
				}
				else
				{
					if (!(parameter is string s))
					{
						return AvaloniaProperty.UnsetValue;
					}
					value = double.Parse(s, NumberFormatInfo.InvariantInfo);
				}
				if (MathUtilities.AreClose(MathUtilities.Clamp(num * 100.0 / (num2 - num3), 0.0, 100.0), value))
				{
					return false;
				}
				return true;
			}
			case ScrollBarVisibility.Visible:
				return true;
			default:
				return false;
			}
		}
	}
	/// <summary>
	/// Converts a <see cref="T:Avalonia.Input.KeyGesture" /> to a string, formatting it according to the current
	/// platform's style guidelines.
	/// </summary>
	public class PlatformKeyGestureConverter : IValueConverter
	{
		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			if (value == null)
			{
				return null;
			}
			if (value is KeyGesture keyGesture && targetType == typeof(string))
			{
				return keyGesture.ToString("p", null);
			}
			throw new NotSupportedException();
		}

		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}

		/// <summary>
		/// Converts a <see cref="T:Avalonia.Input.KeyGesture" /> to a string, formatting it according to the current
		/// platform's style guidelines.
		/// </summary>
		/// <param name="gesture">The gesture.</param>
		/// <returns>The gesture formatted according to the current platform.</returns>
		public static string ToPlatformString(KeyGesture gesture)
		{
			return gesture.ToString("p", null);
		}
	}
	/// <summary>
	/// Calls <see cref="M:System.String.Format(System.String,System.Object[])" /> on the passed in values, where the first element in the list
	/// is the string, and everything after it is passed into the object array in order.
	/// </summary>
	public class StringFormatConverter : IMultiValueConverter
	{
		public object? Convert(IList<object?> values, Type targetType, object? parameter, CultureInfo culture)
		{
			if (values[0] is string format)
			{
				try
				{
					return string.Format(format, values.Skip(1).ToArray());
				}
				catch
				{
					return AvaloniaProperty.UnsetValue;
				}
			}
			return AvaloniaProperty.UnsetValue;
		}
	}
