namespace Avalonia.Controls.Chrome
{
	/// <summary>
	/// Draws window minimize / maximize / close buttons in a <see cref="T:Avalonia.Controls.Chrome.TitleBar" /> when managed client decorations are enabled.
	/// </summary>
	[TemplatePart("PART_CloseButton", typeof(Button))]
	[TemplatePart("PART_RestoreButton", typeof(Button))]
	[TemplatePart("PART_MinimizeButton", typeof(Button))]
	[TemplatePart("PART_FullScreenButton", typeof(Button))]
	[PseudoClasses(new string[] { ":minimized", ":normal", ":maximized", ":fullscreen" })]
	public class CaptionButtons : TemplatedControl
	{
		internal const string PART_CloseButton = "PART_CloseButton";

		internal const string PART_RestoreButton = "PART_RestoreButton";

		internal const string PART_MinimizeButton = "PART_MinimizeButton";

		internal const string PART_FullScreenButton = "PART_FullScreenButton";

		private Button? _restoreButton;

		private Button? _minimizeButton;

		private Button? _fullScreenButton;

		private IDisposable? _disposables;

		/// <summary>
		/// Currently attached window.
		/// </summary>
		protected Window? HostWindow { get; private set; }

		public virtual void Attach(Window hostWindow)
		{
			if (_disposables == null)
			{
				HostWindow = hostWindow;
				_disposables = new CompositeDisposable
				{
					HostWindow.GetObservable(Window.CanMaximizeProperty).Subscribe(delegate
					{
						UpdateRestoreButtonState();
						UpdateFullScreenButtonState();
					}),
					HostWindow.GetObservable(Window.CanMinimizeProperty).Subscribe(delegate
					{
						UpdateMinimizeButtonState();
					}),
					HostWindow.GetObservable(Window.WindowStateProperty).Subscribe(delegate(WindowState x)
					{
						base.PseudoClasses.Set(":minimized", x == WindowState.Minimized);
						base.PseudoClasses.Set(":normal", x == WindowState.Normal);
						base.PseudoClasses.Set(":maximized", x == WindowState.Maximized);
						base.PseudoClasses.Set(":fullscreen", x == WindowState.FullScreen);
						UpdateRestoreButtonState();
						UpdateMinimizeButtonState();
						UpdateFullScreenButtonState();
					})
				};
			}
		}

		public virtual void Detach()
		{
			if (_disposables != null)
			{
				_disposables.Dispose();
				_disposables = null;
				HostWindow = null;
			}
		}

		protected virtual void OnClose()
		{
			HostWindow?.Close();
		}

		protected virtual void OnRestore()
		{
			if (HostWindow != null)
			{
				HostWindow.WindowState = ((HostWindow.WindowState != WindowState.Maximized) ? WindowState.Maximized : WindowState.Normal);
			}
		}

		protected virtual void OnMinimize()
		{
			if (HostWindow != null)
			{
				HostWindow.WindowState = WindowState.Minimized;
			}
		}

		protected virtual void OnToggleFullScreen()
		{
			if (HostWindow != null)
			{
				HostWindow.WindowState = ((HostWindow.WindowState != WindowState.FullScreen) ? WindowState.FullScreen : WindowState.Normal);
			}
		}

		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			Button button = e.NameScope.Find<Button>("PART_CloseButton");
			if (button != null)
			{
				button.Click += delegate(object? _, RoutedEventArgs args)
				{
					OnClose();
					args.Handled = true;
				};
			}
			Button button2 = e.NameScope.Find<Button>("PART_RestoreButton");
			if (button2 != null)
			{
				button2.Click += delegate(object? _, RoutedEventArgs args)
				{
					OnRestore();
					args.Handled = true;
				};
				_restoreButton = button2;
				UpdateRestoreButtonState();
			}
			Button button3 = e.NameScope.Find<Button>("PART_MinimizeButton");
			if (button3 != null)
			{
				button3.Click += delegate(object? _, RoutedEventArgs args)
				{
					OnMinimize();
					args.Handled = true;
				};
				_minimizeButton = button3;
				UpdateMinimizeButtonState();
			}
			Button button4 = e.NameScope.Find<Button>("PART_FullScreenButton");
			if (button4 != null)
			{
				button4.Click += delegate(object? _, RoutedEventArgs args)
				{
					OnToggleFullScreen();
					args.Handled = true;
				};
				_fullScreenButton = button4;
				UpdateFullScreenButtonState();
			}
		}

		private void UpdateRestoreButtonState()
		{
			if (_restoreButton != null)
			{
				Button restoreButton = _restoreButton;
				bool isEnabled;
				switch (HostWindow?.WindowState)
				{
				case WindowState.Maximized:
				case WindowState.FullScreen:
					isEnabled = HostWindow.CanResize;
					break;
				case WindowState.Normal:
					isEnabled = HostWindow.CanMaximize;
					break;
				default:
					isEnabled = true;
					break;
				}
				restoreButton.IsEnabled = isEnabled;
			}
		}

		private void UpdateMinimizeButtonState()
		{
			if (_minimizeButton != null)
			{
				_minimizeButton.IsEnabled = HostWindow?.CanMinimize ?? true;
			}
		}

		private void UpdateFullScreenButtonState()
		{
			if (_fullScreenButton != null)
			{
				Button? fullScreenButton = _fullScreenButton;
				Window? hostWindow = HostWindow;
				fullScreenButton.IsEnabled = ((hostWindow != null && hostWindow.WindowState == WindowState.FullScreen) ? HostWindow.CanResize : (HostWindow?.CanMaximize ?? true));
			}
		}
	}
	/// <summary>
	/// Draws a titlebar when managed client decorations are enabled.
	/// </summary>
	[TemplatePart("PART_CaptionButtons", typeof(CaptionButtons), IsRequired = true)]
	[PseudoClasses(new string[] { ":minimized", ":normal", ":maximized", ":fullscreen" })]
	public class TitleBar : TemplatedControl
	{
		private CompositeDisposable? _disposables;

		private CaptionButtons? _captionButtons;

		private void UpdateSize(Window window)
		{
			base.Margin = new Thickness(window.OffScreenMargin.Left, window.OffScreenMargin.Top, window.OffScreenMargin.Right, window.OffScreenMargin.Bottom);
			if (window.WindowState != WindowState.FullScreen)
			{
				base.Height = Math.Max(0.0, window.WindowDecorationMargin.Top);
				if (_captionButtons != null)
				{
					_captionButtons.Height = base.Height;
				}
			}
			base.IsVisible = window.PlatformImpl?.NeedsManagedDecorations ?? false;
		}

		/// <inheritdoc />
		protected override void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
			base.OnApplyTemplate(e);
			_captionButtons?.Detach();
			_captionButtons = e.NameScope.Get<CaptionButtons>("PART_CaptionButtons");
			if (base.VisualRoot is Window window)
			{
				_captionButtons?.Attach(window);
				UpdateSize(window);
			}
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			IRenderRoot visualRoot = base.VisualRoot;
			Window window = visualRoot as Window;
			if (window != null)
			{
				_disposables = new CompositeDisposable(6)
				{
					window.GetObservable(Window.WindowDecorationMarginProperty).Subscribe(delegate
					{
						UpdateSize(window);
					}),
					window.GetObservable(Window.ExtendClientAreaTitleBarHeightHintProperty).Subscribe(delegate
					{
						UpdateSize(window);
					}),
					window.GetObservable(Window.OffScreenMarginProperty).Subscribe(delegate
					{
						UpdateSize(window);
					}),
					window.GetObservable(Window.ExtendClientAreaChromeHintsProperty).Subscribe(delegate
					{
						UpdateSize(window);
					}),
					window.GetObservable(Window.WindowStateProperty).Subscribe(delegate(WindowState x)
					{
						base.PseudoClasses.Set(":minimized", x == WindowState.Minimized);
						base.PseudoClasses.Set(":normal", x == WindowState.Normal);
						base.PseudoClasses.Set(":maximized", x == WindowState.Maximized);
						base.PseudoClasses.Set(":fullscreen", x == WindowState.FullScreen);
					}),
					window.GetObservable(Window.IsExtendedIntoWindowDecorationsProperty).Subscribe(delegate
					{
						UpdateSize(window);
					})
				};
			}
		}

		/// <inheritdoc />
		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			_disposables?.Dispose();
			_captionButtons?.Detach();
			_captionButtons = null;
		}

		/// <inheritdoc />
		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new TitleBarAutomationPeer(this);
		}
	}
}
namespace Avalonia.Controls.Primitives
{
	public sealed class CalendarBlackoutDatesCollection : ObservableCollection<CalendarDateRange>
	{
		/// <summary>
		/// The Calendar whose dates this object represents.
		/// </summary>
		private readonly Calendar _owner;

		/// <summary>
		/// Initializes a new instance of the
		/// <see cref="T:Avalonia.Controls.Primitives.CalendarBlackoutDatesCollection" />
		/// class.
		/// </summary>
		/// <param name="owner">
		/// The <see cref="T:Avalonia.Controls.Calendar" /> whose dates
		/// this object represents.
		/// </param>
		public CalendarBlackoutDatesCollection(Calendar owner)
		{
			_owner = owner ?? throw new ArgumentNullException("owner");
		}

		/// <summary>
		/// Adds all dates before <see cref="P:System.DateTime.Today" /> to the
		/// collection.
		/// </summary>
		public void AddDatesInPast()
		{
			Add(new CalendarDateRange(DateTime.MinValue, DateTime.Today.AddDays(-1.0)));
		}

		/// <summary>
		/// Returns a value that represents whether this collection contains the
		/// specified date.
		/// </summary>
		/// <param name="date">The date to search for.</param>
		/// <returns>
		/// True if the collection contains the specified date; otherwise,
		/// false.
		/// </returns>
		public bool Contains(DateTime date)
		{
			int count = base.Count;
			for (int i = 0; i < count; i++)
			{
				if (DateTimeHelper.InRange(date, base[i]))
				{
					return true;
				}
			}
			return false;
		}

		/// <summary>
		/// Returns a value that represents whether this collection contains the
		/// specified range of dates.
		/// </summary>
		/// <param name="start">The start of the date range.</param>
		/// <param name="end">The end of the date range.</param>
		/// <returns>
		/// True if all dates in the range are contained in the collection;
		/// otherwise, false.
		/// </returns>
		public bool Contains(DateTime start, DateTime end)
		{
			DateTime t;
			DateTime t2;
			if (DateTime.Compare(end, start) > -1)
			{
				t = DateTimeHelper.DiscardTime(start);
				t2 = DateTimeHelper.DiscardTime(end);
			}
			else
			{
				t = DateTimeHelper.DiscardTime(end);
				t2 = DateTimeHelper.DiscardTime(start);
			}
			int count = base.Count;
			for (int i = 0; i < count; i++)
			{
				CalendarDateRange calendarDateRange = base[i];
				if (DateTime.Compare(calendarDateRange.Start, t) == 0 && DateTime.Compare(calendarDateRange.End, t2) == 0)
				{
					return true;
				}
			}
			return false;
		}

		/// <summary>
		/// Returns a value that represents whether this collection contains any
		/// date in the specified range.
		/// </summary>
		/// <param name="range">The range of dates to search for.</param>
		/// <returns>
		/// True if any date in the range is contained in the collection;
		/// otherwise, false.
		/// </returns>
		public bool ContainsAny(CalendarDateRange range)
		{
			return this.Any((CalendarDateRange r) => r.ContainsAny(range));
		}

		/// <summary>
		/// Removes all items from the collection.
		/// </summary>
		/// <remarks>
		/// This implementation raises the CollectionChanged event.
		/// </remarks>
		protected override void ClearItems()
		{
			EnsureValidThread();
			base.ClearItems();
			_owner.UpdateMonths();
		}

		/// <summary>
		/// Inserts an item into the collection at the specified index.
		/// </summary>
		/// <param name="index">
		/// The zero-based index at which item should be inserted.
		/// </param>
		/// <param name="item">The object to insert.</param>
		/// <remarks>
		/// This implementation raises the CollectionChanged event.
		/// </remarks>
		protected override void InsertItem(int index, CalendarDateRange item)
		{
			EnsureValidThread();
			if (!IsValid(item))
			{
				throw new ArgumentOutOfRangeException("item", "Value is not valid.");
			}
			base.InsertItem(index, item);
			_owner.UpdateMonths();
		}

		/// <summary>
		/// Removes the item at the specified index of the collection.
		/// </summary>
		/// <param name="index">
		/// The zero-based index of the element to remove.
		/// </param>
		/// <remarks>
		/// This implementation raises the CollectionChanged event.
		/// </remarks>
		protected override void RemoveItem(int index)
		{
			EnsureValidThread();
			base.RemoveItem(index);
			_owner.UpdateMonths();
		}

		/// <summary>
		/// Replaces the element at the specified index.
		/// </summary>
		/// <param name="index">
		/// The zero-based index of the element to replace.
		/// </param>
		/// <param name="item">
		/// The new value for the element at the specified index.
		/// </param>
		/// <remarks>
		/// This implementation raises the CollectionChanged event.
		/// </remarks>
		protected override void SetItem(int index, CalendarDateRange item)
		{
			EnsureValidThread();
			if (!IsValid(item))
			{
				throw new ArgumentOutOfRangeException("item", "Value is not valid.");
			}
			base.SetItem(index, item);
			_owner.UpdateMonths();
		}

		private bool IsValid(CalendarDateRange item)
		{
			foreach (DateTime selectedDate in _owner.SelectedDates)
			{
				if (DateTimeHelper.InRange(selectedDate, item))
				{
					return false;
				}
			}
			return true;
		}

		private static void EnsureValidThread()
		{
			Dispatcher.UIThread.VerifyAccess();
		}
	}
