	/// <summary>
	/// A text block that displays a character prefixed with an underscore as an access key.
	/// </summary>
	public class AccessText : TextBlock
	{
		/// <summary>
		/// Defines the <see cref="P:Avalonia.Controls.Primitives.AccessText.ShowAccessKey" /> attached property.
		/// </summary>
		public static readonly AttachedProperty<bool> ShowAccessKeyProperty;

		/// <summary>
		/// The access key handler for the current window.
		/// </summary>
		private IAccessKeyHandler? _accessKeys;

		/// <summary>
		/// Gets the access key.
		/// </summary>
		public char AccessKey { get; private set; }

		/// <summary>
		/// Gets or sets a value indicating whether the access key should be underlined.
		/// </summary>
		public bool ShowAccessKey
		{
			get
			{
				return GetValue(ShowAccessKeyProperty);
			}
			set
			{
				SetValue(ShowAccessKeyProperty, value);
			}
		}

		/// <summary>
		/// Initializes static members of the <see cref="T:Avalonia.Controls.Primitives.AccessText" /> class.
		/// </summary>
		static AccessText()
		{
			ShowAccessKeyProperty = AvaloniaProperty.RegisterAttached<AccessText, Control, bool>("ShowAccessKey", defaultValue: false, inherits: true);
			Visual.AffectsRender<AccessText>(new AvaloniaProperty[1] { ShowAccessKeyProperty });
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Avalonia.Controls.Primitives.AccessText" /> class.
		/// </summary>
		public AccessText()
		{
			this.GetObservable(TextBlock.TextProperty).Subscribe(TextChanged);
		}

		/// <summary>
		/// Renders the <see cref="T:Avalonia.Controls.Primitives.AccessText" /> to a drawing context.
		/// </summary>
		/// <param name="context">The drawing context.</param>
		private protected override void RenderCore(DrawingContext context)
		{
			base.RenderCore(context);
			int num = base.Text?.IndexOf('_') ?? (-1);
			if (num != -1 && ShowAccessKey)
			{
				Rect rect = base.TextLayout.HitTestTextPosition(num);
				double x = Math.Round(rect.Left, MidpointRounding.AwayFromZero);
				double x2 = Math.Round(rect.Right, MidpointRounding.AwayFromZero);
				double y = Math.Round(rect.Bottom, MidpointRounding.AwayFromZero) - 1.5;
				context.DrawLine(new Pen(base.Foreground), new Point(x, y), new Point(x2, y));
			}
		}

		/// <inheritdoc />
		protected override TextLayout CreateTextLayout(string? text)
		{
			return base.CreateTextLayout(RemoveAccessKeyMarker(text));
		}

		/// <inheritdoc />
		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			_accessKeys = (e.Root as TopLevel)?.AccessKeyHandler;
			if (_accessKeys != null && AccessKey != 0)
			{
				_accessKeys.Register(AccessKey, this);
			}
		}

		/// <inheritdoc />
		protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnDetachedFromVisualTree(e);
			if (_accessKeys != null && AccessKey != 0)
			{
				_accessKeys.Unregister(this);
				_accessKeys = null;
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new NoneAutomationPeer(this);
		}

		internal static string? RemoveAccessKeyMarker(string? text)
		{
			if (!string.IsNullOrEmpty(text))
			{
				string text2 = "_";
				string oldValue = text2 + text2;
				int num = FindAccessKeyMarker(text);
				if (num >= 0 && num < text.Length - 1)
				{
					text = text.Remove(num, 1);
				}
				text = text.Replace(oldValue, text2);
			}
			return text;
		}

		private static int FindAccessKeyMarker(string text)
		{
			int length = text.Length;
			int num = 0;
			while (num < length)
			{
				int num2 = text.IndexOf('_', num);
				if (num2 == -1)
				{
					return -1;
				}
				if (num2 + 1 < length && text[num2 + 1] != '_')
				{
					return num2;
				}
				num = num2 + 2;
			}
			return -1;
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.TextBlock.Text" /> property changes.
		/// </summary>
		/// <param name="text">The new text.</param>
		private void TextChanged(string? text)
		{
			char accessKey = '\0';
			if (text != null)
			{
				int num = text.IndexOf('_');
				if (num != -1 && num < text.Length - 1)
				{
					accessKey = text[num + 1];
				}
			}
			AccessKey = accessKey;
			if (_accessKeys != null && AccessKey != 0)
			{
				_accessKeys.Register(AccessKey, this);
			}
		}
	}
