		static OverlayPopupHost()
		{
			TransformProperty = PopupRoot.TransformProperty.AddOwner<OverlayPopupHost>();
			KeyboardNavigation.TabNavigationProperty.OverrideDefaultValue<OverlayPopupHost>(KeyboardNavigationMode.Cycle);
		}

		public OverlayPopupHost(OverlayLayer overlayLayer)
		{
			_overlayLayer = overlayLayer;
			_positioner = new ManagedPopupPositioner(this);
			_keyboardNavigationHandler = AvaloniaLocator.Current.GetService<IKeyboardNavigationHandler>();
			_keyboardNavigationHandler?.SetOwner(this);
		}

		/// <inheritdoc />
		public void SetChild(Control? control)
		{
			base.Content = control;
		}

		/// <inheritdoc />
		public void Dispose()
		{
			Hide();
		}

		/// <inheritdoc />
		public void Show()
		{
			_overlayLayer.Children.Add(this);
			if (base.Content is Visual { IsAttachedToVisualTree: false })
			{
				UpdateLayout();
			}
		}

		/// <inheritdoc />
		public void Hide()
		{
			_overlayLayer.Children.Remove(this);
		}

		public void TakeFocus()
		{
		}

		[Unstable("This API may be removed in Avalonia 12. If you depend on this API, please open an issue with details of your use-case.")]
		public void ConfigurePosition(Visual target, PlacementMode placement, Point offset, PopupAnchor anchor = PopupAnchor.None, PopupGravity gravity = PopupGravity.None, PopupPositionerConstraintAdjustment constraintAdjustment = PopupPositionerConstraintAdjustment.All, Rect? rect = null)
		{
			((IPopupHost)this).ConfigurePosition(new PopupPositionRequest(target, placement, offset, anchor, gravity, constraintAdjustment, rect, null));
		}

		/// <inheritdoc />
		void IPopupHost.ConfigurePosition(PopupPositionRequest positionRequest)
		{
			_popupPositionRequest = positionRequest;
			_needsUpdate = true;
			UpdatePosition();
		}

		/// <inheritdoc />
		protected override Size ArrangeOverride(Size finalSize)
		{
			if (_popupSize != finalSize)
			{
				_popupSize = finalSize;
				_needsUpdate = true;
				UpdatePosition();
			}
			return base.ArrangeOverride(finalSize);
		}

		private void UpdatePosition()
		{
			if (_needsUpdate && _popupPositionRequest != null)
			{
				_needsUpdate = false;
				_positioner.Update(TopLevel.GetTopLevel(_overlayLayer), _popupPositionRequest, _popupSize, base.FlowDirection);
			}
		}

		void IManagedPopupPositionerPopup.MoveAndResize(Point devicePoint, Size virtualSize)
		{
			_lastRequestedPosition = devicePoint;
			MediaContext.Instance.BeginInvokeOnRender(delegate
			{
				Canvas.SetLeft(this, _lastRequestedPosition.X);
				Canvas.SetTop(this, _lastRequestedPosition.Y);
			});
		}

		[Unstable("PopupHost is considered an internal API. Use Popup or any Popup-based controls (Flyout, Tooltip) instead.")]
		public static IPopupHost CreatePopupHost(Visual target, IAvaloniaDependencyResolver? dependencyResolver)
		{
			return CreatePopupHost(target, dependencyResolver, shouldUseOverlayLayer: false);
		}

		internal static IPopupHost CreatePopupHost(Visual target, IAvaloniaDependencyResolver? dependencyResolver, bool shouldUseOverlayLayer)
		{
			if (!shouldUseOverlayLayer)
			{
				TopLevel topLevel = TopLevel.GetTopLevel(target);
				if (topLevel != null)
				{
					IPopupImpl popupImpl = topLevel.PlatformImpl?.CreatePopup();
					if (popupImpl != null)
					{
						return new PopupRoot(topLevel, popupImpl, dependencyResolver);
					}
				}
			}
			OverlayLayer overlayLayer = OverlayLayer.GetOverlayLayer(target);
			if (overlayLayer != null)
			{
				return new OverlayPopupHost(overlayLayer);
			}
			throw new InvalidOperationException("Unable to create IPopupImpl and no overlay layer is found for the target control");
		}

