			void ExecuteScrollWhenLayoutUpdated(object? sender, EventArgs e2)
			{
				base.LayoutUpdated -= ExecuteScrollWhenLayoutUpdated;
				AutoScrollToSelectedItemIfNecessary(GetAnchorIndex());
