		/// <inheritdoc />
		public sealed override void ApplyTemplate()
		{
			IControlTemplate template = Template;
			if (_appliedTemplate == template || (template == null && !((ILogical)this).IsAttachedToLogicalTree))
			{
				return;
			}
			if (base.VisualChildren.Count > 0)
			{
				foreach (Control templateChild in this.GetTemplateChildren())
				{
					templateChild.TemplatedParent = null;
					((ISetLogicalParent)templateChild).SetParent((ILogical?)null);
				}
				base.VisualChildren.Clear();
			}
			if (template != null)
			{
				Logger.TryGet(LogEventLevel.Verbose, "Control")?.Log(this, "Creating control template");
				TemplateResult<Control> templateResult = template.Build(this);
				if (templateResult != null)
				{
					var (control2, nameScope2) = templateResult;
					ApplyTemplatedParent(control2, this);
					((ISetLogicalParent)control2).SetParent((ILogical?)this);
					base.VisualChildren.Add(control2);
					TemplateAppliedEventArgs e = new TemplateAppliedEventArgs(nameScope2);
					OnApplyTemplate(e);
					RaiseEvent(e);
				}
			}
			_appliedTemplate = template;
		}

		/// <inheritdoc />
		protected override Control GetTemplateFocusTarget()
		{
			foreach (Control templateChild in this.GetTemplateChildren())
			{
				if (GetIsTemplateFocusTarget(templateChild))
				{
					return templateChild;
				}
			}
			return this;
		}

		/// <inheritdoc />
		internal sealed override void NotifyChildResourcesChanged(ResourcesChangedToken token)
		{
			int count = base.VisualChildren.Count;
			for (int i = 0; i < count; i++)
			{
				base.VisualChildren[i]?.NotifyResourcesChanged(token);
			}
			base.NotifyChildResourcesChanged(token);
		}

		/// <inheritdoc />
		protected override void OnAttachedToLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			if (base.VisualChildren.Count > 0)
			{
				((ILogical)base.VisualChildren[0]).NotifyAttachedToLogicalTree(e);
			}
			base.OnAttachedToLogicalTree(e);
		}

		/// <inheritdoc />
		protected override void OnDetachedFromLogicalTree(LogicalTreeAttachmentEventArgs e)
		{
			if (base.VisualChildren.Count > 0)
			{
				((ILogical)base.VisualChildren[0]).NotifyDetachedFromLogicalTree(e);
			}
			base.OnDetachedFromLogicalTree(e);
		}

		/// <summary>
		/// Called when the control's template is applied.
		/// In simple terms, this means the method is called just before the control is displayed.
		/// </summary>
		/// <param name="e">The event args.</param>
		protected virtual void OnApplyTemplate(TemplateAppliedEventArgs e)
		{
		}

		/// <summary>
		/// Called when the <see cref="P:Avalonia.Controls.Primitives.TemplatedControl.Template" /> property changes.
		/// </summary>
		/// <param name="e">The event args.</param>
		protected virtual void OnTemplateChanged(AvaloniaPropertyChangedEventArgs e)
		{
			InvalidateMeasure();
		}

		/// <summary>
		/// Sets the TemplatedParent property for the created template children.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <param name="templatedParent">The templated parent to apply.</param>
		internal static void ApplyTemplatedParent(StyledElement control, AvaloniaObject? templatedParent)
		{
			control.TemplatedParent = templatedParent;
			IAvaloniaList<ILogical> logicalChildren = control.LogicalChildren;
			int count = logicalChildren.Count;
			for (int i = 0; i < count; i++)
			{
				if (logicalChildren[i] is StyledElement { TemplatedParent: null } styledElement)
				{
					ApplyTemplatedParent(styledElement, templatedParent);
				}
			}
		}

		private protected override void OnControlThemeChanged()
		{
			base.OnControlThemeChanged();
			int count = base.VisualChildren.Count;
			for (int i = 0; i < count; i++)
			{
				StyledElement styledElement = base.VisualChildren[i];
				if (styledElement != null && styledElement.TemplatedParent == this)
				{
					styledElement.OnTemplatedParentControlThemeChanged();
				}
			}
		}
	}
	/// <summary>
	/// Allows to customize text searching in <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" />.
	/// </summary>
	public static class TextSearch
	{
		/// <summary>
		/// Defines the Text attached property.
		/// This text will be considered during text search in <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" /> (such as <see cref="T:Avalonia.Controls.ComboBox" />).
		/// This property is usually applied to an item container directly.
		/// </summary>
		public static readonly AttachedProperty<string?> TextProperty = AvaloniaProperty.RegisterAttached<Interactive, string>("Text", typeof(TextSearch));

		/// <summary>
		/// Defines the TextBinding attached property.
		/// The binding will be applied to each item during text search in <see cref="T:Avalonia.Controls.Primitives.SelectingItemsControl" /> (such as <see cref="T:Avalonia.Controls.ComboBox" />).
		/// </summary>
		public static readonly AttachedProperty<IBinding?> TextBindingProperty = AvaloniaProperty.RegisterAttached<Interactive, IBinding>("TextBinding", typeof(TextSearch));

		/// <summary>
		/// Sets the value of the <see cref="F:Avalonia.Controls.Primitives.TextSearch.TextProperty" /> attached property to a given <see cref="T:Avalonia.Controls.Control" />.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <param name="text">The search text to set.</param>
		public static void SetText(Control control, string? text)
		{
			control.SetValue(TextProperty, text);
		}

		/// <summary>
		/// Gets the value of the <see cref="F:Avalonia.Controls.Primitives.TextSearch.TextProperty" /> attached property from a given <see cref="T:Avalonia.Controls.Control" />.
		/// </summary>
		/// <param name="control">The control.</param>
		/// <returns>The search text.</returns>
		public static string? GetText(Control control)
		{
			return control.GetValue(TextProperty);
		}

		/// <summary>
		/// Sets the value of the <see cref="F:Avalonia.Controls.Primitives.TextSearch.TextBindingProperty" /> attached property to a given <see cref="T:Avalonia.Interactivity.Interactive" />.
		/// </summary>
		/// <param name="interactive">The interactive element.</param>
		/// <param name="value">The search text binding to set.</param>
		public static void SetTextBinding(Interactive interactive, IBinding? value)
		{
			interactive.SetValue(TextBindingProperty, value);
		}

		/// <summary>
		/// Gets the value of the <see cref="F:Avalonia.Controls.Primitives.TextSearch.TextBindingProperty" /> attached property from a given <see cref="T:Avalonia.Interactivity.Interactive" />.
		/// </summary>
		/// <param name="interactive">The interactive element.</param>
		/// <returns>The search text binding.</returns>
		[AssignBinding]
		public static IBinding? GetTextBinding(Interactive interactive)
		{
			return interactive.GetValue(TextBindingProperty);
		}

		/// <summary>
		/// <para>Gets the effective text of a given item.</para>
		/// <para>
		///   This method uses the first non-empty text from the following list:
		///   <list>
		///     <item><see cref="F:Avalonia.Controls.Primitives.TextSearch.TextProperty" /> (if the item is a control)</item>
		///     <item><see cref="F:Avalonia.Controls.Primitives.TextSearch.TextBindingProperty" /></item>
		///     <item><see cref="P:Avalonia.Controls.ItemsControl.DisplayMemberBinding" /></item>
		///     <item><see cref="P:Avalonia.Controls.IContentControl.Content" />.<see cref="M:System.Object.ToString" /> (if the item is a <see cref="T:Avalonia.Controls.IContentControl" />)</item>
		///     <item><see cref="M:System.Object.ToString" /></item>
		///   </list>
		/// </para>
		/// </summary>
		/// <param name="item">The item.</param>
		/// <param name="textBindingEvaluator">A <see cref="T:Avalonia.Controls.Utils.BindingEvaluator`1" /> used to get the item's text from a binding.</param>
		/// <returns>The item's text.</returns>
		internal static string GetEffectiveText(object? item, BindingEvaluator<string?>? textBindingEvaluator)
		{
			if (item == null)
			{
				return string.Empty;
			}
			if (item is Interactive interactive)
			{
				string value = interactive.GetValue(TextProperty);
				if (!string.IsNullOrEmpty(value))
				{
					return value;
				}
			}
			if (textBindingEvaluator != null)
			{
				string value = textBindingEvaluator.Evaluate(item);
				if (!string.IsNullOrEmpty(value))
				{
					return value;
				}
			}
			if (item is IContentControl contentControl)
			{
				return contentControl.Content?.ToString() ?? string.Empty;
			}
			return item.ToString() ?? string.Empty;
		}
	}
	internal class TextSelectionHandleCanvas : Canvas
	{
		private const int ContextMenuPadding = 16;

		private readonly TextSelectionHandle _caretHandle;

		private readonly TextSelectionHandle _startHandle;

		private readonly TextSelectionHandle _endHandle;

		private TextPresenter? _presenter;

		private TextBox? _textBox;

		private bool _showHandle;

		private bool _canShowContextMenu = true;

		internal bool ShowHandles
		{
			get
			{
				return _showHandle;
			}
			set
			{
				_showHandle = value;
				if (!value)
				{
					_startHandle.IsVisible = false;
					_endHandle.IsVisible = false;
					_caretHandle.IsVisible = false;
				}
				base.IsVisible = !string.IsNullOrEmpty(_presenter?.Text) && value;
			}
		}

		public TextSelectionHandleCanvas()
		{
			_caretHandle = new TextSelectionHandle
			{
				SelectionHandleType = SelectionHandleType.Caret
			};
			_startHandle = new TextSelectionHandle();
			_endHandle = new TextSelectionHandle();
			base.Children.Add(_caretHandle);
			base.Children.Add(_startHandle);
			base.Children.Add(_endHandle);
			_caretHandle.DragStarted += Handle_DragStarted;
			_caretHandle.DragDelta += CaretHandle_DragDelta;
			_caretHandle.DragCompleted += Handle_DragCompleted;
			_startHandle.DragDelta += StartHandle_DragDelta;
			_startHandle.DragCompleted += Handle_DragCompleted;
			_startHandle.DragStarted += Handle_DragStarted;
			_endHandle.DragDelta += EndHandle_DragDelta;
			_endHandle.DragCompleted += Handle_DragCompleted;
			_endHandle.DragStarted += Handle_DragStarted;
			_caretHandle.Classes.Add("caret");
			_startHandle.Classes.Add("start");
			_endHandle.Classes.Add("end");
			_startHandle.SetTopLeft(default(Point));
			_caretHandle.SetTopLeft(default(Point));
			_endHandle.SetTopLeft(default(Point));
			_startHandle.PointerReleased += Handle_PointerReleased;
			_caretHandle.PointerReleased += Handle_PointerReleased;
			_endHandle.PointerReleased += Handle_PointerReleased;
			_startHandle.Holding += Caret_Holding;
			_caretHandle.Holding += Caret_Holding;
			_endHandle.Holding += Caret_Holding;
			base.IsVisible = ShowHandles;
			base.ClipToBounds = false;
		}

		private void Handle_PointerReleased(object? sender, PointerReleasedEventArgs e)
		{
			ShowContextMenu();
		}

		private void Handle_DragStarted(object? sender, VectorEventArgs e)
		{
			(_textBox?.ContextFlyout)?.Hide();
		}

		private void EndHandle_DragDelta(object? sender, VectorEventArgs e)
		{
			if (sender is TextSelectionHandle handle)
			{
				DragSelectionHandle(handle);
			}
		}

		private void StartHandle_DragDelta(object? sender, VectorEventArgs e)
		{
			if (sender is TextSelectionHandle handle)
			{
				DragSelectionHandle(handle);
			}
		}

		private void CaretHandle_DragDelta(object? sender, VectorEventArgs e)
		{
			_canShowContextMenu = false;
			if (_presenter != null && _textBox != null)
			{
				Point point = ToPresenter(_caretHandle.IndicatorPosition);
				_presenter.MoveCaretToPoint(point);
				TextBox? textBox = _textBox;
				int selectionStart = (_textBox.SelectionEnd = _presenter.CaretIndex);
				textBox.SelectionStart = selectionStart;
				(Point, Point) caretPoints = _presenter.GetCaretPoints();
				_caretHandle?.SetTopLeft(ToLayer(caretPoints.Item2));
			}
		}

		private void Handle_DragCompleted(object? sender, VectorEventArgs e)
		{
			MoveHandlesToSelection();
			ShowContextMenu();
		}

		private void EnsureVisible()
		{
			TextBox textBox = _textBox;
			if (textBox != null && textBox.VisualRoot is Visual relativeTo)
			{
				Rect bounds = textBox.Bounds;
				Point valueOrDefault = textBox.TranslatePoint(default(Point), relativeTo).GetValueOrDefault();
				bounds = bounds.WithX(valueOrDefault.X).WithY(valueOrDefault.Y);
				bool flag = _textBox.SelectionStart != _textBox.SelectionEnd;
				_startHandle.IsVisible = bounds.Contains(new Point(Canvas.GetLeft(_startHandle), Canvas.GetTop(_startHandle))) && ShowHandles && flag;
				_endHandle.IsVisible = bounds.Contains(new Point(Canvas.GetLeft(_endHandle), Canvas.GetTop(_endHandle))) && ShowHandles && flag;
				_caretHandle.IsVisible = bounds.Contains(new Point(Canvas.GetLeft(_caretHandle), Canvas.GetTop(_caretHandle))) && ShowHandles && !flag;
			}
		}

		private void DragSelectionHandle(TextSelectionHandle handle)
		{
			if (_presenter != null && _textBox != null)
			{
				_textBox.ContextFlyout?.Hide();
				Point point = ToPresenter(handle.IndicatorPosition);
				point = point.WithY(point.Y - _presenter.FontSize / 2.0);
				TextHitTestResult textHitTestResult = _presenter.TextLayout.HitTestPoint(in point);
				int num = textHitTestResult.CharacterHit.FirstCharacterIndex + textHitTestResult.CharacterHit.TrailingLength;
				TextSelectionHandle textSelectionHandle = ((handle == _startHandle) ? _endHandle : _startHandle);
				if (handle.SelectionHandleType == SelectionHandleType.Start)
				{
					if (num >= _textBox.SelectionEnd)
					{
						num = _textBox.SelectionEnd - 1;
					}
					_textBox.SelectionStart = num;
				}
				else
				{
					if (num <= _textBox.SelectionStart)
					{
						num = _textBox.SelectionStart + 1;
					}
					_textBox.SelectionEnd = num;
				}
				int selectionStart = _textBox.SelectionStart;
				int selectionEnd = _textBox.SelectionEnd;
				int num2 = Math.Min(selectionStart, selectionEnd);
				int length = Math.Max(selectionStart, selectionEnd) - num2;
				List<Rect> list = new List<Rect>(_presenter.TextLayout.HitTestTextRange(num2, length));
				if (list.Count > 0)
				{
					Rect rect = list[0];
					Rect rect2 = list[list.Count - 1];
					if (handle.SelectionHandleType == SelectionHandleType.Start)
					{
						handle?.SetTopLeft(ToLayer(rect.BottomLeft));
					}
					else
					{
						handle?.SetTopLeft(ToLayer(rect2.BottomRight));
					}
					if (textSelectionHandle.SelectionHandleType == SelectionHandleType.Start)
					{
						textSelectionHandle?.SetTopLeft(ToLayer(rect.BottomLeft));
					}
					else
					{
						textSelectionHandle?.SetTopLeft(ToLayer(rect2.BottomRight));
					}
				}
				_presenter?.MoveCaretToTextPosition(num);
			}
			EnsureVisible();
		}

		private Point ToLayer(Point point)
		{
			if (!(_presenter?.VisualRoot is Visual relativeTo))
			{
				return point;
			}
			return _presenter?.TranslatePoint(point, relativeTo) ?? point;
		}

		private Point ToPresenter(Point point)
		{
			TextPresenter presenter = _presenter;
			if (presenter == null)
			{
				return point;
			}
			return (presenter.VisualRoot as Visual)?.TranslatePoint(point, presenter) ?? point;
		}

		private Point ToTextBox(Point point)
		{
			TextBox textBox = _textBox;
			if (textBox == null)
			{
				return point;
			}
			return (textBox.VisualRoot as Visual)?.TranslatePoint(point, textBox) ?? point;
		}

		public void MoveHandlesToSelection()
		{
			if (_presenter == null || _textBox == null || _startHandle.IsDragging || _endHandle.IsDragging)
			{
				return;
			}
			FlyoutBase? contextFlyout = _textBox.ContextFlyout;
			if (contextFlyout != null && contextFlyout.IsOpen)
			{
				return;
			}
			ContextMenu? contextMenu = _textBox.ContextMenu;
			if (contextMenu != null && contextMenu.IsOpen)
			{
				return;
			}
			bool num = _textBox.SelectionStart != _textBox.SelectionEnd;
			(Point, Point) caretPoints = _presenter.GetCaretPoints();
			_caretHandle.SetTopLeft(ToLayer(caretPoints.Item2));
			if (!num)
			{
				return;
			}
			int selectionStart = _textBox.SelectionStart;
			int selectionEnd = _textBox.SelectionEnd;
			int num2 = Math.Min(selectionStart, selectionEnd);
			int length = Math.Max(selectionStart, selectionEnd) - num2;
			List<Rect> list = new List<Rect>(_presenter.TextLayout.HitTestTextRange(num2, length));
			if (list.Count > 0)
			{
				Rect rect = list[0];
				Rect rect2 = list[list.Count - 1];
				if (!_startHandle.IsDragging)
				{
					_startHandle.SetTopLeft(ToLayer(rect.BottomLeft));
					_startHandle.SelectionHandleType = ((selectionStart < selectionEnd) ? SelectionHandleType.Start : SelectionHandleType.End);
				}
				if (!_endHandle.IsDragging)
				{
					_endHandle.SetTopLeft(ToLayer(rect2.BottomRight));
					_endHandle.SelectionHandleType = ((selectionStart > selectionEnd) ? SelectionHandleType.Start : SelectionHandleType.End);
				}
			}
		}

		internal void SetPresenter(TextPresenter? textPresenter)
		{
			if (_presenter == textPresenter)
			{
				return;
			}
			if (_textBox != null)
			{
				_textBox.RemoveHandler(TextBox.TextChangingEvent, TextChanged);
				_textBox.RemoveHandler(InputElement.KeyDownEvent, TextBoxKeyDown);
				_textBox.RemoveHandler(InputElement.PointerReleasedEvent, TextBoxPointerReleased);
				_textBox.PropertyChanged -= TextBoxPropertyChanged;
				_textBox.EffectiveViewportChanged -= TextBoxEffectiveViewportChanged;
				_textBox.SizeChanged -= TextBox_SizeChanged;
				_textBox = null;
			}
			_presenter = textPresenter;
			if (_presenter != null)
			{
				_textBox = _presenter.FindAncestorOfType<TextBox>();
				if (_textBox != null)
				{
					_textBox.AddHandler(TextBox.TextChangingEvent, TextChanged, RoutingStrategies.Direct | RoutingStrategies.Bubble, handledEventsToo: true);
					_textBox.AddHandler(InputElement.KeyDownEvent, TextBoxKeyDown, RoutingStrategies.Direct | RoutingStrategies.Bubble, handledEventsToo: true);
					_textBox.AddHandler(InputElement.PointerReleasedEvent, TextBoxPointerReleased, RoutingStrategies.Direct | RoutingStrategies.Bubble, handledEventsToo: true);
					_textBox.PropertyChanged += TextBoxPropertyChanged;
					_textBox.EffectiveViewportChanged += TextBoxEffectiveViewportChanged;
					_textBox.SizeChanged += TextBox_SizeChanged;
				}
			}
		}

		private void TextBox_SizeChanged(object? sender, SizeChangedEventArgs e)
		{
			InvalidateMeasure();
		}

		private void TextBoxEffectiveViewportChanged(object? sender, EffectiveViewportChangedEventArgs e)
		{
			if (ShowHandles)
			{
				MoveHandlesToSelection();
				EnsureVisible();
			}
		}

		private void Caret_Holding(object? sender, HoldingRoutedEventArgs e)
		{
			if (ShowContextMenu())
			{
				e.Handled = true;
			}
		}

		internal bool ShowContextMenu()
		{
			if (_textBox != null && _canShowContextMenu)
			{
				if (_textBox.ContextFlyout is PopupFlyoutBase popupFlyoutBase)
				{
					double num = (double.IsNaN(_textBox.LineHeight) ? _textBox.FontSize : _textBox.LineHeight) + 16.0;
					TextSelectionHandle textSelectionHandle = null;
					if (_textBox.SelectionStart != _textBox.SelectionEnd)
					{
						if (_startHandle.IsEffectivelyVisible)
						{
							textSelectionHandle = _startHandle;
						}
						else if (_endHandle.IsEffectivelyVisible)
						{
							textSelectionHandle = _endHandle;
						}
					}
					else if (_caretHandle.IsEffectivelyVisible)
					{
						textSelectionHandle = _caretHandle;
					}
					if (textSelectionHandle != null)
					{
						Point point = ToTextBox(textSelectionHandle.GetTopLeft());
						popupFlyoutBase.VerticalOffset = point.Y - num;
						popupFlyoutBase.HorizontalOffset = point.X;
						popupFlyoutBase.Placement = PlacementMode.TopEdgeAlignedLeft;
						_textBox.RaiseEvent(new ContextRequestedEventArgs());
						return true;
					}
				}
				else
				{
					_textBox.RaiseEvent(new ContextRequestedEventArgs());
				}
			}
			_canShowContextMenu = true;
			return false;
		}

		private void TextBoxPointerReleased(object? sender, PointerReleasedEventArgs e)
		{
			if (e.Pointer.Type != PointerType.Mouse)
			{
				ShowHandles = true;
				MoveHandlesToSelection();
				EnsureVisible();
			}
		}

		private void TextBoxPropertyChanged(object? sender, AvaloniaPropertyChangedEventArgs e)
		{
			if (ShowHandles && (e.Property == TextBox.SelectionStartProperty || e.Property == TextBox.SelectionEndProperty))
			{
				MoveHandlesToSelection();
				EnsureVisible();
			}
		}

		private void TextBoxKeyDown(object? sender, KeyEventArgs e)
		{
			ShowHandles = false;
		}

		private void TextChanged(object? sender, TextChangingEventArgs e)
		{
			ShowHandles = false;
			FlyoutBase flyoutBase = _textBox?.ContextFlyout;
			if (flyoutBase != null && flyoutBase.IsOpen)
			{
				flyoutBase.Hide();
			}
		}
	}
	/// <summary>
	/// A controls that enables easy control over text selection using touch based input
	/// </summary>
	public class TextSelectionHandle : Thumb
	{
		private Point _startPosition;

		private Vector _delta;

		private Point? _lastPoint;

		private TranslateTransform? _transform;

		internal SelectionHandleType SelectionHandleType { get; set; }

		internal Point IndicatorPosition
		{
			get
			{
				if (!IsDragging)
				{
					return base.Bounds.Position.WithX(base.Bounds.Position.X).WithY(base.Bounds.Y);
				}
				return _startPosition.WithX(_startPosition.X) + _delta;
			}
		}

		internal bool IsDragging { get; private set; }

		static TextSelectionHandle()
		{
			Thumb.DragStartedEvent.AddClassHandler(delegate(TextSelectionHandle x, VectorEventArgs e)
			{
				x.OnDragStarted(e);
			}, RoutingStrategies.Bubble);
			Thumb.DragDeltaEvent.AddClassHandler(delegate(TextSelectionHandle x, VectorEventArgs e)
			{
				x.OnDragDelta(e);
			}, RoutingStrategies.Bubble);
			Thumb.DragCompletedEvent.AddClassHandler(delegate(TextSelectionHandle x, VectorEventArgs e)
			{
				x.OnDragCompleted(e);
			}, RoutingStrategies.Bubble);
		}

		protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
		{
			base.OnAttachedToVisualTree(e);
			if (_transform == null)
			{
				_transform = new TranslateTransform();
			}
			base.RenderTransform = _transform;
		}

		protected override void OnLoaded(RoutedEventArgs args)
		{
			base.OnLoaded(args);
			InvalidateMeasure();
		}

		protected override void OnDragStarted(VectorEventArgs e)
		{
			base.OnDragStarted(e);
			_startPosition = base.Bounds.Position;
			_delta = default(Vector);
			IsDragging = true;
		}

		protected override void OnDragDelta(VectorEventArgs e)
		{
			base.OnDragDelta(e);
			_delta = e.Vector;
			UpdateTextSelectionHandlePosition();
		}

		protected override void OnDragCompleted(VectorEventArgs e)
		{
			base.OnDragCompleted(e);
			IsDragging = false;
			_startPosition = default(Point);
		}

		private void UpdateTextSelectionHandlePosition()
		{
			SetTopLeft(IndicatorPosition);
		}

		protected override void ArrangeCore(Rect finalRect)
		{
			base.ArrangeCore(finalRect);
			if (_transform != null)
			{
				if (SelectionHandleType == SelectionHandleType.Caret)
				{
					base.HasMirrorTransform = true;
					_transform.X = base.Bounds.Width / 2.0 * -1.0;
				}
				else if (SelectionHandleType == SelectionHandleType.Start)
				{
					base.HasMirrorTransform = true;
					_transform.X = base.Bounds.Width * -1.0;
				}
				else
				{
					base.HasMirrorTransform = false;
