					SetValue(ChromeOverlayLayerProperty, chromeOverlayLayer2);
					chromeOverlayLayer = chromeOverlayLayer2;
				}
				return chromeOverlayLayer;
			}
		}

		public OverlayLayer? OverlayLayer
		{
			get
			{
				if (IsPopup)
				{
					return null;
