	public class EmbeddableControlRootAutomationPeer : ContentControlAutomationPeer, IEmbeddedRootProvider
	{
		private Control? _focus;

		public new EmbeddableControlRoot Owner => (EmbeddableControlRoot)base.Owner;

		public event EventHandler? FocusChanged;

		public EmbeddableControlRootAutomationPeer(EmbeddableControlRoot owner)
			: base(owner)
		{
			if (owner.IsVisible)
			{
				StartTrackingFocus();
			}
			else
			{
				owner.Opened += OnOpened;
			}
			owner.Closed += OnClosed;
		}

		public AutomationPeer? GetFocus()
		{
			if (_focus == null)
			{
				return null;
			}
			return GetOrCreate(_focus);
		}

		public AutomationPeer? GetPeerFromPoint(Point p)
		{
			Control control = Owner.GetVisualAt(p)?.FindAncestorOfType<Control>();
			if (control == null)
			{
				return null;
			}
			return GetOrCreate(control);
		}

		private void StartTrackingFocus()
		{
			if (KeyboardDevice.Instance != null)
			{
				KeyboardDevice.Instance.PropertyChanged += KeyboardDevicePropertyChanged;
				OnFocusChanged(KeyboardDevice.Instance.FocusedElement);
			}
		}

		private void StopTrackingFocus()
		{
			if (KeyboardDevice.Instance != null)
			{
				KeyboardDevice.Instance.PropertyChanged -= KeyboardDevicePropertyChanged;
			}
		}

		private void OnFocusChanged(IInputElement? focus)
		{
			Control focus2 = _focus;
			Control control = focus as Control;
			_focus = ((control?.VisualRoot == Owner) ? control : null);
			if (_focus != focus2)
			{
				if (_focus != null && _focus != Owner)
				{
					GetOrCreate(_focus);
				}
				this.FocusChanged?.Invoke(this, EventArgs.Empty);
			}
		}

		private void KeyboardDevicePropertyChanged(object? sender, PropertyChangedEventArgs e)
		{
			if (e.PropertyName == "FocusedElement")
			{
				OnFocusChanged(KeyboardDevice.Instance.FocusedElement);
			}
		}

		private void OnOpened(object? sender, EventArgs e)
		{
			Owner.Opened -= OnOpened;
			StartTrackingFocus();
		}

		private void OnClosed(object? sender, EventArgs e)
		{
			Owner.Closed -= OnClosed;
			StopTrackingFocus();
		}
	}
	public class ExpanderAutomationPeer : ControlAutomationPeer, IExpandCollapseProvider
	{
		public new Expander Owner => (Expander)base.Owner;

		public ExpandCollapseState ExpandCollapseState => ToState(Owner.IsExpanded);

		public bool ShowsMenu => false;

		public ExpanderAutomationPeer(Control owner)
			: base(owner)
		{
			owner.PropertyChanged += OwnerPropertyChanged;
		}

		public void Collapse()
		{
			Owner.IsExpanded = false;
		}

		public void Expand()
		{
			Owner.IsExpanded = true;
		}

		protected override AutomationControlType GetAutomationControlTypeCore()
		{
			return AutomationControlType.Expander;
		}

		private void OwnerPropertyChanged(object? sender, AvaloniaPropertyChangedEventArgs e)
		{
			if (e.Property == Expander.IsExpandedProperty)
			{
				RaisePropertyChangedEvent(ExpandCollapsePatternIdentifiers.ExpandCollapseStateProperty, ToState((bool)e.OldValue), ToState((bool)e.NewValue));
			}
		}

		private static ExpandCollapseState ToState(bool value)
		{
			if (!value)
			{
				return ExpandCollapseState.Collapsed;
			}
			return ExpandCollapseState.Expanded;
		}

		protected override bool IsContentElementCore()
		{
			return true;
		}

		protected override bool IsControlElementCore()
		{
			return true;
		}
	}
