namespace Avalonia.Controls.ApplicationLifetimes
{
	[PrivateApi]
	public abstract class ActivatableLifetimeBase : IActivatableLifetime
	{
		public event EventHandler<ActivatedEventArgs>? Activated;

		public event EventHandler<ActivatedEventArgs>? Deactivated;

		public virtual bool TryLeaveBackground()
		{
			return false;
		}

		public virtual bool TryEnterBackground()
		{
			return false;
		}

		protected internal void OnActivated(ActivationKind kind)
		{
			OnActivated(new ActivatedEventArgs(kind));
		}

		protected internal void OnActivated(ActivatedEventArgs eventArgs)
		{
			Dispatcher.UIThread.Send(delegate
			{
				this.Activated?.Invoke(this, eventArgs);
			});
		}

		protected internal void OnDeactivated(ActivationKind kind)
		{
			OnDeactivated(new ActivatedEventArgs(kind));
		}

		protected internal void OnDeactivated(ActivatedEventArgs eventArgs)
		{
			Dispatcher.UIThread.Send(delegate
			{
				this.Deactivated?.Invoke(this, eventArgs);
			});
		}
	}
	/// <summary>
	/// Event args for an Application Lifetime Activated or Deactivated events.
	/// </summary>
	public class ActivatedEventArgs : EventArgs
	{
		/// <summary>
		/// The <see cref="T:Avalonia.Controls.ApplicationLifetimes.ActivationKind" /> that this event represents.
		/// </summary>
		public ActivationKind Kind { get; }

		/// <summary>
		/// Ctor for ActivatedEventArgs
		/// </summary>
		/// <param name="kind">The <see cref="T:Avalonia.Controls.ApplicationLifetimes.ActivationKind" /> that this event represents</param>
		public ActivatedEventArgs(ActivationKind kind)
		{
			Kind = kind;
		}
	}
	public enum ActivationKind
	{
		/// <summary>
		/// When the application is passed a file to open.
		/// </summary>
		File = 10,
		/// <summary>
		/// When the application is passed a URI to open, protocol activation.
		/// </summary>
		OpenUri = 20,
		/// <summary>
		/// When the application is asked to reopen.
		/// An example of this is on MacOS when all the windows are closed,
		/// application continues to run in the background and the user clicks
		/// the application's dock icon. 
		/// </summary>
		Reopen = 30,
		/// <summary>
		/// When the application enters or leaves a background state.
		/// An example is when on MacOS the user hides or shows and application (not window),
		/// or when a browser application switchs tabs or when a mobile applications goes into
		/// the background.
		/// </summary>
		Background = 40
	}
	public class ClassicDesktopStyleApplicationLifetime : IClassicDesktopStyleApplicationLifetime, IControlledApplicationLifetime, IApplicationLifetime, IDisposable
	{
		private int _exitCode;

		private CancellationTokenSource? _cts;

		private bool _isShuttingDown;

		private readonly AvaloniaList<Window> _windows = new AvaloniaList<Window>();

		private CompositeDisposable? _compositeDisposable;

		/// <summary>
		/// Gets the arguments passed to the AppBuilder Start method.
		/// </summary>
		public string[]? Args { get; set; }

		/// <inheritdoc />
		public ShutdownMode ShutdownMode { get; set; }

		/// <inheritdoc />
		public Window? MainWindow { get; set; }

		/// <inheritdoc />
		public IReadOnlyList<Window> Windows => _windows;

		/// <inheritdoc />
		public event EventHandler<ControlledApplicationLifetimeStartupEventArgs>? Startup;

		/// <inheritdoc />
		public event EventHandler<ShutdownRequestedEventArgs>? ShutdownRequested;

		/// <inheritdoc />
		public event EventHandler<ControlledApplicationLifetimeExitEventArgs>? Exit;

		private void HandleWindowClosed(Window? window)
		{
			if (window != null && !_isShuttingDown)
			{
				if (ShutdownMode == ShutdownMode.OnLastWindowClose && _windows.Count == 0)
				{
					TryShutdown();
				}
				else if (ShutdownMode == ShutdownMode.OnMainWindowClose && window == MainWindow)
				{
					TryShutdown();
				}
			}
		}

		public void Shutdown(int exitCode = 0)
		{
			DoShutdown(new ShutdownRequestedEventArgs(), isProgrammatic: true, force: true, exitCode);
		}

		public bool TryShutdown(int exitCode = 0)
		{
			return DoShutdown(new ShutdownRequestedEventArgs(), isProgrammatic: true, force: false, exitCode);
		}

		internal void SubscribeGlobalEvents()
		{
			if (_compositeDisposable != null)
			{
				return;
			}
			_compositeDisposable = new CompositeDisposable(Window.WindowOpenedEvent.AddClassHandler(typeof(Window), delegate(object? sender, RoutedEventArgs _)
			{
				Window item = (Window)sender;
				if (!_windows.Contains(item))
				{
					_windows.Add(item);
				}
			}), Window.WindowClosedEvent.AddClassHandler(typeof(Window), delegate(object? sender, RoutedEventArgs _)
			{
				Window window = (Window)sender;
				_windows.Remove(window);
				HandleWindowClosed(window);
			}));
		}

		internal void SetupCore(string[] args)
		{
			SubscribeGlobalEvents();
			this.Startup?.Invoke(this, new ControlledApplicationLifetimeStartupEventArgs(args));
			ClassicDesktopStyleApplicationLifetimeOptions service = AvaloniaLocator.Current.GetService<ClassicDesktopStyleApplicationLifetimeOptions>();
			if (service != null && service.ProcessUrlActivationCommandLine && args.Length != 0)
			{
				((IApplicationPlatformEvents)Application.Current)?.RaiseUrlsOpened(args);
			}
			IPlatformLifetimeEventsImpl service2 = AvaloniaLocator.Current.GetService<IPlatformLifetimeEventsImpl>();
			if (service2 != null)
			{
				service2.ShutdownRequested += OnShutdownRequested;
			}
		}

		public int Start(string[] args)
		{
			return StartCore(args);
		}

		/// <summary>
		/// Since the lifetime must be set up/prepared with 'args' before executing Start(), an overload with no parameters seems more suitable for integrating with some lifetime manager providers, such as MS HostApplicationBuilder.
		/// </summary>
		/// <returns>exit code</returns>
		public int Start()
		{
			return StartCore(Args ?? Array.Empty<string>());
		}

		internal int StartCore(string[] args)
		{
			SetupCore(args);
			_cts = new CancellationTokenSource();
			ShowMainWindow();
			Dispatcher.UIThread.MainLoop(_cts.Token);
			Environment.ExitCode = _exitCode;
			return _exitCode;
		}

		[MethodImpl(MethodImplOptions.NoInlining)]
		private void ShowMainWindow()
		{
			MainWindow?.Show();
		}

		public void Dispose()
		{
			_compositeDisposable?.Dispose();
			_compositeDisposable = null;
		}

		private bool DoShutdown(ShutdownRequestedEventArgs e, bool isProgrammatic, bool force = false, int exitCode = 0)
		{
			if (!force)
			{
				this.ShutdownRequested?.Invoke(this, e);
				if (e.Cancel)
				{
					return false;
				}
				if (_isShuttingDown)
				{
					throw new InvalidOperationException("Application is already shutting down.");
				}
			}
			_exitCode = exitCode;
			_isShuttingDown = true;
			bool flag = false;
			try
			{
				foreach (Window item in new List<Window>(_windows))
				{
					if (item.Owner == null)
					{
						bool ignoreCancel = force || (ShutdownMode == ShutdownMode.OnMainWindowClose && item != MainWindow);
						item.CloseCore(WindowCloseReason.ApplicationShutdown, isProgrammatic, ignoreCancel);
					}
				}
				if (!force && Windows.Count > 0)
				{
					e.Cancel = true;
					flag = true;
					return false;
				}
				ControlledApplicationLifetimeExitEventArgs e2 = new ControlledApplicationLifetimeExitEventArgs(exitCode);
				this.Exit?.Invoke(this, e2);
				_exitCode = e2.ApplicationExitCode;
			}
			finally
			{
				_isShuttingDown = false;
				if (!flag)
				{
					_cts?.Cancel();
					_cts = null;
					Dispatcher.UIThread.InvokeShutdown();
				}
			}
			return true;
		}

		private void OnShutdownRequested(object? sender, ShutdownRequestedEventArgs e)
		{
			DoShutdown(e, isProgrammatic: false);
		}
	}
